-- Beta Exercise Sprint 2 - PREVIEW / reporte previo de importacion.
-- Read-only: no modifica public.exercises.
-- Ejecutar primero en Supabase SQL Editor para revisar cambios, ignorados y conflictos.

BEGIN;

CREATE OR REPLACE FUNCTION pg_temp.be2_null_text(value text)
RETURNS text LANGUAGE sql IMMUTABLE AS $$
  SELECT NULLIF(btrim(value), '')
$$;

CREATE OR REPLACE FUNCTION pg_temp.be2_norm(value text)
RETURNS text LANGUAGE sql IMMUTABLE AS $$
  SELECT lower(regexp_replace(btrim(COALESCE(value, '')), '\s+', ' ', 'g'))
$$;

CREATE OR REPLACE FUNCTION pg_temp.be2_has_mojibake(value text)
RETURNS boolean LANGUAGE sql IMMUTABLE AS $$
  SELECT COALESCE(value, '') ~ '(Ã|Â|â€|â€“|â€œ|�)'
$$;

CREATE OR REPLACE FUNCTION pg_temp.be2_is_json_text_array(value text)
RETURNS boolean LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
  parsed jsonb;
BEGIN
  IF pg_temp.be2_null_text(value) IS NULL THEN
    RETURN true;
  END IF;
  parsed := value::jsonb;
  RETURN jsonb_typeof(parsed) = 'array'
    AND NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(parsed) AS item(value)
      WHERE jsonb_typeof(item.value) <> 'string'
    );
EXCEPTION WHEN others THEN
  RETURN false;
END;
$$;

CREATE OR REPLACE FUNCTION pg_temp.be2_text_array(value text)
RETURNS text[] LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
  parsed jsonb;
  result text[];
BEGIN
  IF pg_temp.be2_null_text(value) IS NULL THEN
    RETURN NULL;
  END IF;
  parsed := value::jsonb;
  IF jsonb_typeof(parsed) <> 'array' THEN
    RETURN NULL;
  END IF;
  SELECT array_agg(NULLIF(btrim(item), ''))
  INTO result
  FROM jsonb_array_elements_text(parsed) AS item
  WHERE NULLIF(btrim(item), '') IS NOT NULL;
  IF cardinality(COALESCE(result, '{}'::text[])) = 0 THEN
    RETURN NULL;
  END IF;
  RETURN result;
EXCEPTION WHEN others THEN
  RETURN NULL;
END;
$$;

CREATE OR REPLACE FUNCTION pg_temp.be2_is_numeric(value text)
RETURNS boolean LANGUAGE sql IMMUTABLE AS $$
  SELECT pg_temp.be2_null_text(value) IS NULL OR btrim(value) ~ '^-?[0-9]+(\.[0-9]+)?$'
$$;

CREATE OR REPLACE FUNCTION pg_temp.be2_int(value text)
RETURNS integer LANGUAGE plpgsql IMMUTABLE AS $$
BEGIN
  IF pg_temp.be2_null_text(value) IS NULL THEN
    RETURN NULL;
  END IF;

  RETURN round(value::numeric)::integer;
EXCEPTION WHEN others THEN
  RETURN NULL;
END;
$$;

CREATE OR REPLACE FUNCTION pg_temp.be2_numeric(value text)
RETURNS numeric LANGUAGE plpgsql IMMUTABLE AS $$
BEGIN
  IF pg_temp.be2_null_text(value) IS NULL THEN
    RETURN NULL;
  END IF;

  RETURN value::numeric;
EXCEPTION WHEN others THEN
  RETURN NULL;
END;
$$;

CREATE OR REPLACE FUNCTION pg_temp.be2_is_machine_like(
  _nombre text,
  _equipamiento text,
  _equipo_requerido text[],
  _patron text,
  _tipo text
)
RETURNS boolean LANGUAGE sql IMMUTABLE AS $$
  SELECT lower(concat_ws(' ', _nombre, _equipamiento, array_to_string(_equipo_requerido, ' '), _patron, _tipo))
    ~ '(m.quina|polea|prensa|smith|hack|pec[ -]?deck|caminadora|cinta de correr|bicicleta|el.ptica|escaladora|stair|remo erg.metro|erg.metro|banco predicador|predicador|asistid[ao]|assisted|multipower|cable|jal.n|leg press|leg curl|leg extension|curl femoral|extensi.n de cu.driceps|press en m.quina|remo en m.quina)'
$$;

CREATE TEMP TABLE exercise_import_staging_raw AS
SELECT
  elem.ordinality::integer AS row_number,
  action,
  id,
  nombre,
  aliases,
  nivel,
  nivel_minimo,
  grupo_muscular,
  musculo_principal,
  musculos_secundarios,
  equipamiento,
  equipo_requerido,
  tipo_entrenamiento,
  patron_movimiento,
  descripcion,
  instrucciones,
  cues_tecnicos,
  errores_comunes,
  contraindicaciones,
  sustituciones,
  progresiones,
  regresiones,
  lugar,
  objetivo,
  series_sugeridas,
  repeticiones_sugeridas,
  rango_reps_min,
  rango_reps_max,
  descanso_segundos_min,
  descanso_segundos_max,
  rir_recomendado,
  duracion_promedio_segundos,
  maquina_gym,
  estado_calidad
FROM jsonb_array_elements($patch_json$
[{"action":"update","id":"45","nombre":"Curl de bíceps con barra EZ","aliases":"[\"Curl de bíceps con barra EZ\",\"Curl bíceps barra EZ\",\"curl con barra EZ\",\"curl de bíceps de pie\",\"EZ-bar curl\",\"standing EZ curl\",\"EZ-bar biceps curl\",\"Curl de bíceps con BB EZ\"]","nivel":"intermedio","nivel_minimo":"principiante","grupo_muscular":"brazos","musculo_principal":"bíceps braquial","musculos_secundarios":"[\"braquial\",\"braquiorradial\",\"antebrazo\"]","equipamiento":"barra EZ","equipo_requerido":"[\"barra EZ\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"curl de codo","descripcion":"Curl de bíceps con barra EZ trabaja principalmente bíceps braquial, con participación de braquial, braquiorradial, antebrazo. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: coloca la barra EZ en un soporte bajo o en el suelo, carga ambos lados por igual y usa cierres. Elige las curvas que permitan un agarre semisupino cómodo al ancho de hombros y despeja espacio para que la barra no roce el cuerpo.\",\"Posición inicial: pies al ancho de caderas, rodillas suaves, pelvis neutra y abdomen firme. Mantén columna erguida, cabeza/cuello neutros, pecho relajado, hombros bajos, escápulas controladas y manos/muñecas alineadas; coloca los codos según la trayectoria sin fijarlos con rigidez.\",\"Agarre: usa supinación para enfatizar la flexión de codo; en barra EZ el ángulo semisupino reduce la exigencia de muñeca. Mantén pulgar cerrado y muñeca neutra; la cuerda permite pasar a neutro si el agarre supino molesta.\",\"Inicio y trayectoria: Inicia flexionando únicamente los codos y acerca la carga en un arco hacia los hombros; conserva el húmero quieto y siente el bíceps/braquial, no la zona lumbar.\",\"Rango y biomecánica: Sube hasta la máxima flexión que mantenga muñecas neutras y codos estables; baja hasta casi extenderlos, sin bloquear ni perder tensión. Los hombros y el tronco permanecen estables.\",\"Tempo y respiración: Tempo orientativo 3-1-1: baja 3 s, pausa 1 s en el estiramiento controlado y sube 1 s. Inhala al bajar y exhala al superar la parte difícil.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Codos en su carril\",\"Muñecas neutras\",\"Hombros lejos de orejas\",\"Costillas sobre pelvis\",\"Aprieta el músculo objetivo\",\"Sin balanceo del torso\",\"Controla la excéntrica\",\"Termina antes de perder postura\",\"Codos quietos\",\"Torso firme\"]","errores_comunes":"[\"Balancear el torso\",\"Adelantar o abrir los codos\",\"Doblar las muñecas\",\"Elevar los hombros\",\"Usar recorrido recortado\",\"Dejar caer la carga\",\"Contener la respiración\",\"Elegir peso que cambia la trayectoria\",\"Balancear la espalda\",\"Adelantar los codos\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Evitar si causa dolor de muñeca o codo\",\"Usar barra EZ o mancuernas si molesta la muñeca\"]","sustituciones":"[\"Curl de bíceps con mancuernas\",\"Curl martillo con mancuernas\",\"Curl en polea baja\",\"Variante equivalente en polea\",\"Variante con mancuernas\",\"Máquina de brazos con apoyo\"]","progresiones":"[\"Aumentar carga\",\"Pausar arriba\",\"Usar tempo lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Curl con mancuernas alterno\",\"Curl en polea ligera\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"12","descanso_segundos_min":"60","descanso_segundos_max":"90","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"sf-curl-preacher","nombre":"Curl de bíceps en banco predicador","aliases":"[\"Curl de bíceps en banco predicador\",\"Curl bíceps en banco predicador\",\"curl predicador\",\"curl Scott\",\"preacher curl\",\"Scott curl\"]","nivel":"intermedio","nivel_minimo":"principiante","grupo_muscular":"brazos","musculo_principal":"bíceps braquial","musculos_secundarios":"[\"braquial\",\"braquiorradial\"]","equipamiento":"banco predicador, barra EZ o mancuerna","equipo_requerido":"[\"banco predicador\",\"barra EZ o mancuerna\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"curl de codo apoyado","descripcion":"Curl de bíceps en banco predicador trabaja principalmente bíceps braquial, con participación de braquial, braquiorradial. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: ajusta el asiento para que las axilas queden cerca del borde superior y toda la parte posterior del brazo se apoye sin clavar el codo en el borde. Coloca la barra EZ en los ganchos, carga ambos lados con cierres y alcanza la barra sin encoger hombros; usa ayuda para sacarla si el banco no permite una entrada segura.\",\"Posición inicial: pies al ancho de caderas, rodillas suaves, pelvis neutra y abdomen firme. Mantén columna erguida, cabeza/cuello neutros, pecho relajado, hombros bajos, escápulas controladas y manos/muñecas alineadas; coloca los codos según la trayectoria sin fijarlos con rigidez.\",\"Agarre: usa supinación para enfatizar la flexión de codo; en barra EZ el ángulo semisupino reduce la exigencia de muñeca. Mantén pulgar cerrado y muñeca neutra; la cuerda permite pasar a neutro si el agarre supino molesta.\",\"Inicio y trayectoria: Inicia flexionando únicamente los codos y acerca la carga en un arco hacia los hombros; conserva el húmero quieto y siente el bíceps/braquial, no la zona lumbar.\",\"Rango y biomecánica: Sube hasta la máxima flexión que mantenga muñecas neutras y codos estables; baja hasta casi extenderlos, sin bloquear ni perder tensión. Los hombros y el tronco permanecen estables.\",\"Tempo y respiración: Tempo orientativo 3-1-1: baja 3 s, pausa 1 s en el estiramiento controlado y sube 1 s. Inhala al bajar y exhala al superar la parte difícil.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Codos en su carril\",\"Muñecas neutras\",\"Hombros lejos de orejas\",\"Costillas sobre pelvis\",\"Aprieta el músculo objetivo\",\"Sin balanceo del torso\",\"Controla la excéntrica\",\"Termina antes de perder postura\",\"Brazos pegados al cojín\",\"Hombros bajos\"]","errores_comunes":"[\"Balancear el torso\",\"Adelantar o abrir los codos\",\"Doblar las muñecas\",\"Elevar los hombros\",\"Usar recorrido recortado\",\"Dejar caer la carga\",\"Contener la respiración\",\"Elegir peso que cambia la trayectoria\",\"Despegar los codos\",\"Flexionar las muñecas\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Evitar si molesta el codo en extensión\",\"No bloquees fuerte abajo\"]","sustituciones":"[\"Curl de bíceps con barra\",\"Curl inclinado con mancuernas\",\"Curl en polea baja\",\"Variante equivalente en polea\",\"Variante con mancuernas\",\"Máquina de brazos con apoyo\"]","progresiones":"[\"Aumentar carga\",\"Usar una mano\",\"Pausar arriba\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Curl con mancuernas sentado\",\"Curl en polea ligera\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"12","descanso_segundos_min":"60","descanso_segundos_max":"90","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"sf-curl-cable","nombre":"Curl en polea baja","aliases":"[\"Curl en polea baja\",\"curl de bíceps en polea\",\"low cable curl\",\"cable biceps curl\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"brazos","musculo_principal":"bíceps braquial","musculos_secundarios":"[\"braquial\",\"braquiorradial\"]","equipamiento":"polea baja, barra o cuerda","equipo_requerido":"[\"polea baja\",\"barra o cuerda\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"curl de codo en polea","descripcion":"Curl en polea baja trabaja principalmente bíceps braquial, con participación de braquial, braquiorradial. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Baja el carro de la polea hasta el punto más bajo, conecta barra recta/EZ o cuerda, comprueba el mosquetón y coloca el pasador por completo. Retrocede solo lo suficiente para que el cable quede tenso sin levantar la pila. La cifra de la pila puede no equivaler a la resistencia efectiva por la relación de poleas; registra siempre la misma torre, ajuste y accesorio.\",\"Posición inicial: pies al ancho de caderas, rodillas suaves, pelvis neutra y abdomen firme. Mantén columna erguida, cabeza/cuello neutros, pecho relajado, hombros bajos, escápulas controladas y manos/muñecas alineadas; coloca los codos según la trayectoria sin fijarlos con rigidez.\",\"Agarre: usa supinación para enfatizar la flexión de codo; en barra EZ el ángulo semisupino reduce la exigencia de muñeca. Mantén pulgar cerrado y muñeca neutra; la cuerda permite pasar a neutro si el agarre supino molesta.\",\"Inicio y trayectoria: Inicia flexionando únicamente los codos y acerca la carga en un arco hacia los hombros; conserva el húmero quieto y siente el bíceps/braquial, no la zona lumbar.\",\"Rango y biomecánica: Sube hasta la máxima flexión que mantenga muñecas neutras y codos estables; baja hasta casi extenderlos, sin bloquear ni perder tensión. Los hombros y el tronco permanecen estables.\",\"Tempo y respiración: Tempo orientativo 3-1-1: baja 3 s, pausa 1 s en el estiramiento controlado y sube 1 s. Inhala al bajar y exhala al superar la parte difícil.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Codos en su carril\",\"Muñecas neutras\",\"Hombros lejos de orejas\",\"Costillas sobre pelvis\",\"Aprieta el músculo objetivo\",\"Sin balanceo del torso\",\"Controla la excéntrica\",\"Termina antes de perder postura\",\"Codos quietos\",\"Torso estable\"]","errores_comunes":"[\"Balancear el torso\",\"Adelantar o abrir los codos\",\"Doblar las muñecas\",\"Elevar los hombros\",\"Usar recorrido recortado\",\"Dejar caer la carga\",\"Contener la respiración\",\"Elegir peso que cambia la trayectoria\",\"Adelantar los codos\",\"Golpear la pila\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Evitar si molesta codo o muñeca\",\"Cambiar agarre si hay molestia\"]","sustituciones":"[\"Curl de bíceps con barra\",\"Curl predicador\",\"Curl inclinado con mancuernas\",\"Variante equivalente en polea\",\"Variante con mancuernas\",\"Máquina de brazos con apoyo\"]","progresiones":"[\"Aumentar peso\",\"Usar cuerda\",\"Pausar en contracción\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir peso\",\"Curl con banda\",\"Curl con mancuernas ligero\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"12","rango_reps_min":"10","rango_reps_max":"15","descanso_segundos_min":"45","descanso_segundos_max":"90","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"Functional Trainer","estado_calidad":"curado"},{"action":"update","id":"sf-triceps-pushdown","nombre":"Pushdown de tríceps con cuerda","aliases":"[\"Pushdown de tríceps con cuerda\",\"Pushdown tríceps con cuerda\",\"jalón de tríceps con cuerda\",\"extensión de tríceps en polea con cuerda\",\"rope pushdown\",\"triceps rope pushdown\",\"Rope triceps pushdown\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"brazos","musculo_principal":"tríceps braquial","musculos_secundarios":"[\"triceps lateral\",\"triceps medial\",\"antebrazo\"]","equipamiento":"polea alta, cuerda","equipo_requerido":"[\"polea alta\",\"cuerda\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"extension de codo en polea","descripcion":"Pushdown de tríceps con cuerda trabaja principalmente tríceps braquial, con participación de tríceps lateral, tríceps medial, antebrazo. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Sube el carro por encima de la cabeza, conecta la cuerda y comprueba mosquetón, cable y pasador. Elige una carga que no te obligue a inclinarte; deja espacio para separar la cuerda sin golpear los muslos. La cifra de la pila puede no equivaler a la resistencia efectiva por la relación de poleas; registra siempre la misma torre, ajuste y accesorio.\",\"Posición inicial: pies al ancho de caderas, rodillas suaves, pelvis neutra y abdomen firme. Mantén columna erguida, cabeza/cuello neutros, pecho relajado, hombros bajos, escápulas controladas y manos/muñecas alineadas; coloca los codos según la trayectoria sin fijarlos con rigidez.\",\"Agarre: barra recta/EZ en prono para una trayectoria estable; cuerda o asa en neutro cuando quieras libertad de muñeca. Mantén pulgar cerrado, muñecas alineadas y no conviertas el movimiento en un press de hombros.\",\"Inicio y trayectoria: Inicia extendiendo los codos hacia abajo; los antebrazos giran alrededor de codos quietos. Siente el tríceps y evita que hombros o torso generen impulso.\",\"Rango y biomecánica: Extiende hasta dejar el brazo recto sin hiperextender el codo; retorna hasta que el antebrazo quede algo por encima de horizontal sin despegar los codos. El hombro y la columna permanecen estables.\",\"Tempo y respiración: Tempo 2-1-2: extiende en 2 s, pausa 1 s abajo y vuelve en 2 s. Exhala al extender e inhala durante el retorno.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Codos en su carril\",\"Muñecas neutras\",\"Hombros lejos de orejas\",\"Costillas sobre pelvis\",\"Aprieta el músculo objetivo\",\"Sin balanceo del torso\",\"Controla la excéntrica\",\"Termina antes de perder postura\",\"Codos pegados\",\"Pecho estable\"]","errores_comunes":"[\"Balancear el torso\",\"Adelantar o abrir los codos\",\"Doblar las muñecas\",\"Elevar los hombros\",\"Usar recorrido recortado\",\"Dejar caer la carga\",\"Contener la respiración\",\"Elegir peso que cambia la trayectoria\",\"Abrir los codos\",\"Inclinarse sobre el cable\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Ten precaución con alto impacto si aún no puedes aterrizar o desacelerar sin dolor ni pérdida de alineación\",\"Evitar si causa dolor de codo\",\"Cambiar agarre si molesta muñeca\"]","sustituciones":"[\"Extensión de tríceps por encima de la cabeza con mancuerna\",\"Press francés con barra\",\"Fondos en banco para tríceps\",\"Variante equivalente en polea\",\"Variante con mancuernas\",\"Máquina de brazos con apoyo\"]","progresiones":"[\"Aumentar peso\",\"Usar cuerda y abrir al final\",\"Pausar abajo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Menos carga\",\"Banda elástica\",\"Extension con mancuerna ligera\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"12","rango_reps_min":"10","rango_reps_max":"15","descanso_segundos_min":"45","descanso_segundos_max":"90","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"Functional Trainer","estado_calidad":"curado"},{"action":"update","id":"47","nombre":"Press francés con barra EZ","aliases":"[\"Press francés con barra EZ\",\"Press francés barra EZ\",\"extensión de tríceps acostado\",\"rompecráneos con barra EZ\",\"EZ-bar skull crusher\",\"lying triceps extension\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"brazos","musculo_principal":"tríceps braquial","musculos_secundarios":"[\"triceps lateral\",\"triceps medial\"]","equipamiento":"barra EZ, banco","equipo_requerido":"[\"barra EZ\",\"banco\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"extension de codo acostado","descripcion":"Press francés con barra EZ trabaja principalmente tríceps braquial, con participación de tríceps lateral, tríceps medial. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: usa banco plano, barra EZ con discos iguales y cierres. Colócala en un rack accesible o pide a un spotter que la entregue sobre hombros; ensaya con barra ligera y confirma que puedes devolverla sin pasarla sobre la cara bajo fatiga.\",\"Posición inicial: pies completos y separados al ancho de caderas, rodillas estables, glúteos y parte alta de la espalda apoyados. Mantén una curva lumbar natural, pecho elevado sin hiperextender, cabeza/cuello neutros, hombros abajo y escápulas apoyadas; alinea codos y muñecas con la carga.\",\"Agarre: prono en barra/suelo o neutro en asas/mancuernas. Usa una anchura que deje antebrazos casi verticales; un agarre cerrado aumenta demanda de tríceps y uno muy ancho acorta el recorrido. Pulgar cerrado y muñeca apilada sobre antebrazo.\",\"Inicio y trayectoria: Mantén el brazo superior estable e inicia moviendo el antebrazo por flexión/extensión del codo. Extiende con el tríceps sin adelantar hombros ni arquear la espalda.\",\"Rango y biomecánica: Recorre desde una flexión cómoda que produzca estiramiento hasta casi extender el codo; evita bloquear con violencia o llevar la carga a un ángulo que cambie a movimiento de hombro.\",\"Tempo y respiración: Tempo 3-0-1 con una pausa breve en extensión: inhala al flexionar el codo y exhala al extender; controla especialmente la excéntrica.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Codos en su carril\",\"Muñecas neutras\",\"Hombros lejos de orejas\",\"Costillas sobre pelvis\",\"Aprieta el músculo objetivo\",\"Sin balanceo del torso\",\"Controla la excéntrica\",\"Termina antes de perder postura\",\"Codos apuntan al techo\",\"Brazos estables\"]","errores_comunes":"[\"Balancear el torso\",\"Adelantar o abrir los codos\",\"Doblar las muñecas\",\"Elevar los hombros\",\"Usar recorrido recortado\",\"Dejar caer la carga\",\"Contener la respiración\",\"Elegir peso que cambia la trayectoria\",\"Abrir los codos\",\"Mover los hombros en exceso\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Evitar si genera dolor de codo\",\"Usar mancuernas o polea si molesta muñeca\"]","sustituciones":"[\"Pushdown de tríceps en polea\",\"Extensión de tríceps por encima de la cabeza con mancuerna\",\"Fondos en banco para tríceps\",\"Variante equivalente en polea\",\"Variante con mancuernas\",\"Máquina de brazos con apoyo\"]","progresiones":"[\"Aumentar carga\",\"Usar pausa abajo\",\"Probar barra EZ\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Pushdown ligero\",\"Extensión con mancuerna\",\"Reducir rango\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"12","descanso_segundos_min":"60","descanso_segundos_max":"90","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"10","nombre":"Extensión de tríceps por encima de la cabeza con mancuerna","aliases":"[\"Extensión de tríceps por encima de la cabeza con mancuerna\",\"Extensión tríceps por encima de la cabeza con mancuerna\",\"extensión de tríceps sobre la cabeza con mancuerna\",\"copa de tríceps\",\"overhead dumbbell triceps extension\",\"dumbbell French press\",\"Single-dumbbell overhead triceps extension\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"brazos","musculo_principal":"tríceps braquial","musculos_secundarios":"[\"triceps lateral\",\"triceps medial\",\"core\"]","equipamiento":"mancuerna","equipo_requerido":"[\"mancuerna\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"extension de codo overhead","descripcion":"Extensión de tríceps por encima de la cabeza con mancuerna trabaja principalmente tríceps braquial, con participación de tríceps lateral, tríceps medial, core. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: elige una mancuerna cuyo disco y asa estén firmes. Para empezar, siéntate en un banco con respaldo de 75–85°, lleva la mancuerna al muslo y ayúdala hasta el pecho; sujétala con ambas palmas por la cara interna del disco superior antes de elevarla.\",\"Posición inicial: pies al ancho de caderas, rodillas suaves, pelvis neutra y abdomen firme. Mantén columna erguida, cabeza/cuello neutros, pecho relajado, hombros bajos, escápulas controladas y manos/muñecas alineadas; coloca los codos según la trayectoria sin fijarlos con rigidez.\",\"Agarre: barra recta/EZ en prono para una trayectoria estable; cuerda o asa en neutro cuando quieras libertad de muñeca. Mantén pulgar cerrado, muñecas alineadas y no conviertas el movimiento en un press de hombros.\",\"Inicio y trayectoria: Mantén el brazo superior estable e inicia moviendo el antebrazo por flexión/extensión del codo. Extiende con el tríceps sin adelantar hombros ni arquear la espalda.\",\"Rango y biomecánica: Recorre desde una flexión cómoda que produzca estiramiento hasta casi extender el codo; evita bloquear con violencia o llevar la carga a un ángulo que cambie a movimiento de hombro.\",\"Tempo y respiración: Tempo 3-0-1 con una pausa breve en extensión: inhala al flexionar el codo y exhala al extender; controla especialmente la excéntrica.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Codos en su carril\",\"Muñecas neutras\",\"Hombros lejos de orejas\",\"Costillas sobre pelvis\",\"Aprieta el músculo objetivo\",\"Sin balanceo del torso\",\"Controla la excéntrica\",\"Termina antes de perder postura\",\"Codos al frente\",\"Costillas controladas\"]","errores_comunes":"[\"Balancear el torso\",\"Adelantar o abrir los codos\",\"Doblar las muñecas\",\"Elevar los hombros\",\"Usar recorrido recortado\",\"Dejar caer la carga\",\"Contener la respiración\",\"Elegir peso que cambia la trayectoria\",\"Abrir mucho los codos\",\"Arquear la espalda\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Evitar si provoca dolor de hombro o codo\",\"Usar polea o menor rango si molesta\"]","sustituciones":"[\"Pushdown de tríceps en polea\",\"Press francés con barra\",\"Patada de tríceps con mancuernas\",\"Variante equivalente en polea\",\"Variante con mancuernas\",\"Máquina de brazos con apoyo\"]","progresiones":"[\"Aumentar carga\",\"Usar polea para tensión continua\",\"Pausar abajo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Usar mancuerna mas ligera\",\"Pushdown en polea\",\"Reducir rango\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"cualquiera","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"12","rango_reps_min":"10","rango_reps_max":"15","descanso_segundos_min":"60","descanso_segundos_max":"90","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"8","nombre":"Curl de bíceps con mancuernas de pie","aliases":"[\"Curl de bíceps con mancuernas de pie\",\"Curl bíceps mancuernas de pie\",\"dumbbell curl\",\"curl alternado\",\"Standing dumbbell curl\",\"Curl de bíceps con DB de pie\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"brazos","musculo_principal":"bíceps braquial","musculos_secundarios":"[\"braquial\",\"braquiorradial\"]","equipamiento":"mancuernas","equipo_requerido":"[\"mancuernas\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"curl de codo","descripcion":"Curl de bíceps con mancuernas de pie trabaja principalmente bíceps braquial, con participación de braquial, braquiorradial. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: coloca dos mancuernas iguales a los lados, levántalas con una bisagra/sentadilla corta y ponte de pie antes de iniciar. Deja espacio para supinar sin chocar las pesas y elige carga que no requiera balanceo.\",\"Posición inicial: pies al ancho de caderas, rodillas suaves, pelvis neutra y abdomen firme. Mantén columna erguida, cabeza/cuello neutros, pecho relajado, hombros bajos, escápulas controladas y manos/muñecas alineadas; coloca los codos según la trayectoria sin fijarlos con rigidez.\",\"Agarre: usa supinación para enfatizar la flexión de codo; en barra EZ el ángulo semisupino reduce la exigencia de muñeca. Mantén pulgar cerrado y muñeca neutra; la cuerda permite pasar a neutro si el agarre supino molesta.\",\"Inicio y trayectoria: Inicia flexionando únicamente los codos y acerca la carga en un arco hacia los hombros; conserva el húmero quieto y siente el bíceps/braquial, no la zona lumbar.\",\"Rango y biomecánica: Sube hasta la máxima flexión que mantenga muñecas neutras y codos estables; baja hasta casi extenderlos, sin bloquear ni perder tensión. Los hombros y el tronco permanecen estables.\",\"Tempo y respiración: Tempo orientativo 3-1-1: baja 3 s, pausa 1 s en el estiramiento controlado y sube 1 s. Inhala al bajar y exhala al superar la parte difícil.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Codos en su carril\",\"Muñecas neutras\",\"Hombros lejos de orejas\",\"Costillas sobre pelvis\",\"Aprieta el músculo objetivo\",\"Sin balanceo del torso\",\"Controla la excéntrica\",\"Termina antes de perder postura\",\"Controla la fase de ida y vuelta\",\"Evita impulsos excesivos\"]","errores_comunes":"[\"Balancear el torso\",\"Adelantar o abrir los codos\",\"Doblar las muñecas\",\"Elevar los hombros\",\"Usar recorrido recortado\",\"Dejar caer la carga\",\"Contener la respiración\",\"Elegir peso que cambia la trayectoria\",\"Usar impulso excesivo\",\"Perder postura\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Curl martillo con mancuernas\",\"Curl de bíceps con barra\",\"Variante equivalente en polea\",\"Variante con mancuernas\",\"Máquina de brazos con apoyo\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"10","rango_reps_max":"15","descanso_segundos_min":"45","descanso_segundos_max":"90","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"46","nombre":"Fondos en banco para tríceps","aliases":"[\"Fondos en banco para tríceps\",\"fondos de tríceps en banco\",\"bench dips\",\"triceps bench dips\",\"Bench dip\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"brazos","musculo_principal":"tríceps braquial","musculos_secundarios":"[\"deltoides anterior\",\"pectoral menor\"]","equipamiento":"banco","equipo_requerido":"[\"banco\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"extensión de codo","descripcion":"Fondos en banco para tríceps trabaja principalmente tríceps braquial, con participación de deltoides anterior, pectoral menor. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: usa un banco pesado contra una pared o rack para que no se deslice. Siéntate en el borde, manos junto a caderas con dedos al frente y baja los glúteos manteniéndolos cerca; empieza con rodillas flexionadas y pies planos.\",\"Posición inicial: pies o apoyos firmes, rodillas y cadera estables, glúteos y abdomen contraídos. Conserva columna y cuello neutros, pecho controlado, hombros lejos de orejas y escápulas estables; apila manos, muñecas y codos según la dirección del empuje.\",\"Agarre: prono en barra/suelo o neutro en asas/mancuernas. Usa una anchura que deje antebrazos casi verticales; un agarre cerrado aumenta demanda de tríceps y uno muy ancho acorta el recorrido. Pulgar cerrado y muñeca apilada sobre antebrazo.\",\"Inicio y trayectoria: Inicia empujando el apoyo o la carga en la línea prevista mientras hombro y codo se extienden coordinados. Siente pectoral/deltoides/tríceps según la variante, con abdomen firme y hombros lejos de orejas.\",\"Rango y biomecánica: Baja hasta que el codo alcance una profundidad tolerable y el hombro conserve centrado, normalmente con antebrazo vertical; sube hasta brazos casi extendidos sin chocar ni hiperextender. Evita rebotes y extremos que despeguen espalda o pelvis.\",\"Tempo y respiración: Tempo base 3-0-1: desciende 3 s, pausa sin rebote y empuja en 1 s controlado. Inhala al bajar y exhala al cruzar el punto de mayor esfuerzo; usa respiración con brace solo si conoces la técnica.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Codos en su carril\",\"Muñecas neutras\",\"Hombros lejos de orejas\",\"Costillas sobre pelvis\",\"Aprieta el músculo objetivo\",\"Sin balanceo del torso\",\"Controla la excéntrica\",\"Termina antes de perder postura\",\"Cadera cerca del banco\",\"Codos hacia atrás\"]","errores_comunes":"[\"Balancear el torso\",\"Adelantar o abrir los codos\",\"Doblar las muñecas\",\"Elevar los hombros\",\"Usar recorrido recortado\",\"Dejar caer la carga\",\"Contener la respiración\",\"Elegir peso que cambia la trayectoria\",\"Bajar demasiado\",\"Alejar la cadera\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Evitar con dolor anterior de hombro, inestabilidad o molestia de muñeca\",\"Preferir pushdown en polea si el rango resulta incómodo\"]","sustituciones":"[\"Extensión de tríceps sobre la cabeza con mancuerna\",\"Patada de tríceps con mancuernas\",\"Press francés con barra\",\"Variante equivalente en polea\",\"Variante con mancuernas\",\"Máquina de brazos con apoyo\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"8","rango_reps_max":"15","descanso_segundos_min":"60","descanso_segundos_max":"90","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"revisar"},{"action":"update","id":"11","nombre":"Patada de tríceps con mancuerna unilateral","aliases":"[\"Patada de tríceps con mancuerna unilateral\",\"Patada tríceps con mancuerna unilateral\",\"triceps kickback\",\"kickback\",\"Single-arm dumbbell triceps kickback\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"brazos","musculo_principal":"tríceps braquial","musculos_secundarios":"[\"deltoides posterior\"]","equipamiento":"mancuernas","equipo_requerido":"[\"mancuernas\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"extensión de codo","descripcion":"Patada de tríceps con mancuerna unilateral trabaja principalmente tríceps braquial, con participación de deltoides posterior. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: coloca una mancuerna junto a un banco estable. Apoya mano y rodilla contrarias o solo una mano, realiza bisagra de cadera y eleva la mancuerna con el codo pegado al torso; no la recojas girando la espalda.\",\"Posición inicial: pies al ancho de caderas, rodillas suaves, pelvis neutra y abdomen firme. Mantén columna erguida, cabeza/cuello neutros, pecho relajado, hombros bajos, escápulas controladas y manos/muñecas alineadas; coloca los codos según la trayectoria sin fijarlos con rigidez.\",\"Agarre: barra recta/EZ en prono para una trayectoria estable; cuerda o asa en neutro cuando quieras libertad de muñeca. Mantén pulgar cerrado, muñecas alineadas y no conviertas el movimiento en un press de hombros.\",\"Inicio y trayectoria: Mantén el brazo superior estable e inicia moviendo el antebrazo por flexión/extensión del codo. Extiende con el tríceps sin adelantar hombros ni arquear la espalda.\",\"Rango y biomecánica: Recorre desde una flexión cómoda que produzca estiramiento hasta casi extender el codo; evita bloquear con violencia o llevar la carga a un ángulo que cambie a movimiento de hombro.\",\"Tempo y respiración: Tempo 3-0-1 con una pausa breve en extensión: inhala al flexionar el codo y exhala al extender; controla especialmente la excéntrica.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Codos en su carril\",\"Muñecas neutras\",\"Hombros lejos de orejas\",\"Costillas sobre pelvis\",\"Aprieta el músculo objetivo\",\"Sin balanceo del torso\",\"Controla la excéntrica\",\"Termina antes de perder postura\",\"Controla la fase de ida y vuelta\",\"Evita impulsos excesivos\"]","errores_comunes":"[\"Balancear el torso\",\"Adelantar o abrir los codos\",\"Doblar las muñecas\",\"Elevar los hombros\",\"Usar recorrido recortado\",\"Dejar caer la carga\",\"Contener la respiración\",\"Elegir peso que cambia la trayectoria\",\"Usar impulso excesivo\",\"Perder postura\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Extensión de tríceps sobre la cabeza con mancuerna\",\"Press francés con barra\",\"Fondos en banco para tríceps\",\"Variante equivalente en polea\",\"Variante con mancuernas\",\"Máquina de brazos con apoyo\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"12","rango_reps_max":"20","descanso_segundos_min":"45","descanso_segundos_max":"75","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"ab0771a8-3e45-40f6-8018-c5a119eaf2c1","nombre":"Bicicleta estática","aliases":"[\"Bicicleta estática\",\"bicicleta fija\",\"bicicleta estacionaria\",\"stationary bike\",\"exercise bike\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"cardio","musculo_principal":"sistema cardiovascular","musculos_secundarios":"[\"glúteos\",\"cuádriceps\",\"isquiosurales\",\"pantorrillas\"]","equipamiento":"bicicleta estática","equipo_requerido":"[\"bicicleta estática\"]","tipo_entrenamiento":"cardio","patron_movimiento":"locomocion/cardio","descripcion":"Bicicleta estática trabaja principalmente sistema cardiovascular, con participación de glúteos, cuádriceps, isquiosurales. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para calentamiento, acondicionamiento y trabajo por intervalos ajustable al nivel.","instrucciones":"[\"Preparación de la bicicleta: ajusta el sillín para que, con el pedal abajo, la rodilla conserve una ligera flexión y la pelvis no se balancee. Regula manubrio para una postura cómoda, fija correas sin comprimir y prueba frenos/parada.\",\"Posición inicial: pies centrados en pedales, rodillas siguiendo la línea del segundo dedo, cadera nivelada, espalda larga, cabeza/cuello neutros, pecho abierto y hombros bajos; manos ligeras y muñecas rectas.\",\"Ajuste de resistencia: comienza muy baja durante 3–5 min y aumenta de forma gradual. Usa una cadencia que permita pedalear redondo sin rebotar en el sillín; la resistencia no debe obligarte a empujar con la espalda.\",\"Ejecución y biomecánica: aplica fuerza durante todo el ciclo, especialmente al bajar el pedal, manteniendo tobillo estable. Debes sentir cuádriceps y glúteos; rodillas, pelvis y tronco no oscilan lateralmente.\",\"Intensidad: para trabajo continuo conserva una respiración rítmica y una percepción sostenible; para intervalos alterna esfuerzo y recuperación sin perder cadencia o alineación. No uses el nivel máximo como punto de partida.\",\"Respiración: inhala por nariz/boca y exhala de forma regular; evita contener el aire. Reduce intensidad si no puedes controlar la respiración, aparece mareo o la técnica cambia.\",\"Errores a corregir: sillín demasiado bajo, rodillas hacia dentro, cadera balanceándose, agarre rígido, hombros elevados, pedalear solo con puntas o resistencia excesiva.\",\"Finalización y seguridad: baja resistencia y pedalea suave 2–5 min; detén el volante según el modelo, espera a que los pedales paren y desmonta sujetándote. Nunca ajustes sillín o correas con la bicicleta en movimiento.\"]","cues_tecnicos":"[\"Postura alta\",\"Respiración rítmica\",\"Pies centrados\",\"Rodillas alineadas\",\"Hombros relajados\",\"Aumenta gradualmente\",\"Técnica antes que velocidad\",\"Enfría al terminar\",\"Rodilla alineada con el pie\",\"Cadera estable\"]","errores_comunes":"[\"Empezar demasiado rápido\",\"Colgarse de las barras\",\"Rodillas desalineadas\",\"Mirar al suelo\",\"Hombros tensos\",\"Contener la respiración\",\"Omitir calentamiento/enfriamiento\",\"Bajar antes de detener la máquina\",\"Sillín demasiado bajo\",\"Cadera oscilante\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Detener la actividad si hay dolor en rodillas o cadera\",\"Consultar si hay hipertensión no controlada\"]","sustituciones":"[\"Ciclismo al aire libre\",\"Elíptica\",\"Remo ergómetro\",\"Bicicleta estática\",\"Caminata a ritmo cómodo\"]","progresiones":"[\"Aumentar resistencia\",\"Aumentar duración\",\"Agregar intervalos\",\"Aumentar duración 5–10 % manteniendo técnica\",\"Añadir intervalos de trabajo/recuperación\",\"Subir una sola variable: ritmo, resistencia o pendiente\"]","regresiones":"[\"Reducir resistencia\",\"Reducir duración\",\"Pedalear a ritmo suave\",\"Reducir ritmo/resistencia\",\"Acortar los intervalos de trabajo\",\"Usar una modalidad de menor impacto\"]","lugar":"gimnasio","objetivo":"cardio","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"","rango_reps_max":"","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"","duracion_promedio_segundos":"600","maquina_gym":"Upright Stationary Bike","estado_calidad":"curado"},{"action":"update","id":"9b62cd98-198f-484b-a098-5dbd9f78d0d3","nombre":"Caminadora","aliases":"[\"Caminadora\",\"cinta de correr\",\"banda caminadora\",\"treadmill\",\"running treadmill\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"cardio","musculo_principal":"sistema cardiovascular","musculos_secundarios":"[\"glúteos\",\"isquiosurales\",\"cuádriceps\",\"pantorrillas\",\"core\"]","equipamiento":"caminadora","equipo_requerido":"[\"caminadora\"]","tipo_entrenamiento":"cardio","patron_movimiento":"locomocion/cardio","descripcion":"Caminadora trabaja principalmente sistema cardiovascular, con participación de glúteos, isquiosurales, cuádriceps. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para calentamiento, acondicionamiento y trabajo por intervalos ajustable al nivel.","instrucciones":"[\"Preparación de la caminadora: conoce botones de inicio, pausa y parada de emergencia; conecta el clip de seguridad a la ropa. Sube con la banda detenida, coloca pies en los laterales y programa una velocidad inicial muy baja.\",\"Configuración: Deja la inclinación en 0–1 % para aprender y aumenta velocidad solo cuando la zancada sea estable.\",\"Posición inicial: mirada al frente, cabeza/cuello neutros, pecho relajado, hombros bajos y brazos libres. Mantén abdomen firme, pelvis estable, pies orientados al frente y rodillas siguiendo su línea natural.\",\"Ejecución: entra a la banda desde los laterales cuando avance despacio; camina o corre cerca del centro, con pasos silenciosos y sin intentar alcanzar el frente. Los brazos se mueven desde hombros con codos flexionados.\",\"Biomecánica: busca apoyo debajo del cuerpo y transición fluida del pie; siente piernas y glúteos, no impacto brusco ni tensión lumbar. Evita sobrezancada, mirar al suelo o sujetarte continuamente.\",\"Respiración e intensidad: respira de forma rítmica; aumenta una variable a la vez —velocidad, pendiente o duración—. Reduce de inmediato si pierdes coordinación, aparece mareo o no puedes accionar los controles.\",\"Rango/seguridad: no camines hacia atrás ni saltes a los laterales durante una sesión normal. Usa las barras solo para subir, bajar o recuperar equilibrio, no para descargar el peso corporal.\",\"Finalización: reduce velocidad e inclinación gradualmente durante 2–5 min, pulsa detener y espera que la banda quede inmóvil. Pasa a los laterales, retira el clip y baja mirando al frente.\"]","cues_tecnicos":"[\"Postura alta\",\"Respiración rítmica\",\"Pies centrados\",\"Rodillas alineadas\",\"Hombros relajados\",\"Aumenta gradualmente\",\"Técnica antes que velocidad\",\"Enfría al terminar\",\"Mira al frente\",\"Pisa bajo el cuerpo\"]","errores_comunes":"[\"Empezar demasiado rápido\",\"Colgarse de las barras\",\"Rodillas desalineadas\",\"Mirar al suelo\",\"Hombros tensos\",\"Contener la respiración\",\"Omitir calentamiento/enfriamiento\",\"Bajar antes de detener la máquina\",\"Saltar a una banda en movimiento\",\"Sujetarse todo el tiempo\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Detén la actividad si experimentas mareos o dolor torácico\",\"Consulta con un profesional si tienes problemas cardíacos\"]","sustituciones":"[\"Saltar cuerda\",\"Ciclismo\",\"Elíptica\",\"Remo ergómetro\",\"Bicicleta estática\",\"Caminata a ritmo cómodo\"]","progresiones":"[\"Aumentar duración\",\"Incrementar velocidad\",\"Agregar intervalos\",\"Aumentar inclinación\",\"Aumentar duración 5–10 % manteniendo técnica\",\"Añadir intervalos de trabajo/recuperación\"]","regresiones":"[\"Disminuir duración\",\"Reducir velocidad\",\"Caminar en lugar de correr\",\"Reducir ritmo/resistencia\",\"Acortar los intervalos de trabajo\",\"Usar una modalidad de menor impacto\"]","lugar":"gimnasio","objetivo":"cardio","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"","rango_reps_max":"","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"","duracion_promedio_segundos":"600","maquina_gym":"Treadmill","estado_calidad":"curado"},{"action":"update","id":"91d0e457-76d9-4624-98ea-f517f06c6995","nombre":"Caminadora inclinada","aliases":"[\"Caminadora inclinada\",\"caminata inclinada\",\"caminadora con inclinación\",\"incline treadmill walk\",\"incline treadmill\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"cardio","musculo_principal":"sistema cardiovascular","musculos_secundarios":"[\"glúteos\",\"isquiosurales\",\"cuádriceps\",\"pantorrillas\",\"core\"]","equipamiento":"caminadora","equipo_requerido":"[\"caminadora\"]","tipo_entrenamiento":"cardio","patron_movimiento":"locomocion/cardio","descripcion":"Caminadora inclinada trabaja principalmente sistema cardiovascular, con participación de glúteos, isquiosurales, cuádriceps. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para calentamiento, acondicionamiento y trabajo por intervalos ajustable al nivel.","instrucciones":"[\"Preparación de la caminadora: conoce botones de inicio, pausa y parada de emergencia; conecta el clip de seguridad a la ropa. Sube con la banda detenida, coloca pies en los laterales y programa una velocidad inicial muy baja.\",\"Configuración: Configura primero una inclinación baja y súbela en incrementos pequeños; una pendiente alta exige más pantorrilla/glúteo y no justifica colgarse de las barras.\",\"Posición inicial: mirada al frente, cabeza/cuello neutros, pecho relajado, hombros bajos y brazos libres. Mantén abdomen firme, pelvis estable, pies orientados al frente y rodillas siguiendo su línea natural.\",\"Ejecución: entra a la banda desde los laterales cuando avance despacio; camina o corre cerca del centro, con pasos silenciosos y sin intentar alcanzar el frente. Los brazos se mueven desde hombros con codos flexionados.\",\"Biomecánica: busca apoyo debajo del cuerpo y transición fluida del pie; siente piernas y glúteos, no impacto brusco ni tensión lumbar. Evita sobrezancada, mirar al suelo o sujetarte continuamente.\",\"Respiración e intensidad: respira de forma rítmica; aumenta una variable a la vez —velocidad, pendiente o duración—. Reduce de inmediato si pierdes coordinación, aparece mareo o no puedes accionar los controles.\",\"Rango/seguridad: no camines hacia atrás ni saltes a los laterales durante una sesión normal. Usa las barras solo para subir, bajar o recuperar equilibrio, no para descargar el peso corporal.\",\"Finalización: reduce velocidad e inclinación gradualmente durante 2–5 min, pulsa detener y espera que la banda quede inmóvil. Pasa a los laterales, retira el clip y baja mirando al frente.\"]","cues_tecnicos":"[\"Postura alta\",\"Respiración rítmica\",\"Pies centrados\",\"Rodillas alineadas\",\"Hombros relajados\",\"Aumenta gradualmente\",\"Técnica antes que velocidad\",\"Enfría al terminar\",\"Torso erguido\",\"Paso natural\"]","errores_comunes":"[\"Empezar demasiado rápido\",\"Colgarse de las barras\",\"Rodillas desalineadas\",\"Mirar al suelo\",\"Hombros tensos\",\"Contener la respiración\",\"Omitir calentamiento/enfriamiento\",\"Bajar antes de detener la máquina\",\"Inclinación demasiado alta\",\"Sujetarse y echarse hacia atrás\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Suspender si hay mareo o dolor torácico\",\"Consultar si hay problemas de rodilla\"]","sustituciones":"[\"Caminadora sin inclinación\",\"Elíptica\",\"Escaladora\",\"Bicicleta estática\",\"Caminata a ritmo cómodo\"]","progresiones":"[\"Aumentar inclinación\",\"Aumentar velocidad\",\"Aumentar duración\",\"Aumentar duración 5–10 % manteniendo técnica\",\"Añadir intervalos de trabajo/recuperación\",\"Subir una sola variable: ritmo, resistencia o pendiente\"]","regresiones":"[\"Reducir inclinación\",\"Bajar velocidad\",\"Caminar\",\"Reducir ritmo/resistencia\",\"Acortar los intervalos de trabajo\",\"Usar una modalidad de menor impacto\"]","lugar":"gimnasio","objetivo":"cardio","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"","rango_reps_max":"","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"","duracion_promedio_segundos":"600","maquina_gym":"Incline Treadmill","estado_calidad":"curado"},{"action":"update","id":"ac218282-fa80-4bb4-93ca-712c55f3c9ad","nombre":"Escaladora de peldaños (StepMill)","aliases":"[\"Escaladora de peldaños (StepMill)\",\"máquina de escaleras\",\"escaladora de peldaños\",\"stair climber\",\"stair stepper\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"cardio","musculo_principal":"sistema cardiovascular","musculos_secundarios":"[\"glúteos\",\"cuádriceps\",\"pantorrillas\",\"isquiosurales\",\"core\"]","equipamiento":"escaladora de peldaños","equipo_requerido":"[\"Stair Climber / StepMill\"]","tipo_entrenamiento":"cardio","patron_movimiento":"locomocion/cardio","descripcion":"Escaladora de peldaños (StepMill) trabaja principalmente sistema cardiovascular, con participación de glúteos, cuádriceps, pantorrillas. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para calentamiento, acondicionamiento y trabajo por intervalos ajustable al nivel.","instrucciones":"[\"Preparación de la escaladora: localiza inicio/parada y freno de emergencia, sube con los escalones detenidos y toma las barras. Selecciona el nivel más bajo y empieza solo cuando ambos pies estén centrados.\",\"Posición inicial: cuerpo alto, mirada al frente, cuello neutro, hombros bajos y manos ligeras. Mantén abdomen y pelvis estables, rodillas alineadas y todo el pie posible sobre cada escalón.\",\"Ejecución: pisa de forma alterna y deja que cada escalón descienda con control; empuja principalmente con la pierna, no con los brazos. Evita saltar escalones antes de dominar el ritmo.\",\"Biomecánica: cadera y rodilla flexionan/extienden mientras el tronco permanece estable. Debes sentir cuádriceps, glúteos y pantorrillas, no presión de muñecas por colgarte del pasamanos.\",\"Intensidad: aumenta un nivel cada vez y mantén una cadencia que permita apoyar el pie y conservar la altura del tronco. No persigas velocidad si obliga a acortar pasos o inclinarte sobre la consola.\",\"Respiración: continua y rítmica; exhala durante los pasos más exigentes. Reduce el nivel si aparece mareo, tropiezos o necesidad de sujetarte con fuerza.\",\"Errores a corregir: caminar de puntas, rodillas hacia dentro, hombros elevados, peso sobre los brazos, mirar los pies, pasos demasiado rápidos y subir de lado sin dominio.\",\"Finalización: reduce nivel, espera que los escalones se detengan, sujétate y baja usando el peldaño indicado. No saltes ni desmontes mientras se mueve.\"]","cues_tecnicos":"[\"Postura alta\",\"Respiración rítmica\",\"Pies centrados\",\"Rodillas alineadas\",\"Hombros relajados\",\"Aumenta gradualmente\",\"Técnica antes que velocidad\",\"Enfría al terminar\",\"Pie completo\",\"Cadera estable\"]","errores_comunes":"[\"Empezar demasiado rápido\",\"Colgarse de las barras\",\"Rodillas desalineadas\",\"Mirar al suelo\",\"Hombros tensos\",\"Contener la respiración\",\"Omitir calentamiento/enfriamiento\",\"Bajar antes de detener la máquina\",\"Apoyarse sobre los brazos\",\"Pisar solo con la punta\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Detener la actividad si sientes mareo o dolor en rodillas\",\"Consultar si hay lesiones de rodilla o tobillo\"]","sustituciones":"[\"Caminadora inclinada\",\"Elíptica\",\"Subir escaleras reales\",\"Bicicleta estática\",\"Caminata a ritmo cómodo\"]","progresiones":"[\"Aumentar ritmo\",\"Aumentar duración\",\"Agregar intervalos\",\"Aumentar duración 5–10 % manteniendo técnica\",\"Añadir intervalos de trabajo/recuperación\",\"Subir una sola variable: ritmo, resistencia o pendiente\"]","regresiones":"[\"Disminuir ritmo\",\"Reducir duración\",\"Usar intervalos más cortos\",\"Reducir ritmo/resistencia\",\"Acortar los intervalos de trabajo\",\"Usar una modalidad de menor impacto\"]","lugar":"gimnasio","objetivo":"cardio","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"","rango_reps_max":"","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"","duracion_promedio_segundos":"600","maquina_gym":"Stair Climber / StepMill","estado_calidad":"curado"},{"action":"update","id":"74","nombre":"Remo ergómetro","aliases":"[\"Remo ergómetro\",\"máquina de remo\",\"remo indoor\",\"rowing ergometer\",\"rowing machine\",\"row erg\",\"RowErg\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"cardio","musculo_principal":"sistema cardiovascular","musculos_secundarios":"[\"dorsal ancho\",\"piernas\",\"gluteos\",\"core\"]","equipamiento":"remo ergómetro","equipo_requerido":"[\"remo ergómetro\"]","tipo_entrenamiento":"cardio","patron_movimiento":"locomocion/cardio","descripcion":"Remo ergómetro trabaja principalmente sistema cardiovascular, con participación de dorsal ancho, piernas, gluteos. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para calentamiento, acondicionamiento y trabajo por intervalos ajustable al nivel.","instrucciones":"[\"Preparación del remo ergómetro: fija ambos pies con la correa sobre la zona más ancha, ajusta el monitor y revisa cadena/maneral. En RowErg empieza con damper 3–5; el damper cambia la sensación, no equivale directamente a intensidad.\",\"Posición de captura: tibias casi verticales, talones pueden elevarse ligeramente, cadera flexionada, espalda larga, cabeza/cuello neutros y hombros bajos. Brazos rectos, muñecas planas y agarre prono relajado.\",\"Impulso: empuja primero con las piernas; cuando las rodillas casi se extiendan, abre la cadera y finalmente lleva el maneral a las costillas bajas. No tires temprano con brazos ni arquees la zona lumbar.\",\"Final: piernas extendidas sin bloquear, torso apenas inclinado atrás, abdomen firme, codos detrás y maneral bajo el pecho. Siente piernas y espalda, no tensión de cuello o antebrazos.\",\"Recuperación: extiende brazos, inclina el torso desde la cadera y solo después flexiona rodillas para deslizarte. Mantén la cadena nivelada y una recuperación más lenta que el impulso.\",\"Ritmo y respiración: empieza alrededor de 18–24 remadas/min para aprender; exhala durante el impulso e inhala en la recuperación. Aumenta potencia con las piernas antes que subir el damper.\",\"Errores a corregir: damper al 10 por defecto, encorvarse, abrir rodillas, cadena ondulante, doblar rodillas antes de que pasen las manos, tirón de brazos temprano y retorno precipitado.\",\"Finalización y seguridad: rema suave 2–5 min, detén el volante, deja el maneral en su soporte y afloja correas antes de levantarte. No sueltes el maneral con la cadena extendida.\"]","cues_tecnicos":"[\"Postura alta\",\"Respiración rítmica\",\"Pies centrados\",\"Rodillas alineadas\",\"Hombros relajados\",\"Aumenta gradualmente\",\"Técnica antes que velocidad\",\"Enfría al terminar\",\"Piernas antes que brazos\",\"Mango a costillas bajas\"]","errores_comunes":"[\"Empezar demasiado rápido\",\"Colgarse de las barras\",\"Rodillas desalineadas\",\"Mirar al suelo\",\"Hombros tensos\",\"Contener la respiración\",\"Omitir calentamiento/enfriamiento\",\"Bajar antes de detener la máquina\",\"Jalar primero con brazos\",\"Redondear la zona lumbar\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Detener si hay mareo, dolor toracico o falta de aire inusual\",\"Reducir intensidad si aparece dolor lumbar\"]","sustituciones":"[\"Elíptica\",\"Ciclismo\",\"Saltar cuerda\",\"Sprints\",\"Bicicleta estática\",\"Caminata a ritmo cómodo\"]","progresiones":"[\"Aumentar duracion\",\"Agregar intervalos\",\"Subir resistencia gradualmente\",\"Aumentar duración 5–10 % manteniendo técnica\",\"Añadir intervalos de trabajo/recuperación\",\"Subir una sola variable: ritmo, resistencia o pendiente\"]","regresiones":"[\"Reducir duracion\",\"Bajar resistencia\",\"Usar ritmo continuo suave\",\"Reducir ritmo/resistencia\",\"Acortar los intervalos de trabajo\",\"Usar una modalidad de menor impacto\"]","lugar":"gimnasio","objetivo":"cardio","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"","rango_reps_max":"","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"","duracion_promedio_segundos":"1200","maquina_gym":"Concept2 RowErg / Rowing Ergometer","estado_calidad":"curado"},{"action":"update","id":"75","nombre":"Ciclismo al aire libre","aliases":"[\"Ciclismo al aire libre\",\"cycling\",\"bicicleta estática\",\"bike\",\"Outdoor cycling\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"cardio","musculo_principal":"sistema cardiovascular","musculos_secundarios":"[\"cuádriceps\",\"glúteos\",\"pantorrillas\"]","equipamiento":"bicicleta de ruta o montaña","equipo_requerido":"[\"bicicleta\",\"casco\",\"luces o reflectantes\",\"kit básico de reparación\"]","tipo_entrenamiento":"cardio","patron_movimiento":"locomoción/cardio","descripcion":"Ciclismo al aire libre trabaja principalmente sistema cardiovascular, con participación de cuádriceps, glúteos, pantorrillas. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para calentamiento, acondicionamiento y trabajo por intervalos ajustable al nivel.","instrucciones":"[\"Preparación de la bicicleta: ajusta el sillín para una ligera flexión de rodilla con el pedal abajo, revisa frenos, neumáticos, cadena y cierre de ruedas. Usa casco, luces/reflectantes y una ruta acorde a tu experiencia.\",\"Posición inicial: pies estables en pedales, rodillas siguiendo la línea de los pies, pelvis nivelada y espalda larga. Mantén cabeza/cuello neutros, hombros bajos, codos suaves, manos ligeras y muñecas rectas.\",\"Inicio: pedalea 5–10 min en una marcha fácil antes de aumentar ritmo o pendiente. Cambia de marcha antes de que la cadencia se vuelva pesada; no cruces la cadena en combinaciones extremas.\",\"Ejecución y biomecánica: aplica fuerza de manera fluida durante el ciclo y evita balancear la pelvis. Debes sentir cuádriceps y glúteos; rodillas no se abren/cierran de forma marcada y el tronco permanece estable.\",\"Intensidad: usa una cadencia sostenible y aumenta primero duración o terreno de forma gradual. En intervalos, recupera en una marcha fácil sin perder control de la bicicleta.\",\"Respiración y entorno: respira rítmicamente, mira lejos y anticipa tráfico, curvas, superficie y frenadas. No uses auriculares que bloqueen señales ni consultes la pantalla mientras circulas.\",\"Errores a corregir: sillín demasiado bajo/alto, rodillas desalineadas, hombros tensos, agarre rígido, marcha excesivamente pesada, sobrepasar visibilidad disponible y omitir hidratación.\",\"Finalización y seguridad: pedalea suave 5 min, frena progresivamente en línea recta, desengancha un pie antes de detenerte y baja en zona segura. Revisa la bicicleta si hubo golpe, ruido o fallo de cambio.\"]","cues_tecnicos":"[\"Postura alta\",\"Respiración rítmica\",\"Pies centrados\",\"Rodillas alineadas\",\"Hombros relajados\",\"Aumenta gradualmente\",\"Técnica antes que velocidad\",\"Enfría al terminar\",\"Mantén una intensidad sostenible\",\"Respira de forma constante\"]","errores_comunes":"[\"Empezar demasiado rápido\",\"Colgarse de las barras\",\"Rodillas desalineadas\",\"Mirar al suelo\",\"Hombros tensos\",\"Contener la respiración\",\"Omitir calentamiento/enfriamiento\",\"Bajar antes de detener la máquina\",\"Empezar demasiado fuerte\",\"Perder técnica por fatiga\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Reducir intensidad si aparece mareo, dolor torácico o falta de aire inusual\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Elíptica\",\"Remo en máquina\",\"Saltar cuerda\",\"Bicicleta estática\",\"Caminata a ritmo cómodo\"]","progresiones":"[\"Aumentar duración\",\"Aumentar ritmo gradualmente\",\"Agregar intervalos controlados\",\"Aumentar duración 5–10 % manteniendo técnica\",\"Añadir intervalos de trabajo/recuperación\",\"Subir una sola variable: ritmo, resistencia o pendiente\"]","regresiones":"[\"Reducir duración\",\"Bajar ritmo\",\"Usar intervalos más cortos\",\"Reducir ritmo/resistencia\",\"Acortar los intervalos de trabajo\",\"Usar una modalidad de menor impacto\"]","lugar":"exterior","objetivo":"cardio","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"","rango_reps_max":"","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"","duracion_promedio_segundos":"1800","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"76","nombre":"Elíptica","aliases":"[\"Elíptica\",\"máquina elíptica\",\"bicicleta elíptica\",\"elliptical trainer\",\"cross trainer\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"cardio","musculo_principal":"sistema cardiovascular","musculos_secundarios":"[\"cuádriceps\",\"glúteos\",\"pantorrillas\",\"hombros\"]","equipamiento":"máquina elíptica","equipo_requerido":"[\"máquina elíptica\"]","tipo_entrenamiento":"cardio","patron_movimiento":"locomoción/cardio","descripcion":"Elíptica trabaja principalmente sistema cardiovascular, con participación de cuádriceps, glúteos, pantorrillas. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para calentamiento, acondicionamiento y trabajo por intervalos ajustable al nivel.","instrucciones":"[\"Preparación de la elíptica: sube con pedales detenidos sujetando asas fijas, coloca pies centrados y localiza parada. Ajusta resistencia e inclinación en nivel bajo; usa asas móviles solo si puedes coordinarlas.\",\"Posición inicial: pies completos, rodillas alineadas, cadera nivelada, abdomen firme y torso alto. Mantén cabeza/cuello neutros, pecho relajado, hombros bajos y muñecas rectas.\",\"Ejecución: impulsa los pedales en óvalos fluidos y, si usas asas, empuja/tira de forma alterna sin rotar el tronco. Distribuye presión en todo el pie y evita rebotar.\",\"Biomecánica: cadera, rodilla y tobillo se mueven de forma continua; pelvis, columna y cabeza permanecen estables. Debes sentir piernas y, con asas, espalda/brazos de forma secundaria.\",\"Intensidad: aumenta resistencia o inclinación de una en una. Pedalear hacia atrás es una variante, no una técnica básica; úsala solo a baja resistencia y con control.\",\"Respiración: continua y rítmica; reduce nivel si necesitas sostenerte, se elevan hombros o aparece mareo. No contengas el aire.\",\"Errores a corregir: despegar talones, rodillas hacia dentro, pasos demasiado cortos, colgarse de las asas, inclinarse sobre consola y resistencia que detiene la fluidez.\",\"Finalización: baja resistencia y ritmo 2–5 min, detente por completo, sujeta asas fijas y baja primero con un pie. No desmontes con pedales en movimiento.\"]","cues_tecnicos":"[\"Postura alta\",\"Respiración rítmica\",\"Pies centrados\",\"Rodillas alineadas\",\"Hombros relajados\",\"Aumenta gradualmente\",\"Técnica antes que velocidad\",\"Enfría al terminar\",\"Pies completos\",\"Torso estable\"]","errores_comunes":"[\"Empezar demasiado rápido\",\"Colgarse de las barras\",\"Rodillas desalineadas\",\"Mirar al suelo\",\"Hombros tensos\",\"Contener la respiración\",\"Omitir calentamiento/enfriamiento\",\"Bajar antes de detener la máquina\",\"Cargar el peso en los brazos\",\"Levantar los talones\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Reducir intensidad si aparece mareo, dolor torácico o falta de aire inusual\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Ciclismo\",\"Remo en máquina\",\"Saltar cuerda\",\"Bicicleta estática\",\"Elíptica\",\"Caminata a ritmo cómodo\"]","progresiones":"[\"Aumentar duración\",\"Aumentar ritmo gradualmente\",\"Agregar intervalos controlados\",\"Aumentar duración 5–10 % manteniendo técnica\",\"Añadir intervalos de trabajo/recuperación\",\"Subir una sola variable: ritmo, resistencia o pendiente\"]","regresiones":"[\"Reducir duración\",\"Bajar ritmo\",\"Usar intervalos más cortos\",\"Reducir ritmo/resistencia\",\"Acortar los intervalos de trabajo\",\"Usar una modalidad de menor impacto\"]","lugar":"gimnasio","objetivo":"cardio","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"","rango_reps_max":"","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"","duracion_promedio_segundos":"1500","maquina_gym":"Elliptical Trainer","estado_calidad":"curado"},{"action":"update","id":"77","nombre":"Natación estilo libre (crol)","aliases":"[\"Natación estilo libre (crol)\",\"swimming\",\"nado libre\",\"front crawl\",\"freestyle swimming\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"cardio","musculo_principal":"sistema cardiovascular","musculos_secundarios":"[\"dorsal ancho\",\"hombros\",\"core\",\"piernas\"]","equipamiento":"piscina o zona de nado supervisada","equipo_requerido":"[\"piscina o zona autorizada\",\"gafas de natación opcionales\"]","tipo_entrenamiento":"cardio","patron_movimiento":"locomoción/cardio","descripcion":"Natación estilo libre (crol) trabaja principalmente sistema cardiovascular, con participación de dorsal ancho, hombros, core. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para calentamiento, acondicionamiento y trabajo por intervalos ajustable al nivel.","instrucciones":"[\"Preparación en piscina: nada solo en una instalación supervisada o zona autorizada, conoce profundidad y reglas del carril y realiza entrada segura. Usa gafas si ayudan y comienza con 5–10 min suaves; no bucees en agua poco profunda.\",\"Posición inicial del crol: cuerpo largo cerca de la superficie, mirada hacia el fondo, cuello neutro y abdomen activo. Mantén piernas extendidas con rodillas suaves, pies relajados y hombros libres para rotar.\",\"Brazada: entra con la mano delante del hombro, alarga sin cruzar la línea media y tracciona el agua hacia atrás con codo alto cómodo. Termina junto a la cadera y recupera el brazo relajado por fuera.\",\"Patada y rotación: patea desde la cadera con amplitud pequeña y tobillos relajados; rota hombros y pelvis como una unidad. Debes sentir dorsal, hombros y core, no tensión cervical por levantar la cabeza.\",\"Respiración: gira la cabeza con el cuerpo y deja una gafa en el agua; exhala continuamente bajo el agua e inhala rápido de lado. No aguantes el aire ni levantes la frente.\",\"Ritmo y rango: prioriza brazadas largas y consistentes sobre velocidad. Detén el largo si pierdes coordinación, tragas agua o el hombro duele; usa tabla o intervalos cortos para practicar una parte.\",\"Errores a corregir: cruzar manos frente a la cabeza, codo caído, patada desde rodillas, cabeza alta, contener la respiración, brazada asimétrica y entrenar solo sin vigilancia.\",\"Finalización y seguridad: nada suave 3–5 min, llega a la pared con control y sal por escalera o borde autorizado. Interrumpe de inmediato ante calambre intenso, mareo, falta de aire inusual o pérdida de orientación.\"]","cues_tecnicos":"[\"Postura alta\",\"Respiración rítmica\",\"Pies centrados\",\"Rodillas alineadas\",\"Hombros relajados\",\"Aumenta gradualmente\",\"Técnica antes que velocidad\",\"Enfría al terminar\",\"Mantén una intensidad sostenible\",\"Respira de forma constante\"]","errores_comunes":"[\"Empezar demasiado rápido\",\"Colgarse de las barras\",\"Rodillas desalineadas\",\"Mirar al suelo\",\"Hombros tensos\",\"Contener la respiración\",\"Omitir calentamiento/enfriamiento\",\"Bajar antes de detener la máquina\",\"Empezar demasiado fuerte\",\"Perder técnica por fatiga\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Reducir intensidad si aparece mareo, dolor torácico o falta de aire inusual\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Elíptica\",\"Ciclismo\",\"Remo en máquina\",\"Saltar cuerda\",\"Bicicleta estática\",\"Caminata a ritmo cómodo\"]","progresiones":"[\"Aumentar duración\",\"Aumentar ritmo gradualmente\",\"Agregar intervalos controlados\",\"Aumentar duración 5–10 % manteniendo técnica\",\"Añadir intervalos de trabajo/recuperación\",\"Subir una sola variable: ritmo, resistencia o pendiente\"]","regresiones":"[\"Reducir duración\",\"Bajar ritmo\",\"Usar intervalos más cortos\",\"Reducir ritmo/resistencia\",\"Acortar los intervalos de trabajo\",\"Usar una modalidad de menor impacto\"]","lugar":"piscina","objetivo":"cardio","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"","rango_reps_max":"","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"","duracion_promedio_segundos":"1800","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"73","nombre":"Salto de cuerda","aliases":"[\"Salto de cuerda\",\"jump rope\",\"cuerda\",\"comba\",\"skipping rope\",\"rope skipping\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"cardio","musculo_principal":"sistema cardiovascular","musculos_secundarios":"[\"pantorrillas\",\"hombros\",\"core\"]","equipamiento":"cuerda","equipo_requerido":"[\"cuerda\"]","tipo_entrenamiento":"cardio","patron_movimiento":"locomoción/cardio","descripcion":"Salto de cuerda trabaja principalmente sistema cardiovascular, con participación de pantorrillas, hombros, core. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para calentamiento, acondicionamiento y trabajo por intervalos ajustable al nivel.","instrucciones":"[\"Preparación: ajusta la cuerda pisando el centro; las asas deberían llegar aproximadamente a axilas/pecho según estilo. Usa piso con ligera absorción, calzado estable, techo alto y un radio libre de personas/objetos.\",\"Posición inicial: pies juntos o alternos, rodillas suaves, pelvis y abdomen firmes, torso alto y mirada al frente. Mantén hombros bajos, codos cerca de costillas, manos a la altura de caderas y muñecas neutras.\",\"Ejecución: gira la cuerda principalmente con muñecas y realiza saltos bajos desde metatarsos; aterriza silencioso y vuelve a despegar sin hundir talones bruscamente. La cuerda pasa bajo los pies, no el cuerpo sobre ella.\",\"Biomecánica: tobillos producen la mayor parte del rebote mientras rodillas/caderas amortiguan; tronco y cabeza permanecen estables. Debes sentir pantorrillas y ritmo cardiovascular, no golpes articulares.\",\"Rango y ritmo: despega solo lo necesario para librar la cuerda; empieza con bloques de 10–30 s y descansos. Domina saltos simples antes de dobles o cruces.\",\"Respiración: continua y rítmica, exhalando cada varios saltos. Reduce ritmo si encoges hombros, aterrizas pesado o no puedes mantener postura.\",\"Errores a corregir: cuerda demasiado larga/corta, girar brazos completos, saltar demasiado alto, aterrizar con rodillas rígidas, mirar los pies y continuar cuando se pierde el ritmo.\",\"Finalización y seguridad: reduce velocidad, detén la cuerda a un lado y camina hasta normalizar respiración. No dejes la cuerda atravesando una zona de paso y evita sesiones de alto impacto si no toleras aterrizajes básicos.\"]","cues_tecnicos":"[\"Postura alta\",\"Respiración rítmica\",\"Pies centrados\",\"Rodillas alineadas\",\"Hombros relajados\",\"Aumenta gradualmente\",\"Técnica antes que velocidad\",\"Enfría al terminar\",\"Mantén una intensidad sostenible\",\"Respira de forma constante\"]","errores_comunes":"[\"Empezar demasiado rápido\",\"Colgarse de las barras\",\"Rodillas desalineadas\",\"Mirar al suelo\",\"Hombros tensos\",\"Contener la respiración\",\"Omitir calentamiento/enfriamiento\",\"Bajar antes de detener la máquina\",\"Empezar demasiado fuerte\",\"Perder técnica por fatiga\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Ten precaución con alto impacto si aún no puedes aterrizar o desacelerar sin dolor ni pérdida de alineación\",\"Reducir intensidad si aparece mareo, dolor torácico o falta de aire inusual\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Elíptica\",\"Ciclismo\",\"Remo en máquina\",\"Bicicleta estática\",\"Caminata a ritmo cómodo\"]","progresiones":"[\"Aumentar duración\",\"Aumentar ritmo gradualmente\",\"Agregar intervalos controlados\",\"Aumentar duración 5–10 % manteniendo técnica\",\"Añadir intervalos de trabajo/recuperación\",\"Subir una sola variable: ritmo, resistencia o pendiente\"]","regresiones":"[\"Reducir duración\",\"Bajar ritmo\",\"Usar intervalos más cortos\",\"Reducir ritmo/resistencia\",\"Acortar los intervalos de trabajo\",\"Usar una modalidad de menor impacto\"]","lugar":"cualquiera","objetivo":"cardio","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"","rango_reps_max":"","descanso_segundos_min":"30","descanso_segundos_max":"90","rir_recomendado":"","duracion_promedio_segundos":"600","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"72","nombre":"Sprints de carrera","aliases":"[\"Sprints de carrera\",\"sprints\",\"carreras de velocidad\",\"Running sprints\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"cardio","musculo_principal":"sistema cardiovascular","musculos_secundarios":"[\"glúteos\",\"isquiosurales\",\"cuádriceps\",\"pantorrillas\"]","equipamiento":"pista o espacio abierto","equipo_requerido":"[\"pista o espacio abierto\"]","tipo_entrenamiento":"cardio intervalo","patron_movimiento":"locomoción/cardio","descripcion":"Sprints de carrera trabaja principalmente sistema cardiovascular, con participación de glúteos, isquiosurales, cuádriceps. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para calentamiento, acondicionamiento y trabajo por intervalos ajustable al nivel.","instrucciones":"[\"Preparación: usa pista o superficie uniforme y despejada, calzado con tracción y una distancia con zona suficiente para acelerar y frenar. Realiza 10–15 min de calentamiento, movilidad dinámica y varias aceleraciones submáximas.\",\"Posición inicial: postura alta o salida escalonada según experiencia, pies orientados al frente, rodillas suaves, pelvis neutra y abdomen firme. Cabeza/cuello siguen el torso, hombros relajados y codos cerca de 90°.\",\"Aceleración: inclina el cuerpo como bloque desde tobillos, impulsa el suelo hacia atrás y aumenta la longitud de zancada gradualmente. Los brazos avanzan/retroceden sin cruzar excesivamente el pecho.\",\"Velocidad: al elevarte, apoya el pie cerca de debajo de la cadera y mantén pasos rápidos y relajados. Debes sentir glúteos, isquios y pantorrillas, no tirones ni frenado delante del cuerpo.\",\"Rango y dosificación: usa 10–30 m o 5–10 s al principio, con recuperación casi completa; la calidad manda. No hagas sprints máximos fatigado ni aumentes distancia y repeticiones a la vez.\",\"Respiración: no la contengas; exhala durante la aceleración y respira libre al alcanzar velocidad. Recupera caminando hasta poder repetir con técnica.\",\"Errores a corregir: empezar sin calentar, sobrezancada, hombros/mandíbula tensos, taloneo muy delante, tronco que se dobla en cadera y frenada brusca al cruzar la meta.\",\"Finalización y seguridad: desacelera durante varios pasos sin detenerte en seco, camina y realiza vuelta a la calma. Termina la sesión ante dolor súbito, tirón, mareo o pérdida de coordinación.\"]","cues_tecnicos":"[\"Postura alta\",\"Respiración rítmica\",\"Pies centrados\",\"Rodillas alineadas\",\"Hombros relajados\",\"Aumenta gradualmente\",\"Técnica antes que velocidad\",\"Enfría al terminar\",\"Mantén una intensidad sostenible\",\"Respira de forma constante\"]","errores_comunes":"[\"Empezar demasiado rápido\",\"Colgarse de las barras\",\"Rodillas desalineadas\",\"Mirar al suelo\",\"Hombros tensos\",\"Contener la respiración\",\"Omitir calentamiento/enfriamiento\",\"Bajar antes de detener la máquina\",\"Empezar demasiado fuerte\",\"Perder técnica por fatiga\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Ten precaución con alto impacto si aún no puedes aterrizar o desacelerar sin dolor ni pérdida de alineación\",\"Reducir intensidad si aparece mareo, dolor torácico o falta de aire inusual\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Elíptica\",\"Ciclismo\",\"Remo en máquina\",\"Saltar cuerda\",\"Bicicleta estática\",\"Caminata a ritmo cómodo\"]","progresiones":"[\"Aumentar duración\",\"Aumentar ritmo gradualmente\",\"Agregar intervalos controlados\",\"Aumentar duración 5–10 % manteniendo técnica\",\"Añadir intervalos de trabajo/recuperación\",\"Subir una sola variable: ritmo, resistencia o pendiente\"]","regresiones":"[\"Reducir duración\",\"Bajar ritmo\",\"Usar intervalos más cortos\",\"Reducir ritmo/resistencia\",\"Acortar los intervalos de trabajo\",\"Usar una modalidad de menor impacto\"]","lugar":"exterior","objetivo":"cardio","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"","rango_reps_max":"","descanso_segundos_min":"90","descanso_segundos_max":"180","rir_recomendado":"","duracion_promedio_segundos":"20","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"18","nombre":"Plancha abdominal","aliases":"[\"Plancha abdominal\",\"plank\",\"plancha\",\"Front plank\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"core","musculo_principal":"core","musculos_secundarios":"[\"recto abdominal\",\"transverso abdominal\",\"glúteos\",\"hombros\"]","equipamiento":"peso corporal","equipo_requerido":"[\"peso corporal\"]","tipo_entrenamiento":"core","patron_movimiento":"core anti-extensión","descripcion":"Plancha abdominal trabaja principalmente core, con participación de recto abdominal, transverso abdominal, glúteos. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: usa una superficie plana, antideslizante y con espacio para todo el cuerpo. Coloca colchoneta si mejora comodidad, retira objetos cercanos y elige una inclinación o palanca que puedas sostener sin perder alineación desde la primera repetición.\",\"Posición inicial: antebrazos paralelos, codos bajo hombros, manos relajadas, pies al ancho de caderas y piernas extendidas. Aprieta glúteos y abdomen para alinear orejas, hombros, cadera y tobillos; mira al suelo, cuello largo, pecho separado del piso y escápulas activas.\",\"Apoyo/agarre: manos completas, dedos separados y muñecas alineadas bajo el soporte cuando estén en el suelo; en barra/anillas usa agarre cerrado con pulgar. Ajusta el ángulo o usa asas si la extensión de muñeca no es tolerable.\",\"Inicio y trayectoria: Empuja antebrazos y puntas de pies contra el suelo mientras acercas costillas y pelvis sin contener la respiración. Siente toda la pared abdominal y glúteos; hombros y columna sostienen una línea estable.\",\"Rango y biomecánica: Mantén la alineación solo mientras puedas respirar y evitar cadera caída, glúteos elevados o dolor lumbar. Termina antes de que el temblor cambie la postura; no persigas tiempo con técnica rota.\",\"Tempo y respiración: Isometría de 10–60 s según nivel, respirando corto y continuo. Exhala de forma lenta sin perder el brace; descansa por completo entre series.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Costillas sobre pelvis\",\"Respira detrás del brace\",\"Cuello largo\",\"Pelvis controlada\",\"Hombros activos\",\"Sin arco lumbar\",\"Calidad antes que tiempo\",\"Recorta palanca si cedes\",\"Activa abdomen antes de iniciar\",\"Mantén columna neutra\"]","errores_comunes":"[\"Arquear la zona lumbar\",\"Tirar del cuello\",\"Contener la respiración\",\"Moverse demasiado rápido\",\"Usar impulso de piernas\",\"Colapsar hombros\",\"Perder posición pélvica\",\"Continuar tras fallar la postura\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Abdominales Bicicleta (Bicycle Crunches)\",\"Abdominales Crunch\",\"Bird Dog (Perro-Pájaro)\",\"Crunch en Polea (Cable Crunch)\",\"Dead bug\",\"Plancha con manos elevadas\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"cualquiera","objetivo":"general","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"","rango_reps_max":"","descanso_segundos_min":"30","descanso_segundos_max":"60","rir_recomendado":"","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"62","nombre":"L-sit","aliases":"[\"L-sit\",\"l sit\",\"L-sit hold\",\"escuadra en paralelas\",\"L-sit en paralelas\",\"LS hold\"]","nivel":"avanzado","nivel_minimo":"avanzado","grupo_muscular":"core","musculo_principal":"core","musculos_secundarios":"[\"flexores de cadera\",\"tríceps\",\"hombros\"]","equipamiento":"paralelas o suelo","equipo_requerido":"[\"paralelas o suelo\"]","tipo_entrenamiento":"core","patron_movimiento":"core isométrico","descripcion":"L-sit trabaja principalmente core, con participación de flexores de cadera, tríceps, hombros. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: usa paralelas o barras de fondos firmes, secas y con espacio para las piernas. Coloca un banco bajo solo para entrar/salir y practica primero el apoyo con rodillas recogidas; evita soportes inestables o demasiado separados.\",\"Posición inicial: manos sobre paralelas junto a caderas, pulgar cerrado, muñecas neutras y codos extendidos sin hiperextender. Deprime hombros, eleva el pecho, junta piernas, apunta pies y lleva pelvis ligeramente atrás; cabeza/cuello neutros y abdomen firme.\",\"Apoyo/agarre: manos completas, dedos separados y muñecas alineadas bajo el soporte cuando estén en el suelo; en barra/anillas usa agarre cerrado con pulgar. Ajusta el ángulo o usa asas si la extensión de muñeca no es tolerable.\",\"Inicio y trayectoria: Empuja las paralelas hacia abajo, eleva la pelvis y extiende las piernas al frente hasta formar una L. Siente abdomen, flexores de cadera, tríceps y depresores escapulares; no cuelgues los hombros.\",\"Rango y biomecánica: Sostén muslos aproximadamente paralelos al suelo o usa rodillas flexionadas; termina cuando codos se doblen, hombros suban o la pelvis caiga. Baja pies con control antes de soltar.\",\"Tempo y respiración: Isometría de 5–30 s con respiraciones breves y continuas. Exhala al elevarte e inhala sin perder la depresión escapular.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: flexiona rodillas, baja pies al banco o suelo y mantén presión sobre las paralelas hasta estar estable; después suelta una mano a la vez. No saltes desde el apoyo ni continúes si hombros suben hacia orejas.\"]","cues_tecnicos":"[\"Costillas sobre pelvis\",\"Respira detrás del brace\",\"Cuello largo\",\"Pelvis controlada\",\"Hombros activos\",\"Sin arco lumbar\",\"Calidad antes que tiempo\",\"Recorta palanca si cedes\",\"Activa abdomen antes de iniciar\",\"Mantén columna neutra\"]","errores_comunes":"[\"Arquear la zona lumbar\",\"Tirar del cuello\",\"Contener la respiración\",\"Moverse demasiado rápido\",\"Usar impulso de piernas\",\"Colapsar hombros\",\"Perder posición pélvica\",\"Continuar tras fallar la postura\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Abdominales Bicicleta (Bicycle Crunches)\",\"Abdominales Crunch\",\"Bird Dog (Perro-Pájaro)\",\"Crunch en Polea (Cable Crunch)\",\"Dead bug\",\"Plancha con manos elevadas\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"habilidad","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"","rango_reps_max":"","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"","duracion_promedio_segundos":"20","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"29","nombre":"Escaladores de montaña","aliases":"[\"Escaladores de montaña\",\"mountain climbers\",\"escalador\",\"climbers\",\"MC\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"core","musculo_principal":"core","musculos_secundarios":"[\"hombros\",\"flexores de cadera\",\"cuádriceps\"]","equipamiento":"peso corporal","equipo_requerido":"[\"peso corporal\"]","tipo_entrenamiento":"cardio","patron_movimiento":"locomoción/cardio","descripcion":"Escaladores de montaña trabaja principalmente core, con participación de hombros, flexores de cadera, cuádriceps. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: usa una superficie plana, antideslizante y con espacio para todo el cuerpo. Coloca colchoneta si mejora comodidad, retira objetos cercanos y elige una inclinación o palanca que puedas sostener sin perder alineación desde la primera repetición.\",\"Posición inicial: manos debajo de hombros, dedos abiertos, brazos largos, pies sobre metatarsos y piernas extendidas. Mantén cabeza, columna y pelvis alineadas, hombros activos, pecho separado del suelo y abdomen firme antes de mover una rodilla.\",\"Apoyo/agarre: manos completas, dedos separados y muñecas alineadas bajo el soporte cuando estén en el suelo; en barra/anillas usa agarre cerrado con pulgar. Ajusta el ángulo o usa asas si la extensión de muñeca no es tolerable.\",\"Inicio y trayectoria: Lleva una rodilla hacia el pecho sin elevar ni rotar la pelvis y cambia de pierna como una carrera en plancha. Siente abdomen, hombros y flexores de cadera; las manos empujan el suelo.\",\"Rango y biomecánica: Acerca la rodilla solo hasta mantener espalda y pelvis neutras; extiende por completo la pierna de regreso sin rebotar. Reduce velocidad antes que acortar la plancha.\",\"Tempo y respiración: Alterna a ritmo controlado o rápido solo con alineación. Exhala al acercar cada rodilla e inhala durante los cambios sin contener el aire.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Costillas sobre pelvis\",\"Respira detrás del brace\",\"Cuello largo\",\"Pelvis controlada\",\"Hombros activos\",\"Sin arco lumbar\",\"Calidad antes que tiempo\",\"Recorta palanca si cedes\",\"Mantén una intensidad sostenible\",\"Respira de forma constante\"]","errores_comunes":"[\"Arquear la zona lumbar\",\"Tirar del cuello\",\"Contener la respiración\",\"Moverse demasiado rápido\",\"Usar impulso de piernas\",\"Colapsar hombros\",\"Perder posición pélvica\",\"Continuar tras fallar la postura\",\"Empezar demasiado fuerte\",\"Perder técnica por fatiga\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Reducir intensidad si aparece mareo, dolor torácico o falta de aire inusual\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Elíptica\",\"Ciclismo\",\"Remo en máquina\",\"Saltar cuerda\",\"Dead bug\",\"Plancha con manos elevadas\"]","progresiones":"[\"Aumentar duración\",\"Aumentar ritmo gradualmente\",\"Agregar intervalos controlados\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir duración\",\"Bajar ritmo\",\"Usar intervalos más cortos\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"cualquiera","objetivo":"resistencia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"","rango_reps_max":"","descanso_segundos_min":"30","descanso_segundos_max":"60","rir_recomendado":"","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"19","nombre":"Plancha lateral","aliases":"[\"Plancha lateral\",\"side plank\",\"plancha de costado\",\"plank lateral\",\"side plank hold\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"core","musculo_principal":"oblicuos","musculos_secundarios":"[\"transverso abdominal\",\"glúteo medio\",\"hombros\"]","equipamiento":"peso corporal","equipo_requerido":"[\"peso corporal\"]","tipo_entrenamiento":"core","patron_movimiento":"core anti-flexión lateral","descripcion":"Plancha lateral trabaja principalmente oblicuos, con participación de transverso abdominal, glúteo medio, hombros. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: usa una superficie plana, antideslizante y con espacio para todo el cuerpo. Coloca colchoneta si mejora comodidad, retira objetos cercanos y elige una inclinación o palanca que puedas sostener sin perder alineación desde la primera repetición.\",\"Posición inicial: codo debajo del hombro, antebrazo perpendicular al cuerpo y pies apilados o escalonados. Eleva cadera hasta alinear cabeza, hombros, pelvis, rodillas y tobillos; pecho abierto, cuello largo y mano libre sobre cadera o extendida.\",\"Apoyo/agarre: manos completas, dedos separados y muñecas alineadas bajo el soporte cuando estén en el suelo; en barra/anillas usa agarre cerrado con pulgar. Ajusta el ángulo o usa asas si la extensión de muñeca no es tolerable.\",\"Inicio y trayectoria: Empuja el antebrazo contra el suelo y eleva la cadera; resiste que el tronco rote o caiga. Siente oblicuos y glúteo medio del lado inferior, no presión aguda en el hombro.\",\"Rango y biomecánica: Mantén una línea recta solo mientras hombro, pelvis y pies conserven su posición. Termina antes de que la cadera caiga o el torso gire; baja lentamente y cambia de lado.\",\"Tempo y respiración: Isometría de 10–45 s por lado con respiración continua. Exhala largo manteniendo costillas y pelvis apiladas.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Costillas sobre pelvis\",\"Respira detrás del brace\",\"Cuello largo\",\"Pelvis controlada\",\"Hombros activos\",\"Sin arco lumbar\",\"Calidad antes que tiempo\",\"Recorta palanca si cedes\",\"Activa abdomen antes de iniciar\",\"Mantén columna neutra\"]","errores_comunes":"[\"Arquear la zona lumbar\",\"Tirar del cuello\",\"Contener la respiración\",\"Moverse demasiado rápido\",\"Usar impulso de piernas\",\"Colapsar hombros\",\"Perder posición pélvica\",\"Continuar tras fallar la postura\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Abdominales Bicicleta (Bicycle Crunches)\",\"Abdominales Crunch\",\"Bird Dog (Perro-Pájaro)\",\"Crunch en Polea (Cable Crunch)\",\"Dead bug\",\"Plancha con manos elevadas\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"cualquiera","objetivo":"general","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"","rango_reps_max":"","descanso_segundos_min":"30","descanso_segundos_max":"60","rir_recomendado":"","duracion_promedio_segundos":"35","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"20","nombre":"Crunch bicicleta","aliases":"[\"Crunch bicicleta\",\"bicycle crunches\",\"Bicycle crunch\",\"abdominal bicicleta\",\"bicycle sit-up\",\"BC\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"core","musculo_principal":"oblicuos","musculos_secundarios":"[\"recto abdominal\",\"flexores de cadera\"]","equipamiento":"peso corporal","equipo_requerido":"[\"peso corporal\"]","tipo_entrenamiento":"core","patron_movimiento":"rotación de tronco","descripcion":"Crunch bicicleta trabaja principalmente oblicuos, con participación de recto abdominal, flexores de cadera. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación para Crunch bicicleta: revisa peso corporal, despeja el área y selecciona una carga o dificultad que puedas colocar y retirar sin impulso. Comprueba cierres, apoyos y estabilidad; ensaya una repetición lenta antes de la serie efectiva.\",\"Posición inicial: tumbado, manos ligeras detrás de la cabeza sin tirar, codos abiertos y piernas elevadas. Aplana suavemente la zona lumbar, costillas hacia pelvis, barbilla separada del pecho y hombros lejos de orejas.\",\"Agarre/apoyo: usa una sujeción cerrada y simétrica, con muñecas neutras. Ajusta la variante si el agarre limita la postura o provoca molestias antes que aumentar la carga.\",\"Inicio y trayectoria: Gira el tórax para acercar una axila a la rodilla contraria mientras extiendes la otra pierna; alterna desde el abdomen, no tirando del cuello. Siente recto abdominal y oblicuos.\",\"Rango y biomecánica: Acerca el codo solo hasta que el hombro se despegue sin levantar la zona lumbar; extiende la pierna hasta donde conserves el brace. No es necesario tocar codo y rodilla.\",\"Tempo y respiración: Alterna 2 s por lado sin tirones. Exhala con cada rotación e inhala durante el cambio.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Costillas sobre pelvis\",\"Respira detrás del brace\",\"Cuello largo\",\"Pelvis controlada\",\"Hombros activos\",\"Sin arco lumbar\",\"Calidad antes que tiempo\",\"Recorta palanca si cedes\",\"Controla la fase de ida y vuelta\",\"Evita impulsos excesivos\"]","errores_comunes":"[\"Arquear la zona lumbar\",\"Tirar del cuello\",\"Contener la respiración\",\"Moverse demasiado rápido\",\"Usar impulso de piernas\",\"Colapsar hombros\",\"Perder posición pélvica\",\"Continuar tras fallar la postura\",\"Usar impulso excesivo\",\"Perder postura\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Abdominales Bicicleta (Bicycle Crunches)\",\"Abdominales Crunch\",\"Bird Dog (Perro-Pájaro)\",\"Crunch en Polea (Cable Crunch)\",\"Dead bug\",\"Plancha con manos elevadas\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"cualquiera","objetivo":"general","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"12","rango_reps_max":"25","descanso_segundos_min":"30","descanso_segundos_max":"60","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"22","nombre":"Giro ruso con mancuerna","aliases":"[\"Giro ruso con mancuerna\",\"russian twist\",\"dumbbell russian twist\",\"torsión rusa\",\"DB Russian twist\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"core","musculo_principal":"oblicuos","musculos_secundarios":"[\"recto abdominal\",\"transverso abdominal\"]","equipamiento":"mancuerna","equipo_requerido":"[\"mancuerna\"]","tipo_entrenamiento":"core","patron_movimiento":"rotación de tronco","descripcion":"Giro ruso con mancuerna trabaja principalmente oblicuos, con participación de recto abdominal, transverso abdominal. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: elige mancuernas/kettlebell que puedas levantar y colocar sin impulso; despeja el área, comprueba cierres y usa banco estable si corresponde. Empieza con una carga que permita controlar la repetición y practica el montaje antes de la serie efectiva.\",\"Posición inicial: siéntate con rodillas flexionadas, pies apoyados para aprender y mancuerna cerca del esternón. Inclina el torso desde caderas manteniendo columna larga, pecho abierto, hombros bajos, codos suaves y cuello neutro.\",\"Agarre/apoyo: usa una sujeción cerrada y simétrica, con muñecas neutras. Ajusta la variante si el agarre limita la postura o provoca molestias antes que aumentar la carga.\",\"Inicio y trayectoria: Rota costillas y hombros como una unidad sobre una pelvis estable, llevando la mancuerna de un lado al otro. Siente oblicuos; brazos solo sostienen la carga.\",\"Rango y biomecánica: Gira hasta antes de que rodillas, pies o zona lumbar acompañen; no golpees la mancuerna contra el suelo. Mantén el implemento cerca para controlar el brazo de palanca.\",\"Tempo y respiración: Rota 2 s, pausa breve y cambia en 2 s. Exhala hacia cada lado e inhala al pasar por el centro.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Costillas sobre pelvis\",\"Respira detrás del brace\",\"Cuello largo\",\"Pelvis controlada\",\"Hombros activos\",\"Sin arco lumbar\",\"Calidad antes que tiempo\",\"Recorta palanca si cedes\",\"Controla la fase de ida y vuelta\",\"Evita impulsos excesivos\"]","errores_comunes":"[\"Arquear la zona lumbar\",\"Tirar del cuello\",\"Contener la respiración\",\"Moverse demasiado rápido\",\"Usar impulso de piernas\",\"Colapsar hombros\",\"Perder posición pélvica\",\"Continuar tras fallar la postura\",\"Usar impulso excesivo\",\"Perder postura\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Abdominales Bicicleta (Bicycle Crunches)\",\"Abdominales Crunch\",\"Bird Dog (Perro-Pájaro)\",\"Crunch en Polea (Cable Crunch)\",\"Dead bug\",\"Plancha con manos elevadas\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"cualquiera","objetivo":"general","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"12","rango_reps_max":"24","descanso_segundos_min":"30","descanso_segundos_max":"75","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"54","nombre":"Rotación de torso en polea de pie","aliases":"[\"Rotación de torso en polea de pie\",\"giro de torso en polea\",\"rotación de tronco en polea\",\"cable torso rotation\",\"standing cable rotation\",\"Standing cable torso rotation\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"core","musculo_principal":"oblicuos","musculos_secundarios":"[\"recto abdominal\",\"transverso abdominal\"]","equipamiento":"polea ajustable, agarre","equipo_requerido":"[\"polea ajustable\",\"agarre\"]","tipo_entrenamiento":"core","patron_movimiento":"rotación de tronco","descripcion":"Rotación de torso en polea de pie trabaja principalmente oblicuos, con participación de recto abdominal, transverso abdominal. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Ajusta una sola polea a la altura del esternón, conecta un asa y verifica el pasador. Colócate de lado a la torre, a una distancia que mantenga tensión sin que la pila se eleve en reposo. La cifra de la pila puede no equivaler a la resistencia efectiva por la relación de poleas; registra siempre la misma torre, ajuste y accesorio.\",\"Posición inicial: de lado a la polea, pies algo más anchos que caderas, rodillas suaves y pelvis al frente. Sostén el asa con ambas manos frente al esternón, brazos largos sin bloquear, hombros bajos, escápulas controladas y cuello neutro.\",\"Agarre/apoyo: usa una sujeción cerrada y simétrica, con muñecas neutras. Ajusta la variante si el agarre limita la postura o provoca molestias antes que aumentar la carga.\",\"Inicio y trayectoria: Rota el tórax alejando las manos de la torre mientras la pelvis permanece al frente; pivota el pie trasero solo si la variante lo permite. Siente oblicuos, serrato y glúteos estabilizando.\",\"Rango y biomecánica: Gira hasta mantener costillas sobre pelvis y brazos a altura constante; retorna sin que la pila golpee. Para antirotación usa Pallof, no confundas ambos patrones.\",\"Tempo y respiración: Gira 1–2 s, pausa 1 s y retorna 3 s. Exhala al alejarte de la torre e inhala al volver.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Costillas sobre pelvis\",\"Respira detrás del brace\",\"Cuello largo\",\"Pelvis controlada\",\"Hombros activos\",\"Sin arco lumbar\",\"Calidad antes que tiempo\",\"Recorta palanca si cedes\",\"Costillas y hombros giran juntos\",\"Pelvis estable\"]","errores_comunes":"[\"Arquear la zona lumbar\",\"Tirar del cuello\",\"Contener la respiración\",\"Moverse demasiado rápido\",\"Usar impulso de piernas\",\"Colapsar hombros\",\"Perder posición pélvica\",\"Continuar tras fallar la postura\",\"Mover solo los brazos\",\"Girar las rodillas\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Abdominales Bicicleta (Bicycle Crunches)\",\"Abdominales Crunch\",\"Bird Dog (Perro-Pájaro)\",\"Crunch en Polea (Cable Crunch)\",\"Dead bug\",\"Plancha con manos elevadas\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"general","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"10","rango_reps_max":"16","descanso_segundos_min":"45","descanso_segundos_max":"90","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"Dual Adjustable Pulley","estado_calidad":"curado"},{"action":"update","id":"53","nombre":"Crunch en polea","aliases":"[\"Crunch en polea\",\"crunch arrodillado en polea\",\"abdominal en polea\",\"cable crunch\",\"kneeling cable crunch\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"core","musculo_principal":"recto abdominal","musculos_secundarios":"[\"oblicuos\",\"transverso abdominal\"]","equipamiento":"polea alta, cuerda","equipo_requerido":"[\"polea alta\",\"cuerda\"]","tipo_entrenamiento":"core","patron_movimiento":"flexión de tronco","descripcion":"Crunch en polea trabaja principalmente recto abdominal, con participación de oblicuos, transverso abdominal. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Coloca la polea alta, conecta cuerda, verifica mosquetón y pasador. Arrodíllate a una distancia que permita flexionar el tronco sin que la pila toque arriba ni abajo; usa una colchoneta si hace falta. La cifra de la pila puede no equivaler a la resistencia efectiva por la relación de poleas; registra siempre la misma torre, ajuste y accesorio.\",\"Posición inicial: arrodillado, caderas sobre rodillas sin sentarte en talones, cuerda a ambos lados de la cabeza y manos quietas. Mantén pelvis neutra, costillas hacia abajo, hombros lejos de orejas y cuello alineado; los brazos solo conectan con el cable.\",\"Agarre/apoyo: usa una sujeción cerrada y simétrica, con muñecas neutras. Ajusta la variante si el agarre limita la postura o provoca molestias antes que aumentar la carga.\",\"Inicio y trayectoria: Flexiona la columna aproximando costillas a pelvis; los codos viajan hacia muslos sin que brazos tiren de la cuerda. Siente el recto abdominal, no un balanceo de cadera.\",\"Rango y biomecánica: Acorta hasta antes de sentarte sobre talones o perder tensión; vuelve a una extensión torácica moderada sin hiperextender la zona lumbar ni dejar reposar la pila.\",\"Tempo y respiración: Flexiona en 2 s, pausa 1 s y vuelve en 3 s. Exhala durante el crunch e inhala al abrir.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Costillas sobre pelvis\",\"Respira detrás del brace\",\"Cuello largo\",\"Pelvis controlada\",\"Hombros activos\",\"Sin arco lumbar\",\"Calidad antes que tiempo\",\"Recorta palanca si cedes\",\"Costillas hacia pelvis\",\"Caderas quietas\"]","errores_comunes":"[\"Arquear la zona lumbar\",\"Tirar del cuello\",\"Contener la respiración\",\"Moverse demasiado rápido\",\"Usar impulso de piernas\",\"Colapsar hombros\",\"Perder posición pélvica\",\"Continuar tras fallar la postura\",\"Hacer una bisagra de cadera\",\"Tirar con los brazos\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Abdominales Bicicleta (Bicycle Crunches)\",\"Abdominales Crunch\",\"Bird Dog (Perro-Pájaro)\",\"Crunch en Polea (Cable Crunch)\",\"Dead bug\",\"Plancha con manos elevadas\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"general","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"10","rango_reps_max":"20","descanso_segundos_min":"45","descanso_segundos_max":"90","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"Functional Trainer","estado_calidad":"curado"},{"action":"update","id":"21","nombre":"Elevación de piernas tumbado","aliases":"[\"Elevación de piernas tumbado\",\"elevaciones de piernas\",\"leg raise\",\"lying leg raise\",\"hanging leg raise\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"core","musculo_principal":"recto abdominal inferior","musculos_secundarios":"[\"flexores de cadera\",\"core\"]","equipamiento":"colchoneta","equipo_requerido":"[\"colchoneta\"]","tipo_entrenamiento":"core","patron_movimiento":"flexión de cadera con retroversión pélvica tumbado","descripcion":"Elevación de piernas tumbado trabaja principalmente recto abdominal inferior, con participación de flexores de cadera, core. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: usa una superficie plana, antideslizante y con espacio para todo el cuerpo. Coloca colchoneta si mejora comodidad, retira objetos cercanos y elige una inclinación o palanca que puedas sostener sin perder alineación desde la primera repetición.\",\"Posición inicial: tumbado, piernas juntas, manos bajo glúteos o a los lados y hombros apoyados. Lleva costillas hacia pelvis, zona lumbar suavemente contra el suelo, cuello neutro y caderas estables; flexiona un poco las rodillas si hace falta.\",\"Agarre/apoyo: usa una sujeción cerrada y simétrica, con muñecas neutras. Ajusta la variante si el agarre limita la postura o provoca molestias antes que aumentar la carga.\",\"Inicio y trayectoria: Eleva las piernas desde la cadera y termina con una leve retroversión pélvica, no con un balanceo. Siente abdomen inferior y flexores de cadera mientras la zona lumbar permanece controlada.\",\"Rango y biomecánica: Sube hasta piernas verticales o pelvis ligeramente elevada; baja solo hasta antes de que la espalda se arquee. Flexiona rodillas para reducir la palanca.\",\"Tempo y respiración: Sube 2 s, pausa 1 s y baja 3 s. Exhala al elevar e inhala al descender.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Costillas sobre pelvis\",\"Respira detrás del brace\",\"Cuello largo\",\"Pelvis controlada\",\"Hombros activos\",\"Sin arco lumbar\",\"Calidad antes que tiempo\",\"Recorta palanca si cedes\",\"Sin balanceo\",\"Baja lento\"]","errores_comunes":"[\"Arquear la zona lumbar\",\"Tirar del cuello\",\"Contener la respiración\",\"Moverse demasiado rápido\",\"Usar impulso de piernas\",\"Colapsar hombros\",\"Perder posición pélvica\",\"Continuar tras fallar la postura\",\"Usar impulso\",\"Soltar la bajada\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Abdominales Bicicleta (Bicycle Crunches)\",\"Abdominales Crunch\",\"Bird Dog (Perro-Pájaro)\",\"Crunch en Polea (Cable Crunch)\",\"Dead bug\",\"Plancha con manos elevadas\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"cualquiera","objetivo":"general","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"8","rango_reps_max":"15","descanso_segundos_min":"45","descanso_segundos_max":"90","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"71","nombre":"Levantamiento turco con kettlebell","aliases":"[\"Levantamiento turco con kettlebell\",\"turkish get-up\",\"tgu\",\"get-up turco\",\"KB Turkish get-up\"]","nivel":"avanzado","nivel_minimo":"avanzado","grupo_muscular":"cuerpo completo","musculo_principal":"core","musculos_secundarios":"[\"hombros\",\"glúteos\",\"cuádriceps\",\"antebrazos\"]","equipamiento":"kettlebell o mancuerna","equipo_requerido":"[\"kettlebell o mancuerna\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"levantamiento complejo","descripcion":"Levantamiento turco con kettlebell trabaja principalmente core, con participación de hombros, glúteos, cuádriceps. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: despeja un área de al menos dos largos corporales y usa una kettlebell muy ligera. Túmbate de lado junto a la pesa, tómala con ambas manos y rueda boca arriba antes de presionarla; nunca la arrastres sobre la cara ni practiques cerca de otras personas.\",\"Posición inicial: tumbado boca arriba, kettlebell junto al hombro. Rueda de lado, toma el asa con ambas manos, llévala al pecho y presiónala con una mano; brazo de carga vertical, muñeca neutra, hombro centrado, rodilla del mismo lado flexionada y pie completo, pierna opuesta abierta y extendida.\",\"Apoyo/agarre: manos completas, dedos separados y muñecas alineadas bajo el soporte cuando estén en el suelo; en barra/anillas usa agarre cerrado con pulgar. Ajusta el ángulo o usa asas si la extensión de muñeca no es tolerable.\",\"Inicio y trayectoria: Pasa por ocho posiciones sin apartar la vista de la pesa: codo, mano, puente, barrido de pierna, media rodilla, zancada y bipedestación. Mantén el brazo de carga vertical y el hombro centrado durante cada transición.\",\"Rango y biomecánica: Usa el recorrido completo solo si cada apoyo es estable; invierte exactamente la secuencia para bajar. Detén y apoya la pesa con ambas manos si la muñeca se dobla, el brazo deja de vertical o pierdes orientación.\",\"Tempo y respiración: Sin prisa: pausa en cada posición, exhala durante las transiciones y recupera aire al estabilizar. Una repetición puede durar 20–40 s.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: invierte toda la secuencia hasta quedar tumbado, baja la kettlebell al pecho con control y usa ambas manos para rodar de lado y depositarla. Nunca la bajes lateralmente con un solo brazo fatigado.\"]","cues_tecnicos":"[\"Base estable\",\"Core firme\",\"Carga cerca del cuerpo\",\"Cadera y rodillas coordinadas\",\"Cuello neutro\",\"Aterriza suave\",\"Respira con el esfuerzo\",\"Detén si se desordena\",\"Controla la fase de ida y vuelta\",\"Evita impulsos excesivos\"]","errores_comunes":"[\"Usar fatiga para aprender técnica\",\"Redondear la espalda\",\"Alejar la carga\",\"Recepción rígida\",\"Rodillas desalineadas\",\"Contener la respiración\",\"Perder equilibrio\",\"Priorizar velocidad sobre control\",\"Usar impulso excesivo\",\"Perder postura\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Burpees\",\"Clean and Press (Cargada y Press)\",\"Muscle-Up\",\"Planche (Plancha horizontal)\",\"Variación con mancuerna ligera\",\"Ejercicio por fases\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"habilidad","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"1","rango_reps_max":"5","descanso_segundos_min":"90","descanso_segundos_max":"180","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"30","nombre":"Burpees","aliases":"[\"Burpees\",\"Burpee\",\"burpee completo\",\"squat thrust con salto\",\"burpee jump\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"cuerpo completo","musculo_principal":"cuerpo completo","musculos_secundarios":"[\"pectorales\",\"cuádriceps\",\"glúteos\",\"core\",\"hombros\"]","equipamiento":"peso corporal","equipo_requerido":"[\"peso corporal\"]","tipo_entrenamiento":"cardio","patron_movimiento":"locomoción/cardio","descripcion":"Burpees trabaja principalmente cuerpo completo, con participación de pectorales, cuádriceps, glúteos. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: usa una superficie plana, antideslizante y con espacio para todo el cuerpo. Coloca colchoneta si mejora comodidad, retira objetos cercanos y elige una inclinación o palanca que puedas sostener sin perder alineación desde la primera repetición.\",\"Posición inicial: base estable, rodillas alineadas, cadera y abdomen firmes, espalda en posición neutra y cabeza siguiendo el torso. Mantén cuello largo, pecho controlado, hombros bajos, escápulas estables y manos/muñecas/codos alineados con el apoyo o implemento.\",\"Apoyo/agarre: manos completas, dedos separados y muñecas alineadas bajo el soporte cuando estén en el suelo; en barra/anillas usa agarre cerrado con pulgar. Ajusta el ángulo o usa asas si la extensión de muñeca no es tolerable.\",\"Inicio y trayectoria: Inicia desde una base estable y acelera sin perder alineación de rodilla, cadera y tronco. Produce fuerza contra el suelo; brazos acompañan sin tensar cuello u hombros.\",\"Rango y biomecánica: Mantén amplitud que permita aterrizar suave o conservar la plancha. Reduce velocidad, altura o recorrido cuando la técnica se deteriore; no uses fatiga extrema para aprender una variante explosiva.\",\"Tempo y respiración: La fase propulsiva es rápida y la recepción/retorno controlados. Respira rítmicamente; exhala en cada esfuerzo y recupera sin contener el aire.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Base estable\",\"Core firme\",\"Carga cerca del cuerpo\",\"Cadera y rodillas coordinadas\",\"Cuello neutro\",\"Aterriza suave\",\"Respira con el esfuerzo\",\"Detén si se desordena\",\"Mantén una intensidad sostenible\",\"Respira de forma constante\"]","errores_comunes":"[\"Usar fatiga para aprender técnica\",\"Redondear la espalda\",\"Alejar la carga\",\"Recepción rígida\",\"Rodillas desalineadas\",\"Contener la respiración\",\"Perder equilibrio\",\"Priorizar velocidad sobre control\",\"Empezar demasiado fuerte\",\"Perder técnica por fatiga\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Ten precaución con alto impacto si aún no puedes aterrizar o desacelerar sin dolor ni pérdida de alineación\",\"Reducir intensidad si aparece mareo, dolor torácico o falta de aire inusual\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Elíptica\",\"Ciclismo\",\"Remo en máquina\",\"Saltar cuerda\",\"Variación con mancuerna ligera\",\"Ejercicio por fases\"]","progresiones":"[\"Aumentar duración\",\"Aumentar ritmo gradualmente\",\"Agregar intervalos controlados\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir duración\",\"Bajar ritmo\",\"Usar intervalos más cortos\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"cualquiera","objetivo":"resistencia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"","rango_reps_max":"","descanso_segundos_min":"45","descanso_segundos_max":"90","rir_recomendado":"","duracion_promedio_segundos":"60","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"70","nombre":"Thruster con barra","aliases":"[\"Thruster con barra\",\"Thruster barra\",\"thrusters\",\"sentadilla con press\",\"Barbell thruster\",\"Thruster con BB\"]","nivel":"avanzado","nivel_minimo":"avanzado","grupo_muscular":"cuerpo completo","musculo_principal":"cuerpo completo","musculos_secundarios":"[\"cuádriceps\",\"glúteos\",\"hombros\",\"tríceps\",\"core\"]","equipamiento":"barra o mancuernas","equipo_requerido":"[\"barra o mancuernas\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"sentadilla/empuje vertical","descripcion":"Thruster con barra trabaja principalmente cuerpo completo, con participación de cuádriceps, glúteos, hombros. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: coloca la barra en un rack a una altura que permita sacarla sin encoger hombros ni ponerte de puntillas. Carga ambos lados por igual, usa seguros de disco y topes de seguridad; ensaya el recorrido con la barra vacía y pide spotter cuando la carga o el ejercicio lo amerite.\",\"Posición inicial: pies firmes y trípode plantar activo, rodillas orientadas hacia los dedos, cadera centrada, abdomen presurizado y columna neutra. Mantén pecho y cabeza siguiendo el torso, cuello largo, hombros estables y manos simétricas; no permitas que talones o pelvis pierdan apoyo.\",\"Agarre: prono cerrado alrededor de la barra y muñecas firmes. En peso muerto pesado puede usarse mixto o hook grip, alternando lados y solo con experiencia; para aprender, usa doble prono. La barra debe permanecer controlada, nunca apoyada en dedos abiertos.\",\"Inicio y trayectoria: Inicia flexionando cadera y rodillas a la vez, siguiendo la dirección de los pies; distribuye presión entre talón, base del dedo gordo y base del meñique. Siente cuádriceps y glúteos, no presión aguda en rodilla o espalda.\",\"Rango y biomecánica: Desciende hasta la mayor profundidad que conserve talones, pelvis y columna controlados; empuja la plataforma/suelo y termina con cadera y rodillas extendidas sin hiperextender ni bloquear con violencia.\",\"Tempo y respiración: Desciende 3 s, pausa breve sin relajarte y sube en 1–2 s. Inhala y crea presión antes de bajar; exhala al superar la parte difícil sin perder el abdomen.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Base estable\",\"Core firme\",\"Carga cerca del cuerpo\",\"Cadera y rodillas coordinadas\",\"Cuello neutro\",\"Aterriza suave\",\"Respira con el esfuerzo\",\"Detén si se desordena\",\"Pie completo apoyado\",\"Rodillas siguen la línea de los pies\"]","errores_comunes":"[\"Usar fatiga para aprender técnica\",\"Redondear la espalda\",\"Alejar la carga\",\"Recepción rígida\",\"Rodillas desalineadas\",\"Contener la respiración\",\"Perder equilibrio\",\"Priorizar velocidad sobre control\",\"Colapsar rodillas hacia adentro\",\"Levantar talones\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Evitar si provoca dolor agudo en hombro, muñeca o codo\",\"Reducir rango o usar alternativa si genera molestia\"]","sustituciones":"[\"Burpees\",\"Clean and Press (Cargada y Press)\",\"Muscle-Up\",\"Planche (Plancha horizontal)\",\"Variación con mancuerna ligera\",\"Ejercicio por fases\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"potencia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"6","rango_reps_max":"12","descanso_segundos_min":"90","descanso_segundos_max":"150","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"sf-assisted-pullup","nombre":"Dominadas asistidas en máquina","aliases":"[\"Dominadas asistidas en máquina\",\"Dominadas asistidas máquina\",\"dominada asistida\",\"máquina de dominadas asistidas\",\"assisted pull-up\",\"assisted chin-up machine\",\"Assisted pull-up machine\",\"Dominadas asistidas en máq.\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"espalda","musculo_principal":"dorsal ancho","musculos_secundarios":"[\"biceps\",\"romboides\",\"trapecio medio\",\"core\"]","equipamiento":"máquina de dominadas asistidas","equipo_requerido":"[\"máquina de dominadas asistidas\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"jalon vertical asistido","descripcion":"Dominadas asistidas en máquina trabaja principalmente dorsal ancho, con participación de bíceps, romboides, trapecio medio. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Selecciona primero bastante asistencia: en esta máquina más peso equivale a más ayuda. Ajusta peldaño o plataforma, elige agarres accesibles y comprueba que la almohadilla móvil recorra libre; sube usando los escalones y apoya ambas rodillas o pies antes de soltar las manos.\",\"Posición inicial: pies apoyados, rodillas suaves o fijadas por el rodillo, pelvis neutra y torso largo. Mantén abdomen firme, columna y cuello neutros, pecho abierto sin arquear, hombros lejos de orejas, escápulas controladas y codos desbloqueados.\",\"Agarre: prono algo más ancho que hombros para esta variante; un agarre excesivamente abierto recorta el recorrido. El neutro suele ser más cómodo para el hombro y el supino aumenta la ayuda del bíceps; usa pulgar cerrado y muñecas neutras.\",\"Inicio y trayectoria: Comienza bajando las escápulas y luego lleva los codos hacia las costillas; evita iniciar con un balanceo. Siente dorsales y espalda alta, con bíceps como asistente y cuello relajado.\",\"Rango y biomecánica: Lleva la barra/agarre hacia la parte alta del pecho o eleva el pecho hacia las manos sin tirar detrás de la nuca; retorna hasta brazos largos sin perder el hombro activo. Evita rango que provoque dolor o que levante el cuerpo del asiento.\",\"Tempo y respiración: Sube o tira en 1–2 s, pausa 1 s y vuelve en 2–3 s. Exhala durante el tirón e inhala en el retorno controlado.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina con brazos largos y hombros activos, deja que la plataforma suba lentamente y mantén ambas manos en las asas. Retira una rodilla o pie a la vez hacia el escalón, baja de frente y no permitas que el contrapeso lance la plataforma.\"]","cues_tecnicos":"[\"Pecho largo\",\"Hombros abajo\",\"Codos hacia costillas\",\"Cuello neutro\",\"Core firme\",\"Barra o cable cerca\",\"Sin tirón lumbar\",\"Controla el retorno\",\"Hombros lejos de orejas\",\"Codos hacia abajo\"]","errores_comunes":"[\"Redondear o hiperextender la espalda\",\"Tirar con impulso\",\"Elevar hombros\",\"Sacar la cabeza\",\"Flexionar muñecas\",\"Acortar el estiramiento\",\"Mover cadera o torso\",\"Golpear la pila\",\"Confundir asistencia con carga\",\"Saltar sobre la plataforma\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Evitar si causa dolor agudo de hombro o codo\",\"Usar jalon al pecho si no hay equipo de asistencia\"]","sustituciones":"[\"Jalón al pecho\",\"Dominadas\",\"Remo en polea sentado\",\"Remo con pecho apoyado\",\"Jalón al pecho con agarre neutro\"]","progresiones":"[\"Reducir asistencia\",\"Pausar arriba\",\"Pasar a dominadas libres\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Aumentar asistencia\",\"Jalón al pecho\",\"Remo en polea ligero\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"12","descanso_segundos_min":"90","descanso_segundos_max":"150","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"Assisted Pull-Up Machine","estado_calidad":"curado"},{"action":"update","id":"35","nombre":"Remo con barra inclinado","aliases":"[\"Remo con barra inclinado\",\"Remo barra inclinado\",\"remo inclinado con barra\",\"remo con barra\",\"bent-over barbell row\",\"barbell row\",\"Remo con BB inclinado\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"espalda","musculo_principal":"espalda media","musculos_secundarios":"[\"dorsal ancho\",\"romboides\",\"trapecio medio\",\"deltoides posterior\",\"biceps\",\"erectores espinales\"]","equipamiento":"barra, discos","equipo_requerido":"[\"barra\",\"discos\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"jalon horizontal","descripcion":"Remo con barra inclinado trabaja principalmente espalda media, con participación de dorsal ancho, romboides, trapecio medio. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: coloca la barra sobre suelo/plataforma nivelada, carga discos iguales y asegura ambos extremos. Deja espacio alrededor, centra la barra sobre el mediopié y usa discos técnicos o bloques si aún no alcanzas la posición inicial con columna neutra.\",\"Posición inicial: pies apoyados, rodillas suaves o fijadas por el rodillo, pelvis neutra y torso largo. Mantén abdomen firme, columna y cuello neutros, pecho abierto sin arquear, hombros lejos de orejas, escápulas controladas y codos desbloqueados.\",\"Agarre: el neutro facilita llevar los codos junto al torso y suele ser cómodo; el prono algo más ancho desplaza énfasis hacia espalda alta y deltoide posterior; el supino añade bíceps. Elige uno que permita muñecas rectas y hombros bajos.\",\"Inicio y trayectoria: Inicia llevando los codos hacia atrás y ligeramente hacia el torso; la escápula se retrae/protrae de forma controlada sin elevar hombros. Siente dorsal y espalda media, no el cuello ni la zona lumbar.\",\"Rango y biomecánica: Tira hasta que el asa se acerque al tronco sin sobreextender hombro ni echarte atrás; retorna hasta brazos largos y escápulas que avancen sin redondear la columna. Cadera y torso permanecen estables.\",\"Tempo y respiración: Tira en 1–2 s, pausa 1 s con hombros bajos y retorna en 2–3 s. Exhala al remar e inhala al extender los brazos.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Pecho largo\",\"Hombros abajo\",\"Codos hacia costillas\",\"Cuello neutro\",\"Core firme\",\"Barra o cable cerca\",\"Sin tirón lumbar\",\"Controla el retorno\",\"Cadera atrás\",\"Columna neutra\"]","errores_comunes":"[\"Redondear o hiperextender la espalda\",\"Tirar con impulso\",\"Elevar hombros\",\"Sacar la cabeza\",\"Flexionar muñecas\",\"Acortar el estiramiento\",\"Mover cadera o torso\",\"Golpear la pila\",\"Redondear la espalda\",\"Levantarse en cada repetición\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Evitar si provoca dolor lumbar agudo\",\"Usar remo pecho apoyado si cuesta estabilizar el torso\"]","sustituciones":"[\"Remo en polea sentado\",\"Remo en T\",\"Remo pecho apoyado\",\"Remo con pecho apoyado\",\"Jalón al pecho con agarre neutro\"]","progresiones":"[\"Aumentar carga\",\"Usar pausa arriba\",\"Usar agarre mas estricto\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Remo pecho apoyado\",\"Remo con mancuerna a una mano\",\"Remo en polea sentado\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"fuerza","series_sugeridas":"4","repeticiones_sugeridas":"8","rango_reps_min":"6","rango_reps_max":"10","descanso_segundos_min":"120","descanso_segundos_max":"180","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"49","nombre":"Remo en polea sentado","aliases":"[\"Remo en polea sentado\",\"remo sentado en polea\",\"remo en polea baja\",\"seated cable row\",\"low cable row\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"espalda","musculo_principal":"espalda media","musculos_secundarios":"[\"dorsal ancho\",\"romboides\",\"trapecio medio\",\"deltoides posterior\",\"biceps\"]","equipamiento":"polea baja, banco y agarre neutro","equipo_requerido":"[\"polea baja\",\"banco\",\"agarre neutro\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"jalon horizontal","descripcion":"Remo en polea sentado trabaja principalmente espalda media, con participación de dorsal ancho, romboides, trapecio medio. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Conecta el agarre a la polea baja y verifica mosquetón/pasador. Ajusta asiento o plataforma para poder tomar el asa con rodillas ligeramente flexionadas y torso vertical; si hay apoyo de pecho, alinéalo con el esternón sin comprimir la respiración.\",\"Posición inicial: pies apoyados, rodillas suaves o fijadas por el rodillo, pelvis neutra y torso largo. Mantén abdomen firme, columna y cuello neutros, pecho abierto sin arquear, hombros lejos de orejas, escápulas controladas y codos desbloqueados.\",\"Agarre: el neutro facilita llevar los codos junto al torso y suele ser cómodo; el prono algo más ancho desplaza énfasis hacia espalda alta y deltoide posterior; el supino añade bíceps. Elige uno que permita muñecas rectas y hombros bajos.\",\"Inicio y trayectoria: Inicia llevando los codos hacia atrás y ligeramente hacia el torso; la escápula se retrae/protrae de forma controlada sin elevar hombros. Siente dorsal y espalda media, no el cuello ni la zona lumbar.\",\"Rango y biomecánica: Tira hasta que el asa se acerque al tronco sin sobreextender hombro ni echarte atrás; retorna hasta brazos largos y escápulas que avancen sin redondear la columna. Cadera y torso permanecen estables.\",\"Tempo y respiración: Tira en 1–2 s, pausa 1 s con hombros bajos y retorna en 2–3 s. Exhala al remar e inhala al extender los brazos.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Pecho largo\",\"Hombros abajo\",\"Codos hacia costillas\",\"Cuello neutro\",\"Core firme\",\"Barra o cable cerca\",\"Sin tirón lumbar\",\"Controla el retorno\",\"Pecho alto\",\"Codos hacia atrás\"]","errores_comunes":"[\"Redondear o hiperextender la espalda\",\"Tirar con impulso\",\"Elevar hombros\",\"Sacar la cabeza\",\"Flexionar muñecas\",\"Acortar el estiramiento\",\"Mover cadera o torso\",\"Golpear la pila\",\"Balancear el tronco\",\"Redondear la espalda\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Evitar si causa dolor agudo de hombro o espalda baja\",\"Reducir carga si pierdes postura\"]","sustituciones":"[\"Remo con mancuerna a una mano\",\"Remo pecho apoyado\",\"Remo con barra inclinado\",\"Remo con pecho apoyado\",\"Jalón al pecho con agarre neutro\",\"Remo en polea sentado\"]","progresiones":"[\"Aumentar carga\",\"Pausar con escapulas retraidas\",\"Usar agarre mas amplio\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar agarre neutral\",\"Remo con banda\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"15","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"Seated Cable Row","estado_calidad":"curado"},{"action":"update","id":"sf-row-tbar","nombre":"Remo en T con barra landmine","aliases":"[\"Remo en T con barra landmine\",\"Remo en T barra landmine\",\"remo landmine\",\"remo con barra en esquina\",\"landmine T-bar row\",\"T-bar row\",\"Remo en T con BB landmine\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"espalda","musculo_principal":"espalda media","musculos_secundarios":"[\"dorsal ancho\",\"romboides\",\"trapecio medio\",\"deltoides posterior\",\"biceps\",\"erectores espinales\"]","equipamiento":"barra, landmine, discos y agarre","equipo_requerido":"[\"barra\",\"landmine\",\"discos\",\"agarre\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"jalon horizontal","descripcion":"Remo en T con barra landmine trabaja principalmente espalda media, con participación de dorsal ancho, romboides, trapecio medio. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: coloca la barra sobre suelo/plataforma nivelada, carga discos iguales y asegura ambos extremos. Deja espacio alrededor, centra la barra sobre el mediopié y usa discos técnicos o bloques si aún no alcanzas la posición inicial con columna neutra.\",\"Posición inicial: pies firmes al ancho adecuado, rodillas suaves, cadera atrás y columna neutra desde sacro hasta cabeza. Mantén abdomen presurizado, pecho largo, cuello alineado, hombros lejos de orejas y escápulas controladas; brazos cuelgan con muñecas rectas.\",\"Agarre: el neutro facilita llevar los codos junto al torso y suele ser cómodo; el prono algo más ancho desplaza énfasis hacia espalda alta y deltoide posterior; el supino añade bíceps. Elige uno que permita muñecas rectas y hombros bajos.\",\"Inicio y trayectoria: Inicia llevando los codos hacia atrás y ligeramente hacia el torso; la escápula se retrae/protrae de forma controlada sin elevar hombros. Siente dorsal y espalda media, no el cuello ni la zona lumbar.\",\"Rango y biomecánica: Tira hasta que el asa se acerque al tronco sin sobreextender hombro ni echarte atrás; retorna hasta brazos largos y escápulas que avancen sin redondear la columna. Cadera y torso permanecen estables.\",\"Tempo y respiración: Tira en 1–2 s, pausa 1 s con hombros bajos y retorna en 2–3 s. Exhala al remar e inhala al extender los brazos.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Pecho largo\",\"Hombros abajo\",\"Codos hacia costillas\",\"Cuello neutro\",\"Core firme\",\"Barra o cable cerca\",\"Sin tirón lumbar\",\"Controla el retorno\",\"Cadera atrás\",\"Torso firme\"]","errores_comunes":"[\"Redondear o hiperextender la espalda\",\"Tirar con impulso\",\"Elevar hombros\",\"Sacar la cabeza\",\"Flexionar muñecas\",\"Acortar el estiramiento\",\"Mover cadera o torso\",\"Golpear la pila\",\"Redondear la espalda\",\"Usar rebote de piernas\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Evitar si provoca dolor lumbar\",\"Usar remo pecho apoyado si cuesta estabilizar torso\"]","sustituciones":"[\"Remo con barra inclinado\",\"Remo en polea sentado\",\"Remo pecho apoyado\",\"Remo con pecho apoyado\",\"Jalón al pecho con agarre neutro\"]","progresiones":"[\"Aumentar carga\",\"Pausar arriba\",\"Usar agarre amplio\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Remo en polea sentado\",\"Remo con mancuerna a una mano\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"4","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"12","descanso_segundos_min":"90","descanso_segundos_max":"150","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"sf-row-chest-supported","nombre":"Remo con mancuernas con pecho apoyado","aliases":"[\"Remo con mancuernas con pecho apoyado\",\"Remo mancuernas con pecho apoyado\",\"remo con pecho apoyado\",\"remo inclinado apoyado\",\"chest-supported dumbbell row\",\"incline bench row\",\"Remo con DB con pecho apoyado\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"espalda","musculo_principal":"espalda media","musculos_secundarios":"[\"dorsal ancho\",\"romboides\",\"trapecio medio\",\"deltoides posterior\",\"biceps\"]","equipamiento":"banco inclinado, mancuernas","equipo_requerido":"[\"banco inclinado\",\"mancuernas\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"jalon horizontal","descripcion":"Remo con mancuernas con pecho apoyado trabaja principalmente espalda media, con participación de dorsal ancho, romboides, trapecio medio. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: elige mancuernas/kettlebell que puedas levantar y colocar sin impulso; despeja el área, comprueba cierres y usa banco estable si corresponde. Empieza con una carga que permita controlar la repetición y practica el montaje antes de la serie efectiva.\",\"Posición inicial: pies apoyados, rodillas suaves o fijadas por el rodillo, pelvis neutra y torso largo. Mantén abdomen firme, columna y cuello neutros, pecho abierto sin arquear, hombros lejos de orejas, escápulas controladas y codos desbloqueados.\",\"Agarre: el neutro facilita llevar los codos junto al torso y suele ser cómodo; el prono algo más ancho desplaza énfasis hacia espalda alta y deltoide posterior; el supino añade bíceps. Elige uno que permita muñecas rectas y hombros bajos.\",\"Inicio y trayectoria: Inicia llevando los codos hacia atrás y ligeramente hacia el torso; la escápula se retrae/protrae de forma controlada sin elevar hombros. Siente dorsal y espalda media, no el cuello ni la zona lumbar.\",\"Rango y biomecánica: Tira hasta que el asa se acerque al tronco sin sobreextender hombro ni echarte atrás; retorna hasta brazos largos y escápulas que avancen sin redondear la columna. Cadera y torso permanecen estables.\",\"Tempo y respiración: Tira en 1–2 s, pausa 1 s con hombros bajos y retorna en 2–3 s. Exhala al remar e inhala al extender los brazos.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Pecho largo\",\"Hombros abajo\",\"Codos hacia costillas\",\"Cuello neutro\",\"Core firme\",\"Barra o cable cerca\",\"Sin tirón lumbar\",\"Controla el retorno\",\"Pecho apoyado\",\"Codos hacia atrás\"]","errores_comunes":"[\"Redondear o hiperextender la espalda\",\"Tirar con impulso\",\"Elevar hombros\",\"Sacar la cabeza\",\"Flexionar muñecas\",\"Acortar el estiramiento\",\"Mover cadera o torso\",\"Golpear la pila\",\"Despegar el pecho\",\"Encoger hombros\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Evitar si molesta el apoyo del pecho o hombros\",\"Reducir inclinacion si incomoda\"]","sustituciones":"[\"Remo en polea sentado\",\"Remo con mancuerna a una mano\",\"Remo con barra inclinado\",\"Remo con pecho apoyado\",\"Jalón al pecho con agarre neutro\"]","progresiones":"[\"Aumentar carga\",\"Usar pausa arriba\",\"Usar agarre neutro\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Remo en polea sentado\",\"Remo con banda\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"12","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"37","nombre":"Peso muerto convencional con barra","aliases":"[\"Peso muerto convencional con barra\",\"Peso muerto convencional barra\",\"deadlift\",\"barbell deadlift\",\"Conventional barbell deadlift\",\"Peso muerto convencional con BB\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"espalda","musculo_principal":"cadena posterior","musculos_secundarios":"[\"glúteos\",\"isquiosurales\",\"erectores espinales\",\"trapecio\",\"antebrazos\"]","equipamiento":"barra, discos","equipo_requerido":"[\"barra\",\"discos\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"bisagra de cadera","descripcion":"Peso muerto convencional con barra trabaja principalmente cadena posterior, con participación de glúteos, isquiosurales, erectores espinales. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: coloca la barra sobre suelo/plataforma nivelada, carga discos iguales y asegura ambos extremos. Deja espacio alrededor, centra la barra sobre el mediopié y usa discos técnicos o bloques si aún no alcanzas la posición inicial con columna neutra.\",\"Posición inicial: pies firmes al ancho adecuado, rodillas suaves, cadera atrás y columna neutra desde sacro hasta cabeza. Mantén abdomen presurizado, pecho largo, cuello alineado, hombros lejos de orejas y escápulas controladas; brazos cuelgan con muñecas rectas.\",\"Agarre: prono cerrado alrededor de la barra y muñecas firmes. En peso muerto pesado puede usarse mixto o hook grip, alternando lados y solo con experiencia; para aprender, usa doble prono. La barra debe permanecer controlada, nunca apoyada en dedos abiertos.\",\"Inicio y trayectoria: Empuja el suelo y extiende rodillas/cadera manteniendo la carga rozando el cuerpo; el tronco y la cadera ascienden coordinados. Siente glúteos, isquiotibiales y espalda trabajando isométricamente, no dolor lumbar.\",\"Rango y biomecánica: Termina erguido con glúteos contraídos, costillas sobre pelvis y sin inclinarte atrás; baja llevando cadera atrás y flexionando rodillas cuando la barra las supera. Detén si la espalda pierde neutralidad.\",\"Tempo y respiración: Sube en 1–2 s con control, pausa erguido y baja en 2–3 s. Inhala y bracea antes de despegar; exhala al terminar o entre repeticiones, sin hiperventilar.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Pecho largo\",\"Hombros abajo\",\"Codos hacia costillas\",\"Cuello neutro\",\"Core firme\",\"Barra o cable cerca\",\"Sin tirón lumbar\",\"Controla el retorno\",\"Cadera hacia atrás\",\"Columna neutra\"]","errores_comunes":"[\"Redondear o hiperextender la espalda\",\"Tirar con impulso\",\"Elevar hombros\",\"Sacar la cabeza\",\"Flexionar muñecas\",\"Acortar el estiramiento\",\"Mover cadera o torso\",\"Golpear la pila\",\"Redondear la espalda\",\"Convertirlo en sentadilla\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Evitar si provoca dolor agudo en rodilla, cadera o espalda baja\",\"Reducir carga o rango si hay molestia\"]","sustituciones":"[\"Peso muerto rumano con mancuernas\",\"Hip thrust con barra\",\"Puente de glúteo\",\"Remo con pecho apoyado\",\"Jalón al pecho con agarre neutro\",\"Remo en polea sentado\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"fuerza","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"3","rango_reps_max":"8","descanso_segundos_min":"150","descanso_segundos_max":"240","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"25","nombre":"Pullover con mancuerna","aliases":"[\"Pullover con mancuerna\",\"dumbbell pullover\",\"pulóver DB\",\"pull-over con mancuerna\",\"DB pullover\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"espalda","musculo_principal":"dorsal ancho","musculos_secundarios":"[\"pectoral mayor\",\"serrato anterior\",\"tríceps\"]","equipamiento":"mancuerna, banco","equipo_requerido":"[\"mancuerna\",\"banco\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"extensión de hombro","descripcion":"Pullover con mancuerna trabaja principalmente dorsal ancho, con participación de pectoral mayor, serrato anterior, tríceps. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: elige mancuernas/kettlebell que puedas levantar y colocar sin impulso; despeja el área, comprueba cierres y usa banco estable si corresponde. Empieza con una carga que permita controlar la repetición y practica el montaje antes de la serie efectiva.\",\"Posición inicial: pies completos y separados al ancho de caderas, rodillas estables, glúteos y parte alta de la espalda apoyados. Mantén una curva lumbar natural, pecho elevado sin hiperextender, cabeza/cuello neutros, hombros abajo y escápulas apoyadas; alinea codos y muñecas con la carga.\",\"Agarre/apoyo: usa una sujeción cerrada y simétrica, con muñecas neutras. Ajusta la variante si el agarre limita la postura o provoca molestias antes que aumentar la carga.\",\"Inicio y trayectoria: Con una leve flexión fija de codo, mueve los brazos desde el hombro en un arco hacia los muslos o sobre la cabeza. Siente dorsal/pectoral según la variante, no el tríceps por flexionar el codo.\",\"Rango y biomecánica: Llega al estiramiento que mantenga costillas, pelvis y hombro controlados; termina cuando brazos se alineen con el torso o el accesorio llegue a muslos. Evita hiperextender la zona lumbar.\",\"Tempo y respiración: Mueve en 2 s hacia la contracción, pausa 1 s y retorna en 3 s. Exhala al llevar brazos hacia el cuerpo e inhala al abrir.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Pecho largo\",\"Hombros abajo\",\"Codos hacia costillas\",\"Cuello neutro\",\"Core firme\",\"Barra o cable cerca\",\"Sin tirón lumbar\",\"Controla el retorno\",\"Controla la fase de ida y vuelta\",\"Evita impulsos excesivos\"]","errores_comunes":"[\"Redondear o hiperextender la espalda\",\"Tirar con impulso\",\"Elevar hombros\",\"Sacar la cabeza\",\"Flexionar muñecas\",\"Acortar el estiramiento\",\"Mover cadera o torso\",\"Golpear la pila\",\"Usar impulso excesivo\",\"Perder postura\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Back Lever\",\"Dominadas / Pull-ups\",\"Front Lever\",\"Jalón al Pecho (Lat Pulldown)\",\"Remo con pecho apoyado\",\"Jalón al pecho con agarre neutro\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"10","rango_reps_max":"15","descanso_segundos_min":"60","descanso_segundos_max":"90","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"36","nombre":"Dominadas","aliases":"[\"Dominadas\",\"dominada pronada\",\"pull-up\",\"pullup\",\"overhand pull-up\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"espalda","musculo_principal":"dorsal ancho","musculos_secundarios":"[\"bíceps\",\"romboides\",\"trapecio medio\",\"core\"]","equipamiento":"barra de dominadas","equipo_requerido":"[\"barra de dominadas\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"jalón vertical","descripcion":"Dominadas trabaja principalmente dorsal ancho, con participación de bíceps, romboides, trapecio medio. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: comprueba que barra, anillas o paralelas estén firmes, secas y a una altura segura; coloca colchoneta y un banco solo para subir/bajar, no para impulsarte. Usa banda o asistencia estable y evita comenzar sobre una zona de paso.\",\"Posición inicial: pies apoyados, rodillas suaves o fijadas por el rodillo, pelvis neutra y torso largo. Mantén abdomen firme, columna y cuello neutros, pecho abierto sin arquear, hombros lejos de orejas, escápulas controladas y codos desbloqueados.\",\"Agarre: prono algo más ancho que hombros para esta variante; un agarre excesivamente abierto recorta el recorrido. El neutro suele ser más cómodo para el hombro y el supino aumenta la ayuda del bíceps; usa pulgar cerrado y muñecas neutras.\",\"Inicio y trayectoria: Comienza bajando las escápulas y luego lleva los codos hacia las costillas; evita iniciar con un balanceo. Siente dorsales y espalda alta, con bíceps como asistente y cuello relajado.\",\"Rango y biomecánica: Lleva la barra/agarre hacia la parte alta del pecho o eleva el pecho hacia las manos sin tirar detrás de la nuca; retorna hasta brazos largos sin perder el hombro activo. Evita rango que provoque dolor o que levante el cuerpo del asiento.\",\"Tempo y respiración: Sube o tira en 1–2 s, pausa 1 s y vuelve en 2–3 s. Exhala durante el tirón e inhala en el retorno controlado.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Pecho largo\",\"Hombros abajo\",\"Codos hacia costillas\",\"Cuello neutro\",\"Core firme\",\"Barra o cable cerca\",\"Sin tirón lumbar\",\"Controla el retorno\",\"Hombros activos\",\"Costillas controladas\"]","errores_comunes":"[\"Redondear o hiperextender la espalda\",\"Tirar con impulso\",\"Elevar hombros\",\"Sacar la cabeza\",\"Flexionar muñecas\",\"Acortar el estiramiento\",\"Mover cadera o torso\",\"Golpear la pila\",\"Patear\",\"Encoger hombros\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Jalón al pecho\",\"Dominada a una mano\",\"Remo con pecho apoyado\",\"Jalón al pecho con agarre neutro\",\"Remo en polea sentado\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"fuerza","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"5","rango_reps_max":"12","descanso_segundos_min":"90","descanso_segundos_max":"180","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"48","nombre":"Jalón al pecho en polea alta","aliases":"[\"Jalón al pecho en polea alta\",\"jalón al pecho\",\"jalón dorsal\",\"lat pulldown\",\"front lat pulldown\",\"Wide-grip lat pulldown\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"espalda","musculo_principal":"dorsal ancho","musculos_secundarios":"[\"bíceps\",\"romboides\",\"trapecio medio\"]","equipamiento":"polea alta o máquina de jalón al pecho","equipo_requerido":"[\"polea alta\",\"barra de jalón\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"jalón vertical","descripcion":"Jalón al pecho en polea alta trabaja principalmente dorsal ancho, con participación de bíceps, romboides, trapecio medio. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Ajusta el asiento para apoyar ambos pies y fija el rodillo firmemente sobre la parte alta de los muslos, sin presionar las rodillas. Toma la barra antes de sentarte, inserta por completo el pasador y no inicies si el rodillo permite que la carga te levante.\",\"Posición inicial: pies apoyados, rodillas suaves o fijadas por el rodillo, pelvis neutra y torso largo. Mantén abdomen firme, columna y cuello neutros, pecho abierto sin arquear, hombros lejos de orejas, escápulas controladas y codos desbloqueados.\",\"Agarre: prono algo más ancho que hombros para esta variante; un agarre excesivamente abierto recorta el recorrido. El neutro suele ser más cómodo para el hombro y el supino aumenta la ayuda del bíceps; usa pulgar cerrado y muñecas neutras.\",\"Inicio y trayectoria: Comienza bajando las escápulas y luego lleva los codos hacia las costillas; evita iniciar con un balanceo. Siente dorsales y espalda alta, con bíceps como asistente y cuello relajado.\",\"Rango y biomecánica: Lleva la barra/agarre hacia la parte alta del pecho o eleva el pecho hacia las manos sin tirar detrás de la nuca; retorna hasta brazos largos sin perder el hombro activo. Evita rango que provoque dolor o que levante el cuerpo del asiento.\",\"Tempo y respiración: Sube o tira en 1–2 s, pausa 1 s y vuelve en 2–3 s. Exhala durante el tirón e inhala en el retorno controlado.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Pecho largo\",\"Hombros abajo\",\"Codos hacia costillas\",\"Cuello neutro\",\"Core firme\",\"Barra o cable cerca\",\"Sin tirón lumbar\",\"Controla el retorno\",\"Muslos fijados\",\"Pecho alto\"]","errores_comunes":"[\"Redondear o hiperextender la espalda\",\"Tirar con impulso\",\"Elevar hombros\",\"Sacar la cabeza\",\"Flexionar muñecas\",\"Acortar el estiramiento\",\"Mover cadera o torso\",\"Golpear la pila\",\"Jalar detrás de la nuca\",\"Balancear el torso\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Dominadas\",\"Dominada a una mano\",\"Remo con pecho apoyado\",\"Jalón al pecho con agarre neutro\",\"Remo en polea sentado\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"8","rango_reps_max":"12","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"Lat Pulldown Machine","estado_calidad":"curado"},{"action":"update","id":"27","nombre":"Superman en suelo","aliases":"[\"Superman en suelo\",\"superman\",\"floor back extension\",\"Floor superman\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"espalda","musculo_principal":"erectores espinales","musculos_secundarios":"[\"glúteos\",\"isquiosurales\",\"trapecio medio\"]","equipamiento":"peso corporal","equipo_requerido":"[\"peso corporal\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"extensión lumbar","descripcion":"Superman en suelo trabaja principalmente erectores espinales, con participación de glúteos, isquiosurales, trapecio medio. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: usa una superficie plana, antideslizante y con espacio para todo el cuerpo. Coloca colchoneta si mejora comodidad, retira objetos cercanos y elige una inclinación o palanca que puedas sostener sin perder alineación desde la primera repetición.\",\"Posición inicial: base estable, rodillas alineadas, cadera y abdomen firmes, espalda en posición neutra y cabeza siguiendo el torso. Mantén cuello largo, pecho controlado, hombros bajos, escápulas estables y manos/muñecas/codos alineados con el apoyo o implemento.\",\"Agarre/apoyo: usa una sujeción cerrada y simétrica, con muñecas neutras. Ajusta la variante si el agarre limita la postura o provoca molestias antes que aumentar la carga.\",\"Inicio y trayectoria: Inicia el movimiento desde la articulación objetivo y dirige la carga con control. Siente principalmente erectores espinales; las articulaciones no móviles permanecen estables y el tronco no genera impulso.\",\"Rango y biomecánica: Usa el mayor recorrido cómodo que conserve alineación y tensión; evita rebotes, bloqueos agresivos y cualquier extremo que cambie la postura.\",\"Tempo y respiración: Tempo orientativo 2-1-3: esfuerzo en 2 s, pausa 1 s y retorno en 3 s. Exhala en el esfuerzo e inhala al regresar.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Pecho largo\",\"Hombros abajo\",\"Codos hacia costillas\",\"Cuello neutro\",\"Core firme\",\"Barra o cable cerca\",\"Sin tirón lumbar\",\"Controla el retorno\",\"Controla la fase de ida y vuelta\",\"Evita impulsos excesivos\"]","errores_comunes":"[\"Redondear o hiperextender la espalda\",\"Tirar con impulso\",\"Elevar hombros\",\"Sacar la cabeza\",\"Flexionar muñecas\",\"Acortar el estiramiento\",\"Mover cadera o torso\",\"Golpear la pila\",\"Usar impulso excesivo\",\"Perder postura\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Back Lever\",\"Dominadas / Pull-ups\",\"Front Lever\",\"Jalón al Pecho (Lat Pulldown)\",\"Remo con pecho apoyado\",\"Jalón al pecho con agarre neutro\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"cualquiera","objetivo":"general","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"10","rango_reps_max":"20","descanso_segundos_min":"30","descanso_segundos_max":"60","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"24","nombre":"Remo inclinado con mancuernas bilateral","aliases":"[\"Remo inclinado con mancuernas bilateral\",\"Remo inclinado mancuernas bilateral\",\"remo con dos mancuernas\",\"bent-over dumbbell row\",\"double dumbbell row\",\"Remo inclinado con DB bilateral\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"espalda","musculo_principal":"espalda media","musculos_secundarios":"[\"dorsal ancho\",\"romboides\",\"bíceps\",\"deltoides posterior\"]","equipamiento":"mancuernas","equipo_requerido":"[\"mancuernas\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"jalón horizontal","descripcion":"Remo inclinado con mancuernas bilateral trabaja principalmente espalda media, con participación de dorsal ancho, romboides, bíceps. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: elige mancuernas/kettlebell que puedas levantar y colocar sin impulso; despeja el área, comprueba cierres y usa banco estable si corresponde. Empieza con una carga que permita controlar la repetición y practica el montaje antes de la serie efectiva.\",\"Posición inicial: pies firmes al ancho adecuado, rodillas suaves, cadera atrás y columna neutra desde sacro hasta cabeza. Mantén abdomen presurizado, pecho largo, cuello alineado, hombros lejos de orejas y escápulas controladas; brazos cuelgan con muñecas rectas.\",\"Agarre: el neutro facilita llevar los codos junto al torso y suele ser cómodo; el prono algo más ancho desplaza énfasis hacia espalda alta y deltoide posterior; el supino añade bíceps. Elige uno que permita muñecas rectas y hombros bajos.\",\"Inicio y trayectoria: Inicia llevando los codos hacia atrás y ligeramente hacia el torso; la escápula se retrae/protrae de forma controlada sin elevar hombros. Siente dorsal y espalda media, no el cuello ni la zona lumbar.\",\"Rango y biomecánica: Tira hasta que el asa se acerque al tronco sin sobreextender hombro ni echarte atrás; retorna hasta brazos largos y escápulas que avancen sin redondear la columna. Cadera y torso permanecen estables.\",\"Tempo y respiración: Tira en 1–2 s, pausa 1 s con hombros bajos y retorna en 2–3 s. Exhala al remar e inhala al extender los brazos.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Pecho largo\",\"Hombros abajo\",\"Codos hacia costillas\",\"Cuello neutro\",\"Core firme\",\"Barra o cable cerca\",\"Sin tirón lumbar\",\"Controla el retorno\",\"Cadera atrás\",\"Torso inmóvil\"]","errores_comunes":"[\"Redondear o hiperextender la espalda\",\"Tirar con impulso\",\"Elevar hombros\",\"Sacar la cabeza\",\"Flexionar muñecas\",\"Acortar el estiramiento\",\"Mover cadera o torso\",\"Golpear la pila\",\"Redondear la espalda\",\"Convertirlo en encogimiento\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Remo con mancuerna a una mano\",\"Remo con barra\",\"Remo en polea baja\",\"Remo con pecho apoyado\",\"Jalón al pecho con agarre neutro\",\"Remo en polea sentado\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"8","rango_reps_max":"12","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"sf-cable-glute-kickback","nombre":"Patada de glúteo en polea","aliases":"[\"Patada de glúteo en polea\",\"patada de glúteo en polea baja\",\"extensión de cadera en polea\",\"cable glute kickback\",\"cable hip extension\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"glúteos","musculo_principal":"glúteo mayor","musculos_secundarios":"[\"isquiosurales\",\"core\",\"gluteo medio\"]","equipamiento":"polea baja, tobillera","equipo_requerido":"[\"polea baja\",\"tobillera\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"extension de cadera","descripcion":"Patada de glúteo en polea trabaja principalmente glúteo mayor, con participación de isquiosurales, core, glúteo medio. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Coloca la polea en el punto más bajo, conecta una tobillera y cierra ambos velcros sobre el tobillo. Verifica mosquetón y pasador; sujétate a la torre y aléjate hasta tener tensión sin levantar la pila en reposo. La cifra de la pila puede no equivaler a la resistencia efectiva por la relación de poleas; registra siempre la misma torre, ajuste y accesorio.\",\"Posición inicial: pies y rodillas alineados con el aparato o la trayectoria, pelvis nivelada y abdomen firme. Mantén espalda y cabeza neutras, pecho estable, hombros bajos, escápulas apoyadas cuando haya respaldo y manos sujetando las asas sin tirar.\",\"Agarre de soporte: toma las asas de la máquina con agarre neutro y pulgar cerrado; sirven para estabilizar pelvis y tronco, no para tirar del cuerpo. Mantén muñecas rectas y no sueltes hasta que el seguro o la pila estén completamente apoyados.\",\"Inicio y trayectoria: Mueve el fémur desde la cadera sin inclinar ni rotar la pelvis. Siente glúteo medio/mayor o aductores según la variante; rodilla, columna y tronco permanecen estables.\",\"Rango y biomecánica: Recorre solo hasta donde la pelvis siga nivelada y el músculo mantenga tensión; vuelve lentamente sin dejar que placas o piernas choquen.\",\"Tempo y respiración: Mueve en 2 s, pausa 1 s y retorna en 3 s. Exhala al separar/juntar o extender; inhala al volver.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Costillas hacia abajo\",\"Pelvis nivelada\",\"Empuja con todo el pie\",\"Aprieta glúteos\",\"No arquees la espalda\",\"Rodillas alineadas\",\"Pausa en contracción\",\"Baja con control\",\"Pelvis al frente\",\"Movimiento desde cadera\"]","errores_comunes":"[\"Hiperextender la zona lumbar\",\"Rotar la pelvis\",\"Empujar solo con puntas\",\"Abrir o cerrar rodillas\",\"Usar impulso\",\"Recortar el estiramiento\",\"Golpear la pila\",\"Perder tensión abdominal\",\"Arquear la espalda\",\"Girar la pelvis\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Evitar si causa dolor lumbar\",\"Reducir rango o carga\"]","sustituciones":"[\"Hip thrust con barra\",\"Puente de glúteo con carga\",\"Abducción de cadera con banda\",\"Puente de glúteo\",\"Hip thrust en máquina\",\"Patada de glúteo en polea\"]","progresiones":"[\"Aumentar carga\",\"Pausar atras\",\"Mas reps\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Puente de glúteo\",\"Patada sin carga\",\"Banda ligera\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"15","rango_reps_min":"12","rango_reps_max":"20","descanso_segundos_min":"45","descanso_segundos_max":"90","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"Functional Trainer","estado_calidad":"curado"},{"action":"update","id":"sf-hip-abduction-band","nombre":"Abducción de cadera con banda","aliases":"[\"Abducción de cadera con banda\",\"band hip abduction\",\"abducciones con banda\",\"Banded hip abduction\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"glúteos","musculo_principal":"gluteo medio","musculos_secundarios":"[\"gluteo menor\",\"gluteo mayor\",\"core\"]","equipamiento":"banda elastica","equipo_requerido":"[\"banda elastica\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"abduccion de cadera","descripcion":"Abducción de cadera con banda trabaja principalmente glúteo medio, con participación de glúteo menor, glúteo mayor, core. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación para Abducción de cadera con banda: revisa banda elástica, despeja el área y selecciona una carga o dificultad que puedas colocar y retirar sin impulso. Comprueba cierres, apoyos y estabilidad; ensaya una repetición lenta antes de la serie efectiva.\",\"Posición inicial: pies y rodillas alineados con el aparato o la trayectoria, pelvis nivelada y abdomen firme. Mantén espalda y cabeza neutras, pecho estable, hombros bajos, escápulas apoyadas cuando haya respaldo y manos sujetando las asas sin tirar.\",\"Agarre de soporte: sujeta asas o implemento con pulgar cerrado y muñecas neutras; las manos estabilizan, no tiran del cuerpo. En máquinas, no uses las asas para acortar el recorrido ni despegar la pelvis.\",\"Inicio y trayectoria: Mueve el fémur desde la cadera sin inclinar ni rotar la pelvis. Siente glúteo medio/mayor o aductores según la variante; rodilla, columna y tronco permanecen estables.\",\"Rango y biomecánica: Recorre solo hasta donde la pelvis siga nivelada y el músculo mantenga tensión; vuelve lentamente sin dejar que placas o piernas choquen.\",\"Tempo y respiración: Mueve en 2 s, pausa 1 s y retorna en 3 s. Exhala al separar/juntar o extender; inhala al volver.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Costillas hacia abajo\",\"Pelvis nivelada\",\"Empuja con todo el pie\",\"Aprieta glúteos\",\"No arquees la espalda\",\"Rodillas alineadas\",\"Pausa en contracción\",\"Baja con control\",\"Pelvis estable\",\"Tension continua\"]","errores_comunes":"[\"Hiperextender la zona lumbar\",\"Rotar la pelvis\",\"Empujar solo con puntas\",\"Abrir o cerrar rodillas\",\"Usar impulso\",\"Recortar el estiramiento\",\"Golpear la pila\",\"Perder tensión abdominal\",\"Moverse con impulso\",\"Perder tensión de banda\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Reducir tensión si hay dolor de cadera\"]","sustituciones":"[\"Patada de glúteo en polea\",\"Puente de glúteo\",\"Step-ups\",\"Hip thrust en máquina\"]","progresiones":"[\"Banda mas fuerte\",\"Pausas mas largas\",\"Mas reps\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Banda ligera\",\"Menor rango\",\"Sin banda\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"cualquiera","objetivo":"general","series_sugeridas":"3","repeticiones_sugeridas":"20","rango_reps_min":"15","rango_reps_max":"25","descanso_segundos_min":"30","descanso_segundos_max":"60","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"66","nombre":"Flexiones en pino asistidas en pared","aliases":"[\"Flexiones en pino asistidas en pared\",\"handstand push-up\",\"hspu\",\"Wall handstand push-up\"]","nivel":"avanzado","nivel_minimo":"avanzado","grupo_muscular":"hombros","musculo_principal":"deltoides anterior","musculos_secundarios":"[\"tríceps\",\"trapecio\",\"core\"]","equipamiento":"peso corporal, pared opcional","equipo_requerido":"[\"peso corporal\",\"pared opcional\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"empuje vertical","descripcion":"Flexiones en pino asistidas en pared trabaja principalmente deltoides anterior, con participación de tríceps, trapecio, core. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: usa pared despejada, piso antideslizante y una almohadilla fina para marcar profundidad, no para soportar peso. Practica primero pike push-up y la salida lateral; no inicies si no puedes bajar una pierna con control desde el pino.\",\"Posición inicial: manos algo más anchas que hombros a 15–30 cm de la pared, dedos abiertos y codos orientados 30–45° hacia atrás. Sube a pino con talones en pared; aprieta glúteos/abdomen, costillas dentro, piernas juntas, hombros activos y cuello neutro.\",\"Agarre: prono en barra/suelo o neutro en asas/mancuernas. Usa una anchura que deje antebrazos casi verticales; un agarre cerrado aumenta demanda de tríceps y uno muy ancho acorta el recorrido. Pulgar cerrado y muñeca apilada sobre antebrazo.\",\"Inicio y trayectoria: Flexiona codos y baja la coronilla hacia una almohadilla formando un trípode con manos; después empuja el suelo, extiende codos y termina elevando activamente los hombros. Siente deltoides/tríceps, no carga sobre el cuello.\",\"Rango y biomecánica: Baja solo hasta mantener antebrazos casi verticales y control cervical; usa almohadillas para reducir profundidad. Nunca descanses peso sobre la cabeza ni continúes si no puedes salir hacia un lado con seguridad.\",\"Tempo y respiración: Baja 3 s, pausa sin apoyar la cabeza y sube 1–2 s. Inhala al bajar y exhala al empujar; termina lejos del fallo.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: tras la última repetición, bloquea hombros activos, separa una pierna de la pared y baja un pie al suelo de forma lateral y controlada; luego el otro. No colapses sobre cabeza/cuello ni saltes hacia atrás.\"]","cues_tecnicos":"[\"Cuello largo\",\"Hombros lejos de orejas\",\"Core firme\",\"Muñecas neutras\",\"Codos guían\",\"Sin impulso lumbar\",\"Recorrido tolerable\",\"Excéntrica lenta\",\"Escápulas firmes\",\"Controla la bajada\"]","errores_comunes":"[\"Encoger hombros\",\"Arquear la zona lumbar\",\"Usar impulso\",\"Elevar por encima del rango tolerable\",\"Doblar muñecas\",\"Adelantar la cabeza\",\"Codos fuera de trayectoria\",\"Soltar la excéntrica\",\"Rebotar la carga\",\"Perder tensión escapular\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Evitar si provoca dolor agudo en hombro, muñeca o codo\",\"Reducir rango o usar alternativa si genera molestia\"]","sustituciones":"[\"Press de hombro con mancuernas\",\"Press militar con barra\",\"Variante unilateral en polea\",\"Variante con mancuernas sentado\",\"Máquina de hombro con agarre neutro\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"cualquiera","objetivo":"habilidad","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"3","rango_reps_max":"8","descanso_segundos_min":"120","descanso_segundos_max":"180","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"revisar"},{"action":"update","id":"4","nombre":"Press de hombro con mancuernas","aliases":"[\"Press de hombro con mancuernas\",\"Press de hombro mancuernas\",\"dumbbell shoulder press\",\"overhead dumbbell press\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"hombros","musculo_principal":"deltoides anterior","musculos_secundarios":"[\"deltoides lateral\",\"tríceps\",\"core\"]","equipamiento":"mancuernas, banco opcional","equipo_requerido":"[\"mancuernas\",\"banco opcional\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"empuje vertical","descripcion":"Press de hombro con mancuernas trabaja principalmente deltoides anterior, con participación de deltoides lateral, tríceps, core. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: elige mancuernas/kettlebell que puedas levantar y colocar sin impulso; despeja el área, comprueba cierres y usa banco estable si corresponde. Empieza con una carga que permita controlar la repetición y practica el montaje antes de la serie efectiva.\",\"Posición inicial: pies o apoyos firmes, rodillas y cadera estables, glúteos y abdomen contraídos. Conserva columna y cuello neutros, pecho controlado, hombros lejos de orejas y escápulas estables; apila manos, muñecas y codos según la dirección del empuje.\",\"Agarre: prono en barra/suelo o neutro en asas/mancuernas. Usa una anchura que deje antebrazos casi verticales; un agarre cerrado aumenta demanda de tríceps y uno muy ancho acorta el recorrido. Pulgar cerrado y muñeca apilada sobre antebrazo.\",\"Inicio y trayectoria: Inicia empujando el apoyo o la carga en la línea prevista mientras hombro y codo se extienden coordinados. Siente pectoral/deltoides/tríceps según la variante, con abdomen firme y hombros lejos de orejas.\",\"Rango y biomecánica: Baja hasta que el codo alcance una profundidad tolerable y el hombro conserve centrado, normalmente con antebrazo vertical; sube hasta brazos casi extendidos sin chocar ni hiperextender. Evita rebotes y extremos que despeguen espalda o pelvis.\",\"Tempo y respiración: Tempo base 3-0-1: desciende 3 s, pausa sin rebote y empuja en 1 s controlado. Inhala al bajar y exhala al cruzar el punto de mayor esfuerzo; usa respiración con brace solo si conoces la técnica.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Cuello largo\",\"Hombros lejos de orejas\",\"Core firme\",\"Muñecas neutras\",\"Codos guían\",\"Sin impulso lumbar\",\"Recorrido tolerable\",\"Excéntrica lenta\",\"Escápulas firmes\",\"Controla la bajada\"]","errores_comunes":"[\"Encoger hombros\",\"Arquear la zona lumbar\",\"Usar impulso\",\"Elevar por encima del rango tolerable\",\"Doblar muñecas\",\"Adelantar la cabeza\",\"Codos fuera de trayectoria\",\"Soltar la excéntrica\",\"Rebotar la carga\",\"Perder tensión escapular\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Evitar si provoca dolor agudo en hombro, muñeca o codo\",\"Reducir rango o usar alternativa si genera molestia\"]","sustituciones":"[\"Press militar con barra\",\"Flexiones en pino\",\"Variante unilateral en polea\",\"Variante con mancuernas sentado\",\"Máquina de hombro con agarre neutro\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"8","rango_reps_max":"12","descanso_segundos_min":"90","descanso_segundos_max":"150","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"6","nombre":"Elevaciones frontales con mancuernas","aliases":"[\"Elevaciones frontales con mancuernas\",\"Elevaciones frontales mancuernas\",\"front raise\",\"dumbbell front raise\",\"Elevaciones frontales con DB\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"hombros","musculo_principal":"deltoides anterior","musculos_secundarios":"[\"deltoides lateral\",\"trapecio superior\"]","equipamiento":"mancuernas","equipo_requerido":"[\"mancuernas\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"flexión de hombro","descripcion":"Elevaciones frontales con mancuernas trabaja principalmente deltoides anterior, con participación de deltoides lateral, trapecio superior. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: elige mancuernas/kettlebell que puedas levantar y colocar sin impulso; despeja el área, comprueba cierres y usa banco estable si corresponde. Empieza con una carga que permita controlar la repetición y practica el montaje antes de la serie efectiva.\",\"Posición inicial: pies al ancho de caderas, rodillas suaves, pelvis neutra y abdomen firme. Mantén columna erguida, cabeza/cuello neutros, pecho relajado, hombros bajos, escápulas controladas y manos/muñecas alineadas; coloca los codos según la trayectoria sin fijarlos con rigidez.\",\"Agarre: neutro o ligeramente prono con presión suave; la mano guía la trayectoria, no aprieta de más. Mantén muñeca alineada y elige una posición que no provoque pinzamiento en el hombro.\",\"Inicio y trayectoria: Eleva o separa los brazos desde el hombro con codos suaves; la escápula acompaña sin encoger los hombros. Siente deltoides y espalda alta, no trapecio superior ni impulso lumbar.\",\"Rango y biomecánica: Detén alrededor de la altura de hombro o antes si pierdes espacio articular; vuelve hasta tensión inicial sin dejar caer la carga. Mantén muñecas neutras y codos siguiendo la trayectoria.\",\"Tempo y respiración: Eleva en 2 s, pausa 1 s y baja en 3 s. Exhala al elevar/tirar e inhala al retornar.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Cuello largo\",\"Hombros lejos de orejas\",\"Core firme\",\"Muñecas neutras\",\"Codos guían\",\"Sin impulso lumbar\",\"Recorrido tolerable\",\"Excéntrica lenta\",\"Controla la fase de ida y vuelta\",\"Evita impulsos excesivos\"]","errores_comunes":"[\"Encoger hombros\",\"Arquear la zona lumbar\",\"Usar impulso\",\"Elevar por encima del rango tolerable\",\"Doblar muñecas\",\"Adelantar la cabeza\",\"Codos fuera de trayectoria\",\"Soltar la excéntrica\",\"Usar impulso excesivo\",\"Perder postura\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Elevaciones Laterales con Mancuernas\",\"Elevaciones Laterales en Polea\",\"Face Pulls (Polea alta)\",\"Variante unilateral en polea\",\"Variante con mancuernas sentado\",\"Máquina de hombro con agarre neutro\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"10","rango_reps_max":"15","descanso_segundos_min":"45","descanso_segundos_max":"90","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"5","nombre":"Elevaciones laterales con mancuernas","aliases":"[\"Elevaciones laterales con mancuernas\",\"Elevaciones laterales mancuernas\",\"dumbbell lateral raise\",\"lateral raises\",\"Elevaciones laterales con DB\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"hombros","musculo_principal":"deltoides lateral","musculos_secundarios":"[\"trapecio superior\"]","equipamiento":"mancuernas","equipo_requerido":"[\"mancuernas\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"elevación lateral","descripcion":"Elevaciones laterales con mancuernas trabaja principalmente deltoides lateral, con participación de trapecio superior. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: elige mancuernas/kettlebell que puedas levantar y colocar sin impulso; despeja el área, comprueba cierres y usa banco estable si corresponde. Empieza con una carga que permita controlar la repetición y practica el montaje antes de la serie efectiva.\",\"Posición inicial: pies al ancho de caderas, rodillas suaves, pelvis neutra y abdomen firme. Mantén columna erguida, cabeza/cuello neutros, pecho relajado, hombros bajos, escápulas controladas y manos/muñecas alineadas; coloca los codos según la trayectoria sin fijarlos con rigidez.\",\"Agarre: neutro o ligeramente prono con presión suave; la mano guía la trayectoria, no aprieta de más. Mantén muñeca alineada y elige una posición que no provoque pinzamiento en el hombro.\",\"Inicio y trayectoria: Eleva o separa los brazos desde el hombro con codos suaves; la escápula acompaña sin encoger los hombros. Siente deltoides y espalda alta, no trapecio superior ni impulso lumbar.\",\"Rango y biomecánica: Detén alrededor de la altura de hombro o antes si pierdes espacio articular; vuelve hasta tensión inicial sin dejar caer la carga. Mantén muñecas neutras y codos siguiendo la trayectoria.\",\"Tempo y respiración: Eleva en 2 s, pausa 1 s y baja en 3 s. Exhala al elevar/tirar e inhala al retornar.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Cuello largo\",\"Hombros lejos de orejas\",\"Core firme\",\"Muñecas neutras\",\"Codos guían\",\"Sin impulso lumbar\",\"Recorrido tolerable\",\"Excéntrica lenta\",\"Controla la fase de ida y vuelta\",\"Evita impulsos excesivos\"]","errores_comunes":"[\"Encoger hombros\",\"Arquear la zona lumbar\",\"Usar impulso\",\"Elevar por encima del rango tolerable\",\"Doblar muñecas\",\"Adelantar la cabeza\",\"Codos fuera de trayectoria\",\"Soltar la excéntrica\",\"Usar impulso excesivo\",\"Perder postura\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Elevaciones Frontales con Mancuernas\",\"Elevaciones Laterales en Polea\",\"Face Pulls (Polea alta)\",\"Variante unilateral en polea\",\"Variante con mancuernas sentado\",\"Máquina de hombro con agarre neutro\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"12","rango_reps_max":"20","descanso_segundos_min":"45","descanso_segundos_max":"90","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"51","nombre":"Elevaciones laterales en polea","aliases":"[\"Elevaciones laterales en polea\",\"elevación lateral en polea baja\",\"cable lateral raise\",\"single-arm cable lateral raise\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"hombros","musculo_principal":"deltoides lateral","musculos_secundarios":"[\"trapecio superior\"]","equipamiento":"polea baja, agarre","equipo_requerido":"[\"polea baja\",\"agarre\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"elevación lateral","descripcion":"Elevaciones laterales en polea trabaja principalmente deltoides lateral, con participación de trapecio superior. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Baja una polea al punto más bajo, conecta un asa individual y verifica el mosquetón. Sitúate de lado con el brazo de trabajo alejado; ajusta la distancia para que el cable cruce delante del cuerpo sin rozar piernas ni levantar la pila al inicio. La cifra de la pila puede no equivaler a la resistencia efectiva por la relación de poleas; registra siempre la misma torre, ajuste y accesorio.\",\"Posición inicial: pies al ancho de caderas, rodillas suaves, pelvis neutra y abdomen firme. Mantén columna erguida, cabeza/cuello neutros, pecho relajado, hombros bajos, escápulas controladas y manos/muñecas alineadas; coloca los codos según la trayectoria sin fijarlos con rigidez.\",\"Agarre: neutro o ligeramente prono con presión suave; la mano guía la trayectoria, no aprieta de más. Mantén muñeca alineada y elige una posición que no provoque pinzamiento en el hombro.\",\"Inicio y trayectoria: Eleva o separa los brazos desde el hombro con codos suaves; la escápula acompaña sin encoger los hombros. Siente deltoides y espalda alta, no trapecio superior ni impulso lumbar.\",\"Rango y biomecánica: Detén alrededor de la altura de hombro o antes si pierdes espacio articular; vuelve hasta tensión inicial sin dejar caer la carga. Mantén muñecas neutras y codos siguiendo la trayectoria.\",\"Tempo y respiración: Eleva en 2 s, pausa 1 s y baja en 3 s. Exhala al elevar/tirar e inhala al retornar.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Cuello largo\",\"Hombros lejos de orejas\",\"Core firme\",\"Muñecas neutras\",\"Codos guían\",\"Sin impulso lumbar\",\"Recorrido tolerable\",\"Excéntrica lenta\",\"Hombro bajo\",\"Codo suave\"]","errores_comunes":"[\"Encoger hombros\",\"Arquear la zona lumbar\",\"Usar impulso\",\"Elevar por encima del rango tolerable\",\"Doblar muñecas\",\"Adelantar la cabeza\",\"Codos fuera de trayectoria\",\"Soltar la excéntrica\",\"Encoger el hombro\",\"Balancear el torso\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Elevaciones Frontales con Mancuernas\",\"Elevaciones Laterales con Mancuernas\",\"Face Pulls (Polea alta)\",\"Variante unilateral en polea\",\"Variante con mancuernas sentado\",\"Máquina de hombro con agarre neutro\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"12","rango_reps_max":"20","descanso_segundos_min":"45","descanso_segundos_max":"90","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"Dual Adjustable Pulley","estado_calidad":"curado"},{"action":"update","id":"7","nombre":"Elevaciones posteriores con mancuernas (pájaros)","aliases":"[\"Elevaciones posteriores con mancuernas (pájaros)\",\"Elevaciones posteriores mancuernas (pájaros)\",\"reverse fly\",\"rear delt fly\",\"Bent-over rear-delt raise\",\"Elevaciones posteriores con DB (pájaros)\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"hombros","musculo_principal":"deltoides posterior","musculos_secundarios":"[\"romboides\",\"trapecio medio\"]","equipamiento":"mancuernas","equipo_requerido":"[\"mancuernas\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"abducción horizontal","descripcion":"Elevaciones posteriores con mancuernas (pájaros) trabaja principalmente deltoides posterior, con participación de romboides, trapecio medio. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: elige mancuernas/kettlebell que puedas levantar y colocar sin impulso; despeja el área, comprueba cierres y usa banco estable si corresponde. Empieza con una carga que permita controlar la repetición y practica el montaje antes de la serie efectiva.\",\"Posición inicial: pies al ancho de caderas, rodillas suaves, pelvis neutra y abdomen firme. Mantén columna erguida, cabeza/cuello neutros, pecho relajado, hombros bajos, escápulas controladas y manos/muñecas alineadas; coloca los codos según la trayectoria sin fijarlos con rigidez.\",\"Agarre: neutro o ligeramente prono con presión suave; la mano guía la trayectoria, no aprieta de más. Mantén muñeca alineada y elige una posición que no provoque pinzamiento en el hombro.\",\"Inicio y trayectoria: Eleva o separa los brazos desde el hombro con codos suaves; la escápula acompaña sin encoger los hombros. Siente deltoides y espalda alta, no trapecio superior ni impulso lumbar.\",\"Rango y biomecánica: Detén alrededor de la altura de hombro o antes si pierdes espacio articular; vuelve hasta tensión inicial sin dejar caer la carga. Mantén muñecas neutras y codos siguiendo la trayectoria.\",\"Tempo y respiración: Eleva en 2 s, pausa 1 s y baja en 3 s. Exhala al elevar/tirar e inhala al retornar.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Cuello largo\",\"Hombros lejos de orejas\",\"Core firme\",\"Muñecas neutras\",\"Codos guían\",\"Sin impulso lumbar\",\"Recorrido tolerable\",\"Excéntrica lenta\",\"Controla la fase de ida y vuelta\",\"Evita impulsos excesivos\"]","errores_comunes":"[\"Encoger hombros\",\"Arquear la zona lumbar\",\"Usar impulso\",\"Elevar por encima del rango tolerable\",\"Doblar muñecas\",\"Adelantar la cabeza\",\"Codos fuera de trayectoria\",\"Soltar la excéntrica\",\"Usar impulso excesivo\",\"Perder postura\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Elevaciones Frontales con Mancuernas\",\"Elevaciones Laterales con Mancuernas\",\"Elevaciones Laterales en Polea\",\"Face Pulls (Polea alta)\",\"Variante unilateral en polea\",\"Variante con mancuernas sentado\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"12","rango_reps_max":"20","descanso_segundos_min":"45","descanso_segundos_max":"90","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"52","nombre":"Face pull en polea alta","aliases":"[\"Face pull en polea alta\",\"tirón a la cara\",\"face pull con cuerda\",\"cable face pull\",\"rope face pull\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"hombros","musculo_principal":"deltoides posterior","musculos_secundarios":"[\"trapecio medio\",\"rotadores externos\",\"romboides\"]","equipamiento":"polea alta, cuerda","equipo_requerido":"[\"polea alta\",\"cuerda\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"jalón horizontal","descripcion":"Face pull en polea alta trabaja principalmente deltoides posterior, con participación de trapecio medio, rotadores externos, romboides. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Ajusta la polea a la altura de ojos o ligeramente por encima, conecta cuerda y verifica mosquetón/pasador. Retrocede hasta tensar el cable y usa una carga con la que el torso no sea arrastrado hacia la torre. La cifra de la pila puede no equivaler a la resistencia efectiva por la relación de poleas; registra siempre la misma torre, ajuste y accesorio.\",\"Posición inicial: pies al ancho de caderas, rodillas suaves, pelvis neutra y abdomen firme. Mantén columna erguida, cabeza/cuello neutros, pecho relajado, hombros bajos, escápulas controladas y manos/muñecas alineadas; coloca los codos según la trayectoria sin fijarlos con rigidez.\",\"Agarre: neutro o ligeramente prono con presión suave; la mano guía la trayectoria, no aprieta de más. Mantén muñeca alineada y elige una posición que no provoque pinzamiento en el hombro.\",\"Inicio y trayectoria: Eleva o separa los brazos desde el hombro con codos suaves; la escápula acompaña sin encoger los hombros. Siente deltoides y espalda alta, no trapecio superior ni impulso lumbar.\",\"Rango y biomecánica: Detén alrededor de la altura de hombro o antes si pierdes espacio articular; vuelve hasta tensión inicial sin dejar caer la carga. Mantén muñecas neutras y codos siguiendo la trayectoria.\",\"Tempo y respiración: Eleva en 2 s, pausa 1 s y baja en 3 s. Exhala al elevar/tirar e inhala al retornar.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Cuello largo\",\"Hombros lejos de orejas\",\"Core firme\",\"Muñecas neutras\",\"Codos guían\",\"Sin impulso lumbar\",\"Recorrido tolerable\",\"Excéntrica lenta\",\"Cuerda hacia la frente\",\"Separa los extremos\"]","errores_comunes":"[\"Encoger hombros\",\"Arquear la zona lumbar\",\"Usar impulso\",\"Elevar por encima del rango tolerable\",\"Doblar muñecas\",\"Adelantar la cabeza\",\"Codos fuera de trayectoria\",\"Soltar la excéntrica\",\"Jalar hacia el pecho\",\"Arquear la espalda\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Remo con mancuerna a una mano\",\"Remo con barra\",\"Remo en polea baja\",\"Variante unilateral en polea\",\"Variante con mancuernas sentado\",\"Máquina de hombro con agarre neutro\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"12","rango_reps_max":"20","descanso_segundos_min":"45","descanso_segundos_max":"90","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"Functional Trainer","estado_calidad":"curado"},{"action":"update","id":"sf-chest-machine-press","nombre":"Press de pecho en máquina","aliases":"[\"Press de pecho en máquina\",\"Press de pecho máquina\",\"press de pecho sentado\",\"press pectoral en máquina\",\"machine chest press\",\"seated chest press\",\"Selectorized chest press\",\"Press de pecho en máq.\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"pecho","musculo_principal":"pectoral mayor","musculos_secundarios":"[\"triceps\",\"deltoides anterior\"]","equipamiento":"máquina de press de pecho","equipo_requerido":"[\"máquina de press de pecho\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"empuje horizontal en maquina","descripcion":"Press de pecho en máquina trabaja principalmente pectoral mayor, con participación de tríceps, deltoides anterior. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Ajusta el asiento para que las empuñaduras queden a la altura del pecho medio y los antebrazos queden aproximadamente perpendiculares al suelo. Regula la posición inicial si existe palanca, apoya cabeza/espalda y coloca el pasador por completo; no empieces con los codos excesivamente detrás del torso.\",\"Posición inicial: pies o apoyos firmes, rodillas y cadera estables, glúteos y abdomen contraídos. Conserva columna y cuello neutros, pecho controlado, hombros lejos de orejas y escápulas estables; apila manos, muñecas y codos según la dirección del empuje.\",\"Agarre: prono en barra/suelo o neutro en asas/mancuernas. Usa una anchura que deje antebrazos casi verticales; un agarre cerrado aumenta demanda de tríceps y uno muy ancho acorta el recorrido. Pulgar cerrado y muñeca apilada sobre antebrazo.\",\"Inicio y trayectoria: Inicia empujando el apoyo o la carga en la línea prevista mientras hombro y codo se extienden coordinados. Siente pectoral/deltoides/tríceps según la variante, con abdomen firme y hombros lejos de orejas.\",\"Rango y biomecánica: Baja hasta que el codo alcance una profundidad tolerable y el hombro conserve centrado, normalmente con antebrazo vertical; sube hasta brazos casi extendidos sin chocar ni hiperextender. Evita rebotes y extremos que despeguen espalda o pelvis.\",\"Tempo y respiración: Tempo base 3-0-1: desciende 3 s, pausa sin rebote y empuja en 1 s controlado. Inhala al bajar y exhala al cruzar el punto de mayor esfuerzo; usa respiración con brace solo si conoces la técnica.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Pies firmes\",\"Glúteos apoyados\",\"Escápulas estables\",\"Pecho controlado\",\"Antebrazos verticales\",\"Muñecas apiladas\",\"Empuja sin rebotar\",\"Baja con control\",\"Manijas a mitad del pecho\",\"Escápulas apoyadas\"]","errores_comunes":"[\"Despegar glúteos o espalda\",\"Rebotar en el pecho o topes\",\"Abrir codos sin control\",\"Doblar muñecas\",\"Elevar hombros\",\"Recortar recorrido\",\"Bloquear codos con golpe\",\"Usar carga sin salida segura\",\"Asiento demasiado bajo\",\"Hombros adelantados\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Evitar si la máquina obliga a dolor de hombro\",\"Ajustar asiento o usar mancuernas\"]","sustituciones":"[\"Press de banca con mancuernas\",\"Press de banca con barra\",\"Lagartijas\",\"Press con mancuernas\",\"Press de pecho en máquina\",\"Flexiones con manos elevadas\"]","progresiones":"[\"Aumentar carga\",\"Pausar en estiramiento\",\"Tempo lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Menor carga\",\"Lagartijas inclinadas\",\"Press con mancuernas ligero\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"12","rango_reps_min":"8","rango_reps_max":"12","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"Chest Press Machine","estado_calidad":"curado"},{"action":"update","id":"32","nombre":"Press inclinado con barra","aliases":"[\"Press inclinado con barra\",\"Press inclinado barra\",\"press de banca inclinado con barra\",\"incline barbell bench press\",\"incline bench press\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"pecho","musculo_principal":"pectoral superior","musculos_secundarios":"[\"deltoides anterior\",\"triceps\"]","equipamiento":"barra, banco inclinado, discos","equipo_requerido":"[\"barra\",\"banco inclinado\",\"discos\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"empuje horizontal inclinado","descripcion":"Press inclinado con barra trabaja principalmente pectoral superior, con participación de deltoides anterior, tríceps. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: coloca la barra en un rack a una altura que permita sacarla sin encoger hombros ni ponerte de puntillas. Carga ambos lados por igual, usa seguros de disco y topes de seguridad; ensaya el recorrido con la barra vacía y pide spotter cuando la carga o el ejercicio lo amerite.\",\"Posición inicial: pies completos y separados al ancho de caderas, rodillas estables, glúteos y parte alta de la espalda apoyados. Mantén una curva lumbar natural, pecho elevado sin hiperextender, cabeza/cuello neutros, hombros abajo y escápulas apoyadas; alinea codos y muñecas con la carga.\",\"Agarre: prono en barra/suelo o neutro en asas/mancuernas. Usa una anchura que deje antebrazos casi verticales; un agarre cerrado aumenta demanda de tríceps y uno muy ancho acorta el recorrido. Pulgar cerrado y muñeca apilada sobre antebrazo.\",\"Inicio y trayectoria: Inicia empujando el apoyo o la carga en la línea prevista mientras hombro y codo se extienden coordinados. Siente pectoral/deltoides/tríceps según la variante, con abdomen firme y hombros lejos de orejas.\",\"Rango y biomecánica: Baja hasta que el codo alcance una profundidad tolerable y el hombro conserve centrado, normalmente con antebrazo vertical; sube hasta brazos casi extendidos sin chocar ni hiperextender. Evita rebotes y extremos que despeguen espalda o pelvis.\",\"Tempo y respiración: Tempo base 3-0-1: desciende 3 s, pausa sin rebote y empuja en 1 s controlado. Inhala al bajar y exhala al cruzar el punto de mayor esfuerzo; usa respiración con brace solo si conoces la técnica.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Pies firmes\",\"Glúteos apoyados\",\"Escápulas estables\",\"Pecho controlado\",\"Antebrazos verticales\",\"Muñecas apiladas\",\"Empuja sin rebotar\",\"Baja con control\",\"Banco moderadamente inclinado\",\"Escápulas apoyadas\"]","errores_comunes":"[\"Despegar glúteos o espalda\",\"Rebotar en el pecho o topes\",\"Abrir codos sin control\",\"Doblar muñecas\",\"Elevar hombros\",\"Recortar recorrido\",\"Bloquear codos con golpe\",\"Usar carga sin salida segura\",\"Banco demasiado vertical\",\"Codos totalmente abiertos\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Evitar si causa dolor de hombro\",\"Usar mancuernas si la barra molesta\"]","sustituciones":"[\"Press inclinado con mancuernas\",\"Press de banca con barra\",\"Press en máquina de pecho\",\"Press con mancuernas\",\"Press de pecho en máquina\",\"Flexiones con manos elevadas\"]","progresiones":"[\"Aumentar carga\",\"Pausa en pecho\",\"Tempo lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Press inclinado con mancuernas ligero\",\"Lagartijas inclinadas\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"4","repeticiones_sugeridas":"8","rango_reps_min":"6","rango_reps_max":"10","descanso_segundos_min":"120","descanso_segundos_max":"180","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"sf-press-incline-db","nombre":"Press inclinado con mancuernas","aliases":"[\"Press inclinado con mancuernas\",\"Press inclinado mancuernas\",\"incline dumbbell press\",\"dumbbell incline bench press\",\"Incline dumbbell bench press\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"pecho","musculo_principal":"pectoral superior","musculos_secundarios":"[\"deltoides anterior\",\"triceps\"]","equipamiento":"mancuernas, banco inclinado","equipo_requerido":"[\"mancuernas\",\"banco inclinado\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"empuje horizontal inclinado","descripcion":"Press inclinado con mancuernas trabaja principalmente pectoral superior, con participación de deltoides anterior, tríceps. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: elige mancuernas/kettlebell que puedas levantar y colocar sin impulso; despeja el área, comprueba cierres y usa banco estable si corresponde. Empieza con una carga que permita controlar la repetición y practica el montaje antes de la serie efectiva.\",\"Posición inicial: pies completos y separados al ancho de caderas, rodillas estables, glúteos y parte alta de la espalda apoyados. Mantén una curva lumbar natural, pecho elevado sin hiperextender, cabeza/cuello neutros, hombros abajo y escápulas apoyadas; alinea codos y muñecas con la carga.\",\"Agarre: prono en barra/suelo o neutro en asas/mancuernas. Usa una anchura que deje antebrazos casi verticales; un agarre cerrado aumenta demanda de tríceps y uno muy ancho acorta el recorrido. Pulgar cerrado y muñeca apilada sobre antebrazo.\",\"Inicio y trayectoria: Inicia empujando el apoyo o la carga en la línea prevista mientras hombro y codo se extienden coordinados. Siente pectoral/deltoides/tríceps según la variante, con abdomen firme y hombros lejos de orejas.\",\"Rango y biomecánica: Baja hasta que el codo alcance una profundidad tolerable y el hombro conserve centrado, normalmente con antebrazo vertical; sube hasta brazos casi extendidos sin chocar ni hiperextender. Evita rebotes y extremos que despeguen espalda o pelvis.\",\"Tempo y respiración: Tempo base 3-0-1: desciende 3 s, pausa sin rebote y empuja en 1 s controlado. Inhala al bajar y exhala al cruzar el punto de mayor esfuerzo; usa respiración con brace solo si conoces la técnica.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Pies firmes\",\"Glúteos apoyados\",\"Escápulas estables\",\"Pecho controlado\",\"Antebrazos verticales\",\"Muñecas apiladas\",\"Empuja sin rebotar\",\"Baja con control\",\"Escápulas apoyadas\",\"Muñeca sobre codo\"]","errores_comunes":"[\"Despegar glúteos o espalda\",\"Rebotar en el pecho o topes\",\"Abrir codos sin control\",\"Doblar muñecas\",\"Elevar hombros\",\"Recortar recorrido\",\"Bloquear codos con golpe\",\"Usar carga sin salida segura\",\"Banco demasiado vertical\",\"Chocar mancuernas\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Evitar si causa dolor anterior de hombro\",\"Reducir inclinacion o carga\"]","sustituciones":"[\"Press inclinado con barra\",\"Press de banca con mancuernas\",\"Lagartijas declinadas\",\"Press con mancuernas\",\"Press de pecho en máquina\",\"Flexiones con manos elevadas\"]","progresiones":"[\"Aumentar carga\",\"Pausar abajo\",\"Tempo lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Press plano con mancuernas\",\"Lagartijas inclinadas\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"cualquiera","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"12","descanso_segundos_min":"90","descanso_segundos_max":"150","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"33","nombre":"Fondos en paralelas para pecho","aliases":"[\"Fondos en paralelas para pecho\",\"fondos para pecho\",\"dips inclinados\",\"chest dips\",\"parallel bar chest dips\",\"Chest dip\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"pecho","musculo_principal":"pectoral inferior","musculos_secundarios":"[\"tríceps\",\"deltoides anterior\"]","equipamiento":"barras paralelas","equipo_requerido":"[\"barras paralelas\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"empuje vertical","descripcion":"Fondos en paralelas para pecho trabaja principalmente pectoral inferior, con participación de tríceps, deltoides anterior. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación para Fondos en paralelas para pecho: revisa barras paralelas, despeja el área y selecciona una carga o dificultad que puedas colocar y retirar sin impulso. Comprueba cierres, apoyos y estabilidad; ensaya una repetición lenta antes de la serie efectiva.\",\"Posición inicial: pies o apoyos firmes, rodillas y cadera estables, glúteos y abdomen contraídos. Conserva columna y cuello neutros, pecho controlado, hombros lejos de orejas y escápulas estables; apila manos, muñecas y codos según la dirección del empuje.\",\"Agarre: prono en barra/suelo o neutro en asas/mancuernas. Usa una anchura que deje antebrazos casi verticales; un agarre cerrado aumenta demanda de tríceps y uno muy ancho acorta el recorrido. Pulgar cerrado y muñeca apilada sobre antebrazo.\",\"Inicio y trayectoria: Inicia empujando el apoyo o la carga en la línea prevista mientras hombro y codo se extienden coordinados. Siente pectoral/deltoides/tríceps según la variante, con abdomen firme y hombros lejos de orejas.\",\"Rango y biomecánica: Baja hasta que el codo alcance una profundidad tolerable y el hombro conserve centrado, normalmente con antebrazo vertical; sube hasta brazos casi extendidos sin chocar ni hiperextender. Evita rebotes y extremos que despeguen espalda o pelvis.\",\"Tempo y respiración: Tempo base 3-0-1: desciende 3 s, pausa sin rebote y empuja en 1 s controlado. Inhala al bajar y exhala al cruzar el punto de mayor esfuerzo; usa respiración con brace solo si conoces la técnica.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Pies firmes\",\"Glúteos apoyados\",\"Escápulas estables\",\"Pecho controlado\",\"Antebrazos verticales\",\"Muñecas apiladas\",\"Empuja sin rebotar\",\"Baja con control\",\"Torso ligeramente inclinado\",\"Hombros bajos\"]","errores_comunes":"[\"Despegar glúteos o espalda\",\"Rebotar en el pecho o topes\",\"Abrir codos sin control\",\"Doblar muñecas\",\"Elevar hombros\",\"Recortar recorrido\",\"Bloquear codos con golpe\",\"Usar carga sin salida segura\",\"Bajar demasiado\",\"Encoger hombros\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Evitar con dolor anterior de hombro o inestabilidad\",\"Usar máquina asistida o press de pecho como regresión\"]","sustituciones":"[\"Press de hombro con mancuernas\",\"Press militar con barra\",\"Flexiones en pino\",\"Press con mancuernas\",\"Press de pecho en máquina\",\"Flexiones con manos elevadas\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"6","rango_reps_max":"12","descanso_segundos_min":"90","descanso_segundos_max":"150","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"50","nombre":"Aperturas en polea","aliases":"[\"Aperturas en polea\",\"cruce de poleas\",\"aperturas con cable\",\"cable fly\",\"cable crossover\",\"Cable crossover fly\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"pecho","musculo_principal":"pectoral mayor","musculos_secundarios":"[\"deltoides anterior\"]","equipamiento":"estación de poleas dobles, agarres","equipo_requerido":"[\"poleas dobles\",\"agarres\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"apertura horizontal","descripcion":"Aperturas en polea trabaja principalmente pectoral mayor, con participación de deltoides anterior. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Coloca ambas poleas a la misma altura —media para una apertura horizontal—, conecta asas iguales y comprueba ambos mosquetones. Selecciona la misma carga en las dos torres; toma un asa a la vez, avanza al centro y adopta una base escalonada estable. La cifra de la pila puede no equivaler a la resistencia efectiva por la relación de poleas; registra siempre la misma torre, ajuste y accesorio.\",\"Posición inicial: base estable, rodillas alineadas, cadera y abdomen firmes, espalda en posición neutra y cabeza siguiendo el torso. Mantén cuello largo, pecho controlado, hombros bajos, escápulas estables y manos/muñecas/codos alineados con el apoyo o implemento.\",\"Agarre/apoyo: usa una sujeción cerrada y simétrica, con muñecas neutras. Ajusta la variante si el agarre limita la postura o provoca molestias antes que aumentar la carga.\",\"Inicio y trayectoria: Inicia el movimiento desde la articulación objetivo y dirige la carga con control. Siente principalmente pectoral mayor; las articulaciones no móviles permanecen estables y el tronco no genera impulso.\",\"Rango y biomecánica: Usa el mayor recorrido cómodo que conserve alineación y tensión; evita rebotes, bloqueos agresivos y cualquier extremo que cambie la postura.\",\"Tempo y respiración: Tempo orientativo 2-1-3: esfuerzo en 2 s, pausa 1 s y retorno en 3 s. Exhala en el esfuerzo e inhala al regresar.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Pies firmes\",\"Glúteos apoyados\",\"Escápulas estables\",\"Pecho controlado\",\"Antebrazos verticales\",\"Muñecas apiladas\",\"Empuja sin rebotar\",\"Baja con control\",\"Codos suaves\",\"Arco amplio\"]","errores_comunes":"[\"Despegar glúteos o espalda\",\"Rebotar en el pecho o topes\",\"Abrir codos sin control\",\"Doblar muñecas\",\"Elevar hombros\",\"Recortar recorrido\",\"Bloquear codos con golpe\",\"Usar carga sin salida segura\",\"Flexionar demasiado los codos\",\"Usar impulso\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Aperturas con Mancuernas (Plano/Inclinado)\",\"Aperturas en Polea (Cable Flyes)\",\"Clapping Push-ups (Flexiones con palmada)\",\"Fondos en Paralelas (Dips para Pecho)\",\"Press con mancuernas\",\"Press de pecho en máquina\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"10","rango_reps_max":"15","descanso_segundos_min":"45","descanso_segundos_max":"90","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"Cable Crossover","estado_calidad":"curado"},{"action":"update","id":"2","nombre":"Flexiones de pecho","aliases":"[\"Flexiones de pecho\",\"push-ups\",\"flexiones\",\"push ups\",\"Push-up\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"pecho","musculo_principal":"pectoral mayor","musculos_secundarios":"[\"tríceps\",\"deltoides anterior\",\"core\"]","equipamiento":"peso corporal","equipo_requerido":"[\"peso corporal\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"empuje horizontal","descripcion":"Flexiones de pecho trabaja principalmente pectoral mayor, con participación de tríceps, deltoides anterior, core. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: usa una superficie plana, antideslizante y con espacio para todo el cuerpo. Coloca colchoneta si mejora comodidad, retira objetos cercanos y elige una inclinación o palanca que puedas sostener sin perder alineación desde la primera repetición.\",\"Posición inicial: pies o apoyos firmes, rodillas y cadera estables, glúteos y abdomen contraídos. Conserva columna y cuello neutros, pecho controlado, hombros lejos de orejas y escápulas estables; apila manos, muñecas y codos según la dirección del empuje.\",\"Agarre: prono en barra/suelo o neutro en asas/mancuernas. Usa una anchura que deje antebrazos casi verticales; un agarre cerrado aumenta demanda de tríceps y uno muy ancho acorta el recorrido. Pulgar cerrado y muñeca apilada sobre antebrazo.\",\"Inicio y trayectoria: Inicia empujando el apoyo o la carga en la línea prevista mientras hombro y codo se extienden coordinados. Siente pectoral/deltoides/tríceps según la variante, con abdomen firme y hombros lejos de orejas.\",\"Rango y biomecánica: Baja hasta que el codo alcance una profundidad tolerable y el hombro conserve centrado, normalmente con antebrazo vertical; sube hasta brazos casi extendidos sin chocar ni hiperextender. Evita rebotes y extremos que despeguen espalda o pelvis.\",\"Tempo y respiración: Tempo base 3-0-1: desciende 3 s, pausa sin rebote y empuja en 1 s controlado. Inhala al bajar y exhala al cruzar el punto de mayor esfuerzo; usa respiración con brace solo si conoces la técnica.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Pies firmes\",\"Glúteos apoyados\",\"Escápulas estables\",\"Pecho controlado\",\"Antebrazos verticales\",\"Muñecas apiladas\",\"Empuja sin rebotar\",\"Baja con control\",\"Escápulas firmes\",\"Controla la bajada\"]","errores_comunes":"[\"Despegar glúteos o espalda\",\"Rebotar en el pecho o topes\",\"Abrir codos sin control\",\"Doblar muñecas\",\"Elevar hombros\",\"Recortar recorrido\",\"Bloquear codos con golpe\",\"Usar carga sin salida segura\",\"Rebotar la carga\",\"Perder tensión escapular\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Evitar si provoca dolor agudo en hombro, muñeca o codo\",\"Reducir rango o usar alternativa si genera molestia\"]","sustituciones":"[\"Press de banca con mancuernas\",\"Press de banca con barra\",\"Aperturas en polea\",\"Press con mancuernas\",\"Press de pecho en máquina\",\"Flexiones con manos elevadas\"]","progresiones":"[\"Flexiones declinadas\",\"Flexiones con pausa\",\"Flexiones lastradas\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Flexiones inclinadas\",\"Flexiones con rodillas apoyadas\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"cualquiera","objetivo":"general","series_sugeridas":"0","repeticiones_sugeridas":"0","rango_reps_min":"8","rango_reps_max":"20","descanso_segundos_min":"45","descanso_segundos_max":"90","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"31","nombre":"Press de banca con barra","aliases":"[\"Press de banca con barra\",\"Press de banca barra\",\"bench press\",\"barbell bench press\",\"press banca\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"pecho","musculo_principal":"pectoral mayor","musculos_secundarios":"[\"tríceps\",\"deltoides anterior\"]","equipamiento":"barra, banco, discos","equipo_requerido":"[\"barra\",\"banco\",\"discos\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"empuje horizontal","descripcion":"Press de banca con barra trabaja principalmente pectoral mayor, con participación de tríceps, deltoides anterior. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: coloca la barra en un rack a una altura que permita sacarla sin encoger hombros ni ponerte de puntillas. Carga ambos lados por igual, usa seguros de disco y topes de seguridad; ensaya el recorrido con la barra vacía y pide spotter cuando la carga o el ejercicio lo amerite.\",\"Posición inicial: pies completos y separados al ancho de caderas, rodillas estables, glúteos y parte alta de la espalda apoyados. Mantén una curva lumbar natural, pecho elevado sin hiperextender, cabeza/cuello neutros, hombros abajo y escápulas apoyadas; alinea codos y muñecas con la carga.\",\"Agarre: prono en barra/suelo o neutro en asas/mancuernas. Usa una anchura que deje antebrazos casi verticales; un agarre cerrado aumenta demanda de tríceps y uno muy ancho acorta el recorrido. Pulgar cerrado y muñeca apilada sobre antebrazo.\",\"Inicio y trayectoria: Inicia empujando el apoyo o la carga en la línea prevista mientras hombro y codo se extienden coordinados. Siente pectoral/deltoides/tríceps según la variante, con abdomen firme y hombros lejos de orejas.\",\"Rango y biomecánica: Baja hasta que el codo alcance una profundidad tolerable y el hombro conserve centrado, normalmente con antebrazo vertical; sube hasta brazos casi extendidos sin chocar ni hiperextender. Evita rebotes y extremos que despeguen espalda o pelvis.\",\"Tempo y respiración: Tempo base 3-0-1: desciende 3 s, pausa sin rebote y empuja en 1 s controlado. Inhala al bajar y exhala al cruzar el punto de mayor esfuerzo; usa respiración con brace solo si conoces la técnica.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Pies firmes\",\"Glúteos apoyados\",\"Escápulas estables\",\"Pecho controlado\",\"Antebrazos verticales\",\"Muñecas apiladas\",\"Empuja sin rebotar\",\"Baja con control\",\"Escápulas firmes\",\"Controla la bajada\"]","errores_comunes":"[\"Despegar glúteos o espalda\",\"Rebotar en el pecho o topes\",\"Abrir codos sin control\",\"Doblar muñecas\",\"Elevar hombros\",\"Recortar recorrido\",\"Bloquear codos con golpe\",\"Usar carga sin salida segura\",\"Rebotar la carga\",\"Perder tensión escapular\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Evitar si provoca dolor agudo en hombro, muñeca o codo\",\"Reducir rango o usar alternativa si genera molestia\"]","sustituciones":"[\"Press de banca con mancuernas\",\"Lagartijas\",\"Aperturas en polea\",\"Press con mancuernas\",\"Press de pecho en máquina\",\"Flexiones con manos elevadas\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"fuerza","series_sugeridas":"0","repeticiones_sugeridas":"0","rango_reps_min":"5","rango_reps_max":"10","descanso_segundos_min":"120","descanso_segundos_max":"180","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"1","nombre":"Press de banca con mancuernas","aliases":"[\"Press de banca con mancuernas\",\"Press de banca mancuernas\",\"dumbbell bench press\",\"press plano con mancuernas\",\"press inclinado con mancuernas\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"pecho","musculo_principal":"pectoral mayor","musculos_secundarios":"[\"tríceps\",\"deltoides anterior\"]","equipamiento":"mancuernas, banco","equipo_requerido":"[\"mancuernas\",\"banco\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"empuje horizontal","descripcion":"Press de banca con mancuernas trabaja principalmente pectoral mayor, con participación de tríceps, deltoides anterior. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: coloca la barra en un rack a una altura que permita sacarla sin encoger hombros ni ponerte de puntillas. Carga ambos lados por igual, usa seguros de disco y topes de seguridad; ensaya el recorrido con la barra vacía y pide spotter cuando la carga o el ejercicio lo amerite.\",\"Posición inicial: pies completos y separados al ancho de caderas, rodillas estables, glúteos y parte alta de la espalda apoyados. Mantén una curva lumbar natural, pecho elevado sin hiperextender, cabeza/cuello neutros, hombros abajo y escápulas apoyadas; alinea codos y muñecas con la carga.\",\"Agarre: prono en barra/suelo o neutro en asas/mancuernas. Usa una anchura que deje antebrazos casi verticales; un agarre cerrado aumenta demanda de tríceps y uno muy ancho acorta el recorrido. Pulgar cerrado y muñeca apilada sobre antebrazo.\",\"Inicio y trayectoria: Inicia empujando el apoyo o la carga en la línea prevista mientras hombro y codo se extienden coordinados. Siente pectoral/deltoides/tríceps según la variante, con abdomen firme y hombros lejos de orejas.\",\"Rango y biomecánica: Baja hasta que el codo alcance una profundidad tolerable y el hombro conserve centrado, normalmente con antebrazo vertical; sube hasta brazos casi extendidos sin chocar ni hiperextender. Evita rebotes y extremos que despeguen espalda o pelvis.\",\"Tempo y respiración: Tempo base 3-0-1: desciende 3 s, pausa sin rebote y empuja en 1 s controlado. Inhala al bajar y exhala al cruzar el punto de mayor esfuerzo; usa respiración con brace solo si conoces la técnica.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Pies firmes\",\"Glúteos apoyados\",\"Escápulas estables\",\"Pecho controlado\",\"Antebrazos verticales\",\"Muñecas apiladas\",\"Empuja sin rebotar\",\"Baja con control\",\"Escápulas firmes\",\"Controla la bajada\"]","errores_comunes":"[\"Despegar glúteos o espalda\",\"Rebotar en el pecho o topes\",\"Abrir codos sin control\",\"Doblar muñecas\",\"Elevar hombros\",\"Recortar recorrido\",\"Bloquear codos con golpe\",\"Usar carga sin salida segura\",\"Rebotar la carga\",\"Perder tensión escapular\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Evitar si provoca dolor agudo en hombro, muñeca o codo\",\"Reducir rango o usar alternativa si genera molestia\"]","sustituciones":"[\"Press de banca con barra\",\"Lagartijas\",\"Aperturas en polea\",\"Press con mancuernas\",\"Press de pecho en máquina\",\"Flexiones con manos elevadas\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"0","repeticiones_sugeridas":"0","rango_reps_min":"8","rango_reps_max":"12","descanso_segundos_min":"90","descanso_segundos_max":"150","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"68","nombre":"Flexiones con palmada","aliases":"[\"Flexiones con palmada\",\"clapping push-ups\",\"plyometric push-up\",\"Plyometric clap push-up\"]","nivel":"avanzado","nivel_minimo":"avanzado","grupo_muscular":"pecho","musculo_principal":"pectoral mayor","musculos_secundarios":"[\"tríceps\",\"deltoides anterior\",\"core\"]","equipamiento":"peso corporal","equipo_requerido":"[\"peso corporal\"]","tipo_entrenamiento":"potencia","patron_movimiento":"salto/potencia","descripcion":"Flexiones con palmada trabaja principalmente pectoral mayor, con participación de tríceps, deltoides anterior, core. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: usa superficie antideslizante con espacio para manos y cara. Calienta muñecas/hombros y comprueba primero flexiones rápidas sin palmada; comienza en inclinación o desde rodillas si no puedes despegar y aterrizar con codos suaves.\",\"Posición inicial: manos algo más anchas que hombros, dedos abiertos, pies juntos o al ancho de caderas y cuerpo en línea recta. Aprieta glúteos/abdomen, separa el pecho del suelo, coloca hombros lejos de orejas y mira entre las manos.\",\"Agarre: prono en barra/suelo o neutro en asas/mancuernas. Usa una anchura que deje antebrazos casi verticales; un agarre cerrado aumenta demanda de tríceps y uno muy ancho acorta el recorrido. Pulgar cerrado y muñeca apilada sobre antebrazo.\",\"Inicio y trayectoria: Desciende como una flexión controlada y empuja el suelo de forma explosiva hasta despegar las manos; da una palmada solo si queda tiempo para recolocarlas. Aterriza con codos suaves y hombros activos.\",\"Rango y biomecánica: Usa profundidad de flexión completa controlada y altura mínima necesaria; elimina la palmada si obliga a caer con codos rígidos o manos fuera de posición. Detén la serie al perder aterrizaje silencioso.\",\"Tempo y respiración: Bajada 2–3 s, cambio breve y concéntrica máxima; absorbe la recepción en 1–2 s. Inhala al bajar y exhala al despegar.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: aterriza la última repetición con codos suaves, estabiliza una plancha completa y después apoya rodillas antes de levantarte. Termina al primer aterrizaje ruidoso o desalineado.\"]","cues_tecnicos":"[\"Pies firmes\",\"Glúteos apoyados\",\"Escápulas estables\",\"Pecho controlado\",\"Antebrazos verticales\",\"Muñecas apiladas\",\"Empuja sin rebotar\",\"Baja con control\",\"Controla la fase de ida y vuelta\",\"Evita impulsos excesivos\"]","errores_comunes":"[\"Despegar glúteos o espalda\",\"Rebotar en el pecho o topes\",\"Abrir codos sin control\",\"Doblar muñecas\",\"Elevar hombros\",\"Recortar recorrido\",\"Bloquear codos con golpe\",\"Usar carga sin salida segura\",\"Usar impulso excesivo\",\"Perder postura\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Aperturas con Mancuernas (Plano/Inclinado)\",\"Aperturas en Polea (Cable Flyes)\",\"Clapping Push-ups (Flexiones con palmada)\",\"Fondos en Paralelas (Dips para Pecho)\",\"Press con mancuernas\",\"Press de pecho en máquina\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"cualquiera","objetivo":"potencia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"5","rango_reps_max":"10","descanso_segundos_min":"90","descanso_segundos_max":"150","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"revisar"},{"action":"update","id":"42","nombre":"Prensa de piernas a 45 grados","aliases":"[\"Prensa de piernas a 45 grados\",\"prensa inclinada de piernas\",\"prensa 45 grados\",\"45-degree leg press\",\"incline leg press\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"piernas","musculo_principal":"cuádriceps","musculos_secundarios":"[\"gluteo mayor\",\"isquiosurales\",\"aductores\"]","equipamiento":"máquina de prensa de piernas a 45 grados","equipo_requerido":"[\"máquina de prensa de piernas a 45 grados\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"sentadilla en máquina","descripcion":"Prensa de piernas a 45 grados trabaja principalmente cuádriceps, con participación de glúteo mayor, isquiosurales, aductores. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Carga ambos lados con el mismo peso, coloca topes y ajusta respaldo si el modelo lo permite. Siéntate con pelvis y espalda completas contra el apoyo, pies al ancho de caderas; libera los seguros solo con las rodillas extendidas sin hiperextender y confirma cómo volver a engancharlos antes de bajar.\",\"Posición inicial: pies firmes y trípode plantar activo, rodillas orientadas hacia los dedos, cadera centrada, abdomen presurizado y columna neutra. Mantén pecho y cabeza siguiendo el torso, cuello largo, hombros estables y manos simétricas; no permitas que talones o pelvis pierdan apoyo.\",\"Agarre de soporte: toma las asas de la máquina con agarre neutro y pulgar cerrado; sirven para estabilizar pelvis y tronco, no para tirar del cuerpo. Mantén muñecas rectas y no sueltes hasta que el seguro o la pila estén completamente apoyados.\",\"Inicio y trayectoria: Inicia flexionando cadera y rodillas a la vez, siguiendo la dirección de los pies; distribuye presión entre talón, base del dedo gordo y base del meñique. Siente cuádriceps y glúteos, no presión aguda en rodilla o espalda.\",\"Rango y biomecánica: Desciende hasta la mayor profundidad que conserve talones, pelvis y columna controlados; empuja la plataforma/suelo y termina con cadera y rodillas extendidas sin hiperextender ni bloquear con violencia.\",\"Tempo y respiración: Desciende 3 s, pausa breve sin relajarte y sube en 1–2 s. Inhala y crea presión antes de bajar; exhala al superar la parte difícil sin perder el abdomen.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición en la posición de control, reengancha ambos seguros y verifica visualmente que soporten el carro/barra antes de relajarte. Baja con cuidado, descarga discos de forma alterna y deja la máquina estable; nunca abandones un lado cargado.\"]","cues_tecnicos":"[\"Trípode del pie\",\"Rodillas siguen los dedos\",\"Pelvis estable\",\"Core presurizado\",\"Empuja el suelo\",\"No rebotes\",\"Sin bloqueo agresivo\",\"Profundidad controlada\",\"Espalda y pelvis apoyadas\",\"Pie completo\"]","errores_comunes":"[\"Rodillas colapsan hacia dentro\",\"Talones se despegan\",\"Pelvis se enrolla o despega\",\"Rebotar abajo\",\"Bloquear rodillas con violencia\",\"Profundidad forzada\",\"Carga desigual\",\"Perder el brace\",\"Bajar hasta despegar la pelvis\",\"Bloquear rodillas\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la flexión profunda de rodilla o cadera provoca dolor; ajusta asiento, profundidad y carga\",\"Evitar si provoca dolor agudo de rodilla o cadera\",\"Ajustar pies y rango si hay molestia\"]","sustituciones":"[\"Sentadilla goblet\",\"Sentadilla con barra\",\"Zancadas con mancuernas\",\"Prensa horizontal de piernas\",\"Ejercicio unilateral con apoyo\"]","progresiones":"[\"Aumentar carga\",\"Aumentar rango controlado\",\"Usar tempo lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Sentadilla goblet\",\"Step-up\",\"Rango parcial controlado\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"4","repeticiones_sugeridas":"12","rango_reps_min":"10","rango_reps_max":"15","descanso_segundos_min":"90","descanso_segundos_max":"150","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"Leg Press 45°","estado_calidad":"curado"},{"action":"update","id":"44","nombre":"Curl femoral sentado en máquina","aliases":"[\"Curl femoral sentado en máquina\",\"Curl femoral sentado máquina\",\"curl femoral sentado\",\"curl de isquios sentado\",\"seated leg curl\",\"seated hamstring curl\",\"Curl femoral sentado en máq.\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"piernas","musculo_principal":"isquiosurales","musculos_secundarios":"[\"gastrocnemio\"]","equipamiento":"máquina de curl femoral sentado","equipo_requerido":"[\"máquina de curl femoral sentado\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"flexion de rodilla","descripcion":"Curl femoral sentado en máquina trabaja principalmente isquiosurales, con participación de gastrocnemio. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Ajusta el respaldo para alinear las rodillas con el eje de giro. Coloca el rodillo móvil justo por encima de los talones/Aquiles y el apoyo de muslos firme sobre ellos; fija pasadores y palanca de inicio sin forzar la flexión de rodilla.\",\"Posición inicial: pies y rodillas alineados con el aparato o la trayectoria, pelvis nivelada y abdomen firme. Mantén espalda y cabeza neutras, pecho estable, hombros bajos, escápulas apoyadas cuando haya respaldo y manos sujetando las asas sin tirar.\",\"Agarre de soporte: toma las asas de la máquina con agarre neutro y pulgar cerrado; sirven para estabilizar pelvis y tronco, no para tirar del cuerpo. Mantén muñecas rectas y no sueltes hasta que el seguro o la pila estén completamente apoyados.\",\"Inicio y trayectoria: Flexiona la rodilla llevando el rodillo hacia los glúteos sin mover la pelvis. Siente isquiotibiales; la cadera y la columna permanecen estables.\",\"Rango y biomecánica: Flexiona hasta donde el talón avance sin que la cadera se levante; vuelve casi a extensión completa sin que la pila descanse ni la rodilla se bloquee.\",\"Tempo y respiración: Flexiona en 1–2 s, pausa 1 s y extiende en 3 s. Exhala al flexionar e inhala al regresar.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Trípode del pie\",\"Rodillas siguen los dedos\",\"Pelvis estable\",\"Core presurizado\",\"Empuja el suelo\",\"No rebotes\",\"Sin bloqueo agresivo\",\"Profundidad controlada\",\"Rodillas alineadas con el eje\",\"Muslos fijados\"]","errores_comunes":"[\"Rodillas colapsan hacia dentro\",\"Talones se despegan\",\"Pelvis se enrolla o despega\",\"Rebotar abajo\",\"Bloquear rodillas con violencia\",\"Profundidad forzada\",\"Carga desigual\",\"Perder el brace\",\"Eje mal alineado\",\"Rodillo sobre el tendón de Aquiles\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la flexión profunda de rodilla o cadera provoca dolor; ajusta asiento, profundidad y carga\",\"Evitar si causa dolor posterior de rodilla\",\"Reducir carga si hay calambre\"]","sustituciones":"[\"Peso muerto rumano con mancuernas\",\"Curl femoral con pelota\",\"Peso muerto rumano con barra\",\"Sentadilla goblet\",\"Prensa horizontal de piernas\",\"Ejercicio unilateral con apoyo\"]","progresiones":"[\"Aumentar carga\",\"Pausar en contracción\",\"Tempo lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Curl femoral con pelota\",\"Peso muerto rumano ligero\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"12","rango_reps_min":"10","rango_reps_max":"15","descanso_segundos_min":"60","descanso_segundos_max":"90","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"Seated Leg Curl Machine","estado_calidad":"curado"},{"action":"update","id":"sf-calf-seated","nombre":"Elevación de talones sentado","aliases":"[\"Elevación de talones sentado\",\"elevación de pantorrillas sentado\",\"gemelo sentado\",\"seated calf raise\",\"seated soleus raise\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"piernas","musculo_principal":"sóleo","musculos_secundarios":"[\"gastrocnemio\",\"estabilizadores de tobillo\"]","equipamiento":"máquina de elevación de talones sentado","equipo_requerido":"[\"máquina de elevación de talones sentado\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"flexion plantar sentado","descripcion":"Elevación de talones sentado trabaja principalmente sóleo, con participación de gastrocnemio, estabilizadores de tobillo. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Ajusta el asiento o almohadilla para que el soporte quede sobre los muslos, cerca de las rodillas pero no encima de la rótula. Apoya solo el antepié en la plataforma, selecciona carga o discos simétricos y eleva los talones antes de liberar el seguro.\",\"Posición inicial: pies y rodillas alineados con el aparato o la trayectoria, pelvis nivelada y abdomen firme. Mantén espalda y cabeza neutras, pecho estable, hombros bajos, escápulas apoyadas cuando haya respaldo y manos sujetando las asas sin tirar.\",\"Agarre de soporte: toma las asas de la máquina con agarre neutro y pulgar cerrado; sirven para estabilizar pelvis y tronco, no para tirar del cuerpo. Mantén muñecas rectas y no sueltes hasta que el seguro o la pila estén completamente apoyados.\",\"Inicio y trayectoria: Eleva los talones empujando con el antepié sin girar tobillos ni flexionar rodillas. Siente gemelos y sóleo; cadera y tronco permanecen apilados.\",\"Rango y biomecánica: Sube hasta una flexión plantar completa controlada y baja el talón por debajo de la plataforma solo hasta un estiramiento tolerable. Evita rebotes en el tendón de Aquiles.\",\"Tempo y respiración: Sube en 2 s, pausa 1–2 s y baja en 3 s. Exhala al elevar e inhala al descender.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: eleva los talones para descargar el mecanismo, coloca por completo el seguro y verifica que el brazo descanse antes de bajar los talones. Retira las piernas solo sin tensión y descarga discos alternando lados.\"]","cues_tecnicos":"[\"Trípode del pie\",\"Rodillas siguen los dedos\",\"Pelvis estable\",\"Core presurizado\",\"Empuja el suelo\",\"No rebotes\",\"Sin bloqueo agresivo\",\"Profundidad controlada\",\"Antepié firme\",\"Rodillas estables\"]","errores_comunes":"[\"Rodillas colapsan hacia dentro\",\"Talones se despegan\",\"Pelvis se enrolla o despega\",\"Rebotar abajo\",\"Bloquear rodillas con violencia\",\"Profundidad forzada\",\"Carga desigual\",\"Perder el brace\",\"Rango muy corto\",\"Cojín sobre la rótula\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Evitar si hay dolor de tobillo o Aquiles\"]","sustituciones":"[\"Elevación de talones de pie con mancuernas\",\"Elevación de talones en escalón\",\"Elevación de talones en máquina\",\"Sentadilla goblet\",\"Prensa horizontal de piernas\",\"Ejercicio unilateral con apoyo\"]","progresiones":"[\"Aumentar carga\",\"Pausar arriba\",\"Mas reps\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Peso corporal\",\"Menor rango\",\"Carga ligera\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"4","repeticiones_sugeridas":"15","rango_reps_min":"12","rango_reps_max":"20","descanso_segundos_min":"45","descanso_segundos_max":"90","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"Seated Calf Raise Machine","estado_calidad":"curado"},{"action":"update","id":"43","nombre":"Extensión de cuádriceps en máquina","aliases":"[\"Extensión de cuádriceps en máquina\",\"Extensión de cuádriceps máquina\",\"extensión de piernas\",\"máquina de cuádriceps\",\"leg extension\",\"machine leg extension\",\"Extensión de cuádriceps en máq.\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"piernas","musculo_principal":"cuádriceps","musculos_secundarios":"[\"recto femoral\"]","equipamiento":"máquina de extensión de cuádriceps","equipo_requerido":"[\"máquina de extensión de cuádriceps\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"extensión de rodilla","descripcion":"Extensión de cuádriceps en máquina trabaja principalmente cuádriceps, con participación de recto femoral. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Ajusta el respaldo para que las rodillas coincidan con el eje de giro y el borde del asiento no comprima detrás de ellas. Coloca el rodillo sobre la parte baja de las tibias, por encima del empeine; fija pasadores y sujeta las asas.\",\"Posición inicial: pies y rodillas alineados con el aparato o la trayectoria, pelvis nivelada y abdomen firme. Mantén espalda y cabeza neutras, pecho estable, hombros bajos, escápulas apoyadas cuando haya respaldo y manos sujetando las asas sin tirar.\",\"Agarre de soporte: toma las asas de la máquina con agarre neutro y pulgar cerrado; sirven para estabilizar pelvis y tronco, no para tirar del cuerpo. Mantén muñecas rectas y no sueltes hasta que el seguro o la pila estén completamente apoyados.\",\"Inicio y trayectoria: Extiende las rodillas elevando el rodillo sin despegar pelvis ni muslos. Siente el cuádriceps; cadera, espalda y tobillos permanecen estables.\",\"Rango y biomecánica: Sube hasta casi extender por completo sin golpe ni bloqueo agresivo; baja hasta la flexión configurada y tolerable sin que la pila repose.\",\"Tempo y respiración: Extiende en 2 s, pausa 1 s y baja en 3 s. Exhala al extender e inhala al flexionar.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Trípode del pie\",\"Rodillas siguen los dedos\",\"Pelvis estable\",\"Core presurizado\",\"Empuja el suelo\",\"No rebotes\",\"Sin bloqueo agresivo\",\"Profundidad controlada\",\"Rodilla alineada con el eje\",\"Cadera apoyada\"]","errores_comunes":"[\"Rodillas colapsan hacia dentro\",\"Talones se despegan\",\"Pelvis se enrolla o despega\",\"Rebotar abajo\",\"Bloquear rodillas con violencia\",\"Profundidad forzada\",\"Carga desigual\",\"Perder el brace\",\"Eje mal alineado\",\"Rodillo sobre el tobillo\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la flexión profunda de rodilla o cadera provoca dolor; ajusta asiento, profundidad y carga\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Box Jumps (Saltos a Caja)\",\"Curl Femoral (Leg Curl)\",\"Elevación de Talones (Calf Raise) de pie con Mancuernas\",\"Extensión de Cuádriceps (Leg Extension)\",\"Sentadilla goblet\",\"Prensa horizontal de piernas\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"10","rango_reps_max":"15","descanso_segundos_min":"60","descanso_segundos_max":"90","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"Leg Extension Machine","estado_calidad":"curado"},{"action":"update","id":"69","nombre":"Saltos a caja","aliases":"[\"Saltos a caja\",\"box jumps\",\"Box jump\",\"salto al cajón\",\"BJ\"]","nivel":"avanzado","nivel_minimo":"avanzado","grupo_muscular":"piernas","musculo_principal":"cuádriceps","musculos_secundarios":"[\"glúteos\",\"isquiosurales\",\"pantorrillas\",\"core\"]","equipamiento":"caja pliométrica","equipo_requerido":"[\"caja pliométrica\"]","tipo_entrenamiento":"potencia","patron_movimiento":"salto/potencia","descripcion":"Saltos a caja trabaja principalmente cuádriceps, con participación de glúteos, isquiosurales, pantorrillas. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: elige una caja antideslizante que no se desplace, colócala contra una pared si procede y despeja el aterrizaje. Empieza con una altura que puedas subir caminando; practica despegar, estabilizar y bajar con un pie a la vez.\",\"Posición inicial: base estable, rodillas alineadas, cadera y abdomen firmes, espalda en posición neutra y cabeza siguiendo el torso. Mantén cuello largo, pecho controlado, hombros bajos, escápulas estables y manos/muñecas/codos alineados con el apoyo o implemento.\",\"Agarre de soporte: sujeta asas o implemento con pulgar cerrado y muñecas neutras; las manos estabilizan, no tiran del cuerpo. En máquinas, no uses las asas para acortar el recorrido ni despegar la pelvis.\",\"Inicio y trayectoria: Inicia desde una base estable y acelera sin perder alineación de rodilla, cadera y tronco. Produce fuerza contra el suelo; brazos acompañan sin tensar cuello u hombros.\",\"Rango y biomecánica: Mantén amplitud que permita aterrizar suave o conservar la plancha. Reduce velocidad, altura o recorrido cuando la técnica se deteriore; no uses fatiga extrema para aprender una variante explosiva.\",\"Tempo y respiración: La fase propulsiva es rápida y la recepción/retorno controlados. Respira rítmicamente; exhala en cada esfuerzo y recupera sin contener el aire.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Trípode del pie\",\"Rodillas siguen los dedos\",\"Pelvis estable\",\"Core presurizado\",\"Empuja el suelo\",\"No rebotes\",\"Sin bloqueo agresivo\",\"Profundidad controlada\",\"Controla la fase de ida y vuelta\",\"Evita impulsos excesivos\"]","errores_comunes":"[\"Rodillas colapsan hacia dentro\",\"Talones se despegan\",\"Pelvis se enrolla o despega\",\"Rebotar abajo\",\"Bloquear rodillas con violencia\",\"Profundidad forzada\",\"Carga desigual\",\"Perder el brace\",\"Usar impulso excesivo\",\"Perder postura\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Ten precaución con alto impacto si aún no puedes aterrizar o desacelerar sin dolor ni pérdida de alineación\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Box Jumps (Saltos a Caja)\",\"Curl Femoral (Leg Curl)\",\"Elevación de Talones (Calf Raise) de pie con Mancuernas\",\"Extensión de Cuádriceps (Leg Extension)\",\"Sentadilla goblet\",\"Prensa horizontal de piernas\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"potencia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"5","rango_reps_max":"10","descanso_segundos_min":"90","descanso_segundos_max":"150","rir_recomendado":"2","duracion_promedio_segundos":"30","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"38","nombre":"Sentadilla con barra","aliases":"[\"Sentadilla con barra\",\"Sentadilla barra\",\"back squat\",\"barbell squat\",\"Sentadilla con BB\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"piernas","musculo_principal":"cuádriceps","musculos_secundarios":"[\"glúteos\",\"isquiosurales\",\"aductores\",\"core\"]","equipamiento":"barra, rack, discos","equipo_requerido":"[\"barra\",\"rack\",\"discos\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"sentadilla","descripcion":"Sentadilla con barra trabaja principalmente cuádriceps, con participación de glúteos, isquiosurales, aductores. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: coloca la barra en un rack a una altura que permita sacarla sin encoger hombros ni ponerte de puntillas. Carga ambos lados por igual, usa seguros de disco y topes de seguridad; ensaya el recorrido con la barra vacía y pide spotter cuando la carga o el ejercicio lo amerite.\",\"Posición inicial: pies firmes y trípode plantar activo, rodillas orientadas hacia los dedos, cadera centrada, abdomen presurizado y columna neutra. Mantén pecho y cabeza siguiendo el torso, cuello largo, hombros estables y manos simétricas; no permitas que talones o pelvis pierdan apoyo.\",\"Agarre: prono cerrado alrededor de la barra y muñecas firmes. En peso muerto pesado puede usarse mixto o hook grip, alternando lados y solo con experiencia; para aprender, usa doble prono. La barra debe permanecer controlada, nunca apoyada en dedos abiertos.\",\"Inicio y trayectoria: Inicia flexionando cadera y rodillas a la vez, siguiendo la dirección de los pies; distribuye presión entre talón, base del dedo gordo y base del meñique. Siente cuádriceps y glúteos, no presión aguda en rodilla o espalda.\",\"Rango y biomecánica: Desciende hasta la mayor profundidad que conserve talones, pelvis y columna controlados; empuja la plataforma/suelo y termina con cadera y rodillas extendidas sin hiperextender ni bloquear con violencia.\",\"Tempo y respiración: Desciende 3 s, pausa breve sin relajarte y sube en 1–2 s. Inhala y crea presión antes de bajar; exhala al superar la parte difícil sin perder el abdomen.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Trípode del pie\",\"Rodillas siguen los dedos\",\"Pelvis estable\",\"Core presurizado\",\"Empuja el suelo\",\"No rebotes\",\"Sin bloqueo agresivo\",\"Profundidad controlada\",\"Pie completo apoyado\",\"Rodillas siguen la línea de los pies\"]","errores_comunes":"[\"Rodillas colapsan hacia dentro\",\"Talones se despegan\",\"Pelvis se enrolla o despega\",\"Rebotar abajo\",\"Bloquear rodillas con violencia\",\"Profundidad forzada\",\"Carga desigual\",\"Perder el brace\",\"Colapsar rodillas hacia adentro\",\"Levantar talones\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la flexión profunda de rodilla o cadera provoca dolor; ajusta asiento, profundidad y carga\",\"Evitar si provoca dolor agudo en rodilla, cadera o espalda baja\",\"Reducir carga o rango si hay molestia\"]","sustituciones":"[\"Sentadilla goblet\",\"Prensa de piernas\",\"Sentadilla búlgara con mancuernas\",\"Prensa horizontal de piernas\",\"Ejercicio unilateral con apoyo\"]","progresiones":"[\"Sentadilla con pausa\",\"Sentadilla frontal\",\"Aumentar carga gradualmente\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Sentadilla goblet\",\"Sentadilla a caja\",\"Prensa de piernas\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"fuerza","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"5","rango_reps_max":"10","descanso_segundos_min":"120","descanso_segundos_max":"180","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"55","nombre":"Sentadilla frontal con barra","aliases":"[\"Sentadilla frontal con barra\",\"Sentadilla frontal barra\",\"front squat\",\"Sentadilla frontal con BB\"]","nivel":"avanzado","nivel_minimo":"avanzado","grupo_muscular":"piernas","musculo_principal":"cuádriceps","musculos_secundarios":"[\"glúteos\",\"core\",\"espalda alta\"]","equipamiento":"barra, rack, discos","equipo_requerido":"[\"barra\",\"rack\",\"discos\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"sentadilla","descripcion":"Sentadilla frontal con barra trabaja principalmente cuádriceps, con participación de glúteos, core, espalda alta. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: coloca la barra en un rack a una altura que permita sacarla sin encoger hombros ni ponerte de puntillas. Carga ambos lados por igual, usa seguros de disco y topes de seguridad; ensaya el recorrido con la barra vacía y pide spotter cuando la carga o el ejercicio lo amerite.\",\"Posición inicial: pies firmes y trípode plantar activo, rodillas orientadas hacia los dedos, cadera centrada, abdomen presurizado y columna neutra. Mantén pecho y cabeza siguiendo el torso, cuello largo, hombros estables y manos simétricas; no permitas que talones o pelvis pierdan apoyo.\",\"Agarre: prono cerrado alrededor de la barra y muñecas firmes. En peso muerto pesado puede usarse mixto o hook grip, alternando lados y solo con experiencia; para aprender, usa doble prono. La barra debe permanecer controlada, nunca apoyada en dedos abiertos.\",\"Inicio y trayectoria: Inicia flexionando cadera y rodillas a la vez, siguiendo la dirección de los pies; distribuye presión entre talón, base del dedo gordo y base del meñique. Siente cuádriceps y glúteos, no presión aguda en rodilla o espalda.\",\"Rango y biomecánica: Desciende hasta la mayor profundidad que conserve talones, pelvis y columna controlados; empuja la plataforma/suelo y termina con cadera y rodillas extendidas sin hiperextender ni bloquear con violencia.\",\"Tempo y respiración: Desciende 3 s, pausa breve sin relajarte y sube en 1–2 s. Inhala y crea presión antes de bajar; exhala al superar la parte difícil sin perder el abdomen.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Trípode del pie\",\"Rodillas siguen los dedos\",\"Pelvis estable\",\"Core presurizado\",\"Empuja el suelo\",\"No rebotes\",\"Sin bloqueo agresivo\",\"Profundidad controlada\",\"Pie completo apoyado\",\"Rodillas siguen la línea de los pies\"]","errores_comunes":"[\"Rodillas colapsan hacia dentro\",\"Talones se despegan\",\"Pelvis se enrolla o despega\",\"Rebotar abajo\",\"Bloquear rodillas con violencia\",\"Profundidad forzada\",\"Carga desigual\",\"Perder el brace\",\"Colapsar rodillas hacia adentro\",\"Levantar talones\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la flexión profunda de rodilla o cadera provoca dolor; ajusta asiento, profundidad y carga\",\"Evitar si provoca dolor agudo en rodilla, cadera o espalda baja\",\"Reducir carga o rango si hay molestia\"]","sustituciones":"[\"Sentadilla goblet\",\"Sentadilla con barra\",\"Prensa de piernas\",\"Sentadilla búlgara con mancuernas\",\"Prensa horizontal de piernas\",\"Ejercicio unilateral con apoyo\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"fuerza","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"5","rango_reps_max":"10","descanso_segundos_min":"120","descanso_segundos_max":"180","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"14","nombre":"Sentadilla goblet","aliases":"[\"Sentadilla goblet\",\"goblet squat\",\"sentadilla copa\",\"KB goblet squat\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"piernas","musculo_principal":"cuádriceps","musculos_secundarios":"[\"glúteos\",\"aductores\",\"core\"]","equipamiento":"mancuerna o kettlebell","equipo_requerido":"[\"mancuerna o kettlebell\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"sentadilla","descripcion":"Sentadilla goblet trabaja principalmente cuádriceps, con participación de glúteos, aductores, core. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: elige mancuernas/kettlebell que puedas levantar y colocar sin impulso; despeja el área, comprueba cierres y usa banco estable si corresponde. Empieza con una carga que permita controlar la repetición y practica el montaje antes de la serie efectiva.\",\"Posición inicial: pies firmes y trípode plantar activo, rodillas orientadas hacia los dedos, cadera centrada, abdomen presurizado y columna neutra. Mantén pecho y cabeza siguiendo el torso, cuello largo, hombros estables y manos simétricas; no permitas que talones o pelvis pierdan apoyo.\",\"Agarre: prono cerrado alrededor de la barra y muñecas firmes. En peso muerto pesado puede usarse mixto o hook grip, alternando lados y solo con experiencia; para aprender, usa doble prono. La barra debe permanecer controlada, nunca apoyada en dedos abiertos.\",\"Inicio y trayectoria: Inicia flexionando cadera y rodillas a la vez, siguiendo la dirección de los pies; distribuye presión entre talón, base del dedo gordo y base del meñique. Siente cuádriceps y glúteos, no presión aguda en rodilla o espalda.\",\"Rango y biomecánica: Desciende hasta la mayor profundidad que conserve talones, pelvis y columna controlados; empuja la plataforma/suelo y termina con cadera y rodillas extendidas sin hiperextender ni bloquear con violencia.\",\"Tempo y respiración: Desciende 3 s, pausa breve sin relajarte y sube en 1–2 s. Inhala y crea presión antes de bajar; exhala al superar la parte difícil sin perder el abdomen.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Trípode del pie\",\"Rodillas siguen los dedos\",\"Pelvis estable\",\"Core presurizado\",\"Empuja el suelo\",\"No rebotes\",\"Sin bloqueo agresivo\",\"Profundidad controlada\",\"Pie completo apoyado\",\"Rodillas siguen la línea de los pies\"]","errores_comunes":"[\"Rodillas colapsan hacia dentro\",\"Talones se despegan\",\"Pelvis se enrolla o despega\",\"Rebotar abajo\",\"Bloquear rodillas con violencia\",\"Profundidad forzada\",\"Carga desigual\",\"Perder el brace\",\"Colapsar rodillas hacia adentro\",\"Levantar talones\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la flexión profunda de rodilla o cadera provoca dolor; ajusta asiento, profundidad y carga\",\"Evitar si provoca dolor agudo en rodilla, cadera o espalda baja\",\"Reducir carga o rango si hay molestia\"]","sustituciones":"[\"Sentadilla con barra\",\"Prensa de piernas\",\"Sentadilla búlgara con mancuernas\",\"Sentadilla goblet\",\"Prensa horizontal de piernas\",\"Ejercicio unilateral con apoyo\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"10","rango_reps_max":"15","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"60","nombre":"Sentadilla pistol a una pierna","aliases":"[\"Sentadilla pistol a una pierna\",\"pistol squat\",\"sentadilla pistola\",\"single-leg squat\",\"pistol\"]","nivel":"avanzado","nivel_minimo":"avanzado","grupo_muscular":"piernas","musculo_principal":"cuádriceps","musculos_secundarios":"[\"glúteos\",\"isquiosurales\",\"core\",\"aductores\"]","equipamiento":"peso corporal","equipo_requerido":"[\"peso corporal\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"sentadilla unilateral","descripcion":"Sentadilla pistol a una pierna trabaja principalmente cuádriceps, con participación de glúteos, isquiosurales, core. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: usa un poste, TRX o contrapeso ligero para aprender y despeja el frente para la pierna libre. Prueba la profundidad con una caja alta detrás; el pie de apoyo debe permanecer completo y el soporte no debe moverse.\",\"Posición inicial: pies firmes y trípode plantar activo, rodillas orientadas hacia los dedos, cadera centrada, abdomen presurizado y columna neutra. Mantén pecho y cabeza siguiendo el torso, cuello largo, hombros estables y manos simétricas; no permitas que talones o pelvis pierdan apoyo.\",\"Agarre: prono cerrado alrededor de la barra y muñecas firmes. En peso muerto pesado puede usarse mixto o hook grip, alternando lados y solo con experiencia; para aprender, usa doble prono. La barra debe permanecer controlada, nunca apoyada en dedos abiertos.\",\"Inicio y trayectoria: Inicia flexionando cadera y rodillas a la vez, siguiendo la dirección de los pies; distribuye presión entre talón, base del dedo gordo y base del meñique. Siente cuádriceps y glúteos, no presión aguda en rodilla o espalda.\",\"Rango y biomecánica: Desciende hasta la mayor profundidad que conserve talones, pelvis y columna controlados; empuja la plataforma/suelo y termina con cadera y rodillas extendidas sin hiperextender ni bloquear con violencia.\",\"Tempo y respiración: Desciende 3 s, pausa breve sin relajarte y sube en 1–2 s. Inhala y crea presión antes de bajar; exhala al superar la parte difícil sin perder el abdomen.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Trípode del pie\",\"Rodillas siguen los dedos\",\"Pelvis estable\",\"Core presurizado\",\"Empuja el suelo\",\"No rebotes\",\"Sin bloqueo agresivo\",\"Profundidad controlada\",\"Pie completo apoyado\",\"Rodillas siguen la línea de los pies\"]","errores_comunes":"[\"Rodillas colapsan hacia dentro\",\"Talones se despegan\",\"Pelvis se enrolla o despega\",\"Rebotar abajo\",\"Bloquear rodillas con violencia\",\"Profundidad forzada\",\"Carga desigual\",\"Perder el brace\",\"Colapsar rodillas hacia adentro\",\"Levantar talones\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la flexión profunda de rodilla o cadera provoca dolor; ajusta asiento, profundidad y carga\",\"Evitar si provoca dolor agudo en rodilla, cadera o espalda baja\",\"Reducir carga o rango si hay molestia\"]","sustituciones":"[\"Box Jumps (Saltos a Caja)\",\"Curl Femoral (Leg Curl)\",\"Elevación de Talones (Calf Raise) de pie con Mancuernas\",\"Extensión de Cuádriceps (Leg Extension)\",\"Sentadilla goblet\",\"Prensa horizontal de piernas\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"cualquiera","objetivo":"habilidad","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"3","rango_reps_max":"8","descanso_segundos_min":"90","descanso_segundos_max":"150","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"revisar"},{"action":"update","id":"12","nombre":"Sentadilla búlgara con mancuernas","aliases":"[\"Sentadilla búlgara con mancuernas\",\"Sentadilla búlgara mancuernas\",\"bulgarian split squat\",\"split squat\",\"Sentadilla búlgara con DB\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"piernas","musculo_principal":"cuádriceps","musculos_secundarios":"[\"glúteo mayor\",\"isquiosurales\",\"aductores\",\"core\"]","equipamiento":"mancuernas, banco","equipo_requerido":"[\"mancuernas\",\"banco\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"zancada/unilateral","descripcion":"Sentadilla búlgara con mancuernas trabaja principalmente cuádriceps, con participación de glúteo mayor, isquiosurales, aductores. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: elige mancuernas/kettlebell que puedas levantar y colocar sin impulso; despeja el área, comprueba cierres y usa banco estable si corresponde. Empieza con una carga que permita controlar la repetición y practica el montaje antes de la serie efectiva.\",\"Posición inicial: pies firmes y trípode plantar activo, rodillas orientadas hacia los dedos, cadera centrada, abdomen presurizado y columna neutra. Mantén pecho y cabeza siguiendo el torso, cuello largo, hombros estables y manos simétricas; no permitas que talones o pelvis pierdan apoyo.\",\"Agarre: prono cerrado alrededor de la barra y muñecas firmes. En peso muerto pesado puede usarse mixto o hook grip, alternando lados y solo con experiencia; para aprender, usa doble prono. La barra debe permanecer controlada, nunca apoyada en dedos abiertos.\",\"Inicio y trayectoria: Inicia flexionando cadera y rodillas a la vez, siguiendo la dirección de los pies; distribuye presión entre talón, base del dedo gordo y base del meñique. Siente cuádriceps y glúteos, no presión aguda en rodilla o espalda.\",\"Rango y biomecánica: Desciende hasta la mayor profundidad que conserve talones, pelvis y columna controlados; empuja la plataforma/suelo y termina con cadera y rodillas extendidas sin hiperextender ni bloquear con violencia.\",\"Tempo y respiración: Desciende 3 s, pausa breve sin relajarte y sube en 1–2 s. Inhala y crea presión antes de bajar; exhala al superar la parte difícil sin perder el abdomen.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Trípode del pie\",\"Rodillas siguen los dedos\",\"Pelvis estable\",\"Core presurizado\",\"Empuja el suelo\",\"No rebotes\",\"Sin bloqueo agresivo\",\"Profundidad controlada\",\"Controla la fase de ida y vuelta\",\"Evita impulsos excesivos\"]","errores_comunes":"[\"Rodillas colapsan hacia dentro\",\"Talones se despegan\",\"Pelvis se enrolla o despega\",\"Rebotar abajo\",\"Bloquear rodillas con violencia\",\"Profundidad forzada\",\"Carga desigual\",\"Perder el brace\",\"Usar impulso excesivo\",\"Perder postura\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la flexión profunda de rodilla o cadera provoca dolor; ajusta asiento, profundidad y carga\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Zancadas con mancuernas\",\"Sentadilla a una pierna\",\"Sentadilla goblet\",\"Prensa horizontal de piernas\",\"Ejercicio unilateral con apoyo\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"8","rango_reps_max":"12","descanso_segundos_min":"90","descanso_segundos_max":"150","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"13","nombre":"Zancada hacia delante con mancuernas","aliases":"[\"Zancada hacia delante con mancuernas\",\"Zancada hacia delante mancuernas\",\"lunges\",\"dumbbell lunges\",\"desplantes\",\"Dumbbell lunge\",\"Zancada hacia delante con DB\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"piernas","musculo_principal":"cuádriceps","musculos_secundarios":"[\"glúteo mayor\",\"isquiosurales\",\"core\"]","equipamiento":"mancuernas","equipo_requerido":"[\"mancuernas\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"zancada/unilateral","descripcion":"Zancada hacia delante con mancuernas trabaja principalmente cuádriceps, con participación de glúteo mayor, isquiosurales, core. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: elige mancuernas/kettlebell que puedas levantar y colocar sin impulso; despeja el área, comprueba cierres y usa banco estable si corresponde. Empieza con una carga que permita controlar la repetición y practica el montaje antes de la serie efectiva.\",\"Posición inicial: pies firmes y trípode plantar activo, rodillas orientadas hacia los dedos, cadera centrada, abdomen presurizado y columna neutra. Mantén pecho y cabeza siguiendo el torso, cuello largo, hombros estables y manos simétricas; no permitas que talones o pelvis pierdan apoyo.\",\"Agarre de soporte: sujeta asas o implemento con pulgar cerrado y muñecas neutras; las manos estabilizan, no tiran del cuerpo. En máquinas, no uses las asas para acortar el recorrido ni despegar la pelvis.\",\"Inicio y trayectoria: Inicia flexionando cadera y rodillas a la vez, siguiendo la dirección de los pies; distribuye presión entre talón, base del dedo gordo y base del meñique. Siente cuádriceps y glúteos, no presión aguda en rodilla o espalda.\",\"Rango y biomecánica: Desciende hasta la mayor profundidad que conserve talones, pelvis y columna controlados; empuja la plataforma/suelo y termina con cadera y rodillas extendidas sin hiperextender ni bloquear con violencia.\",\"Tempo y respiración: Desciende 3 s, pausa breve sin relajarte y sube en 1–2 s. Inhala y crea presión antes de bajar; exhala al superar la parte difícil sin perder el abdomen.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Trípode del pie\",\"Rodillas siguen los dedos\",\"Pelvis estable\",\"Core presurizado\",\"Empuja el suelo\",\"No rebotes\",\"Sin bloqueo agresivo\",\"Profundidad controlada\",\"Controla la fase de ida y vuelta\",\"Evita impulsos excesivos\"]","errores_comunes":"[\"Rodillas colapsan hacia dentro\",\"Talones se despegan\",\"Pelvis se enrolla o despega\",\"Rebotar abajo\",\"Bloquear rodillas con violencia\",\"Profundidad forzada\",\"Carga desigual\",\"Perder el brace\",\"Usar impulso excesivo\",\"Perder postura\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la flexión profunda de rodilla o cadera provoca dolor; ajusta asiento, profundidad y carga\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Sentadilla búlgara con mancuernas\",\"Sentadilla a una pierna\",\"Sentadilla goblet\",\"Prensa horizontal de piernas\",\"Ejercicio unilateral con apoyo\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"10","rango_reps_max":"16","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"41","nombre":"Hip thrust con barra","aliases":"[\"Hip thrust con barra\",\"Hip thrust barra\",\"empuje de cadera con barra\",\"hip thrust\",\"barbell hip thrust\",\"barbell glute thrust\",\"Hip thrust con BB\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"piernas","musculo_principal":"glúteo mayor","musculos_secundarios":"[\"isquiosurales\",\"aductores\",\"core\"]","equipamiento":"barra, banco, discos, protector de barra","equipo_requerido":"[\"barra\",\"banco\",\"discos\",\"protector de barra\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"bisagra de cadera","descripcion":"Hip thrust con barra trabaja principalmente glúteo mayor, con participación de isquiosurales, aductores, core. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación para Hip thrust con barra: revisa barra, banco, discos, protector de barra, despeja el área y selecciona una carga o dificultad que puedas colocar y retirar sin impulso. Comprueba cierres, apoyos y estabilidad; ensaya una repetición lenta antes de la serie efectiva.\",\"Posición inicial: pies y rodillas alineados con el aparato o la trayectoria, pelvis nivelada y abdomen firme. Mantén espalda y cabeza neutras, pecho estable, hombros bajos, escápulas apoyadas cuando haya respaldo y manos sujetando las asas sin tirar.\",\"Agarre de soporte: sujeta asas o implemento con pulgar cerrado y muñecas neutras; las manos estabilizan, no tiran del cuerpo. En máquinas, no uses las asas para acortar el recorrido ni despegar la pelvis.\",\"Inicio y trayectoria: Empuja el suelo con los pies y extiende la cadera; mantén costillas hacia abajo y barbilla levemente recogida. Siente glúteos, no hiperextensión lumbar ni calambres dominantes en isquiotibiales.\",\"Rango y biomecánica: Sube hasta que hombros, cadera y rodillas formen una línea con tibias casi verticales; no eleves más arqueando la espalda. Baja hasta una flexión de cadera controlada sin perder los apoyos.\",\"Tempo y respiración: Sube en 1–2 s, pausa 2 s arriba y baja en 3 s. Exhala al extender la cadera e inhala al descender.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Trípode del pie\",\"Rodillas siguen los dedos\",\"Pelvis estable\",\"Core presurizado\",\"Empuja el suelo\",\"No rebotes\",\"Sin bloqueo agresivo\",\"Profundidad controlada\",\"Barra sobre el pliegue de cadera\",\"Costillas abajo\"]","errores_comunes":"[\"Rodillas colapsan hacia dentro\",\"Talones se despegan\",\"Pelvis se enrolla o despega\",\"Rebotar abajo\",\"Bloquear rodillas con violencia\",\"Profundidad forzada\",\"Carga desigual\",\"Perder el brace\",\"Hiperextender la espalda\",\"Pies demasiado lejos\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Evitar si provoca dolor agudo en rodilla, cadera o espalda baja\",\"Reducir carga o rango si hay molestia\"]","sustituciones":"[\"Peso muerto rumano con mancuernas\",\"Peso muerto convencional con barra\",\"Puente de glúteo\",\"Sentadilla goblet\",\"Prensa horizontal de piernas\",\"Ejercicio unilateral con apoyo\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"8","rango_reps_max":"12","descanso_segundos_min":"90","descanso_segundos_max":"150","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"56","nombre":"Peso muerto sumo","aliases":"[\"Peso muerto sumo\",\"sumo deadlift\",\"peso muerto piernas abiertas\",\"sumo DL\",\"wide-stance deadlift\"]","nivel":"avanzado","nivel_minimo":"avanzado","grupo_muscular":"piernas","musculo_principal":"glúteo mayor","musculos_secundarios":"[\"aductores\",\"isquiosurales\",\"cuádriceps\",\"erectores espinales\"]","equipamiento":"barra, discos","equipo_requerido":"[\"barra\",\"discos\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"bisagra de cadera","descripcion":"Peso muerto sumo trabaja principalmente glúteo mayor, con participación de aductores, isquiosurales, cuádriceps. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: coloca la barra sobre suelo/plataforma nivelada, carga discos iguales y asegura ambos extremos. Deja espacio alrededor, centra la barra sobre el mediopié y usa discos técnicos o bloques si aún no alcanzas la posición inicial con columna neutra.\",\"Posición inicial: pies firmes al ancho adecuado, rodillas suaves, cadera atrás y columna neutra desde sacro hasta cabeza. Mantén abdomen presurizado, pecho largo, cuello alineado, hombros lejos de orejas y escápulas controladas; brazos cuelgan con muñecas rectas.\",\"Agarre: prono cerrado alrededor de la barra y muñecas firmes. En peso muerto pesado puede usarse mixto o hook grip, alternando lados y solo con experiencia; para aprender, usa doble prono. La barra debe permanecer controlada, nunca apoyada en dedos abiertos.\",\"Inicio y trayectoria: Empuja el suelo y extiende rodillas/cadera manteniendo la carga rozando el cuerpo; el tronco y la cadera ascienden coordinados. Siente glúteos, isquiotibiales y espalda trabajando isométricamente, no dolor lumbar.\",\"Rango y biomecánica: Termina erguido con glúteos contraídos, costillas sobre pelvis y sin inclinarte atrás; baja llevando cadera atrás y flexionando rodillas cuando la barra las supera. Detén si la espalda pierde neutralidad.\",\"Tempo y respiración: Sube en 1–2 s con control, pausa erguido y baja en 2–3 s. Inhala y bracea antes de despegar; exhala al terminar o entre repeticiones, sin hiperventilar.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Trípode del pie\",\"Rodillas siguen los dedos\",\"Pelvis estable\",\"Core presurizado\",\"Empuja el suelo\",\"No rebotes\",\"Sin bloqueo agresivo\",\"Profundidad controlada\",\"Cadera hacia atrás\",\"Columna neutra\"]","errores_comunes":"[\"Rodillas colapsan hacia dentro\",\"Talones se despegan\",\"Pelvis se enrolla o despega\",\"Rebotar abajo\",\"Bloquear rodillas con violencia\",\"Profundidad forzada\",\"Carga desigual\",\"Perder el brace\",\"Redondear la espalda\",\"Convertirlo en sentadilla\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Evitar si provoca dolor agudo en rodilla, cadera o espalda baja\",\"Reducir carga o rango si hay molestia\"]","sustituciones":"[\"Peso muerto rumano con mancuernas\",\"Peso muerto convencional con barra\",\"Hip thrust con barra\",\"Puente de glúteo\",\"Sentadilla goblet\",\"Prensa horizontal de piernas\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"fuerza","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"3","rango_reps_max":"8","descanso_segundos_min":"150","descanso_segundos_max":"240","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"17","nombre":"Puente de glúteo","aliases":"[\"Puente de glúteo\",\"glute bridge\",\"puente gluteo\",\"puente de cadera\",\"hip bridge\",\"bodyweight glute bridge\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"piernas","musculo_principal":"glúteo mayor","musculos_secundarios":"[\"isquiosurales\",\"core\"]","equipamiento":"peso corporal","equipo_requerido":"[\"peso corporal\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"bisagra de cadera","descripcion":"Puente de glúteo trabaja principalmente glúteo mayor, con participación de isquiosurales, core. Sirve para mejorar la capacidad física específica y el control técnico. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: usa una superficie plana, antideslizante y con espacio para todo el cuerpo. Coloca colchoneta si mejora comodidad, retira objetos cercanos y elige una inclinación o palanca que puedas sostener sin perder alineación desde la primera repetición.\",\"Posición inicial: pies y rodillas alineados con el aparato o la trayectoria, pelvis nivelada y abdomen firme. Mantén espalda y cabeza neutras, pecho estable, hombros bajos, escápulas apoyadas cuando haya respaldo y manos sujetando las asas sin tirar.\",\"Agarre de soporte: sujeta asas o implemento con pulgar cerrado y muñecas neutras; las manos estabilizan, no tiran del cuerpo. En máquinas, no uses las asas para acortar el recorrido ni despegar la pelvis.\",\"Inicio y trayectoria: Empuja el suelo con los pies y extiende la cadera; mantén costillas hacia abajo y barbilla levemente recogida. Siente glúteos, no hiperextensión lumbar ni calambres dominantes en isquiotibiales.\",\"Rango y biomecánica: Sube hasta que hombros, cadera y rodillas formen una línea con tibias casi verticales; no eleves más arqueando la espalda. Baja hasta una flexión de cadera controlada sin perder los apoyos.\",\"Tempo y respiración: Sube en 1–2 s, pausa 2 s arriba y baja en 3 s. Exhala al extender la cadera e inhala al descender.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Trípode del pie\",\"Rodillas siguen los dedos\",\"Pelvis estable\",\"Core presurizado\",\"Empuja el suelo\",\"No rebotes\",\"Sin bloqueo agresivo\",\"Profundidad controlada\",\"Cadera hacia atrás\",\"Columna neutra\"]","errores_comunes":"[\"Rodillas colapsan hacia dentro\",\"Talones se despegan\",\"Pelvis se enrolla o despega\",\"Rebotar abajo\",\"Bloquear rodillas con violencia\",\"Profundidad forzada\",\"Carga desigual\",\"Perder el brace\",\"Redondear la espalda\",\"Convertirlo en sentadilla\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Evitar si provoca dolor agudo en rodilla, cadera o espalda baja\",\"Reducir carga o rango si hay molestia\"]","sustituciones":"[\"Peso muerto rumano con mancuernas\",\"Peso muerto convencional con barra\",\"Hip thrust con barra\",\"Sentadilla goblet\",\"Prensa horizontal de piernas\",\"Ejercicio unilateral con apoyo\"]","progresiones":"[\"Hip thrust con barra\",\"Pausa arriba\",\"Versión a una pierna\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Puente de glúteo con pausa corta\",\"Puente bilateral sin carga\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"cualquiera","objetivo":"general","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"12","rango_reps_max":"20","descanso_segundos_min":"45","descanso_segundos_max":"90","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"update","id":"40","nombre":"Puente de glúteo con barra","aliases":"[\"Puente de glúteo con barra\",\"Puente de glúteo barra\",\"weighted glute bridge\",\"glute bridge con peso\",\"Loaded glute bridge\",\"Puente de glúteo con BB\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"piernas","musculo_principal":"glúteo mayor","musculos_secundarios":"[\"isquiosurales\",\"aductores\",\"core\"]","equipamiento":"mancuerna o disco, colchoneta","equipo_requerido":"[\"mancuerna o disco\",\"colchoneta\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"bisagra de cadera","descripcion":"Puente de glúteo con barra trabaja principalmente glúteo mayor, con participación de isquiosurales, aductores, core. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: usa una superficie plana, antideslizante y con espacio para todo el cuerpo. Coloca colchoneta si mejora comodidad, retira objetos cercanos y elige una inclinación o palanca que puedas sostener sin perder alineación desde la primera repetición.\",\"Posición inicial: pies y rodillas alineados con el aparato o la trayectoria, pelvis nivelada y abdomen firme. Mantén espalda y cabeza neutras, pecho estable, hombros bajos, escápulas apoyadas cuando haya respaldo y manos sujetando las asas sin tirar.\",\"Agarre de soporte: sujeta asas o implemento con pulgar cerrado y muñecas neutras; las manos estabilizan, no tiran del cuerpo. En máquinas, no uses las asas para acortar el recorrido ni despegar la pelvis.\",\"Inicio y trayectoria: Empuja el suelo con los pies y extiende la cadera; mantén costillas hacia abajo y barbilla levemente recogida. Siente glúteos, no hiperextensión lumbar ni calambres dominantes en isquiotibiales.\",\"Rango y biomecánica: Sube hasta que hombros, cadera y rodillas formen una línea con tibias casi verticales; no eleves más arqueando la espalda. Baja hasta una flexión de cadera controlada sin perder los apoyos.\",\"Tempo y respiración: Sube en 1–2 s, pausa 2 s arriba y baja en 3 s. Exhala al extender la cadera e inhala al descender.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Trípode del pie\",\"Rodillas siguen los dedos\",\"Pelvis estable\",\"Core presurizado\",\"Empuja el suelo\",\"No rebotes\",\"Sin bloqueo agresivo\",\"Profundidad controlada\",\"Cadera hacia atrás\",\"Columna neutra\"]","errores_comunes":"[\"Rodillas colapsan hacia dentro\",\"Talones se despegan\",\"Pelvis se enrolla o despega\",\"Rebotar abajo\",\"Bloquear rodillas con violencia\",\"Profundidad forzada\",\"Carga desigual\",\"Perder el brace\",\"Redondear la espalda\",\"Convertirlo en sentadilla\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Evitar si provoca dolor agudo en rodilla, cadera o espalda baja\",\"Reducir carga o rango si hay molestia\"]","sustituciones":"[\"Peso muerto rumano con mancuernas\",\"Peso muerto convencional con barra\",\"Hip thrust con barra\",\"Puente de glúteo\",\"Sentadilla goblet\",\"Prensa horizontal de piernas\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"10","rango_reps_max":"15","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"curado"},{"action":"insert","id":"sf-cable-pullover","nombre":"Pullover en polea alta","aliases":"[\"Pullover en polea alta\",\"jalón con brazos rectos\",\"pullover con cable\",\"straight-arm pulldown\",\"cable pullover\",\"Straight-arm cable pulldown\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"espalda","musculo_principal":"dorsal ancho","musculos_secundarios":"[\"redondo mayor\",\"cabeza larga del tríceps\",\"core\"]","equipamiento":"polea alta, barra recta o cuerda","equipo_requerido":"[\"polea alta\",\"barra recta o cuerda\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"extensión de hombro","descripcion":"Pullover en polea alta trabaja principalmente dorsal ancho, con participación de redondo mayor, cabeza larga del tríceps, core. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Coloca barra recta o cuerda en una polea alta y verifica el mosquetón. Retrocede hasta tensar el cable, inclina ligeramente el torso desde la cadera y deja espacio para que el accesorio llegue a los muslos sin que la pila choque. La cifra de la pila puede no equivaler a la resistencia efectiva por la relación de poleas; registra siempre la misma torre, ajuste y accesorio.\",\"Posición inicial: pies completos y separados al ancho de caderas, rodillas estables, glúteos y parte alta de la espalda apoyados. Mantén una curva lumbar natural, pecho elevado sin hiperextender, cabeza/cuello neutros, hombros abajo y escápulas apoyadas; alinea codos y muñecas con la carga.\",\"Agarre/apoyo: usa una sujeción cerrada y simétrica, con muñecas neutras. Ajusta la variante si el agarre limita la postura o provoca molestias antes que aumentar la carga.\",\"Inicio y trayectoria: Con una leve flexión fija de codo, mueve los brazos desde el hombro en un arco hacia los muslos o sobre la cabeza. Siente dorsal/pectoral según la variante, no el tríceps por flexionar el codo.\",\"Rango y biomecánica: Llega al estiramiento que mantenga costillas, pelvis y hombro controlados; termina cuando brazos se alineen con el torso o el accesorio llegue a muslos. Evita hiperextender la zona lumbar.\",\"Tempo y respiración: Mueve en 2 s hacia la contracción, pausa 1 s y retorna en 3 s. Exhala al llevar brazos hacia el cuerpo e inhala al abrir.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Pecho largo\",\"Hombros abajo\",\"Codos hacia costillas\",\"Cuello neutro\",\"Core firme\",\"Barra o cable cerca\",\"Sin tirón lumbar\",\"Controla el retorno\",\"Codos casi fijos\",\"Costillas controladas\"]","errores_comunes":"[\"Redondear o hiperextender la espalda\",\"Tirar con impulso\",\"Elevar hombros\",\"Sacar la cabeza\",\"Flexionar muñecas\",\"Acortar el estiramiento\",\"Mover cadera o torso\",\"Golpear la pila\",\"Convertirlo en pushdown\",\"Arquear la espalda\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Reducir el rango si hay molestia de hombro\",\"Detener ante dolor agudo\"]","sustituciones":"[\"Pullover con mancuerna\",\"Jalón al pecho en polea alta\",\"Remo en polea sentado\",\"Remo con pecho apoyado\",\"Jalón al pecho con agarre neutro\"]","progresiones":"[\"Aumentar carga\",\"Pausa abajo\",\"Tempo lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Menor carga\",\"Rango menor\",\"Cuerda para una trayectoria más cómoda\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"15","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"60","maquina_gym":"Functional Trainer","estado_calidad":"curado"},{"action":"insert","id":"sf-calf-standing-machine","nombre":"Elevación de talones de pie en máquina","aliases":"[\"Elevación de talones de pie en máquina\",\"Elevación de talones de pie máquina\",\"gemelo de pie en máquina\",\"standing calf raise machine\",\"machine standing calf raise\",\"Elevación de talones de pie en máq.\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"piernas","musculo_principal":"gastrocnemio","musculos_secundarios":"[\"sóleo\",\"estabilizadores del tobillo\"]","equipamiento":"máquina de elevación de talones de pie","equipo_requerido":"[\"máquina de elevación de talones de pie\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"flexión plantar de pie","descripcion":"Elevación de talones de pie en máquina trabaja principalmente gastrocnemio, con participación de sóleo, estabilizadores del tobillo. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Coloca hombros bajo las almohadillas, ajusta su altura para poder estar erguido con rodillas suaves y apoya solo los metatarsos en el borde. Selecciona carga o discos simétricos; eleva el carro antes de liberar el seguro y localiza el mecanismo de reenganche.\",\"Posición inicial: pies y rodillas alineados con el aparato o la trayectoria, pelvis nivelada y abdomen firme. Mantén espalda y cabeza neutras, pecho estable, hombros bajos, escápulas apoyadas cuando haya respaldo y manos sujetando las asas sin tirar.\",\"Agarre de soporte: toma las asas de la máquina con agarre neutro y pulgar cerrado; sirven para estabilizar pelvis y tronco, no para tirar del cuerpo. Mantén muñecas rectas y no sueltes hasta que el seguro o la pila estén completamente apoyados.\",\"Inicio y trayectoria: Eleva los talones empujando con el antepié sin girar tobillos ni flexionar rodillas. Siente gemelos y sóleo; cadera y tronco permanecen apilados.\",\"Rango y biomecánica: Sube hasta una flexión plantar completa controlada y baja el talón por debajo de la plataforma solo hasta un estiramiento tolerable. Evita rebotes en el tendón de Aquiles.\",\"Tempo y respiración: Sube en 2 s, pausa 1–2 s y baja en 3 s. Exhala al elevar e inhala al descender.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición en la posición de control, reengancha ambos seguros y verifica visualmente que soporten el carro/barra antes de relajarte. Baja con cuidado, descarga discos de forma alterna y deja la máquina estable; nunca abandones un lado cargado.\"]","cues_tecnicos":"[\"Trípode del pie\",\"Rodillas siguen los dedos\",\"Pelvis estable\",\"Core presurizado\",\"Empuja el suelo\",\"No rebotes\",\"Sin bloqueo agresivo\",\"Profundidad controlada\",\"Antepié firme\",\"Cuerpo vertical\"]","errores_comunes":"[\"Rodillas colapsan hacia dentro\",\"Talones se despegan\",\"Pelvis se enrolla o despega\",\"Rebotar abajo\",\"Bloquear rodillas con violencia\",\"Profundidad forzada\",\"Carga desigual\",\"Perder el brace\",\"Rebotar\",\"Flexionar mucho las rodillas\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Reducir rango si hay dolor de tobillo o tendón de Aquiles\",\"Detener ante dolor agudo\"]","sustituciones":"[\"Elevación de talones sentado\",\"Elevación de talones de pie con mancuernas\",\"Elevación de talones en escalón\",\"Sentadilla goblet\",\"Prensa horizontal de piernas\",\"Ejercicio unilateral con apoyo\"]","progresiones":"[\"Aumentar carga\",\"Pausa arriba\",\"Unilateral con apoyo\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Menor carga\",\"Peso corporal\",\"Menor rango\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"15","rango_reps_min":"10","rango_reps_max":"20","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"60","maquina_gym":"Standing Calf Raise Machine","estado_calidad":"curado"},{"action":"insert","id":"sf-core-machine-crunch","nombre":"Crunch en máquina","aliases":"[\"Crunch en máquina\",\"Crunch máquina\",\"abdominal en máquina\",\"machine crunch\",\"abdominal crunch machine\",\"Crunch en máq.\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"core","musculo_principal":"recto abdominal","musculos_secundarios":"[\"oblicuos\"]","equipamiento":"máquina de crunch abdominal","equipo_requerido":"[\"máquina de crunch abdominal\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"flexión de tronco","descripcion":"Crunch en máquina trabaja principalmente recto abdominal, con participación de oblicuos. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Ajusta asiento y almohadillas para que el eje de la máquina coincida con la zona media del tronco y los apoyos contacten pecho/hombros sin comprimir el cuello. Fija pies o piernas, coloca el pasador por completo y empieza con abdomen ya tenso, no desde una hiperextensión lumbar.\",\"Posición inicial: espalda y pelvis apoyadas, pies/rodillas fijados por los soportes y abdomen pretensado. Coloca manos o brazos según el diseño sin tirar del cuello; cabeza neutra, hombros bajos y pecho relajado contra la almohadilla.\",\"Agarre/apoyo: usa una sujeción cerrada y simétrica, con muñecas neutras. Ajusta la variante si el agarre limita la postura o provoca molestias antes que aumentar la carga.\",\"Inicio y trayectoria: Flexiona el tronco aproximando costillas a pelvis contra la almohadilla; las caderas permanecen apoyadas y brazos/piernas solo conectan con la máquina. Siente el recto abdominal, no tirón de cuello.\",\"Rango y biomecánica: Acorta hasta la máxima flexión controlada del tronco sin que la pelvis se levante; retorna a una apertura moderada sin hiperextender la zona lumbar ni dejar reposar la pila.\",\"Tempo y respiración: Flexiona 2 s, pausa 1 s y retorna 3 s. Exhala al cerrar e inhala al abrir.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Costillas sobre pelvis\",\"Respira detrás del brace\",\"Cuello largo\",\"Pelvis controlada\",\"Hombros activos\",\"Sin arco lumbar\",\"Calidad antes que tiempo\",\"Recorta palanca si cedes\",\"Costillas hacia pelvis\",\"Brazos pasivos\"]","errores_comunes":"[\"Arquear la zona lumbar\",\"Tirar del cuello\",\"Contener la respiración\",\"Moverse demasiado rápido\",\"Usar impulso de piernas\",\"Colapsar hombros\",\"Perder posición pélvica\",\"Continuar tras fallar la postura\",\"Tirar con brazos\",\"Hacer solo flexión de cadera\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Reducir rango si hay molestia lumbar o cervical\",\"Detener ante dolor agudo\"]","sustituciones":"[\"Crunch en polea\",\"Crunch abdominal\",\"Dead bug\",\"Plancha con manos elevadas\",\"Press Pallof\"]","progresiones":"[\"Aumentar carga\",\"Pausa flexionado\",\"Tempo lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Menor carga\",\"Menor rango\",\"Crunch en suelo\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"10","rango_reps_max":"20","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"60","maquina_gym":"Abdominal Crunch Machine","estado_calidad":"curado"},{"action":"insert","id":"sf-core-pallof-press","nombre":"Press Pallof en polea","aliases":"[\"Press Pallof en polea\",\"Pallof press\",\"press antirotación\",\"cable Pallof press\",\"anti-rotation press\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"core","musculo_principal":"oblicuos","musculos_secundarios":"[\"transverso abdominal\",\"recto abdominal\",\"glúteo medio\"]","equipamiento":"polea ajustable, agarre","equipo_requerido":"[\"polea ajustable\",\"agarre\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"anti-rotación","descripcion":"Press Pallof en polea trabaja principalmente oblicuos, con participación de transverso abdominal, recto abdominal, glúteo medio. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Ajusta la polea a la altura del esternón, conecta asa o cuerda y verifica mosquetón/pasador. Colócate de lado, aléjate hasta obtener tensión moderada y despeja un radio suficiente para que el cable no roce el cuerpo. La cifra de la pila puede no equivaler a la resistencia efectiva por la relación de poleas; registra siempre la misma torre, ajuste y accesorio.\",\"Posición inicial: de lado a la polea, pies al ancho de hombros, rodillas suaves y pelvis al frente. Sostén el asa con ambas manos en el esternón, codos flexionados, muñecas neutras, hombros bajos y costillas sobre pelvis.\",\"Agarre: prono en barra/suelo o neutro en asas/mancuernas. Usa una anchura que deje antebrazos casi verticales; un agarre cerrado aumenta demanda de tríceps y uno muy ancho acorta el recorrido. Pulgar cerrado y muñeca apilada sobre antebrazo.\",\"Inicio y trayectoria: Extiende los brazos al frente sin permitir que el cable rote el torso hacia la torre. Siente oblicuos, transverso, glúteos y hombros estabilizando; la pelvis y el pecho siguen al frente.\",\"Rango y biomecánica: Lleva manos hasta codos casi extendidos sin encoger hombros ni girar; pausa y vuelve al esternón manteniendo tensión. Ajusta distancia, no la postura, para cambiar el brazo de palanca.\",\"Tempo y respiración: Presiona 2 s, mantén 2–3 s y vuelve 2 s. Exhala durante la pausa e inhala al regresar sin perder el brace.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Costillas sobre pelvis\",\"Respira detrás del brace\",\"Cuello largo\",\"Pelvis controlada\",\"Hombros activos\",\"Sin arco lumbar\",\"Calidad antes que tiempo\",\"Recorta palanca si cedes\",\"Pelvis al frente\",\"Costillas controladas\"]","errores_comunes":"[\"Arquear la zona lumbar\",\"Tirar del cuello\",\"Contener la respiración\",\"Moverse demasiado rápido\",\"Usar impulso de piernas\",\"Colapsar hombros\",\"Perder posición pélvica\",\"Continuar tras fallar la postura\",\"Girar hacia la torre\",\"Inclinar el torso\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Reducir carga o base de palanca si hay molestia lumbar\",\"Detener ante dolor agudo\"]","sustituciones":"[\"Press Pallof con banda\",\"Plancha lateral\",\"Dead bug\",\"Plancha con manos elevadas\",\"Press Pallof\"]","progresiones":"[\"Aumentar distancia a la torre\",\"Pausa con brazos extendidos\",\"Base más estrecha\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Menor carga\",\"Base más amplia\",\"Versión de rodillas\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"15","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"60","maquina_gym":"Dual Adjustable Pulley","estado_calidad":"curado"},{"action":"insert","id":"sf-decline-barbell-press","nombre":"Press declinado con barra","aliases":"[\"Press declinado con barra\",\"Press declinado barra\",\"press de banca declinado\",\"decline barbell bench press\",\"decline bench press\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"pecho","musculo_principal":"pectoral mayor","musculos_secundarios":"[\"tríceps braquial\",\"deltoides anterior\"]","equipamiento":"barra, banco declinado, rack y discos","equipo_requerido":"[\"barra\",\"banco declinado\",\"rack\",\"discos\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"empuje horizontal declinado","descripcion":"Press declinado con barra trabaja principalmente pectoral mayor, con participación de tríceps braquial, deltoides anterior. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para desarrollar fuerza e hipertrofia y progresar el patrón con carga o dificultad graduable.","instrucciones":"[\"Preparación: coloca la barra en un rack a una altura que permita sacarla sin encoger hombros ni ponerte de puntillas. Carga ambos lados por igual, usa seguros de disco y topes de seguridad; ensaya el recorrido con la barra vacía y pide spotter cuando la carga o el ejercicio lo amerite.\",\"Posición inicial: pies completos y separados al ancho de caderas, rodillas estables, glúteos y parte alta de la espalda apoyados. Mantén una curva lumbar natural, pecho elevado sin hiperextender, cabeza/cuello neutros, hombros abajo y escápulas apoyadas; alinea codos y muñecas con la carga.\",\"Agarre: prono en barra/suelo o neutro en asas/mancuernas. Usa una anchura que deje antebrazos casi verticales; un agarre cerrado aumenta demanda de tríceps y uno muy ancho acorta el recorrido. Pulgar cerrado y muñeca apilada sobre antebrazo.\",\"Inicio y trayectoria: Inicia empujando el apoyo o la carga en la línea prevista mientras hombro y codo se extienden coordinados. Siente pectoral/deltoides/tríceps según la variante, con abdomen firme y hombros lejos de orejas.\",\"Rango y biomecánica: Baja hasta que el codo alcance una profundidad tolerable y el hombro conserve centrado, normalmente con antebrazo vertical; sube hasta brazos casi extendidos sin chocar ni hiperextender. Evita rebotes y extremos que despeguen espalda o pelvis.\",\"Tempo y respiración: Tempo base 3-0-1: desciende 3 s, pausa sin rebote y empuja en 1 s controlado. Inhala al bajar y exhala al cruzar el punto de mayor esfuerzo; usa respiración con brace solo si conoces la técnica.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Pies firmes\",\"Glúteos apoyados\",\"Escápulas estables\",\"Pecho controlado\",\"Antebrazos verticales\",\"Muñecas apiladas\",\"Empuja sin rebotar\",\"Baja con control\",\"Piernas aseguradas\",\"Escápulas apoyadas\"]","errores_comunes":"[\"Despegar glúteos o espalda\",\"Rebotar en el pecho o topes\",\"Abrir codos sin control\",\"Doblar muñecas\",\"Elevar hombros\",\"Recortar recorrido\",\"Bloquear codos con golpe\",\"Usar carga sin salida segura\",\"No asegurar las piernas\",\"Rebotar la barra\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Evitar si la posición declinada causa mareo o molestia de hombro\",\"Usar observador con cargas exigentes\"]","sustituciones":"[\"Press de banca con barra\",\"Press en máquina de pecho\",\"Fondos en paralelas para pecho\",\"Press con mancuernas\",\"Press de pecho en máquina\",\"Flexiones con manos elevadas\"]","progresiones":"[\"Aumentar carga\",\"Pausa en el pecho\",\"Tempo lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Menor carga\",\"Press de banca plano\",\"Máquina de press de pecho\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"15","descanso_segundos_min":"90","descanso_segundos_max":"150","rir_recomendado":"2","duracion_promedio_segundos":"60","maquina_gym":"","estado_calidad":"curado"},{"action":"insert","id":"sf-hack-squat-machine","nombre":"Sentadilla hack en máquina","aliases":"[\"Sentadilla hack en máquina\",\"Sentadilla hack máquina\",\"sentadilla hack\",\"hack squat\",\"machine hack squat\",\"Hack squat machine\",\"Sentadilla hack en máq.\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"piernas","musculo_principal":"cuádriceps","musculos_secundarios":"[\"glúteo mayor\",\"aductores\",\"isquiosurales\"]","equipamiento":"máquina hack squat","equipo_requerido":"[\"máquina hack squat\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"sentadilla en máquina","descripcion":"Sentadilla hack en máquina trabaja principalmente cuádriceps, con participación de glúteo mayor, aductores, isquiosurales. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Carga ambos lados por igual y coloca seguros de disco. Ajusta los topes de profundidad si existen; apoya espalda y pelvis completas, hombros bajo las almohadillas y pies al ancho de caderas. Extiende las piernas para liberar el seguro solo cuando estés estable y confirma la dirección de reenganche.\",\"Posición inicial: pies firmes y trípode plantar activo, rodillas orientadas hacia los dedos, cadera centrada, abdomen presurizado y columna neutra. Mantén pecho y cabeza siguiendo el torso, cuello largo, hombros estables y manos simétricas; no permitas que talones o pelvis pierdan apoyo.\",\"Agarre de soporte: toma las asas de la máquina con agarre neutro y pulgar cerrado; sirven para estabilizar pelvis y tronco, no para tirar del cuerpo. Mantén muñecas rectas y no sueltes hasta que el seguro o la pila estén completamente apoyados.\",\"Inicio y trayectoria: Inicia flexionando cadera y rodillas a la vez, siguiendo la dirección de los pies; distribuye presión entre talón, base del dedo gordo y base del meñique. Siente cuádriceps y glúteos, no presión aguda en rodilla o espalda.\",\"Rango y biomecánica: Desciende hasta la mayor profundidad que conserve talones, pelvis y columna controlados; empuja la plataforma/suelo y termina con cadera y rodillas extendidas sin hiperextender ni bloquear con violencia.\",\"Tempo y respiración: Desciende 3 s, pausa breve sin relajarte y sube en 1–2 s. Inhala y crea presión antes de bajar; exhala al superar la parte difícil sin perder el abdomen.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición en la posición de control, reengancha ambos seguros y verifica visualmente que soporten el carro/barra antes de relajarte. Baja con cuidado, descarga discos de forma alterna y deja la máquina estable; nunca abandones un lado cargado.\"]","cues_tecnicos":"[\"Trípode del pie\",\"Rodillas siguen los dedos\",\"Pelvis estable\",\"Core presurizado\",\"Empuja el suelo\",\"No rebotes\",\"Sin bloqueo agresivo\",\"Profundidad controlada\",\"Espalda apoyada\",\"Pie completo\"]","errores_comunes":"[\"Rodillas colapsan hacia dentro\",\"Talones se despegan\",\"Pelvis se enrolla o despega\",\"Rebotar abajo\",\"Bloquear rodillas con violencia\",\"Profundidad forzada\",\"Carga desigual\",\"Perder el brace\",\"Pies demasiado bajos\",\"Rodillas hacia dentro\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la flexión profunda de rodilla o cadera provoca dolor; ajusta asiento, profundidad y carga\",\"Ajustar rango y posición de pies si hay molestia de rodilla\",\"Evitar con dolor agudo\"]","sustituciones":"[\"Prensa de piernas a 45 grados\",\"Sentadilla en máquina Smith\",\"Sentadilla con barra\",\"Sentadilla goblet\",\"Prensa horizontal de piernas\",\"Ejercicio unilateral con apoyo\"]","progresiones":"[\"Aumentar carga\",\"Pausa abajo\",\"Tempo excéntrico lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Menor carga\",\"Menor profundidad\",\"Prensa horizontal de piernas\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"15","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"60","maquina_gym":"Hack Squat Machine","estado_calidad":"curado"},{"action":"insert","id":"sf-hip-abduction-machine","nombre":"Abducción de cadera en máquina","aliases":"[\"Abducción de cadera en máquina\",\"Abducción de cadera máquina\",\"abductores en máquina\",\"máquina de abductores\",\"machine hip abduction\",\"seated hip abduction\",\"Hip abduction machine\",\"Abducción de cadera en máq.\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"glúteos","musculo_principal":"glúteo medio","musculos_secundarios":"[\"glúteo menor\",\"tensor de la fascia lata\"]","equipamiento":"máquina de abducción de cadera","equipo_requerido":"[\"máquina de abducción de cadera\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"abducción de cadera","descripcion":"Abducción de cadera en máquina trabaja principalmente glúteo medio, con participación de glúteo menor, tensor de la fascia lata. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Ajusta el asiento/respaldo para apoyar toda la pelvis y coloca las almohadillas por fuera de los muslos, justo encima de las rodillas. Elige una apertura inicial cómoda con la palanca de ajuste, fija el pasador y sujeta las asas.\",\"Posición inicial: pies y rodillas alineados con el aparato o la trayectoria, pelvis nivelada y abdomen firme. Mantén espalda y cabeza neutras, pecho estable, hombros bajos, escápulas apoyadas cuando haya respaldo y manos sujetando las asas sin tirar.\",\"Agarre de soporte: toma las asas de la máquina con agarre neutro y pulgar cerrado; sirven para estabilizar pelvis y tronco, no para tirar del cuerpo. Mantén muñecas rectas y no sueltes hasta que el seguro o la pila estén completamente apoyados.\",\"Inicio y trayectoria: Mueve el fémur desde la cadera sin inclinar ni rotar la pelvis. Siente glúteo medio/mayor o aductores según la variante; rodilla, columna y tronco permanecen estables.\",\"Rango y biomecánica: Recorre solo hasta donde la pelvis siga nivelada y el músculo mantenga tensión; vuelve lentamente sin dejar que placas o piernas choquen.\",\"Tempo y respiración: Mueve en 2 s, pausa 1 s y retorna en 3 s. Exhala al separar/juntar o extender; inhala al volver.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Costillas hacia abajo\",\"Pelvis nivelada\",\"Empuja con todo el pie\",\"Aprieta glúteos\",\"No arquees la espalda\",\"Rodillas alineadas\",\"Pausa en contracción\",\"Baja con control\",\"Pelvis estable\",\"Rodillas contra cojines\"]","errores_comunes":"[\"Hiperextender la zona lumbar\",\"Rotar la pelvis\",\"Empujar solo con puntas\",\"Abrir o cerrar rodillas\",\"Usar impulso\",\"Recortar el estiramiento\",\"Golpear la pila\",\"Perder tensión abdominal\",\"Rebotar al cerrar\",\"Inclinar el torso\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Reducir rango si hay dolor lateral de cadera\",\"Detener ante dolor agudo\"]","sustituciones":"[\"Abducción de cadera con banda\",\"Caminata lateral con banda\",\"Patada lateral en polea\",\"Puente de glúteo\",\"Hip thrust en máquina\",\"Patada de glúteo en polea\"]","progresiones":"[\"Aumentar carga\",\"Pausa abierta\",\"Tempo lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Menor carga\",\"Menor rango\",\"Banda ligera\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"15","rango_reps_min":"12","rango_reps_max":"20","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"60","maquina_gym":"Hip Abductor Machine","estado_calidad":"curado"},{"action":"insert","id":"sf-hip-adduction-machine","nombre":"Aducción de cadera en máquina","aliases":"[\"Aducción de cadera en máquina\",\"Aducción de cadera máquina\",\"aductores en máquina\",\"máquina de aductores\",\"machine hip adduction\",\"seated hip adduction\",\"Hip adduction machine\",\"Aducción de cadera en máq.\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"piernas","musculo_principal":"aductores","musculos_secundarios":"[\"pectíneo\",\"grácil\"]","equipamiento":"máquina de aducción de cadera","equipo_requerido":"[\"máquina de aducción de cadera\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"aducción de cadera","descripcion":"Aducción de cadera en máquina trabaja principalmente aductores, con participación de pectíneo, grácil. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Ajusta asiento/respaldo y coloca las almohadillas por dentro de los muslos, por encima de las rodillas. Usa la palanca para abrir las piernas solo hasta un estiramiento tolerable, fija pasador y mantén los pies sobre sus apoyos.\",\"Posición inicial: pies y rodillas alineados con el aparato o la trayectoria, pelvis nivelada y abdomen firme. Mantén espalda y cabeza neutras, pecho estable, hombros bajos, escápulas apoyadas cuando haya respaldo y manos sujetando las asas sin tirar.\",\"Agarre de soporte: toma las asas de la máquina con agarre neutro y pulgar cerrado; sirven para estabilizar pelvis y tronco, no para tirar del cuerpo. Mantén muñecas rectas y no sueltes hasta que el seguro o la pila estén completamente apoyados.\",\"Inicio y trayectoria: Mueve el fémur desde la cadera sin inclinar ni rotar la pelvis. Siente glúteo medio/mayor o aductores según la variante; rodilla, columna y tronco permanecen estables.\",\"Rango y biomecánica: Recorre solo hasta donde la pelvis siga nivelada y el músculo mantenga tensión; vuelve lentamente sin dejar que placas o piernas choquen.\",\"Tempo y respiración: Mueve en 2 s, pausa 1 s y retorna en 3 s. Exhala al separar/juntar o extender; inhala al volver.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Trípode del pie\",\"Rodillas siguen los dedos\",\"Pelvis estable\",\"Core presurizado\",\"Empuja el suelo\",\"No rebotes\",\"Sin bloqueo agresivo\",\"Profundidad controlada\",\"Espalda apoyada\",\"Pelvis neutra\"]","errores_comunes":"[\"Rodillas colapsan hacia dentro\",\"Talones se despegan\",\"Pelvis se enrolla o despega\",\"Rebotar abajo\",\"Bloquear rodillas con violencia\",\"Profundidad forzada\",\"Carga desigual\",\"Perder el brace\",\"Apertura inicial excesiva\",\"Rebotar al cerrar\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usar un rango menor si hay molestia inguinal\",\"Detener ante dolor agudo\"]","sustituciones":"[\"Aducción de cadera en polea\",\"Sentadilla sumo\",\"Zancada lateral\",\"Sentadilla goblet\",\"Prensa horizontal de piernas\",\"Ejercicio unilateral con apoyo\"]","progresiones":"[\"Aumentar carga\",\"Pausa cerrada\",\"Tempo lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Menor carga\",\"Menor apertura\",\"Isométrico suave con pelota\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"15","rango_reps_min":"12","rango_reps_max":"20","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"60","maquina_gym":"Hip Adductor Machine","estado_calidad":"curado"},{"action":"insert","id":"sf-hip-thrust-machine","nombre":"Hip thrust en máquina","aliases":"[\"Hip thrust en máquina\",\"Hip thrust máquina\",\"empuje de cadera en máquina\",\"glute drive\",\"machine hip thrust\",\"glute drive machine\",\"Hip thrust machine\",\"Hip thrust en máq.\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"glúteos","musculo_principal":"glúteo mayor","musculos_secundarios":"[\"isquiosurales\",\"aductores\",\"core\"]","equipamiento":"máquina de hip thrust","equipo_requerido":"[\"máquina de hip thrust\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"extensión de cadera","descripcion":"Hip thrust en máquina trabaja principalmente glúteo mayor, con participación de isquiosurales, aductores, core. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Ajusta la plataforma para que, arriba, las tibias queden casi verticales. Coloca el cinturón o almohadilla sobre el pliegue de la cadera —no sobre el abdomen—, apoya las escápulas en el respaldo si existe y selecciona carga; cierra el seguro antes de iniciar.\",\"Posición inicial: pies y rodillas alineados con el aparato o la trayectoria, pelvis nivelada y abdomen firme. Mantén espalda y cabeza neutras, pecho estable, hombros bajos, escápulas apoyadas cuando haya respaldo y manos sujetando las asas sin tirar.\",\"Agarre de soporte: toma las asas de la máquina con agarre neutro y pulgar cerrado; sirven para estabilizar pelvis y tronco, no para tirar del cuerpo. Mantén muñecas rectas y no sueltes hasta que el seguro o la pila estén completamente apoyados.\",\"Inicio y trayectoria: Empuja el suelo con los pies y extiende la cadera; mantén costillas hacia abajo y barbilla levemente recogida. Siente glúteos, no hiperextensión lumbar ni calambres dominantes en isquiotibiales.\",\"Rango y biomecánica: Sube hasta que hombros, cadera y rodillas formen una línea con tibias casi verticales; no eleves más arqueando la espalda. Baja hasta una flexión de cadera controlada sin perder los apoyos.\",\"Tempo y respiración: Sube en 1–2 s, pausa 2 s arriba y baja en 3 s. Exhala al extender la cadera e inhala al descender.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: baja hasta la posición soportada, acciona el cierre o deja descansar por completo la palanca/pila y comprueba que no haya tensión. Solo entonces abre el cinturón o retira la almohadilla y sal; no liberes el seguro con la cadera elevada.\"]","cues_tecnicos":"[\"Costillas hacia abajo\",\"Pelvis nivelada\",\"Empuja con todo el pie\",\"Aprieta glúteos\",\"No arquees la espalda\",\"Rodillas alineadas\",\"Pausa en contracción\",\"Baja con control\",\"Carga sobre pelvis\",\"Tibias casi verticales\"]","errores_comunes":"[\"Hiperextender la zona lumbar\",\"Rotar la pelvis\",\"Empujar solo con puntas\",\"Abrir o cerrar rodillas\",\"Usar impulso\",\"Recortar el estiramiento\",\"Golpear la pila\",\"Perder tensión abdominal\",\"Hiperextender la espalda\",\"Pies demasiado lejos\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Ajustar rango si hay molestia lumbar o de cadera\",\"Detener ante dolor agudo\"]","sustituciones":"[\"Hip thrust con barra\",\"Puente de glúteo con carga\",\"Patada de glúteo en polea\",\"Puente de glúteo\",\"Hip thrust en máquina\"]","progresiones":"[\"Aumentar carga\",\"Pausa arriba\",\"Tempo lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Menor carga\",\"Menor rango\",\"Puente de glúteo\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"15","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"60","maquina_gym":"Hip Thrust Machine","estado_calidad":"curado"},{"action":"insert","id":"sf-lat-pulldown-neutral-close","nombre":"Jalón al pecho con agarre neutro cerrado","aliases":"[\"Jalón al pecho con agarre neutro cerrado\",\"jalón cerrado\",\"jalón neutro\",\"close-grip lat pulldown\",\"neutral-grip pulldown\",\"Close neutral-grip lat pulldown\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"espalda","musculo_principal":"dorsal ancho","musculos_secundarios":"[\"bíceps braquial\",\"redondo mayor\",\"romboides\"]","equipamiento":"polea alta, agarre neutro cerrado","equipo_requerido":"[\"polea alta\",\"agarre neutro cerrado\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"jalón vertical","descripcion":"Jalón al pecho con agarre neutro cerrado trabaja principalmente dorsal ancho, con participación de bíceps braquial, redondo mayor, romboides. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Ajusta asiento y rodillo para inmovilizar los muslos; conecta un agarre V/neutro y comprueba el pasador. Toma el accesorio antes de sentarte y evita que la carga te eleve del asiento.\",\"Posición inicial: pies apoyados, rodillas suaves o fijadas por el rodillo, pelvis neutra y torso largo. Mantén abdomen firme, columna y cuello neutros, pecho abierto sin arquear, hombros lejos de orejas, escápulas controladas y codos desbloqueados.\",\"Agarre: neutro y cerrado, con palmas enfrentadas; suele permitir un recorrido cómodo y mayor ayuda del bíceps. Mantén pulgar cerrado y no dejes que las muñecas se doblen.\",\"Inicio y trayectoria: Comienza bajando las escápulas y luego lleva los codos hacia las costillas; evita iniciar con un balanceo. Siente dorsales y espalda alta, con bíceps como asistente y cuello relajado.\",\"Rango y biomecánica: Lleva la barra/agarre hacia la parte alta del pecho o eleva el pecho hacia las manos sin tirar detrás de la nuca; retorna hasta brazos largos sin perder el hombro activo. Evita rango que provoque dolor o que levante el cuerpo del asiento.\",\"Tempo y respiración: Sube o tira en 1–2 s, pausa 1 s y vuelve en 2–3 s. Exhala durante el tirón e inhala en el retorno controlado.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Pecho largo\",\"Hombros abajo\",\"Codos hacia costillas\",\"Cuello neutro\",\"Core firme\",\"Barra o cable cerca\",\"Sin tirón lumbar\",\"Controla el retorno\",\"Palmas enfrentadas\",\"Codos junto al torso\"]","errores_comunes":"[\"Redondear o hiperextender la espalda\",\"Tirar con impulso\",\"Elevar hombros\",\"Sacar la cabeza\",\"Flexionar muñecas\",\"Acortar el estiramiento\",\"Mover cadera o torso\",\"Golpear la pila\",\"Balancear el torso\",\"Convertirlo en remo\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Ajustar el recorrido ante molestia de hombro o codo\",\"Detener ante dolor agudo\"]","sustituciones":"[\"Jalón al pecho en polea alta\",\"Jalón al pecho con agarre supino\",\"Dominadas asistidas en máquina\",\"Remo con pecho apoyado\",\"Jalón al pecho con agarre neutro\",\"Remo en polea sentado\"]","progresiones":"[\"Aumentar carga\",\"Pausa abajo\",\"Tempo lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Menor carga\",\"Rango menor\",\"Máquina de dominadas asistidas\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"15","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"60","maquina_gym":"Lat Pulldown Machine","estado_calidad":"curado"},{"action":"insert","id":"sf-lat-pulldown-supinated","nombre":"Jalón al pecho con agarre supino","aliases":"[\"Jalón al pecho con agarre supino\",\"jalón supino\",\"jalón inverso\",\"reverse-grip lat pulldown\",\"supinated lat pulldown\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"espalda","musculo_principal":"dorsal ancho","musculos_secundarios":"[\"bíceps braquial\",\"redondo mayor\",\"romboides\"]","equipamiento":"polea alta, barra recta","equipo_requerido":"[\"polea alta\",\"barra recta\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"jalón vertical","descripcion":"Jalón al pecho con agarre supino trabaja principalmente dorsal ancho, con participación de bíceps braquial, redondo mayor, romboides. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Ajusta asiento y rodillo sobre los muslos; conecta una barra recta y usa una separación cercana al ancho de hombros. Verifica pasador, toma la barra en supinación antes de sentarte y comienza con una carga conservadora para muñecas y codos.\",\"Posición inicial: pies apoyados, rodillas suaves o fijadas por el rodillo, pelvis neutra y torso largo. Mantén abdomen firme, columna y cuello neutros, pecho abierto sin arquear, hombros lejos de orejas, escápulas controladas y codos desbloqueados.\",\"Agarre: supino y cercano al ancho de hombros; aumenta la participación del bíceps y exige tolerancia de muñeca. Mantén muñecas rectas y pulgar cerrado; cambia a neutro si la supinación incomoda.\",\"Inicio y trayectoria: Comienza bajando las escápulas y luego lleva los codos hacia las costillas; evita iniciar con un balanceo. Siente dorsales y espalda alta, con bíceps como asistente y cuello relajado.\",\"Rango y biomecánica: Lleva la barra/agarre hacia la parte alta del pecho o eleva el pecho hacia las manos sin tirar detrás de la nuca; retorna hasta brazos largos sin perder el hombro activo. Evita rango que provoque dolor o que levante el cuerpo del asiento.\",\"Tempo y respiración: Sube o tira en 1–2 s, pausa 1 s y vuelve en 2–3 s. Exhala durante el tirón e inhala en el retorno controlado.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Pecho largo\",\"Hombros abajo\",\"Codos hacia costillas\",\"Cuello neutro\",\"Core firme\",\"Barra o cable cerca\",\"Sin tirón lumbar\",\"Controla el retorno\",\"Muñecas cómodas\",\"Codos junto al torso\"]","errores_comunes":"[\"Redondear o hiperextender la espalda\",\"Tirar con impulso\",\"Elevar hombros\",\"Sacar la cabeza\",\"Flexionar muñecas\",\"Acortar el estiramiento\",\"Mover cadera o torso\",\"Golpear la pila\",\"Agarre demasiado ancho\",\"Doblar las muñecas\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Usar agarre neutro si la supinación molesta muñeca o codo\",\"Detener ante dolor agudo\"]","sustituciones":"[\"Jalón al pecho con agarre neutro cerrado\",\"Jalón al pecho en polea alta\",\"Dominadas asistidas en máquina\",\"Remo con pecho apoyado\",\"Jalón al pecho con agarre neutro\",\"Remo en polea sentado\"]","progresiones":"[\"Aumentar carga\",\"Pausa abajo\",\"Tempo lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Menor carga\",\"Agarre neutro\",\"Máquina de dominadas asistidas\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"15","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"60","maquina_gym":"Lat Pulldown Machine","estado_calidad":"curado"},{"action":"insert","id":"sf-lat-pulldown-wide","nombre":"Jalón al pecho con agarre amplio","aliases":"[\"Jalón al pecho con agarre amplio\",\"jalón amplio\",\"wide-grip lat pulldown\",\"wide lat pulldown\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"espalda","musculo_principal":"dorsal ancho","musculos_secundarios":"[\"redondo mayor\",\"bíceps braquial\",\"romboides\"]","equipamiento":"polea alta, barra larga","equipo_requerido":"[\"polea alta\",\"barra larga\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"jalón vertical","descripcion":"Jalón al pecho con agarre amplio trabaja principalmente dorsal ancho, con participación de redondo mayor, bíceps braquial, romboides. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Ajusta asiento y rodillo sobre los muslos. Toma la barra curva en pronación algo más ancha que los hombros —no en los extremos si obliga a doblar muñecas—, coloca el pasador y siéntate sin dejar que la carga te levante.\",\"Posición inicial: pies apoyados, rodillas suaves o fijadas por el rodillo, pelvis neutra y torso largo. Mantén abdomen firme, columna y cuello neutros, pecho abierto sin arquear, hombros lejos de orejas, escápulas controladas y codos desbloqueados.\",\"Agarre: prono algo más ancho que hombros para esta variante; un agarre excesivamente abierto recorta el recorrido. El neutro suele ser más cómodo para el hombro y el supino aumenta la ayuda del bíceps; usa pulgar cerrado y muñecas neutras.\",\"Inicio y trayectoria: Comienza bajando las escápulas y luego lleva los codos hacia las costillas; evita iniciar con un balanceo. Siente dorsales y espalda alta, con bíceps como asistente y cuello relajado.\",\"Rango y biomecánica: Lleva la barra/agarre hacia la parte alta del pecho o eleva el pecho hacia las manos sin tirar detrás de la nuca; retorna hasta brazos largos sin perder el hombro activo. Evita rango que provoque dolor o que levante el cuerpo del asiento.\",\"Tempo y respiración: Sube o tira en 1–2 s, pausa 1 s y vuelve en 2–3 s. Exhala durante el tirón e inhala en el retorno controlado.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Pecho largo\",\"Hombros abajo\",\"Codos hacia costillas\",\"Cuello neutro\",\"Core firme\",\"Barra o cable cerca\",\"Sin tirón lumbar\",\"Controla el retorno\",\"Agarre amplio cómodo\",\"Pecho alto\"]","errores_comunes":"[\"Redondear o hiperextender la espalda\",\"Tirar con impulso\",\"Elevar hombros\",\"Sacar la cabeza\",\"Flexionar muñecas\",\"Acortar el estiramiento\",\"Mover cadera o torso\",\"Golpear la pila\",\"Agarre excesivamente ancho\",\"Jalar tras la nuca\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Usar agarre neutro si el prono amplio molesta hombros o muñecas\",\"Detener ante dolor agudo\"]","sustituciones":"[\"Jalón al pecho en polea alta\",\"Jalón al pecho con agarre neutro cerrado\",\"Dominadas asistidas en máquina\",\"Remo con pecho apoyado\",\"Jalón al pecho con agarre neutro\",\"Remo en polea sentado\"]","progresiones":"[\"Aumentar carga\",\"Pausa abajo\",\"Tempo lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Menor carga\",\"Agarre menos ancho\",\"Máquina de dominadas asistidas\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"15","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"60","maquina_gym":"Lat Pulldown Machine","estado_calidad":"curado"},{"action":"insert","id":"sf-leg-curl-lying","nombre":"Curl femoral acostado en máquina","aliases":"[\"Curl femoral acostado en máquina\",\"Curl femoral acostado máquina\",\"curl femoral tumbado\",\"curl femoral boca abajo\",\"lying leg curl\",\"prone leg curl\",\"Curl femoral acostado en máq.\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"piernas","musculo_principal":"isquiosurales","musculos_secundarios":"[\"gastrocnemio\"]","equipamiento":"máquina de curl femoral acostado","equipo_requerido":"[\"máquina de curl femoral acostado\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"flexión de rodilla","descripcion":"Curl femoral acostado en máquina trabaja principalmente isquiosurales, con participación de gastrocnemio. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Ajusta el eje de la máquina a las rodillas y el rodillo justo encima de los talones. Regula la palanca inicial para una extensión cómoda, apoya pelvis y torso completos, fija pasadores y agarra las asas antes de mover la carga.\",\"Posición inicial: pies y rodillas alineados con el aparato o la trayectoria, pelvis nivelada y abdomen firme. Mantén espalda y cabeza neutras, pecho estable, hombros bajos, escápulas apoyadas cuando haya respaldo y manos sujetando las asas sin tirar.\",\"Agarre de soporte: toma las asas de la máquina con agarre neutro y pulgar cerrado; sirven para estabilizar pelvis y tronco, no para tirar del cuerpo. Mantén muñecas rectas y no sueltes hasta que el seguro o la pila estén completamente apoyados.\",\"Inicio y trayectoria: Flexiona la rodilla llevando el rodillo hacia los glúteos sin mover la pelvis. Siente isquiotibiales; la cadera y la columna permanecen estables.\",\"Rango y biomecánica: Flexiona hasta donde el talón avance sin que la cadera se levante; vuelve casi a extensión completa sin que la pila descanse ni la rodilla se bloquee.\",\"Tempo y respiración: Flexiona en 1–2 s, pausa 1 s y extiende en 3 s. Exhala al flexionar e inhala al regresar.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Trípode del pie\",\"Rodillas siguen los dedos\",\"Pelvis estable\",\"Core presurizado\",\"Empuja el suelo\",\"No rebotes\",\"Sin bloqueo agresivo\",\"Profundidad controlada\",\"Cadera apoyada\",\"Rodillas alineadas\"]","errores_comunes":"[\"Rodillas colapsan hacia dentro\",\"Talones se despegan\",\"Pelvis se enrolla o despega\",\"Rebotar abajo\",\"Bloquear rodillas con violencia\",\"Profundidad forzada\",\"Carga desigual\",\"Perder el brace\",\"Levantar la pelvis\",\"Rodillo sobre el Aquiles\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la flexión profunda de rodilla o cadera provoca dolor; ajusta asiento, profundidad y carga\",\"Reducir rango si hay molestia posterior de rodilla\",\"Detener ante dolor agudo\"]","sustituciones":"[\"Curl femoral sentado en máquina\",\"Curl femoral de pie en máquina\",\"Curl femoral con pelota\",\"Sentadilla goblet\",\"Prensa horizontal de piernas\",\"Ejercicio unilateral con apoyo\"]","progresiones":"[\"Aumentar carga\",\"Pausa arriba\",\"Tempo lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Menor carga\",\"Rango parcial\",\"Curl femoral con pelota\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"15","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"60","maquina_gym":"Lying Leg Curl Machine","estado_calidad":"curado"},{"action":"insert","id":"sf-leg-curl-standing","nombre":"Curl femoral de pie en máquina","aliases":"[\"Curl femoral de pie en máquina\",\"Curl femoral de pie máquina\",\"curl femoral unilateral de pie\",\"standing leg curl\",\"single-leg standing curl\",\"Standing single-leg curl\",\"Curl femoral de pie en máq.\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"piernas","musculo_principal":"isquiosurales","musculos_secundarios":"[\"gastrocnemio\",\"glúteo medio\"]","equipamiento":"máquina de curl femoral de pie","equipo_requerido":"[\"máquina de curl femoral de pie\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"flexión de rodilla unilateral","descripcion":"Curl femoral de pie en máquina trabaja principalmente isquiosurales, con participación de gastrocnemio, glúteo medio. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Ajusta plataforma y rodillo para alinear la rodilla de trabajo con el eje y apoyar el rodillo sobre el talón/Aquiles. Apoya el muslo contra la almohadilla, fija pasadores y sujeta las asas; la pierna de apoyo permanece estable.\",\"Posición inicial: pies y rodillas alineados con el aparato o la trayectoria, pelvis nivelada y abdomen firme. Mantén espalda y cabeza neutras, pecho estable, hombros bajos, escápulas apoyadas cuando haya respaldo y manos sujetando las asas sin tirar.\",\"Agarre de soporte: toma las asas de la máquina con agarre neutro y pulgar cerrado; sirven para estabilizar pelvis y tronco, no para tirar del cuerpo. Mantén muñecas rectas y no sueltes hasta que el seguro o la pila estén completamente apoyados.\",\"Inicio y trayectoria: Flexiona la rodilla llevando el rodillo hacia los glúteos sin mover la pelvis. Siente isquiotibiales; la cadera y la columna permanecen estables.\",\"Rango y biomecánica: Flexiona hasta donde el talón avance sin que la cadera se levante; vuelve casi a extensión completa sin que la pila descanse ni la rodilla se bloquee.\",\"Tempo y respiración: Flexiona en 1–2 s, pausa 1 s y extiende en 3 s. Exhala al flexionar e inhala al regresar.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Trípode del pie\",\"Rodillas siguen los dedos\",\"Pelvis estable\",\"Core presurizado\",\"Empuja el suelo\",\"No rebotes\",\"Sin bloqueo agresivo\",\"Profundidad controlada\",\"Pelvis al frente\",\"Rodilla alineada\"]","errores_comunes":"[\"Rodillas colapsan hacia dentro\",\"Talones se despegan\",\"Pelvis se enrolla o despega\",\"Rebotar abajo\",\"Bloquear rodillas con violencia\",\"Profundidad forzada\",\"Carga desigual\",\"Perder el brace\",\"Girar la cadera\",\"Arquear la espalda\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la flexión profunda de rodilla o cadera provoca dolor; ajusta asiento, profundidad y carga\",\"Reducir rango si hay molestia posterior de rodilla\",\"Usar variante sentada si falta estabilidad\"]","sustituciones":"[\"Curl femoral sentado en máquina\",\"Curl femoral acostado en máquina\",\"Curl femoral con pelota\",\"Sentadilla goblet\",\"Prensa horizontal de piernas\",\"Ejercicio unilateral con apoyo\"]","progresiones":"[\"Aumentar carga\",\"Pausa arriba\",\"Tempo lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Menor carga\",\"Apoyo adicional\",\"Curl femoral sentado\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"15","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"60","maquina_gym":"Standing Leg Curl Machine","estado_calidad":"curado"},{"action":"insert","id":"sf-leg-press-horizontal","nombre":"Prensa horizontal de piernas","aliases":"[\"Prensa horizontal de piernas\",\"prensa sentada de piernas\",\"horizontal leg press\",\"seated leg press\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"piernas","musculo_principal":"cuádriceps","musculos_secundarios":"[\"glúteo mayor\",\"isquiosurales\",\"aductores\"]","equipamiento":"máquina de prensa horizontal de piernas","equipo_requerido":"[\"máquina de prensa horizontal de piernas\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"sentadilla en máquina","descripcion":"Prensa horizontal de piernas trabaja principalmente cuádriceps, con participación de glúteo mayor, isquiosurales, aductores. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Ajusta el asiento para que la pelvis permanezca apoyada en el fondo con una flexión de rodilla tolerable. Coloca pies al ancho de caderas, selecciona carga y posición inicial; si hay seguro, localízalo y libéralo solo tras presionar la plataforma con control.\",\"Posición inicial: pies firmes y trípode plantar activo, rodillas orientadas hacia los dedos, cadera centrada, abdomen presurizado y columna neutra. Mantén pecho y cabeza siguiendo el torso, cuello largo, hombros estables y manos simétricas; no permitas que talones o pelvis pierdan apoyo.\",\"Agarre de soporte: toma las asas de la máquina con agarre neutro y pulgar cerrado; sirven para estabilizar pelvis y tronco, no para tirar del cuerpo. Mantén muñecas rectas y no sueltes hasta que el seguro o la pila estén completamente apoyados.\",\"Inicio y trayectoria: Inicia flexionando cadera y rodillas a la vez, siguiendo la dirección de los pies; distribuye presión entre talón, base del dedo gordo y base del meñique. Siente cuádriceps y glúteos, no presión aguda en rodilla o espalda.\",\"Rango y biomecánica: Desciende hasta la mayor profundidad que conserve talones, pelvis y columna controlados; empuja la plataforma/suelo y termina con cadera y rodillas extendidas sin hiperextender ni bloquear con violencia.\",\"Tempo y respiración: Desciende 3 s, pausa breve sin relajarte y sube en 1–2 s. Inhala y crea presión antes de bajar; exhala al superar la parte difícil sin perder el abdomen.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Trípode del pie\",\"Rodillas siguen los dedos\",\"Pelvis estable\",\"Core presurizado\",\"Empuja el suelo\",\"No rebotes\",\"Sin bloqueo agresivo\",\"Profundidad controlada\",\"Pelvis apoyada\",\"Pie completo\"]","errores_comunes":"[\"Rodillas colapsan hacia dentro\",\"Talones se despegan\",\"Pelvis se enrolla o despega\",\"Rebotar abajo\",\"Bloquear rodillas con violencia\",\"Profundidad forzada\",\"Carga desigual\",\"Perder el brace\",\"Asiento demasiado cerca\",\"Rodillas hacia dentro\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la flexión profunda de rodilla o cadera provoca dolor; ajusta asiento, profundidad y carga\",\"Reducir rango si hay molestia de rodilla o cadera\",\"Detener ante dolor agudo\"]","sustituciones":"[\"Prensa de piernas a 45 grados\",\"Sentadilla en máquina Smith\",\"Sentadilla goblet\",\"Prensa horizontal de piernas\",\"Ejercicio unilateral con apoyo\"]","progresiones":"[\"Aumentar carga gradualmente\",\"Pausa en la posición baja\",\"Unilateral con carga reducida si la máquina lo permite\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Menor carga\",\"Menor rango\",\"Sentadilla a caja\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"15","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"60","maquina_gym":"Horizontal Leg Press","estado_calidad":"curado"},{"action":"insert","id":"sf-pec-deck","nombre":"Aperturas en pec deck","aliases":"[\"Aperturas en pec deck\",\"contractor de pecho\",\"mariposa en máquina\",\"pec deck fly\",\"machine chest fly\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"pecho","musculo_principal":"pectoral mayor","musculos_secundarios":"[\"deltoides anterior\",\"serrato anterior\"]","equipamiento":"pec deck","equipo_requerido":"[\"pec deck\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"aducción horizontal de hombro","descripcion":"Aperturas en pec deck trabaja principalmente pectoral mayor, con participación de deltoides anterior, serrato anterior. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Ajusta el asiento para que codos/antebrazos queden a la altura del pecho y alinea hombros con el eje de giro. Regula el inicio para un estiramiento moderado, apoya espalda y cabeza, coloca el pasador por completo y toma ambos apoyos antes de mover la pila.\",\"Posición inicial: base estable, rodillas alineadas, cadera y abdomen firmes, espalda en posición neutra y cabeza siguiendo el torso. Mantén cuello largo, pecho controlado, hombros bajos, escápulas estables y manos/muñecas/codos alineados con el apoyo o implemento.\",\"Agarre/apoyo: usa una sujeción cerrada y simétrica, con muñecas neutras. Ajusta la variante si el agarre limita la postura o provoca molestias antes que aumentar la carga.\",\"Inicio y trayectoria: Inicia el movimiento desde la articulación objetivo y dirige la carga con control. Siente principalmente pectoral mayor; las articulaciones no móviles permanecen estables y el tronco no genera impulso.\",\"Rango y biomecánica: Usa el mayor recorrido cómodo que conserve alineación y tensión; evita rebotes, bloqueos agresivos y cualquier extremo que cambie la postura.\",\"Tempo y respiración: Tempo orientativo 2-1-3: esfuerzo en 2 s, pausa 1 s y retorno en 3 s. Exhala en el esfuerzo e inhala al regresar.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Pies firmes\",\"Glúteos apoyados\",\"Escápulas estables\",\"Pecho controlado\",\"Antebrazos verticales\",\"Muñecas apiladas\",\"Empuja sin rebotar\",\"Baja con control\",\"Pecho apoyado\",\"Hombros bajos\"]","errores_comunes":"[\"Despegar glúteos o espalda\",\"Rebotar en el pecho o topes\",\"Abrir codos sin control\",\"Doblar muñecas\",\"Elevar hombros\",\"Recortar recorrido\",\"Bloquear codos con golpe\",\"Usar carga sin salida segura\",\"Asiento mal ajustado\",\"Abrir demasiado\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Reducir la apertura ante molestia anterior de hombro\",\"Detener ante dolor agudo\"]","sustituciones":"[\"Aperturas en polea\",\"Aperturas con mancuernas\",\"Press en máquina de pecho\",\"Press con mancuernas\",\"Press de pecho en máquina\",\"Flexiones con manos elevadas\"]","progresiones":"[\"Aumentar carga\",\"Pausa al cerrar\",\"Tempo lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Menor carga\",\"Menor apertura\",\"Press de pecho con agarre neutro\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"15","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"60","maquina_gym":"Pec Deck","estado_calidad":"curado"},{"action":"insert","id":"sf-reverse-pec-deck","nombre":"Aperturas inversas en pec deck","aliases":"[\"Aperturas inversas en pec deck\",\"reverse pec deck\",\"pájaros en máquina\",\"rear delt fly machine\",\"reverse fly machine\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"hombros","musculo_principal":"deltoides posterior","musculos_secundarios":"[\"romboides\",\"trapecio medio\",\"infraespinoso\"]","equipamiento":"pec deck reversible","equipo_requerido":"[\"pec deck reversible\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"abducción horizontal de hombro","descripcion":"Aperturas inversas en pec deck trabaja principalmente deltoides posterior, con participación de romboides, trapecio medio, infraespinoso. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Gira o ajusta los brazos al modo deltoide posterior. Regula el asiento para que las empuñaduras queden a la altura de hombros, coloca pecho contra el respaldo, elige un inicio sin hombros forzados y fija el pasador.\",\"Posición inicial: base estable, rodillas alineadas, cadera y abdomen firmes, espalda en posición neutra y cabeza siguiendo el torso. Mantén cuello largo, pecho controlado, hombros bajos, escápulas estables y manos/muñecas/codos alineados con el apoyo o implemento.\",\"Agarre/apoyo: usa una sujeción cerrada y simétrica, con muñecas neutras. Ajusta la variante si el agarre limita la postura o provoca molestias antes que aumentar la carga.\",\"Inicio y trayectoria: Inicia el movimiento desde la articulación objetivo y dirige la carga con control. Siente principalmente deltoides posterior; las articulaciones no móviles permanecen estables y el tronco no genera impulso.\",\"Rango y biomecánica: Usa el mayor recorrido cómodo que conserve alineación y tensión; evita rebotes, bloqueos agresivos y cualquier extremo que cambie la postura.\",\"Tempo y respiración: Tempo orientativo 2-1-3: esfuerzo en 2 s, pausa 1 s y retorno en 3 s. Exhala en el esfuerzo e inhala al regresar.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Cuello largo\",\"Hombros lejos de orejas\",\"Core firme\",\"Muñecas neutras\",\"Codos guían\",\"Sin impulso lumbar\",\"Recorrido tolerable\",\"Excéntrica lenta\",\"Pecho apoyado\",\"Hombros bajos\"]","errores_comunes":"[\"Encoger hombros\",\"Arquear la zona lumbar\",\"Usar impulso\",\"Elevar por encima del rango tolerable\",\"Doblar muñecas\",\"Adelantar la cabeza\",\"Codos fuera de trayectoria\",\"Soltar la excéntrica\",\"Asiento mal ajustado\",\"Despegar el pecho\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Reducir rango si hay dolor posterior o anterior de hombro\",\"Detener ante dolor agudo\"]","sustituciones":"[\"Pájaros con mancuernas\",\"Face pull en polea alta\",\"Aperturas inversas en polea\",\"Variante unilateral en polea\",\"Variante con mancuernas sentado\",\"Máquina de hombro con agarre neutro\"]","progresiones":"[\"Aumentar carga\",\"Pausa abierta\",\"Tempo lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Menor carga\",\"Menor rango\",\"Face pull ligero\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"15","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"60","maquina_gym":"Reverse Pec Deck","estado_calidad":"curado"},{"action":"insert","id":"sf-row-tbar-chest-supported","nombre":"Remo en T con soporte de pecho","aliases":"[\"Remo en T con soporte de pecho\",\"remo T pecho apoyado\",\"chest-supported T-bar row\",\"supported T-bar row\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"espalda","musculo_principal":"espalda media","musculos_secundarios":"[\"dorsal ancho\",\"romboides\",\"trapecio medio\",\"bíceps braquial\"]","equipamiento":"máquina de remo en T con soporte de pecho","equipo_requerido":"[\"máquina de remo en T con soporte de pecho\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"jalón horizontal","descripcion":"Remo en T con soporte de pecho trabaja principalmente espalda media, con participación de dorsal ancho, romboides, trapecio medio. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Ajusta plataforma o apoyo de pecho para que el esternón descanse sin comprimir la respiración y los brazos alcancen las asas sin despegar el torso. Carga ambos lados si corresponde, coloca seguros y elige agarre antes de elevar el carro.\",\"Posición inicial: pies apoyados, rodillas suaves o fijadas por el rodillo, pelvis neutra y torso largo. Mantén abdomen firme, columna y cuello neutros, pecho abierto sin arquear, hombros lejos de orejas, escápulas controladas y codos desbloqueados.\",\"Agarre: el neutro facilita llevar los codos junto al torso y suele ser cómodo; el prono algo más ancho desplaza énfasis hacia espalda alta y deltoide posterior; el supino añade bíceps. Elige uno que permita muñecas rectas y hombros bajos.\",\"Inicio y trayectoria: Inicia llevando los codos hacia atrás y ligeramente hacia el torso; la escápula se retrae/protrae de forma controlada sin elevar hombros. Siente dorsal y espalda media, no el cuello ni la zona lumbar.\",\"Rango y biomecánica: Tira hasta que el asa se acerque al tronco sin sobreextender hombro ni echarte atrás; retorna hasta brazos largos y escápulas que avancen sin redondear la columna. Cadera y torso permanecen estables.\",\"Tempo y respiración: Tira en 1–2 s, pausa 1 s con hombros bajos y retorna en 2–3 s. Exhala al remar e inhala al extender los brazos.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Pecho largo\",\"Hombros abajo\",\"Codos hacia costillas\",\"Cuello neutro\",\"Core firme\",\"Barra o cable cerca\",\"Sin tirón lumbar\",\"Controla el retorno\",\"Pecho apoyado\",\"Codos atrás\"]","errores_comunes":"[\"Redondear o hiperextender la espalda\",\"Tirar con impulso\",\"Elevar hombros\",\"Sacar la cabeza\",\"Flexionar muñecas\",\"Acortar el estiramiento\",\"Mover cadera o torso\",\"Golpear la pila\",\"Despegar el pecho\",\"Encoger hombros\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Ajustar el cojín si comprime de forma incómoda el esternón\",\"Detener ante dolor agudo\"]","sustituciones":"[\"Remo pecho apoyado\",\"Remo en polea sentado\",\"Remo en T con barra landmine\",\"Remo con pecho apoyado\",\"Jalón al pecho con agarre neutro\"]","progresiones":"[\"Aumentar carga\",\"Pausa arriba\",\"Tempo lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Menor carga\",\"Agarre neutro\",\"Remo en polea sentado\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"15","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"60","maquina_gym":"Chest-Supported T-Bar Row Machine","estado_calidad":"curado"},{"action":"insert","id":"sf-shoulder-machine-press","nombre":"Press en máquina de hombro","aliases":"[\"Press en máquina de hombro\",\"Press máquina de hombro\",\"press de hombro sentado en máquina\",\"machine shoulder press\",\"seated shoulder press machine\",\"Shoulder press machine\",\"Press en máq. de hombro\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"hombros","musculo_principal":"deltoides anterior","musculos_secundarios":"[\"deltoides lateral\",\"tríceps braquial\",\"trapecio superior\"]","equipamiento":"máquina de press de hombro","equipo_requerido":"[\"máquina de press de hombro\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"empuje vertical","descripcion":"Press en máquina de hombro trabaja principalmente deltoides anterior, con participación de deltoides lateral, tríceps braquial, trapecio superior. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Ajusta el asiento para que las empuñaduras comiencen entre mentón y orejas y los pies queden planos. Apoya pelvis, espalda y cabeza, regula el inicio si existe, coloca el pasador por completo y evita una profundidad que lleve los codos muy detrás del tronco.\",\"Posición inicial: pies o apoyos firmes, rodillas y cadera estables, glúteos y abdomen contraídos. Conserva columna y cuello neutros, pecho controlado, hombros lejos de orejas y escápulas estables; apila manos, muñecas y codos según la dirección del empuje.\",\"Agarre: prono en barra/suelo o neutro en asas/mancuernas. Usa una anchura que deje antebrazos casi verticales; un agarre cerrado aumenta demanda de tríceps y uno muy ancho acorta el recorrido. Pulgar cerrado y muñeca apilada sobre antebrazo.\",\"Inicio y trayectoria: Inicia empujando el apoyo o la carga en la línea prevista mientras hombro y codo se extienden coordinados. Siente pectoral/deltoides/tríceps según la variante, con abdomen firme y hombros lejos de orejas.\",\"Rango y biomecánica: Baja hasta que el codo alcance una profundidad tolerable y el hombro conserve centrado, normalmente con antebrazo vertical; sube hasta brazos casi extendidos sin chocar ni hiperextender. Evita rebotes y extremos que despeguen espalda o pelvis.\",\"Tempo y respiración: Tempo base 3-0-1: desciende 3 s, pausa sin rebote y empuja en 1 s controlado. Inhala al bajar y exhala al cruzar el punto de mayor esfuerzo; usa respiración con brace solo si conoces la técnica.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Cuello largo\",\"Hombros lejos de orejas\",\"Core firme\",\"Muñecas neutras\",\"Codos guían\",\"Sin impulso lumbar\",\"Recorrido tolerable\",\"Excéntrica lenta\",\"Manijas a altura de hombros\",\"Espalda apoyada\"]","errores_comunes":"[\"Encoger hombros\",\"Arquear la zona lumbar\",\"Usar impulso\",\"Elevar por encima del rango tolerable\",\"Doblar muñecas\",\"Adelantar la cabeza\",\"Codos fuera de trayectoria\",\"Soltar la excéntrica\",\"Asiento demasiado bajo\",\"Arquear la espalda\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Usar agarre neutro y rango menor si hay molestia de hombro\",\"Detener ante dolor agudo\"]","sustituciones":"[\"Press de hombro con mancuernas\",\"Landmine press\",\"Press militar con barra\",\"Variante unilateral en polea\",\"Variante con mancuernas sentado\",\"Máquina de hombro con agarre neutro\"]","progresiones":"[\"Aumentar carga\",\"Pausa abajo\",\"Tempo lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Menor carga\",\"Agarre neutro\",\"Landmine press\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"15","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"60","maquina_gym":"Shoulder Press Machine","estado_calidad":"curado"},{"action":"insert","id":"sf-smith-squat","nombre":"Sentadilla en máquina Smith","aliases":"[\"Sentadilla en máquina Smith\",\"Sentadilla máquina Smith\",\"sentadilla Smith\",\"Smith machine squat\",\"Smith squat\",\"Sentadilla en máq. Smith\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"piernas","musculo_principal":"cuádriceps","musculos_secundarios":"[\"glúteo mayor\",\"aductores\",\"isquiosurales\",\"core\"]","equipamiento":"máquina Smith","equipo_requerido":"[\"máquina Smith\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"sentadilla guiada","descripcion":"Sentadilla en máquina Smith trabaja principalmente cuádriceps, con participación de glúteo mayor, aductores, isquiosurales. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Coloca la barra sobre trapecios —no sobre el cuello—, ajusta los topes de seguridad justo por debajo de tu profundidad prevista y carga discos iguales con seguros. Gira la barra para desenganchar solo cuando pies, tronco y agarre estén estables; practica el reenganche con la barra vacía.\",\"Posición inicial: pies firmes y trípode plantar activo, rodillas orientadas hacia los dedos, cadera centrada, abdomen presurizado y columna neutra. Mantén pecho y cabeza siguiendo el torso, cuello largo, hombros estables y manos simétricas; no permitas que talones o pelvis pierdan apoyo.\",\"Agarre: prono cerrado alrededor de la barra y muñecas firmes. En peso muerto pesado puede usarse mixto o hook grip, alternando lados y solo con experiencia; para aprender, usa doble prono. La barra debe permanecer controlada, nunca apoyada en dedos abiertos.\",\"Inicio y trayectoria: Inicia flexionando cadera y rodillas a la vez, siguiendo la dirección de los pies; distribuye presión entre talón, base del dedo gordo y base del meñique. Siente cuádriceps y glúteos, no presión aguda en rodilla o espalda.\",\"Rango y biomecánica: Desciende hasta la mayor profundidad que conserve talones, pelvis y columna controlados; empuja la plataforma/suelo y termina con cadera y rodillas extendidas sin hiperextender ni bloquear con violencia.\",\"Tempo y respiración: Desciende 3 s, pausa breve sin relajarte y sube en 1–2 s. Inhala y crea presión antes de bajar; exhala al superar la parte difícil sin perder el abdomen.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición en la posición de control, reengancha ambos seguros y verifica visualmente que soporten el carro/barra antes de relajarte. Baja con cuidado, descarga discos de forma alterna y deja la máquina estable; nunca abandones un lado cargado.\"]","cues_tecnicos":"[\"Trípode del pie\",\"Rodillas siguen los dedos\",\"Pelvis estable\",\"Core presurizado\",\"Empuja el suelo\",\"No rebotes\",\"Sin bloqueo agresivo\",\"Profundidad controlada\",\"Topes ajustados\",\"Barra sobre trapecios\"]","errores_comunes":"[\"Rodillas colapsan hacia dentro\",\"Talones se despegan\",\"Pelvis se enrolla o despega\",\"Rebotar abajo\",\"Bloquear rodillas con violencia\",\"Profundidad forzada\",\"Carga desigual\",\"Perder el brace\",\"No colocar topes\",\"Barra sobre el cuello\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la flexión profunda de rodilla o cadera provoca dolor; ajusta asiento, profundidad y carga\",\"Ajustar la posición de pies o elegir otra variante si la trayectoria causa molestia\",\"Detener ante dolor agudo\"]","sustituciones":"[\"Sentadilla hack en máquina\",\"Prensa de piernas a 45 grados\",\"Sentadilla goblet\",\"Prensa horizontal de piernas\",\"Ejercicio unilateral con apoyo\"]","progresiones":"[\"Aumentar carga\",\"Pausa abajo\",\"Tempo excéntrico lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Menor carga\",\"Sentadilla a caja en Smith\",\"Prensa horizontal de piernas\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"15","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"60","maquina_gym":"Smith Machine","estado_calidad":"curado"},{"action":"insert","id":"sf-triceps-cable-kickback","nombre":"Patada de tríceps en polea","aliases":"[\"Patada de tríceps en polea\",\"Patada tríceps en polea\",\"extensión de tríceps atrás en polea\",\"cable triceps kickback\",\"single-arm cable kickback\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"brazos","musculo_principal":"tríceps braquial","musculos_secundarios":"[\"ancóneo\"]","equipamiento":"polea baja, agarre individual","equipo_requerido":"[\"polea baja\",\"agarre individual\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"extensión de codo","descripcion":"Patada de tríceps en polea trabaja principalmente tríceps braquial, con participación de ancóneo. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Coloca la polea baja con asa individual, comprueba mosquetón/pasador y retrocede hasta tensar el cable. Apoya la mano libre en la torre o banco y deja el brazo de trabajo paralelo al torso. La cifra de la pila puede no equivaler a la resistencia efectiva por la relación de poleas; registra siempre la misma torre, ajuste y accesorio.\",\"Posición inicial: pies al ancho de caderas, rodillas suaves, pelvis neutra y abdomen firme. Mantén columna erguida, cabeza/cuello neutros, pecho relajado, hombros bajos, escápulas controladas y manos/muñecas alineadas; coloca los codos según la trayectoria sin fijarlos con rigidez.\",\"Agarre: barra recta/EZ en prono para una trayectoria estable; cuerda o asa en neutro cuando quieras libertad de muñeca. Mantén pulgar cerrado, muñecas alineadas y no conviertas el movimiento en un press de hombros.\",\"Inicio y trayectoria: Mantén el brazo superior estable e inicia moviendo el antebrazo por flexión/extensión del codo. Extiende con el tríceps sin adelantar hombros ni arquear la espalda.\",\"Rango y biomecánica: Recorre desde una flexión cómoda que produzca estiramiento hasta casi extender el codo; evita bloquear con violencia o llevar la carga a un ángulo que cambie a movimiento de hombro.\",\"Tempo y respiración: Tempo 3-0-1 con una pausa breve en extensión: inhala al flexionar el codo y exhala al extender; controla especialmente la excéntrica.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Codos en su carril\",\"Muñecas neutras\",\"Hombros lejos de orejas\",\"Costillas sobre pelvis\",\"Aprieta el músculo objetivo\",\"Sin balanceo del torso\",\"Controla la excéntrica\",\"Termina antes de perder postura\",\"Codo fijo\",\"Espalda neutra\"]","errores_comunes":"[\"Balancear el torso\",\"Adelantar o abrir los codos\",\"Doblar las muñecas\",\"Elevar los hombros\",\"Usar recorrido recortado\",\"Dejar caer la carga\",\"Contener la respiración\",\"Elegir peso que cambia la trayectoria\",\"Balancear el brazo\",\"Mover el hombro\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Reducir carga si hay molestia de codo\",\"Detener ante dolor agudo\"]","sustituciones":"[\"Patada de tríceps con mancuernas\",\"Pushdown de tríceps con cuerda\",\"Extensión de tríceps sobre la cabeza en polea\",\"Variante equivalente en polea\",\"Variante con mancuernas\",\"Máquina de brazos con apoyo\"]","progresiones":"[\"Aumentar carga\",\"Pausa extendido\",\"Tempo lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Menor carga\",\"Apoyo del torso\",\"Pushdown unilateral\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"15","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"60","maquina_gym":"Functional Trainer","estado_calidad":"curado"},{"action":"insert","id":"sf-triceps-overhead-cable","nombre":"Extensión de tríceps sobre la cabeza en polea","aliases":"[\"Extensión de tríceps sobre la cabeza en polea\",\"Extensión tríceps sobre la cabeza en polea\",\"extensión overhead en polea\",\"cable overhead triceps extension\",\"rope overhead extension\",\"Overhead cable triceps extension\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"brazos","musculo_principal":"tríceps braquial","musculos_secundarios":"[\"ancóneo\",\"core\"]","equipamiento":"polea ajustable, cuerda","equipo_requerido":"[\"polea ajustable\",\"cuerda\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"extensión de codo sobre la cabeza","descripcion":"Extensión de tríceps sobre la cabeza en polea trabaja principalmente tríceps braquial, con participación de ancóneo, core. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Ajusta la polea entre altura baja y media según el modelo, conecta cuerda y verifica el mosquetón. De espaldas a la torre, lleva la cuerda sobre la cabeza con un paso escalonado; aléjate hasta tensar el cable sin perder equilibrio. La cifra de la pila puede no equivaler a la resistencia efectiva por la relación de poleas; registra siempre la misma torre, ajuste y accesorio.\",\"Posición inicial: pies al ancho de caderas, rodillas suaves, pelvis neutra y abdomen firme. Mantén columna erguida, cabeza/cuello neutros, pecho relajado, hombros bajos, escápulas controladas y manos/muñecas alineadas; coloca los codos según la trayectoria sin fijarlos con rigidez.\",\"Agarre: barra recta/EZ en prono para una trayectoria estable; cuerda o asa en neutro cuando quieras libertad de muñeca. Mantén pulgar cerrado, muñecas alineadas y no conviertas el movimiento en un press de hombros.\",\"Inicio y trayectoria: Mantén el brazo superior estable e inicia moviendo el antebrazo por flexión/extensión del codo. Extiende con el tríceps sin adelantar hombros ni arquear la espalda.\",\"Rango y biomecánica: Recorre desde una flexión cómoda que produzca estiramiento hasta casi extender el codo; evita bloquear con violencia o llevar la carga a un ángulo que cambie a movimiento de hombro.\",\"Tempo y respiración: Tempo 3-0-1 con una pausa breve en extensión: inhala al flexionar el codo y exhala al extender; controla especialmente la excéntrica.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Codos en su carril\",\"Muñecas neutras\",\"Hombros lejos de orejas\",\"Costillas sobre pelvis\",\"Aprieta el músculo objetivo\",\"Sin balanceo del torso\",\"Controla la excéntrica\",\"Termina antes de perder postura\",\"Codos al frente\",\"Costillas controladas\"]","errores_comunes":"[\"Balancear el torso\",\"Adelantar o abrir los codos\",\"Doblar las muñecas\",\"Elevar los hombros\",\"Usar recorrido recortado\",\"Dejar caer la carga\",\"Contener la respiración\",\"Elegir peso que cambia la trayectoria\",\"Arquear la espalda\",\"Abrir los codos\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Reducir rango si hay molestia de hombro o codo\",\"Detener ante dolor agudo\"]","sustituciones":"[\"Extensión de tríceps sobre la cabeza con mancuerna\",\"Pushdown de tríceps con cuerda\",\"Press francés con barra EZ\",\"Variante equivalente en polea\",\"Variante con mancuernas\",\"Máquina de brazos con apoyo\"]","progresiones":"[\"Aumentar carga\",\"Pausa extendido\",\"Tempo lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Menor carga\",\"Unilateral\",\"Pushdown con cuerda\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"15","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"60","maquina_gym":"Dual Adjustable Pulley","estado_calidad":"curado"},{"action":"insert","id":"sf-triceps-parallel-dips","nombre":"Fondos asistidos en máquina","aliases":"[\"Fondos asistidos en máquina\",\"Fondos asistidos máquina\",\"fondos de tríceps\",\"triceps dips\",\"upright parallel bar dips\",\"Assisted dip machine\",\"Fondos asistidos en máq.\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"brazos","musculo_principal":"tríceps braquial","musculos_secundarios":"[\"pectoral mayor\",\"deltoides anterior\"]","equipamiento":"máquina de fondos asistidos","equipo_requerido":"[\"Assisted Dip Machine\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"empuje vertical","descripcion":"Fondos asistidos en máquina trabaja principalmente tríceps braquial, con participación de pectoral mayor, deltoides anterior. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Selecciona suficiente asistencia —más peso significa más ayuda—, ajusta asas si son móviles y verifica que la plataforma recorra libre. Sube por los escalones, toma agarre neutro, apoya ambas rodillas o pies y transfiere el peso lentamente antes de bajar.\",\"Posición inicial: pies o apoyos firmes, rodillas y cadera estables, glúteos y abdomen contraídos. Conserva columna y cuello neutros, pecho controlado, hombros lejos de orejas y escápulas estables; apila manos, muñecas y codos según la dirección del empuje.\",\"Agarre: prono en barra/suelo o neutro en asas/mancuernas. Usa una anchura que deje antebrazos casi verticales; un agarre cerrado aumenta demanda de tríceps y uno muy ancho acorta el recorrido. Pulgar cerrado y muñeca apilada sobre antebrazo.\",\"Inicio y trayectoria: Inicia empujando el apoyo o la carga en la línea prevista mientras hombro y codo se extienden coordinados. Siente pectoral/deltoides/tríceps según la variante, con abdomen firme y hombros lejos de orejas.\",\"Rango y biomecánica: Baja hasta que el codo alcance una profundidad tolerable y el hombro conserve centrado, normalmente con antebrazo vertical; sube hasta brazos casi extendidos sin chocar ni hiperextender. Evita rebotes y extremos que despeguen espalda o pelvis.\",\"Tempo y respiración: Tempo base 3-0-1: desciende 3 s, pausa sin rebote y empuja en 1 s controlado. Inhala al bajar y exhala al cruzar el punto de mayor esfuerzo; usa respiración con brace solo si conoces la técnica.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina arriba sin hiperextender codos, controla la plataforma hasta su posición alta y conserva ambas manos en las asas. Retira una rodilla o pie a la vez hacia el escalón y baja de frente; no saltes ni dejes que el contrapeso impulse la plataforma.\"]","cues_tecnicos":"[\"Codos en su carril\",\"Muñecas neutras\",\"Hombros lejos de orejas\",\"Costillas sobre pelvis\",\"Aprieta el músculo objetivo\",\"Sin balanceo del torso\",\"Controla la excéntrica\",\"Termina antes de perder postura\",\"Torso vertical\",\"Codos hacia atrás\"]","errores_comunes":"[\"Balancear el torso\",\"Adelantar o abrir los codos\",\"Doblar las muñecas\",\"Elevar los hombros\",\"Usar recorrido recortado\",\"Dejar caer la carga\",\"Contener la respiración\",\"Elegir peso que cambia la trayectoria\",\"Bajar demasiado\",\"Abrir codos\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Evitar con dolor anterior de hombro o inestabilidad\",\"Usar asistencia si no se controla el descenso\"]","sustituciones":"[\"Pushdown de tríceps con barra\",\"Fondos en banco para tríceps\",\"Press francés con barra EZ\",\"Variante equivalente en polea\",\"Variante con mancuernas\",\"Máquina de brazos con apoyo\"]","progresiones":"[\"Añadir carga\",\"Pausa abajo\",\"Tempo lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Máquina de fondos asistidos\",\"Banda de asistencia\",\"Pushdown en polea\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"15","descanso_segundos_min":"90","descanso_segundos_max":"150","rir_recomendado":"2","duracion_promedio_segundos":"60","maquina_gym":"Assisted Dip Machine","estado_calidad":"curado"},{"action":"insert","id":"sf-triceps-pushdown-bar","nombre":"Pushdown de tríceps con barra","aliases":"[\"Pushdown de tríceps con barra\",\"Pushdown tríceps barra\",\"jalón de tríceps con barra\",\"triceps bar pushdown\",\"straight-bar pushdown\",\"Straight-bar triceps pushdown\",\"Pushdown de tríceps con BB\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"brazos","musculo_principal":"tríceps braquial","musculos_secundarios":"[\"ancóneo\"]","equipamiento":"polea alta, barra recta o barra V","equipo_requerido":"[\"polea alta\",\"barra recta o barra V\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"extensión de codo en polea","descripcion":"Pushdown de tríceps con barra trabaja principalmente tríceps braquial, con participación de ancóneo. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Sube la polea por encima de la cabeza, conecta barra recta/EZ y comprueba mosquetón, cable y pasador. Retrocede lo suficiente para que los antebrazos puedan flexionarse sin que la pila descanse entre repeticiones. La cifra de la pila puede no equivaler a la resistencia efectiva por la relación de poleas; registra siempre la misma torre, ajuste y accesorio.\",\"Posición inicial: pies al ancho de caderas, rodillas suaves, pelvis neutra y abdomen firme. Mantén columna erguida, cabeza/cuello neutros, pecho relajado, hombros bajos, escápulas controladas y manos/muñecas alineadas; coloca los codos según la trayectoria sin fijarlos con rigidez.\",\"Agarre: barra recta/EZ en prono para una trayectoria estable; cuerda o asa en neutro cuando quieras libertad de muñeca. Mantén pulgar cerrado, muñecas alineadas y no conviertas el movimiento en un press de hombros.\",\"Inicio y trayectoria: Inicia extendiendo los codos hacia abajo; los antebrazos giran alrededor de codos quietos. Siente el tríceps y evita que hombros o torso generen impulso.\",\"Rango y biomecánica: Extiende hasta dejar el brazo recto sin hiperextender el codo; retorna hasta que el antebrazo quede algo por encima de horizontal sin despegar los codos. El hombro y la columna permanecen estables.\",\"Tempo y respiración: Tempo 2-1-2: extiende en 2 s, pausa 1 s abajo y vuelve en 2 s. Exhala al extender e inhala durante el retorno.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Codos en su carril\",\"Muñecas neutras\",\"Hombros lejos de orejas\",\"Costillas sobre pelvis\",\"Aprieta el músculo objetivo\",\"Sin balanceo del torso\",\"Controla la excéntrica\",\"Termina antes de perder postura\",\"Codos pegados\",\"Torso firme\"]","errores_comunes":"[\"Balancear el torso\",\"Adelantar o abrir los codos\",\"Doblar las muñecas\",\"Elevar los hombros\",\"Usar recorrido recortado\",\"Dejar caer la carga\",\"Contener la respiración\",\"Elegir peso que cambia la trayectoria\",\"Abrir los codos\",\"Inclinarse sobre la barra\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usar cuerda o menor carga si hay molestia de muñeca o codo\",\"Detener ante dolor agudo\"]","sustituciones":"[\"Pushdown de tríceps con cuerda\",\"Extensión de tríceps sobre la cabeza en polea\",\"Press francés con barra EZ\",\"Variante equivalente en polea\",\"Variante con mancuernas\",\"Máquina de brazos con apoyo\"]","progresiones":"[\"Aumentar carga\",\"Pausa abajo\",\"Tempo lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Menor carga\",\"Barra V\",\"Pushdown con cuerda\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"10","rango_reps_min":"8","rango_reps_max":"15","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"60","maquina_gym":"Functional Trainer","estado_calidad":"curado"},{"action":"deprecate_review","id":"61","nombre":"Dragon flag en banco","aliases":"[\"Dragon flag en banco\",\"bandera de dragón\",\"dragon flag\",\"dragon flag raise\"]","nivel":"avanzado","nivel_minimo":"avanzado","grupo_muscular":"core","musculo_principal":"core","musculos_secundarios":"[\"recto abdominal\",\"dorsal ancho\",\"flexores de cadera\"]","equipamiento":"banco o barra fija","equipo_requerido":"[\"banco o barra fija\"]","tipo_entrenamiento":"core","patron_movimiento":"core anti-extensión","descripcion":"Dragon flag en banco trabaja principalmente core, con participación de recto abdominal, dorsal ancho, flexores de cadera. Sirve para mejorar la capacidad física específica y el control técnico. Conviene solo como habilidad avanzada, después de dominar sus progresiones y preferentemente con supervisión presencial.","instrucciones":"[\"Preparación: usa un banco pesado que no pueda volcar y despeja la zona detrás de la cabeza. Túmbate y toma bordes o soporte fijo con pulgar cerrado; practica primero descensos con rodillas flexionadas y nunca agarres una pieza móvil.\",\"Posición inicial: tumbado en un banco pesado y estable, toma sus bordes detrás de la cabeza con pulgar cerrado y codos flexionados. Eleva piernas y pelvis, mantén hombros/parte alta de la espalda apoyados, abdomen y glúteos tensos, piernas juntas y cuello sin cargar peso.\",\"Apoyo/agarre: manos completas, dedos separados y muñecas alineadas bajo el soporte cuando estén en el suelo; en barra/anillas usa agarre cerrado con pulgar. Ajusta el ángulo o usa asas si la extensión de muñeca no es tolerable.\",\"Inicio y trayectoria: Desde hombros apoyados, eleva pelvis y cuerpo como una unidad y desciende lentamente desde hombros, no doblando la cadera. Siente abdomen, dorsal y glúteos; el cuello no soporta la carga.\",\"Rango y biomecánica: Baja solo hasta conservar línea de hombros a tobillos y zona lumbar sin arco; flexiona rodillas para regresar. No intentes llegar paralelo al suelo si se despega la parte alta de la espalda.\",\"Tempo y respiración: Desciende 3–5 s, pausa breve y regresa con control o ayuda. Exhala durante el ascenso e inhala en el descenso sin perder el brace.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: flexiona rodillas hacia el pecho, baja pelvis y pies al banco/suelo y solo entonces suelta el agarre. Levántate de lado; no dejes caer las piernas ni gires el cuello bajo tensión.\"]","cues_tecnicos":"[\"Costillas sobre pelvis\",\"Respira detrás del brace\",\"Cuello largo\",\"Pelvis controlada\",\"Hombros activos\",\"Sin arco lumbar\",\"Calidad antes que tiempo\",\"Recorta palanca si cedes\",\"Activa abdomen antes de iniciar\",\"Mantén columna neutra\"]","errores_comunes":"[\"Arquear la zona lumbar\",\"Tirar del cuello\",\"Contener la respiración\",\"Moverse demasiado rápido\",\"Usar impulso de piernas\",\"Colapsar hombros\",\"Perder posición pélvica\",\"Continuar tras fallar la postura\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"No asignar automáticamente: exige alta fuerza anti-extensión y control lumbopélvico\",\"Evitar con dolor lumbar, cervical o de hombro\"]","sustituciones":"[\"Abdominales Bicicleta (Bicycle Crunches)\",\"Abdominales Crunch\",\"Bird Dog (Perro-Pájaro)\",\"Crunch en Polea (Cable Crunch)\",\"Dead bug\",\"Plancha con manos elevadas\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Practicar la progresión previa con control\",\"Aumentar tiempo o repeticiones sin perder posición\",\"Añadir carga solo con supervisión técnica\"]","regresiones":"[\"Hollow hold\",\"Elevación de piernas con rodillas flexionadas\",\"Negativas parciales de dragon flag\",\"Usar banda o asistencia externa\",\"Reducir la palanca o trabajar una fase\",\"Volver a la progresión básica con un entrenador\"]","lugar":"gimnasio","objetivo":"habilidad","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"3","rango_reps_max":"8","descanso_segundos_min":"90","descanso_segundos_max":"150","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"revisar"},{"action":"deprecate_review","id":"58","nombre":"Arrancada olímpica con barra","aliases":"[\"Arrancada olímpica con barra\",\"Arrancada olímpica barra\",\"snatch\",\"barbell snatch\",\"Arrancada olímpica con BB\"]","nivel":"avanzado","nivel_minimo":"avanzado","grupo_muscular":"cuerpo completo","musculo_principal":"cuerpo completo","musculos_secundarios":"[\"glúteos\",\"isquiosurales\",\"hombros\",\"trapecio\",\"core\"]","equipamiento":"barra, discos","equipo_requerido":"[\"barra\",\"discos\"]","tipo_entrenamiento":"potencia","patron_movimiento":"potencia","descripcion":"Arrancada olímpica con barra trabaja principalmente cuerpo completo, con participación de glúteos, isquiosurales, hombros. Sirve para mejorar la capacidad física específica y el control técnico. Conviene solo como habilidad avanzada, después de dominar sus progresiones y preferentemente con supervisión presencial.","instrucciones":"[\"Preparación: coloca la barra sobre suelo/plataforma nivelada, carga discos iguales y asegura ambos extremos. Deja espacio alrededor, centra la barra sobre el mediopié y usa discos técnicos o bloques si aún no alcanzas la posición inicial con columna neutra.\",\"Posición inicial: base estable, rodillas alineadas, cadera y abdomen firmes, espalda en posición neutra y cabeza siguiendo el torso. Mantén cuello largo, pecho controlado, hombros bajos, escápulas estables y manos/muñecas/codos alineados con el apoyo o implemento.\",\"Agarre: prono cerrado alrededor de la barra y muñecas firmes. En peso muerto pesado puede usarse mixto o hook grip, alternando lados y solo con experiencia; para aprender, usa doble prono. La barra debe permanecer controlada, nunca apoyada en dedos abiertos.\",\"Inicio y trayectoria: Inicia empujando el suelo con la barra pegada al cuerpo; extiende cadera, rodillas y tobillos y luego recibe la barra con pies estables. La potencia viene de piernas/cadera, no de tirar temprano con brazos.\",\"Rango y biomecánica: Cada fase debe conservar barra cercana, espalda neutra y recepción equilibrada. No persigas una profundidad o carga que cambie la trayectoria; practica desde bloques o posición colgante antes del suelo.\",\"Tempo y respiración: La preparación es deliberada, el tirón y la recepción son explosivos y la bajada es controlada. Toma aire y bracea antes del tirón; exhala al estabilizar la recepción.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Base estable\",\"Core firme\",\"Carga cerca del cuerpo\",\"Cadera y rodillas coordinadas\",\"Cuello neutro\",\"Aterriza suave\",\"Respira con el esfuerzo\",\"Detén si se desordena\",\"Controla la fase de ida y vuelta\",\"Evita impulsos excesivos\"]","errores_comunes":"[\"Usar fatiga para aprender técnica\",\"Redondear la espalda\",\"Alejar la carga\",\"Recepción rígida\",\"Rodillas desalineadas\",\"Contener la respiración\",\"Perder equilibrio\",\"Priorizar velocidad sobre control\",\"Usar impulso excesivo\",\"Perder postura\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Burpees\",\"Clean and Press (Cargada y Press)\",\"Muscle-Up\",\"Planche (Plancha horizontal)\",\"Variación con mancuerna ligera\",\"Ejercicio por fases\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Practicar la progresión previa con control\",\"Aumentar tiempo o repeticiones sin perder posición\",\"Añadir carga solo con supervisión técnica\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Usar banda o asistencia externa\",\"Reducir la palanca o trabajar una fase\",\"Volver a la progresión básica con un entrenador\"]","lugar":"gimnasio","objetivo":"potencia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"2","rango_reps_max":"5","descanso_segundos_min":"150","descanso_segundos_max":"240","rir_recomendado":"2","duracion_promedio_segundos":"30","maquina_gym":"","estado_calidad":"revisar"},{"action":"deprecate_review","id":"57","nombre":"Cargada y press con barra","aliases":"[\"Cargada y press con barra\",\"Cargada y press barra\",\"clean and press\",\"cargada más press\",\"clean & press\",\"C&P\"]","nivel":"avanzado","nivel_minimo":"avanzado","grupo_muscular":"cuerpo completo","musculo_principal":"cuerpo completo","musculos_secundarios":"[\"hombros\",\"trapecio\",\"glúteos\",\"cuádriceps\",\"core\"]","equipamiento":"barra, discos","equipo_requerido":"[\"barra\",\"discos\"]","tipo_entrenamiento":"potencia","patron_movimiento":"potencia/empuje vertical","descripcion":"Cargada y press con barra trabaja principalmente cuerpo completo, con participación de hombros, trapecio, glúteos. Sirve para mejorar la capacidad física específica y el control técnico. Conviene solo como habilidad avanzada, después de dominar sus progresiones y preferentemente con supervisión presencial.","instrucciones":"[\"Preparación: coloca la barra en un rack a una altura que permita sacarla sin encoger hombros ni ponerte de puntillas. Carga ambos lados por igual, usa seguros de disco y topes de seguridad; ensaya el recorrido con la barra vacía y pide spotter cuando la carga o el ejercicio lo amerite.\",\"Posición inicial: pies o apoyos firmes, rodillas y cadera estables, glúteos y abdomen contraídos. Conserva columna y cuello neutros, pecho controlado, hombros lejos de orejas y escápulas estables; apila manos, muñecas y codos según la dirección del empuje.\",\"Agarre: prono en barra/suelo o neutro en asas/mancuernas. Usa una anchura que deje antebrazos casi verticales; un agarre cerrado aumenta demanda de tríceps y uno muy ancho acorta el recorrido. Pulgar cerrado y muñeca apilada sobre antebrazo.\",\"Inicio y trayectoria: Inicia empujando el apoyo o la carga en la línea prevista mientras hombro y codo se extienden coordinados. Siente pectoral/deltoides/tríceps según la variante, con abdomen firme y hombros lejos de orejas.\",\"Rango y biomecánica: Baja hasta que el codo alcance una profundidad tolerable y el hombro conserve centrado, normalmente con antebrazo vertical; sube hasta brazos casi extendidos sin chocar ni hiperextender. Evita rebotes y extremos que despeguen espalda o pelvis.\",\"Tempo y respiración: Tempo base 3-0-1: desciende 3 s, pausa sin rebote y empuja en 1 s controlado. Inhala al bajar y exhala al cruzar el punto de mayor esfuerzo; usa respiración con brace solo si conoces la técnica.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Base estable\",\"Core firme\",\"Carga cerca del cuerpo\",\"Cadera y rodillas coordinadas\",\"Cuello neutro\",\"Aterriza suave\",\"Respira con el esfuerzo\",\"Detén si se desordena\",\"Escápulas firmes\",\"Controla la bajada\"]","errores_comunes":"[\"Usar fatiga para aprender técnica\",\"Redondear la espalda\",\"Alejar la carga\",\"Recepción rígida\",\"Rodillas desalineadas\",\"Contener la respiración\",\"Perder equilibrio\",\"Priorizar velocidad sobre control\",\"Rebotar la carga\",\"Perder tensión escapular\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Evitar si provoca dolor agudo en hombro, muñeca o codo\",\"Reducir rango o usar alternativa si genera molestia\"]","sustituciones":"[\"Burpees\",\"Clean and Press (Cargada y Press)\",\"Muscle-Up\",\"Planche (Plancha horizontal)\",\"Variación con mancuerna ligera\",\"Ejercicio por fases\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Practicar la progresión previa con control\",\"Aumentar tiempo o repeticiones sin perder posición\",\"Añadir carga solo con supervisión técnica\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Usar banda o asistencia externa\",\"Reducir la palanca o trabajar una fase\",\"Volver a la progresión básica con un entrenador\"]","lugar":"gimnasio","objetivo":"potencia","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"3","rango_reps_max":"6","descanso_segundos_min":"120","descanso_segundos_max":"180","rir_recomendado":"2","duracion_promedio_segundos":"30","maquina_gym":"","estado_calidad":"revisar"},{"action":"deprecate_review","id":"59","nombre":"Muscle-up estricto en barra","aliases":"[\"Muscle-up estricto en barra\",\"muscle up\",\"Muscle-up\",\"Muscle-up estricto en BB\"]","nivel":"avanzado","nivel_minimo":"avanzado","grupo_muscular":"cuerpo completo","musculo_principal":"dorsal ancho","musculos_secundarios":"[\"pectoral\",\"tríceps\",\"bíceps\",\"core\"]","equipamiento":"barra de dominadas","equipo_requerido":"[\"barra de dominadas\",\"colchoneta\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"jalón vertical/empuje","descripcion":"Muscle-up estricto en barra trabaja principalmente dorsal ancho, con participación de pectoral, tríceps, bíceps. Sirve para mejorar la capacidad física específica y el control técnico. Conviene solo como habilidad avanzada, después de dominar sus progresiones y preferentemente con supervisión presencial.","instrucciones":"[\"Preparación: comprueba una barra alta y firme, seca manos y coloca colchoneta sin obstáculos. Verifica espacio por encima y detrás, domina dominadas altas y fondos antes de intentar la transición y usa banda solo si queda anclada de forma segura.\",\"Posición inicial: cuelga con agarre cerrado ligeramente más ancho que hombros; en anillas usa falso agarre solo si ya lo dominas. Brazos largos, escápulas activas, piernas juntas, glúteos/abdomen firmes, cuello neutro y espacio libre por encima de la barra.\",\"Agarre/apoyo: usa una sujeción cerrada y simétrica, con muñecas neutras. Ajusta la variante si el agarre limita la postura o provoca molestias antes que aumentar la carga.\",\"Inicio y trayectoria: Genera una dominada alta llevando la barra hacia el esternón; acerca el pecho, pasa hombros y muñecas sobre el soporte y termina con un fondo. En anillas manténlas cerca del cuerpo durante la transición.\",\"Rango y biomecánica: Cada fase debe ser controlable: tirón por encima del pecho, transición sin impacto y bloqueo estable arriba. No uses kip hasta dominar la versión estricta y no dejes caer hombros en la transición.\",\"Tempo y respiración: Tirón explosivo, transición rápida pero precisa y descenso de 3–4 s. Exhala al tirar y al presionar; recupera aire arriba.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: desde el apoyo, baja a fondo controlado, pasa la transición en reversa y vuelve al colgado; apoya pies en banco o suelo antes de soltar. No te dejes caer desde arriba ni entrenes al fallo sin supervisión.\"]","cues_tecnicos":"[\"Base estable\",\"Core firme\",\"Carga cerca del cuerpo\",\"Cadera y rodillas coordinadas\",\"Cuello neutro\",\"Aterriza suave\",\"Respira con el esfuerzo\",\"Detén si se desordena\",\"Inicia con escápulas controladas\",\"Lleva los codos hacia el cuerpo\"]","errores_comunes":"[\"Usar fatiga para aprender técnica\",\"Redondear la espalda\",\"Alejar la carga\",\"Recepción rígida\",\"Rodillas desalineadas\",\"Contener la respiración\",\"Perder equilibrio\",\"Priorizar velocidad sobre control\",\"Usar impulso excesivo\",\"Encoger hombros\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Evitar si provoca dolor agudo en hombro, muñeca o codo\",\"Reducir rango o usar alternativa si genera molestia\"]","sustituciones":"[\"Burpees\",\"Clean and Press (Cargada y Press)\",\"Planche (Plancha horizontal)\",\"Variación con mancuerna ligera\",\"Ejercicio por fases\",\"Patrón sin impacto\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Practicar la progresión previa con control\",\"Aumentar tiempo o repeticiones sin perder posición\",\"Añadir carga solo con supervisión técnica\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Usar banda o asistencia externa\",\"Reducir la palanca o trabajar una fase\",\"Volver a la progresión básica con un entrenador\"]","lugar":"gimnasio","objetivo":"habilidad","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"3","rango_reps_max":"8","descanso_segundos_min":"120","descanso_segundos_max":"180","rir_recomendado":"2","duracion_promedio_segundos":"30","maquina_gym":"","estado_calidad":"revisar"},{"action":"deprecate_review","id":"63","nombre":"Planche completa de calistenia","aliases":"[\"Planche completa de calistenia\",\"planche\",\"Full planche\",\"plancha de calistenia\",\"full planche hold\",\"planche hold\"]","nivel":"avanzado","nivel_minimo":"avanzado","grupo_muscular":"cuerpo completo","musculo_principal":"hombros","musculos_secundarios":"[\"pectoral\",\"tríceps\",\"core\",\"serrato anterior\"]","equipamiento":"peso corporal","equipo_requerido":"[\"peso corporal\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"empuje isométrico","descripcion":"Planche completa de calistenia trabaja principalmente hombros, con participación de pectoral, tríceps, core. Sirve para mejorar la capacidad física específica y el control técnico. Conviene solo como habilidad avanzada, después de dominar sus progresiones y preferentemente con supervisión presencial.","instrucciones":"[\"Preparación: usa suelo antideslizante o paralelas firmes y una zona despejada. Calienta muñecas, practica lean y tuck planche, y coloca los pies sobre un apoyo bajo para poder salir; no inicies con codos o muñecas doloridos.\",\"Posición inicial: manos al ancho de hombros con dedos abiertos, codos extendidos, escápulas protraídas y hombros delante de muñecas. Junta piernas, aprieta glúteos/abdomen, lleva pelvis en retroversión y mantén cabeza neutra; usa paralelas si las muñecas no toleran el suelo.\",\"Apoyo/agarre: manos completas, dedos separados y muñecas alineadas bajo el soporte cuando estén en el suelo; en barra/anillas usa agarre cerrado con pulgar. Ajusta el ángulo o usa asas si la extensión de muñeca no es tolerable.\",\"Inicio y trayectoria: Inclina hombros delante de manos y eleva pies hasta dejar el cuerpo paralelo al suelo; empuja fuerte, protrae escápulas y conserva codos rectos. Siente hombros, serrato, pecho y abdomen.\",\"Rango y biomecánica: Sostén solo mientras pelvis no caiga, codos no se doblen y hombros permanezcan activos. Regresa pies al suelo de forma controlada; no colapses sobre muñecas.\",\"Tempo y respiración: Isometrías de 3–15 s con respiraciones breves. Exhala lentamente y usa progresiones tuck/straddle antes de la completa.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: lleva rodillas al pecho o apoya un pie, desplaza hombros atrás y baja ambos pies antes de relajar codos. No abandones la posición colapsando sobre muñecas o cara.\"]","cues_tecnicos":"[\"Base estable\",\"Core firme\",\"Carga cerca del cuerpo\",\"Cadera y rodillas coordinadas\",\"Cuello neutro\",\"Aterriza suave\",\"Respira con el esfuerzo\",\"Detén si se desordena\",\"Escápulas firmes\",\"Controla la bajada\"]","errores_comunes":"[\"Usar fatiga para aprender técnica\",\"Redondear la espalda\",\"Alejar la carga\",\"Recepción rígida\",\"Rodillas desalineadas\",\"Contener la respiración\",\"Perder equilibrio\",\"Priorizar velocidad sobre control\",\"Rebotar la carga\",\"Perder tensión escapular\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Evitar si provoca dolor agudo en hombro, muñeca o codo\",\"Reducir rango o usar alternativa si genera molestia\"]","sustituciones":"[\"Burpees\",\"Clean and Press (Cargada y Press)\",\"Muscle-Up\",\"Planche (Plancha horizontal)\",\"Variación con mancuerna ligera\",\"Ejercicio por fases\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Practicar la progresión previa con control\",\"Aumentar tiempo o repeticiones sin perder posición\",\"Añadir carga solo con supervisión técnica\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Usar banda o asistencia externa\",\"Reducir la palanca o trabajar una fase\",\"Volver a la progresión básica con un entrenador\"]","lugar":"cualquiera","objetivo":"habilidad","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"","rango_reps_max":"","descanso_segundos_min":"120","descanso_segundos_max":"180","rir_recomendado":"","duracion_promedio_segundos":"10","maquina_gym":"","estado_calidad":"revisar"},{"action":"deprecate_review","id":"64","nombre":"Front lever en barra","aliases":"[\"Front lever en barra\",\"front lever\",\"palanca frontal\",\"front lever hold\",\"FL hold\",\"Front lever en BB\"]","nivel":"avanzado","nivel_minimo":"avanzado","grupo_muscular":"espalda","musculo_principal":"dorsal ancho","musculos_secundarios":"[\"core\",\"bíceps\",\"deltoides posterior\"]","equipamiento":"barra de dominadas","equipo_requerido":"[\"barra de dominadas\",\"colchoneta\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"jalón isométrico","descripcion":"Front lever en barra trabaja principalmente dorsal ancho, con participación de core, bíceps, deltoides posterior. Sirve para mejorar la capacidad física específica y el control técnico. Conviene solo como habilidad avanzada, después de dominar sus progresiones y preferentemente con supervisión presencial.","instrucciones":"[\"Preparación: comprueba barra/anillas firmes, altura y espacio inferior; coloca colchoneta y usa un cajón solo para subir/bajar. Practica tuck lever y descenso desde invertido con asistencia antes de extender las piernas.\",\"Posición inicial: cuelga de barra/anillas con agarre prono cerrado, brazos rectos y hombros activos. Junta piernas, apunta pies, coloca costillas sobre pelvis y crea una línea rígida; cuello neutro y espacio despejado debajo.\",\"Apoyo/agarre: manos completas, dedos separados y muñecas alineadas bajo el soporte cuando estén en el suelo; en barra/anillas usa agarre cerrado con pulgar. Ajusta el ángulo o usa asas si la extensión de muñeca no es tolerable.\",\"Inicio y trayectoria: Deprime escápulas y lleva cadera hacia la barra hasta que cuerpo quede horizontal mirando arriba; conserva codos rectos y pelvis en retroversión. Siente dorsal, espalda alta y abdomen.\",\"Rango y biomecánica: Sostén la línea que puedas mantener sin flexionar cadera ni doblar brazos. Regresa a tuck y luego al colgado; no sueltes desde la posición horizontal.\",\"Tempo y respiración: Isometrías de 5–20 s con respiración continua. Progresa tuck, advanced tuck, una pierna, straddle y completa.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: recoge piernas a tuck, vuelve al colgado activo y apoya pies en banco/suelo antes de soltar. No abras las manos ni caigas desde la palanca horizontal.\"]","cues_tecnicos":"[\"Pecho largo\",\"Hombros abajo\",\"Codos hacia costillas\",\"Cuello neutro\",\"Core firme\",\"Barra o cable cerca\",\"Sin tirón lumbar\",\"Controla el retorno\",\"Inicia con escápulas controladas\",\"Lleva los codos hacia el cuerpo\"]","errores_comunes":"[\"Redondear o hiperextender la espalda\",\"Tirar con impulso\",\"Elevar hombros\",\"Sacar la cabeza\",\"Flexionar muñecas\",\"Acortar el estiramiento\",\"Mover cadera o torso\",\"Golpear la pila\",\"Usar impulso excesivo\",\"Encoger hombros\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Back Lever\",\"Dominadas / Pull-ups\",\"Jalón al Pecho (Lat Pulldown)\",\"Remo con pecho apoyado\",\"Jalón al pecho con agarre neutro\",\"Remo en polea sentado\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Practicar la progresión previa con control\",\"Aumentar tiempo o repeticiones sin perder posición\",\"Añadir carga solo con supervisión técnica\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Usar banda o asistencia externa\",\"Reducir la palanca o trabajar una fase\",\"Volver a la progresión básica con un entrenador\"]","lugar":"gimnasio","objetivo":"habilidad","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"","rango_reps_max":"","descanso_segundos_min":"120","descanso_segundos_max":"180","rir_recomendado":"","duracion_promedio_segundos":"10","maquina_gym":"","estado_calidad":"revisar"},{"action":"deprecate_review","id":"67","nombre":"Dominada a una mano","aliases":"[\"Dominada a una mano\",\"one-arm pull-up\",\"one arm pull up\",\"dominada unilateral\",\"single-arm pull-up\",\"OAP\"]","nivel":"avanzado","nivel_minimo":"avanzado","grupo_muscular":"espalda","musculo_principal":"dorsal ancho","musculos_secundarios":"[\"bíceps\",\"braquial\",\"core\",\"romboides\"]","equipamiento":"barra de dominadas","equipo_requerido":"[\"barra de dominadas\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"jalón vertical","descripcion":"Dominada a una mano trabaja principalmente dorsal ancho, con participación de bíceps, braquial, core. Sirve para mejorar la capacidad física específica y el control técnico. Conviene solo como habilidad avanzada, después de dominar sus progresiones y preferentemente con supervisión presencial.","instrucciones":"[\"Preparación: comprueba barra firme y coloca banda/asistencia antes de subir. Calienta hombros/codos, domina dominadas lastradas y archer pull-ups, y trabaja lejos del fallo para poder bajar con control.\",\"Posición inicial: cuelga de una barra firme con la mano de trabajo en agarre prono o neutro y pulgar cerrado; la otra mano usa banda, muñeca o asistencia según progresión. Hombro activo, piernas quietas, pelvis neutra, abdomen firme y cuello largo.\",\"Agarre: prono algo más ancho que hombros para esta variante; un agarre excesivamente abierto recorta el recorrido. El neutro suele ser más cómodo para el hombro y el supino aumenta la ayuda del bíceps; usa pulgar cerrado y muñecas neutras.\",\"Inicio y trayectoria: Deprime la escápula y tira llevando el codo de trabajo hacia las costillas; resiste la rotación con abdomen y glúteos. Siente dorsal y flexores del codo sin colapsar el hombro libre.\",\"Rango y biomecánica: Eleva hasta que mentón o parte alta del pecho supere la mano sin girar bruscamente; baja hasta brazo largo con hombro activo. Usa asistencia para igualar ambos lados.\",\"Tempo y respiración: Sube 1–2 s, pausa 1 s y baja 3–5 s. Exhala al tirar e inhala al descender.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: baja hasta colgado activo con asistencia, coloca ambos pies en banco/suelo y suelta solo cuando no haya tensión unilateral. Evita descensos máximos fatigados que terminen en caída.\"]","cues_tecnicos":"[\"Pecho largo\",\"Hombros abajo\",\"Codos hacia costillas\",\"Cuello neutro\",\"Core firme\",\"Barra o cable cerca\",\"Sin tirón lumbar\",\"Controla el retorno\",\"Inicia con escápulas controladas\",\"Lleva los codos hacia el cuerpo\"]","errores_comunes":"[\"Redondear o hiperextender la espalda\",\"Tirar con impulso\",\"Elevar hombros\",\"Sacar la cabeza\",\"Flexionar muñecas\",\"Acortar el estiramiento\",\"Mover cadera o torso\",\"Golpear la pila\",\"Usar impulso excesivo\",\"Encoger hombros\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Si hay dolor agudo, detén el ejercicio y consulta a un profesional\"]","sustituciones":"[\"Jalón al pecho\",\"Dominadas\",\"Remo con pecho apoyado\",\"Jalón al pecho con agarre neutro\",\"Remo en polea sentado\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Practicar la progresión previa con control\",\"Aumentar tiempo o repeticiones sin perder posición\",\"Añadir carga solo con supervisión técnica\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Usar banda o asistencia externa\",\"Reducir la palanca o trabajar una fase\",\"Volver a la progresión básica con un entrenador\"]","lugar":"gimnasio","objetivo":"habilidad","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"1","rango_reps_max":"5","descanso_segundos_min":"150","descanso_segundos_max":"240","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"revisar"},{"action":"deprecate_review","id":"65","nombre":"Back lever en barra","aliases":"[\"Back lever en barra\",\"back lever\",\"palanca dorsal\",\"back lever hold\",\"BL hold\",\"Back lever en BB\"]","nivel":"avanzado","nivel_minimo":"avanzado","grupo_muscular":"espalda","musculo_principal":"hombros","musculos_secundarios":"[\"pectoral\",\"dorsal ancho\",\"core\",\"bíceps\"]","equipamiento":"barra o anillas","equipo_requerido":"[\"barra o anillas\",\"colchoneta\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"empuje/jalón isométrico","descripcion":"Back lever en barra trabaja principalmente hombros, con participación de pectoral, dorsal ancho, core. Sirve para mejorar la capacidad física específica y el control técnico. Conviene solo como habilidad avanzada, después de dominar sus progresiones y preferentemente con supervisión presencial.","instrucciones":"[\"Preparación: usa anillas o barra firmes con colchoneta y espacio inferior. Aprende skin-the-cat y tuck back lever con un entrenador; ajusta anillas bajas para poder apoyar pies si falla la posición.\",\"Posición inicial: desde apoyo en anillas/barra, usa agarre cerrado, brazos rectos y hombros deprimidos. Lleva cuerpo a posición invertida controlada, junta piernas, aprieta glúteos/abdomen y mantén cuello neutro antes de abrir hacia la palanca.\",\"Apoyo/agarre: manos completas, dedos separados y muñecas alineadas bajo el soporte cuando estén en el suelo; en barra/anillas usa agarre cerrado con pulgar. Ajusta el ángulo o usa asas si la extensión de muñeca no es tolerable.\",\"Inicio y trayectoria: Desde invertido, abre hombros y baja el cuerpo como bloque hasta quedar horizontal mirando al suelo; mantén codos rectos y escápulas controladas. Siente pecho, hombros, dorsal y abdomen.\",\"Rango y biomecánica: Detén antes de perder posición de hombro, flexionar codos o arquear la espalda. Vuelve a invertido/tuck antes de bajar; nunca abandones la palanca soltando el agarre.\",\"Tempo y respiración: Isometrías breves de 3–15 s con respiración continua. Usa tuck y asistencia antes de palanca completa.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: vuelve a tuck/invertido, deshaz la rotación con control y apoya pies antes de soltar. No continúes si pierdes orientación del hombro o no puedes regresar sin caída.\"]","cues_tecnicos":"[\"Pecho largo\",\"Hombros abajo\",\"Codos hacia costillas\",\"Cuello neutro\",\"Core firme\",\"Barra o cable cerca\",\"Sin tirón lumbar\",\"Controla el retorno\",\"Inicia con escápulas controladas\",\"Lleva los codos hacia el cuerpo\"]","errores_comunes":"[\"Redondear o hiperextender la espalda\",\"Tirar con impulso\",\"Elevar hombros\",\"Sacar la cabeza\",\"Flexionar muñecas\",\"Acortar el estiramiento\",\"Mover cadera o torso\",\"Golpear la pila\",\"Usar impulso excesivo\",\"Encoger hombros\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Evitar si provoca dolor agudo en hombro, muñeca o codo\",\"Reducir rango o usar alternativa si genera molestia\"]","sustituciones":"[\"Dominadas / Pull-ups\",\"Front Lever\",\"Jalón al Pecho (Lat Pulldown)\",\"Remo con pecho apoyado\",\"Jalón al pecho con agarre neutro\",\"Remo en polea sentado\"]","progresiones":"[\"Aumentar repeticiones dentro del rango\",\"Aumentar carga gradualmente\",\"Controlar mejor el tempo\",\"Practicar la progresión previa con control\",\"Aumentar tiempo o repeticiones sin perder posición\",\"Añadir carga solo con supervisión técnica\"]","regresiones":"[\"Reducir carga\",\"Usar una variante más estable\",\"Reducir rango temporalmente\",\"Usar banda o asistencia externa\",\"Reducir la palanca o trabajar una fase\",\"Volver a la progresión básica con un entrenador\"]","lugar":"gimnasio","objetivo":"habilidad","series_sugeridas":"","repeticiones_sugeridas":"","rango_reps_min":"","rango_reps_max":"","descanso_segundos_min":"120","descanso_segundos_max":"180","rir_recomendado":"","duracion_promedio_segundos":"10","maquina_gym":"","estado_calidad":"revisar"},{"action":"deprecate_review","id":"sf-shoulder-upright-row","nombre":"Remo vertical con barra EZ","aliases":"[\"Remo vertical con barra EZ\",\"Remo vertical barra EZ\",\"remo al mentón\",\"upright row\",\"EZ-bar upright row\",\"cable upright row\",\"Remo vertical con BB EZ\"]","nivel":"intermedio","nivel_minimo":"intermedio","grupo_muscular":"hombros","musculo_principal":"deltoides lateral","musculos_secundarios":"[\"trapecio superior\",\"deltoides anterior\",\"biceps\"]","equipamiento":"barra EZ o mancuernas","equipo_requerido":"[\"barra EZ o mancuernas\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"elevacion vertical","descripcion":"Remo vertical con barra EZ trabaja principalmente deltoides lateral, con participación de trapecio superior, deltoides anterior, bíceps. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene solo como habilidad avanzada, después de dominar sus progresiones y preferentemente con supervisión presencial.","instrucciones":"[\"Preparación: coloca una barra EZ ligera en soporte bajo o suelo, carga ambos lados por igual y usa cierres. Elige una curva semiprona algo más ancha que hombros; practica el límite de altura sin discos antes de aumentar carga.\",\"Posición inicial: pies al ancho de caderas, rodillas suaves, pelvis/costillas apiladas y barra EZ frente a muslos. Toma agarre prono o semiprono algo más ancho que hombros, muñecas rectas, brazos largos, hombros bajos y cuello neutro.\",\"Agarre: el neutro facilita llevar los codos junto al torso y suele ser cómodo; el prono algo más ancho desplaza énfasis hacia espalda alta y deltoide posterior; el supino añade bíceps. Elige uno que permita muñecas rectas y hombros bajos.\",\"Inicio y trayectoria: Desliza la barra cerca del cuerpo elevando codos hacia arriba y afuera; hombros y codos se mueven mientras tronco/cadera permanecen quietos. Siente deltoides lateral y trapecio, no pinzamiento anterior.\",\"Rango y biomecánica: Detén cuando brazos superiores se aproximen a la altura de hombros o antes si muñecas/hombros pierden comodidad; no es necesario llevar la barra a la barbilla. Baja hasta brazos largos sin dejar caer.\",\"Tempo y respiración: Sube 2 s, pausa breve y baja 3 s. Exhala al elevar e inhala al descender.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: completa la última repetición con control, vuelve el implemento a la posición segura y colócalo en rack/suelo sin dejarlo caer. Si fallaría la siguiente repetición, termina la serie; no sacrifiques técnica por carga y usa ayuda o topes cuando quedar atrapado sea posible.\"]","cues_tecnicos":"[\"Cuello largo\",\"Hombros lejos de orejas\",\"Core firme\",\"Muñecas neutras\",\"Codos guían\",\"Sin impulso lumbar\",\"Recorrido tolerable\",\"Excéntrica lenta\",\"Codos guian\",\"Rango sin dolor\"]","errores_comunes":"[\"Encoger hombros\",\"Arquear la zona lumbar\",\"Usar impulso\",\"Elevar por encima del rango tolerable\",\"Doblar muñecas\",\"Adelantar la cabeza\",\"Codos fuera de trayectoria\",\"Soltar la excéntrica\",\"Subir codos demasiado alto\",\"Encoger cuello\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"No asignar automáticamente si existe dolor o pinzamiento de hombro\",\"Limitar el recorrido antes de que los hombros pierdan comodidad\"]","sustituciones":"[\"Elevaciones laterales con mancuernas\",\"Face pull en polea alta\",\"Elevaciones laterales en polea\",\"Variante unilateral en polea\",\"Variante con mancuernas sentado\",\"Máquina de hombro con agarre neutro\"]","progresiones":"[\"Aumentar reps\",\"Usar mancuernas\",\"Tempo lento\",\"Practicar la progresión previa con control\",\"Aumentar tiempo o repeticiones sin perder posición\",\"Añadir carga solo con supervisión técnica\"]","regresiones":"[\"Elevaciones laterales con mancuernas\",\"Elevaciones laterales en polea\",\"Face pull en polea alta\",\"Usar banda o asistencia externa\",\"Reducir la palanca o trabajar una fase\",\"Volver a la progresión básica con un entrenador\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"12","rango_reps_min":"10","rango_reps_max":"15","descanso_segundos_min":"45","descanso_segundos_max":"90","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"","estado_calidad":"revisar"},{"action":"insert","id":"sf-hammer-strength-chest-press","nombre":"Press de pecho Hammer Strength","aliases":"[\"Press de pecho Hammer Strength\",\"press Hammer\",\"press convergente de pecho\",\"Hammer Strength chest press\",\"plate-loaded chest press\",\"Hammer Strength plate-loaded chest press\"]","nivel":"principiante","nivel_minimo":"principiante","grupo_muscular":"pecho","musculo_principal":"pectoral mayor","musculos_secundarios":"[\"triceps\",\"deltoides anterior\"]","equipamiento":"máquina de press de pecho Hammer Strength con discos","equipo_requerido":"[\"Hammer Strength Plate-Loaded Chest Press\",\"discos\",\"seguros de disco\"]","tipo_entrenamiento":"fuerza","patron_movimiento":"empuje horizontal convergente","descripcion":"Press de pecho Hammer Strength trabaja principalmente pectoral mayor, con participación de tríceps, deltoides anterior. Sirve para ganar masa muscular y mejorar el control del movimiento. Conviene para aprender el patrón con una trayectoria guiada, acumular volumen de hipertrofia y dosificar la carga con precisión.","instrucciones":"[\"Preparación y ajuste: consulta el placard del modelo para identificar seguros y dirección de entrada; no ajustes piezas con la carga suspendida. Ajusta el asiento para que las empuñaduras queden a mitad del pecho y carga los brazos con discos iguales, usando seguros. Ajusta el inicio si existe, apoya espalda y cabeza y comprueba que ambos brazos se muevan libres antes de presionar; no cargues un solo lado.\",\"Posición inicial: pies o apoyos firmes, rodillas y cadera estables, glúteos y abdomen contraídos. Conserva columna y cuello neutros, pecho controlado, hombros lejos de orejas y escápulas estables; apila manos, muñecas y codos según la dirección del empuje.\",\"Agarre: prono en barra/suelo o neutro en asas/mancuernas. Usa una anchura que deje antebrazos casi verticales; un agarre cerrado aumenta demanda de tríceps y uno muy ancho acorta el recorrido. Pulgar cerrado y muñeca apilada sobre antebrazo.\",\"Inicio y trayectoria: Inicia empujando el apoyo o la carga en la línea prevista mientras hombro y codo se extienden coordinados. Siente pectoral/deltoides/tríceps según la variante, con abdomen firme y hombros lejos de orejas.\",\"Rango y biomecánica: Baja hasta que el codo alcance una profundidad tolerable y el hombro conserve centrado, normalmente con antebrazo vertical; sube hasta brazos casi extendidos sin chocar ni hiperextender. Evita rebotes y extremos que despeguen espalda o pelvis.\",\"Tempo y respiración: Tempo base 3-0-1: desciende 3 s, pausa sin rebote y empuja en 1 s controlado. Inhala al bajar y exhala al cruzar el punto de mayor esfuerzo; usa respiración con brace solo si conoces la técnica.\",\"Control de la serie: conserva la misma trayectoria desde la primera hasta la última repetición; detén la serie si necesitas impulso, pierdes un apoyo o aparece dolor agudo. Ajusta carga o rango antes de alterar la técnica.\",\"Finalización y seguridad: termina la última repetición en la posición inicial con control, deja que la pila descienda sin golpear y suelta el agarre solo cuando el cable o palanca no tenga tensión. Retira accesorios personales y deja el pasador en una carga ligera; no introduzcas dedos entre placas o articulaciones móviles.\"]","cues_tecnicos":"[\"Pies firmes\",\"Glúteos apoyados\",\"Escápulas estables\",\"Pecho controlado\",\"Antebrazos verticales\",\"Muñecas apiladas\",\"Empuja sin rebotar\",\"Baja con control\",\"Manijas a mitad del pecho\",\"Escápulas apoyadas\"]","errores_comunes":"[\"Despegar glúteos o espalda\",\"Rebotar en el pecho o topes\",\"Abrir codos sin control\",\"Doblar muñecas\",\"Elevar hombros\",\"Recortar recorrido\",\"Bloquear codos con golpe\",\"Usar carga sin salida segura\",\"Asiento demasiado bajo\",\"Hombros adelantados\"]","contraindicaciones":"[\"Detén el ejercicio ante dolor agudo, hormigueo, mareo o pérdida súbita de fuerza/control\",\"Reduce carga y recorrido si una articulación no tolera el extremo; no fuerces para igualar una demostración\",\"Tras una lesión reciente, cirugía o restricción médica, confirma la variante y el rango con un profesional cualificado\",\"Usa precaución si la posición por encima de la cabeza o la extensión profunda del hombro produce molestia; cambia agarre, rango o ejercicio\",\"Evitar si la máquina obliga a dolor de hombro\",\"Ajustar asiento o usar mancuernas\"]","sustituciones":"[\"Press de banca con mancuernas\",\"Press de banca con barra\",\"Lagartijas\",\"Press con mancuernas\",\"Press de pecho en máquina\",\"Flexiones con manos elevadas\"]","progresiones":"[\"Aumentar carga\",\"Pausar en estiramiento\",\"Tempo lento\",\"Aumentar la carga 2–5 % al completar el rango con el RIR previsto\",\"Añadir una pausa de 1–2 s en la posición difícil\",\"Aumentar repeticiones o recorrido antes que sacrificar control\"]","regresiones":"[\"Menor carga\",\"Lagartijas inclinadas\",\"Press con mancuernas ligero\",\"Reducir carga y recorrido temporalmente\",\"Usar apoyo o una variante bilateral estable\",\"Practicar el patrón sin carga a tempo lento\"]","lugar":"gimnasio","objetivo":"hipertrofia","series_sugeridas":"3","repeticiones_sugeridas":"12","rango_reps_min":"8","rango_reps_max":"12","descanso_segundos_min":"60","descanso_segundos_max":"120","rir_recomendado":"2","duracion_promedio_segundos":"45","maquina_gym":"Hammer Strength Plate-Loaded Chest Press","estado_calidad":"curado"}]
$patch_json$::jsonb) WITH ORDINALITY AS elem(data, ordinality)
CROSS JOIN LATERAL jsonb_to_record(elem.data) AS patch (
  action text,
  id text,
  nombre text,
  aliases text,
  nivel text,
  nivel_minimo text,
  grupo_muscular text,
  musculo_principal text,
  musculos_secundarios text,
  equipamiento text,
  equipo_requerido text,
  tipo_entrenamiento text,
  patron_movimiento text,
  descripcion text,
  instrucciones text,
  cues_tecnicos text,
  errores_comunes text,
  contraindicaciones text,
  sustituciones text,
  progresiones text,
  regresiones text,
  lugar text,
  objetivo text,
  series_sugeridas text,
  repeticiones_sugeridas text,
  rango_reps_min text,
  rango_reps_max text,
  descanso_segundos_min text,
  descanso_segundos_max text,
  rir_recomendado text,
  duracion_promedio_segundos text,
  maquina_gym text,
  estado_calidad text
);

CREATE TEMP TABLE exercise_import_staging AS
SELECT
  row_number,
  lower(pg_temp.be2_null_text(action)) AS action,
  pg_temp.be2_null_text(id) AS id,
  pg_temp.be2_null_text(nombre) AS nombre,
  pg_temp.be2_text_array(aliases) AS aliases,
  pg_temp.be2_null_text(nivel) AS nivel,
  pg_temp.be2_null_text(nivel_minimo) AS nivel_minimo,
  pg_temp.be2_null_text(grupo_muscular) AS grupo_muscular,
  pg_temp.be2_null_text(musculo_principal) AS musculo_principal,
  pg_temp.be2_text_array(musculos_secundarios) AS musculos_secundarios,
  pg_temp.be2_null_text(equipamiento) AS equipamiento,
  pg_temp.be2_text_array(equipo_requerido) AS equipo_requerido,
  pg_temp.be2_null_text(tipo_entrenamiento) AS tipo_entrenamiento,
  pg_temp.be2_null_text(patron_movimiento) AS patron_movimiento,
  pg_temp.be2_null_text(descripcion) AS descripcion,
  pg_temp.be2_text_array(instrucciones) AS instrucciones,
  pg_temp.be2_text_array(cues_tecnicos) AS cues_tecnicos,
  pg_temp.be2_text_array(errores_comunes) AS errores_comunes,
  pg_temp.be2_text_array(contraindicaciones) AS contraindicaciones,
  pg_temp.be2_text_array(sustituciones) AS sustituciones,
  pg_temp.be2_text_array(progresiones) AS progresiones,
  pg_temp.be2_text_array(regresiones) AS regresiones,
  pg_temp.be2_null_text(lugar) AS lugar,
  pg_temp.be2_null_text(objetivo) AS objetivo,
  pg_temp.be2_int(series_sugeridas) AS series_sugeridas,
  pg_temp.be2_int(repeticiones_sugeridas) AS repeticiones_sugeridas,
  pg_temp.be2_int(rango_reps_min) AS rango_reps_min,
  pg_temp.be2_int(rango_reps_max) AS rango_reps_max,
  pg_temp.be2_int(descanso_segundos_min) AS descanso_segundos_min,
  pg_temp.be2_int(descanso_segundos_max) AS descanso_segundos_max,
  pg_temp.be2_numeric(rir_recomendado) AS rir_recomendado,
  pg_temp.be2_int(duracion_promedio_segundos) AS duracion_promedio_segundos,
  pg_temp.be2_null_text(maquina_gym) AS maquina_gym,
  pg_temp.be2_null_text(estado_calidad) AS estado_calidad
FROM exercise_import_staging_raw;

CREATE TEMP TABLE exercise_import_validation_errors (
  row_number integer,
  action text,
  id text,
  nombre text,
  error_code text,
  error_detail text
);

CREATE TEMP TABLE exercise_import_warnings (
  row_number integer,
  action text,
  id text,
  nombre text,
  warning_code text,
  warning_detail text
);

INSERT INTO exercise_import_validation_errors
SELECT row_number, lower(pg_temp.be2_null_text(action)), pg_temp.be2_null_text(id), pg_temp.be2_null_text(nombre), 'invalid_action', COALESCE(action, '')
FROM exercise_import_staging_raw
WHERE lower(COALESCE(pg_temp.be2_null_text(action), '')) NOT IN ('update', 'insert', 'deprecate_review');

INSERT INTO exercise_import_validation_errors
SELECT row_number, lower(pg_temp.be2_null_text(action)), pg_temp.be2_null_text(id), pg_temp.be2_null_text(nombre), 'invalid_json_array', column_name
FROM exercise_import_staging_raw
CROSS JOIN LATERAL (VALUES
  ('aliases', aliases),
  ('musculos_secundarios', musculos_secundarios),
  ('equipo_requerido', equipo_requerido),
  ('instrucciones', instrucciones),
  ('cues_tecnicos', cues_tecnicos),
  ('errores_comunes', errores_comunes),
  ('contraindicaciones', contraindicaciones),
  ('sustituciones', sustituciones),
  ('progresiones', progresiones),
  ('regresiones', regresiones)
) AS arrays(column_name, raw_value)
WHERE NOT pg_temp.be2_is_json_text_array(raw_value);

INSERT INTO exercise_import_validation_errors
SELECT row_number, lower(pg_temp.be2_null_text(action)), pg_temp.be2_null_text(id), pg_temp.be2_null_text(nombre), 'invalid_numeric', column_name
FROM exercise_import_staging_raw
CROSS JOIN LATERAL (VALUES
  ('series_sugeridas', series_sugeridas),
  ('repeticiones_sugeridas', repeticiones_sugeridas),
  ('rango_reps_min', rango_reps_min),
  ('rango_reps_max', rango_reps_max),
  ('descanso_segundos_min', descanso_segundos_min),
  ('descanso_segundos_max', descanso_segundos_max),
  ('rir_recomendado', rir_recomendado),
  ('duracion_promedio_segundos', duracion_promedio_segundos)
) AS nums(column_name, raw_value)
WHERE NOT pg_temp.be2_is_numeric(raw_value);

INSERT INTO exercise_import_validation_errors
SELECT row_number, lower(pg_temp.be2_null_text(action)), pg_temp.be2_null_text(id), pg_temp.be2_null_text(nombre), 'mojibake_detected', 'Texto parece tener caracteres mal codificados'
FROM exercise_import_staging_raw
WHERE pg_temp.be2_has_mojibake(concat_ws(' ', action, id, nombre, aliases, nivel, nivel_minimo, grupo_muscular, musculo_principal, musculos_secundarios, equipamiento, equipo_requerido, tipo_entrenamiento, patron_movimiento, descripcion, instrucciones, cues_tecnicos, errores_comunes, contraindicaciones, sustituciones, progresiones, regresiones, lugar, objetivo, series_sugeridas, repeticiones_sugeridas, rango_reps_min, rango_reps_max, descanso_segundos_min, descanso_segundos_max, rir_recomendado, duracion_promedio_segundos, maquina_gym, estado_calidad));

INSERT INTO exercise_import_validation_errors
SELECT s.row_number, s.action, s.id, s.nombre, 'missing_id_for_existing_action', 'update/deprecate_review requieren id'
FROM exercise_import_staging s
WHERE s.action IN ('update', 'deprecate_review')
  AND s.id IS NULL;

INSERT INTO exercise_import_validation_errors
SELECT s.row_number, s.action, s.id, s.nombre, 'target_exercise_not_found', 'No existe public.exercises.id para update/deprecate_review'
FROM exercise_import_staging s
LEFT JOIN public.exercises e ON e.id = s.id
WHERE s.action IN ('update', 'deprecate_review')
  AND s.id IS NOT NULL
  AND e.id IS NULL;

CREATE TEMP TABLE exercise_import_effective AS
SELECT
  s.*,
  e.id AS existing_id,
  COALESCE(s.nombre, e.nombre) AS eff_nombre,
  COALESCE(s.nivel, e.nivel) AS eff_nivel,
  COALESCE(s.nivel_minimo, e.nivel_minimo) AS eff_nivel_minimo,
  COALESCE(s.grupo_muscular, e.grupo_muscular) AS eff_grupo_muscular,
  COALESCE(s.musculo_principal, e.musculo_principal) AS eff_musculo_principal,
  COALESCE(s.tipo_entrenamiento, e.tipo_entrenamiento) AS eff_tipo_entrenamiento,
  COALESCE(s.patron_movimiento, e.patron_movimiento) AS eff_patron_movimiento,
  COALESCE(s.descripcion, e.descripcion) AS eff_descripcion,
  COALESCE(s.instrucciones, e.instrucciones) AS eff_instrucciones,
  COALESCE(s.cues_tecnicos, e.cues_tecnicos) AS eff_cues_tecnicos,
  COALESCE(s.errores_comunes, e.errores_comunes) AS eff_errores_comunes,
  COALESCE(s.sustituciones, e.sustituciones) AS eff_sustituciones,
  COALESCE(s.aliases, e.aliases) AS eff_aliases,
  COALESCE(s.equipamiento, e.equipamiento) AS eff_equipamiento,
  COALESCE(s.equipo_requerido, e.equipo_requerido) AS eff_equipo_requerido,
  COALESCE(s.lugar, e.lugar) AS eff_lugar,
  COALESCE(s.maquina_gym, e.maquina_gym) AS eff_maquina_gym,
  COALESCE(s.estado_calidad, e.estado_calidad) AS eff_estado_calidad,
  COALESCE(
    CASE WHEN s.action = 'update' THEN NULLIF(s.series_sugeridas, 0) ELSE s.series_sugeridas END,
    e.series_sugeridas,
    CASE
      WHEN s.action = 'update'
       AND lower(COALESCE(s.tipo_entrenamiento, e.tipo_entrenamiento, '')) NOT LIKE '%cardio%'
      THEN 3
    END
  ) AS eff_series_sugeridas,
  COALESCE(CASE WHEN s.action = 'update' THEN NULLIF(s.repeticiones_sugeridas, 0) ELSE s.repeticiones_sugeridas END, e.repeticiones_sugeridas) AS eff_repeticiones_sugeridas,
  COALESCE(CASE WHEN s.action = 'update' THEN NULLIF(s.rango_reps_min, 0) ELSE s.rango_reps_min END, e.rango_reps_min) AS eff_rango_reps_min,
  COALESCE(CASE WHEN s.action = 'update' THEN NULLIF(s.rango_reps_max, 0) ELSE s.rango_reps_max END, e.rango_reps_max) AS eff_rango_reps_max,
  COALESCE(CASE WHEN s.action = 'update' THEN NULLIF(s.descanso_segundos_min, 0) ELSE s.descanso_segundos_min END, e.descanso_segundos_min) AS eff_descanso_segundos_min,
  COALESCE(CASE WHEN s.action = 'update' THEN NULLIF(s.descanso_segundos_max, 0) ELSE s.descanso_segundos_max END, e.descanso_segundos_max) AS eff_descanso_segundos_max,
  COALESCE(s.rir_recomendado, e.rir_recomendado) AS eff_rir_recomendado,
  COALESCE(CASE WHEN s.action = 'update' THEN NULLIF(s.duracion_promedio_segundos, 0) ELSE s.duracion_promedio_segundos END, e.duracion_promedio_segundos) AS eff_duracion_promedio_segundos
FROM exercise_import_staging s
LEFT JOIN public.exercises e ON e.id = s.id
WHERE s.action IN ('update', 'insert');

INSERT INTO exercise_import_validation_errors
SELECT row_number, action, id, nombre, error_code, error_detail
FROM exercise_import_effective
CROSS JOIN LATERAL (VALUES
  ('missing_nombre', CASE WHEN pg_temp.be2_null_text(eff_nombre) IS NULL THEN 'nombre vacio' END),
  ('missing_grupo_muscular', CASE WHEN pg_temp.be2_null_text(eff_grupo_muscular) IS NULL THEN 'grupo_muscular vacio' END),
  ('missing_musculo_principal', CASE WHEN pg_temp.be2_null_text(eff_musculo_principal) IS NULL THEN 'musculo_principal vacio' END),
  ('missing_patron_movimiento', CASE WHEN pg_temp.be2_null_text(eff_patron_movimiento) IS NULL THEN 'patron_movimiento vacio' END),
  ('missing_nivel', CASE WHEN pg_temp.be2_null_text(eff_nivel) IS NULL THEN 'nivel vacio' END),
  ('missing_estado_calidad', CASE WHEN pg_temp.be2_null_text(eff_estado_calidad) IS NULL THEN 'estado_calidad vacio' END),
  ('missing_descripcion', CASE WHEN pg_temp.be2_null_text(eff_descripcion) IS NULL THEN 'descripcion vacia' END),
  ('missing_instrucciones', CASE WHEN cardinality(COALESCE(eff_instrucciones, '{}'::text[])) = 0 THEN 'instrucciones vacias' END),
  ('missing_cues', CASE WHEN cardinality(COALESCE(eff_cues_tecnicos, '{}'::text[])) = 0 THEN 'cues_tecnicos vacios' END),
  ('missing_errores', CASE WHEN cardinality(COALESCE(eff_errores_comunes, '{}'::text[])) = 0 THEN 'errores_comunes vacios' END),
  ('missing_sustituciones', CASE WHEN cardinality(COALESCE(eff_sustituciones, '{}'::text[])) = 0 THEN 'sustituciones vacias' END),
  ('missing_aliases', CASE WHEN cardinality(COALESCE(eff_aliases, '{}'::text[])) = 0 THEN 'aliases vacios' END),
  ('invalid_estado_calidad', CASE WHEN lower(COALESCE(eff_estado_calidad, '')) NOT IN ('legacy', 'pendiente', 'basico', 'básico', 'revisar', 'curado', 'deprecado', 'premium') THEN COALESCE(eff_estado_calidad, '') END),
  ('invalid_level', CASE WHEN lower(COALESCE(eff_nivel, '')) NOT IN ('principiante', 'intermedio', 'avanzado', 'b', 'i', 'p') THEN COALESCE(eff_nivel, '') END),
  ('invalid_min_level', CASE WHEN eff_nivel_minimo IS NOT NULL AND lower(eff_nivel_minimo) NOT IN ('principiante', 'intermedio', 'avanzado', 'b', 'i', 'p') THEN eff_nivel_minimo END),
  ('invalid_rep_range', CASE WHEN action = 'insert' AND eff_rango_reps_min IS NOT NULL AND eff_rango_reps_max IS NOT NULL AND eff_rango_reps_min > eff_rango_reps_max THEN concat(eff_rango_reps_min, '>', eff_rango_reps_max) END),
  ('invalid_rest_range', CASE WHEN action = 'insert' AND eff_descanso_segundos_min IS NOT NULL AND eff_descanso_segundos_max IS NOT NULL AND eff_descanso_segundos_min > eff_descanso_segundos_max THEN concat(eff_descanso_segundos_min, '>', eff_descanso_segundos_max) END),
  ('invalid_rest_seconds', CASE WHEN action = 'insert' AND ((eff_descanso_segundos_min IS NOT NULL AND (eff_descanso_segundos_min < 15 OR eff_descanso_segundos_min > 600)) OR (eff_descanso_segundos_max IS NOT NULL AND (eff_descanso_segundos_max < 15 OR eff_descanso_segundos_max > 600))) THEN concat('min=', eff_descanso_segundos_min, ', max=', eff_descanso_segundos_max) END),
  ('invalid_rir', CASE WHEN action = 'insert' AND eff_rir_recomendado IS NOT NULL AND (eff_rir_recomendado < 0 OR eff_rir_recomendado > 5) THEN eff_rir_recomendado::text END),
  ('invalid_series', CASE WHEN action = 'insert' AND eff_series_sugeridas IS NOT NULL AND (eff_series_sugeridas < 1 OR eff_series_sugeridas > 10) THEN eff_series_sugeridas::text END),
  ('invalid_duration', CASE WHEN action = 'insert' AND eff_duracion_promedio_segundos IS NOT NULL AND (eff_duracion_promedio_segundos < 5 OR eff_duracion_promedio_segundos > 7200) THEN eff_duracion_promedio_segundos::text END),
  ('strength_missing_programming', CASE WHEN action = 'insert' AND lower(COALESCE(eff_tipo_entrenamiento, '')) NOT LIKE '%cardio%' AND (eff_series_sugeridas IS NULL OR eff_rango_reps_min IS NULL OR eff_rango_reps_max IS NULL OR eff_descanso_segundos_min IS NULL OR eff_descanso_segundos_max IS NULL OR eff_rir_recomendado IS NULL) THEN 'fuerza sin series/reps/descanso/RIR completos' END),
  ('cardio_has_strength_prescription', CASE WHEN action = 'insert' AND lower(COALESCE(eff_tipo_entrenamiento, '')) LIKE '%cardio%' AND (eff_rir_recomendado IS NOT NULL OR eff_rango_reps_min IS NOT NULL OR eff_rango_reps_max IS NOT NULL OR eff_repeticiones_sugeridas IS NOT NULL) THEN concat('rir=', eff_rir_recomendado, ', reps=', eff_rango_reps_min, '-', eff_rango_reps_max) END),
  ('cardio_missing_duration', CASE WHEN action = 'insert' AND lower(COALESCE(eff_tipo_entrenamiento, '')) LIKE '%cardio%' AND eff_duracion_promedio_segundos IS NULL THEN 'cardio sin duracion' END)
) AS validations(error_code, error_detail)
WHERE error_detail IS NOT NULL;

INSERT INTO exercise_import_warnings
SELECT row_number, action, id, nombre, 'maquina_gym_vacia', 'Ejercicio de gimnasio parece usar maquina/equipo especifico pero maquina_gym esta vacia'
FROM exercise_import_effective
WHERE lower(COALESCE(eff_lugar, '')) = 'gimnasio'
  AND pg_temp.be2_null_text(eff_maquina_gym) IS NULL
  AND pg_temp.be2_is_machine_like(eff_nombre, eff_equipamiento, eff_equipo_requerido, eff_patron_movimiento, eff_tipo_entrenamiento);

INSERT INTO exercise_import_warnings
SELECT row_number, action, id, nombre, 'update_programming_incomplete', 'Update importable, pero la programacion efectiva queda incompleta; revisar series/reps/descanso/RIR despues del import'
FROM exercise_import_effective
WHERE action = 'update'
  AND lower(COALESCE(eff_tipo_entrenamiento, '')) NOT LIKE '%cardio%'
  AND (
    eff_series_sugeridas IS NULL
    OR eff_rango_reps_min IS NULL
    OR eff_rango_reps_max IS NULL
    OR eff_descanso_segundos_min IS NULL
    OR eff_descanso_segundos_max IS NULL
    OR eff_rir_recomendado IS NULL
  );

INSERT INTO exercise_import_warnings
SELECT row_number, action, id, nombre, 'update_zero_programming_ignored', 'Uno o mas campos de programacion vinieron en 0 y se trataran como vacios para no sobrescribir datos buenos'
FROM exercise_import_staging
WHERE action = 'update'
  AND (
    series_sugeridas = 0
    OR repeticiones_sugeridas = 0
    OR rango_reps_min = 0
    OR rango_reps_max = 0
    OR descanso_segundos_min = 0
    OR descanso_segundos_max = 0
    OR duracion_promedio_segundos = 0
  );

CREATE TEMP TABLE exercise_import_valid AS
SELECT s.*
FROM exercise_import_staging s
WHERE NOT EXISTS (
  SELECT 1 FROM exercise_import_validation_errors err
  WHERE err.row_number = s.row_number
);

CREATE TEMP TABLE exercise_import_insert_conflicts AS
WITH insert_rows AS (
  SELECT v.*, pg_temp.be2_norm(v.nombre) AS normalized_nombre
  FROM exercise_import_valid v
  WHERE v.action = 'insert'
), existing_aliases AS (
  SELECT e.id, e.nombre, pg_temp.be2_norm(alias) AS alias_norm
  FROM public.exercises e
  CROSS JOIN LATERAL unnest(COALESCE(e.aliases, '{}'::text[])) AS alias
), insert_aliases AS (
  SELECT r.row_number, pg_temp.be2_norm(alias) AS alias_norm
  FROM insert_rows r
  CROSS JOIN LATERAL unnest(COALESCE(r.aliases, '{}'::text[])) AS alias
), name_conflicts AS (
  SELECT DISTINCT r.row_number, r.action, r.id, r.nombre, e.id AS conflicting_id, e.nombre AS conflicting_nombre, 'duplicate_normalized_nombre' AS conflict_reason
  FROM insert_rows r
  JOIN public.exercises e ON pg_temp.be2_norm(e.nombre) = r.normalized_nombre
), alias_conflicts AS (
  SELECT DISTINCT r.row_number, r.action, r.id, r.nombre, ea.id AS conflicting_id, ea.nombre AS conflicting_nombre, 'duplicate_alias' AS conflict_reason
  FROM insert_rows r
  JOIN insert_aliases ia ON ia.row_number = r.row_number AND ia.alias_norm <> ''
  JOIN existing_aliases ea ON ea.alias_norm = ia.alias_norm
)
SELECT * FROM name_conflicts
UNION
SELECT * FROM alias_conflicts;

CREATE TEMP TABLE exercise_import_update_diff AS
SELECT
  v.row_number,
  v.id,
  array_remove(ARRAY[
    CASE WHEN v.nombre IS NOT NULL AND v.nombre IS DISTINCT FROM e.nombre THEN 'nombre' END,
    CASE WHEN v.aliases IS NOT NULL AND v.aliases IS DISTINCT FROM e.aliases THEN 'aliases' END,
    CASE WHEN v.nivel IS NOT NULL AND v.nivel IS DISTINCT FROM e.nivel THEN 'nivel' END,
    CASE WHEN v.nivel_minimo IS NOT NULL AND v.nivel_minimo IS DISTINCT FROM e.nivel_minimo THEN 'nivel_minimo' END,
    CASE WHEN v.grupo_muscular IS NOT NULL AND v.grupo_muscular IS DISTINCT FROM e.grupo_muscular THEN 'grupo_muscular' END,
    CASE WHEN v.musculo_principal IS NOT NULL AND v.musculo_principal IS DISTINCT FROM e.musculo_principal THEN 'musculo_principal' END,
    CASE WHEN v.musculos_secundarios IS NOT NULL AND v.musculos_secundarios IS DISTINCT FROM e.musculos_secundarios THEN 'musculos_secundarios' END,
    CASE WHEN v.equipamiento IS NOT NULL AND v.equipamiento IS DISTINCT FROM e.equipamiento THEN 'equipamiento' END,
    CASE WHEN v.equipo_requerido IS NOT NULL AND v.equipo_requerido IS DISTINCT FROM e.equipo_requerido THEN 'equipo_requerido' END,
    CASE WHEN v.tipo_entrenamiento IS NOT NULL AND v.tipo_entrenamiento IS DISTINCT FROM e.tipo_entrenamiento THEN 'tipo_entrenamiento' END,
    CASE WHEN v.patron_movimiento IS NOT NULL AND v.patron_movimiento IS DISTINCT FROM e.patron_movimiento THEN 'patron_movimiento' END,
    CASE WHEN v.descripcion IS NOT NULL AND v.descripcion IS DISTINCT FROM e.descripcion THEN 'descripcion' END,
    CASE WHEN v.instrucciones IS NOT NULL AND v.instrucciones IS DISTINCT FROM e.instrucciones THEN 'instrucciones' END,
    CASE WHEN v.cues_tecnicos IS NOT NULL AND v.cues_tecnicos IS DISTINCT FROM e.cues_tecnicos THEN 'cues_tecnicos' END,
    CASE WHEN v.errores_comunes IS NOT NULL AND v.errores_comunes IS DISTINCT FROM e.errores_comunes THEN 'errores_comunes' END,
    CASE WHEN v.contraindicaciones IS NOT NULL AND v.contraindicaciones IS DISTINCT FROM e.contraindicaciones THEN 'contraindicaciones' END,
    CASE WHEN v.sustituciones IS NOT NULL AND v.sustituciones IS DISTINCT FROM e.sustituciones THEN 'sustituciones' END,
    CASE WHEN v.progresiones IS NOT NULL AND v.progresiones IS DISTINCT FROM e.progresiones THEN 'progresiones' END,
    CASE WHEN v.regresiones IS NOT NULL AND v.regresiones IS DISTINCT FROM e.regresiones THEN 'regresiones' END,
    CASE WHEN v.lugar IS NOT NULL AND v.lugar IS DISTINCT FROM e.lugar THEN 'lugar' END,
    CASE WHEN v.objetivo IS NOT NULL AND v.objetivo IS DISTINCT FROM e.objetivo THEN 'objetivo' END,
    CASE
      WHEN COALESCE(
        NULLIF(v.series_sugeridas, 0),
        CASE
          WHEN e.series_sugeridas IS NULL
           AND lower(COALESCE(v.tipo_entrenamiento, e.tipo_entrenamiento, '')) NOT LIKE '%cardio%'
          THEN 3
        END
      ) IS NOT NULL
      AND COALESCE(
        NULLIF(v.series_sugeridas, 0),
        CASE
          WHEN e.series_sugeridas IS NULL
           AND lower(COALESCE(v.tipo_entrenamiento, e.tipo_entrenamiento, '')) NOT LIKE '%cardio%'
          THEN 3
        END
      ) IS DISTINCT FROM e.series_sugeridas
      THEN 'series_sugeridas'
    END,
    CASE WHEN NULLIF(v.repeticiones_sugeridas, 0) IS NOT NULL AND NULLIF(v.repeticiones_sugeridas, 0) IS DISTINCT FROM e.repeticiones_sugeridas THEN 'repeticiones_sugeridas' END,
    CASE WHEN NULLIF(v.rango_reps_min, 0) IS NOT NULL AND NULLIF(v.rango_reps_min, 0) IS DISTINCT FROM e.rango_reps_min THEN 'rango_reps_min' END,
    CASE WHEN NULLIF(v.rango_reps_max, 0) IS NOT NULL AND NULLIF(v.rango_reps_max, 0) IS DISTINCT FROM e.rango_reps_max THEN 'rango_reps_max' END,
    CASE WHEN NULLIF(v.descanso_segundos_min, 0) IS NOT NULL AND NULLIF(v.descanso_segundos_min, 0) IS DISTINCT FROM e.descanso_segundos_min THEN 'descanso_segundos_min' END,
    CASE WHEN NULLIF(v.descanso_segundos_max, 0) IS NOT NULL AND NULLIF(v.descanso_segundos_max, 0) IS DISTINCT FROM e.descanso_segundos_max THEN 'descanso_segundos_max' END,
    CASE WHEN v.rir_recomendado IS NOT NULL AND v.rir_recomendado IS DISTINCT FROM e.rir_recomendado THEN 'rir_recomendado' END,
    CASE WHEN NULLIF(v.duracion_promedio_segundos, 0) IS NOT NULL AND NULLIF(v.duracion_promedio_segundos, 0) IS DISTINCT FROM e.duracion_promedio_segundos THEN 'duracion_promedio_segundos' END,
    CASE WHEN v.maquina_gym IS NOT NULL AND v.maquina_gym IS DISTINCT FROM e.maquina_gym THEN 'maquina_gym' END,
    CASE WHEN v.estado_calidad IS NOT NULL AND v.estado_calidad IS DISTINCT FROM e.estado_calidad THEN 'estado_calidad' END
  ], NULL) AS modified_columns
FROM exercise_import_valid v
JOIN public.exercises e ON e.id = v.id
WHERE v.action = 'update';

CREATE TEMP TABLE exercise_import_deprecate_diff AS
SELECT v.row_number, v.id, ARRAY['estado_calidad']::text[] AS modified_columns
FROM exercise_import_valid v
JOIN public.exercises e ON e.id = v.id
WHERE v.action = 'deprecate_review'
  AND e.estado_calidad IS DISTINCT FROM COALESCE(v.estado_calidad, 'revisar');
SELECT
  'summary' AS report_type,
  metric,
  value::text AS value,
  NULL::integer AS row_number,
  NULL::text AS action,
  NULL::text AS id,
  NULL::text AS nombre,
  NULL::text AS detail
FROM (VALUES
  ('csv_rows', (SELECT count(*) FROM exercise_import_staging_raw)::bigint),
  ('valid_rows', (SELECT count(*) FROM exercise_import_valid)::bigint),
  ('blocking_validation_errors', (SELECT count(*) FROM exercise_import_validation_errors)::bigint),
  ('warnings', (SELECT count(*) FROM exercise_import_warnings)::bigint),
  ('updates_that_would_change', (SELECT count(*) FROM exercise_import_update_diff WHERE cardinality(modified_columns) > 0)::bigint),
  ('updates_no_change', (SELECT count(*) FROM exercise_import_update_diff WHERE cardinality(modified_columns) = 0)::bigint),
  ('inserts_that_would_apply', (SELECT count(*) FROM exercise_import_valid v WHERE v.action = 'insert' AND NOT EXISTS (SELECT 1 FROM exercise_import_insert_conflicts c WHERE c.row_number = v.row_number))::bigint),
  ('insert_conflicts_ignored', (SELECT count(DISTINCT row_number) FROM exercise_import_insert_conflicts)::bigint),
  ('deprecate_review_that_would_apply', (SELECT count(*) FROM exercise_import_deprecate_diff)::bigint)
) AS metrics(metric, value)

UNION ALL
SELECT 'update_diff', 'modified_columns', array_to_string(modified_columns, ', '), d.row_number, v.action, v.id, v.nombre, NULL::text
FROM exercise_import_update_diff d
JOIN exercise_import_valid v ON v.row_number = d.row_number
WHERE cardinality(d.modified_columns) > 0

UNION ALL
SELECT 'insert_candidate', 'will_insert', 'true', v.row_number, v.action, v.id, v.nombre, concat('nuevo id uuid se generara al aplicar; musculo=', v.musculo_principal, ', patron=', v.patron_movimiento)
FROM exercise_import_valid v
WHERE v.action = 'insert'
  AND NOT EXISTS (SELECT 1 FROM exercise_import_insert_conflicts c WHERE c.row_number = v.row_number)

UNION ALL
SELECT 'deprecate_candidate', 'will_deprecate_review', COALESCE(v.estado_calidad, 'revisar'), v.row_number, v.action, v.id, v.nombre, 'estado_calidad permitido por constraint'
FROM exercise_import_valid v
JOIN exercise_import_deprecate_diff d ON d.row_number = v.row_number

UNION ALL
SELECT 'ignored', error_code, 'validation_error', row_number, action, id, nombre, error_detail
FROM exercise_import_validation_errors

UNION ALL
SELECT DISTINCT 'ignored', conflict_reason, 'insert_conflict', row_number, action, id, nombre, concat('conflicts_with=', conflicting_id, ' ', conflicting_nombre)
FROM exercise_import_insert_conflicts

UNION ALL
SELECT 'warning', warning_code, 'non_blocking', row_number, action, id, nombre, warning_detail
FROM exercise_import_warnings

ORDER BY report_type, metric, row_number NULLS FIRST, id NULLS LAST;

ROLLBACK;
